});

css:
@font-face {
 font-family: 'Insignia';
 src: url('assets/Insignia LT W04 Regular.ttf') format('truetype');
 font-weight: normal;
 font-style: normal;
}

:root {
 --amber: #FFBF00;
 --charcoal: #36454F;
 --teal: #008080;
 --aqua: #00A9A9;
 --ivory: #FFF8E7;
 --graphite: #1C1C1C;
 --gold: #FFD700;
 --font-heading: 'JetBrains Mono', monospace;
 --font-subheading: 'IBM Plex Mono', monospace;
 --font-body: 'Recursive', monospace;
 --font-note: 'Fira Code', monospace;
 --font-menu: 'Space Mono', monospace;
 --font-logo: 'Insignia', serif;
}

body {
 background-color: var(--ivory);
 color: var(--charcoal);
 font-family: var(--font-body);
 padding-top: 70px;
 cursor: none;
}

a,
button,
.service-card {
 cursor: none;
}

.cursor-dot {
 width: 8px;
 height: 8px;
 background-color: var(--teal);
 position: fixed;
 top: 50%;
 left: 50%;
 transform: translate(-50%, -50%);
 border-radius: 50%;
 pointer-events: none;
 z-index: 9999;
 transition: transform 0.1s ease-out;
}

.cursor-circle {
 width: 40px;
 height: 40px;
 border: 2px solid var(--teal);
 position: fixed;
 top: 50%;
 left: 50%;
 transform: translate(-50%, -50%);
 border-radius: 50%;
 pointer-events: none;
 z-index: 9999;
 transition: transform 0.2s ease-out, width 0.3s, height 0.3s, opacity 0.3s, border-color 0.3s;
 box-shadow: 0 0 15px rgba(0, 128, 128, 0.3);
 animation: cursorPulse 2s ease-in-out infinite;
}

@keyframes cursorPulse {
 0%, 100% { 
 transform: translate(-50%, -50%) scale(1);
 opacity: 0.8;
 }
 50% { 
 transform: translate(-50%, -50%) scale(1.1);
 opacity: 1;
 }
}

.cursor-grow {
 transform: translate(-50%, -50%) scale(5.8);
 opacity: 0.7;
 border-color: var(--amber);
 box-shadow: 0 0 25px rgba(255, 191, 0, 0.5);
}

.fade-in-section,
.fade-in-card {
 opacity: 0;
 transform: translateY(30px);
 transition: opacity 0.6s ease-out, transform 0.6s ease-out;
}

.fade-in-section.visible,
.fade-in-card.visible {
 opacity: 1;
 transform: translateY(0);
}

.service-card.fade-in-card {
 transition-delay: calc(var(--card-index) * 100ms);
}

h1,
h2,
h3,
h4,
h5,
h6 {
 font-family: var(--font-heading);
 font-weight: 700;
 color: var(--charcoal);
}

.section-heading {
 font-family: var(--font-heading);
 position: relative;
 display: inline-block;
 padding-bottom: 15px;
 opacity: 0;
 transform: translateY(30px);
 transition: all 0.8s ease;
}

.section-heading.visible {
 opacity: 1;
 transform: translateY(0);
}

.section-heading::after {
 content: '';
 position: absolute;
 bottom: 0;
 left: 50%;
 transform: translateX(-50%);
 width: 0;
 height: 4px;
 background: linear-gradient(45deg, var(--amber), var(--gold));
 transition: width 0.6s ease;
 border-radius: 2px;
 box-shadow: 0 2px 8px rgba(255, 191, 0, 0.3);
}

.visible .section-heading::after {
 width: 80px;
}

.section-heading:hover::after {
 width: 100%;
 box-shadow: 0 4px 12px rgba(255, 191, 0, 0.5);
}

.section-subheading {
 font-family: var(--font-subheading);
 font-size: 1.1rem;
 line-height: 1.6;
}

.navbar {
 background-color: rgba(255, 248, 231, 0.85);
 backdrop-filter: blur(15px);
 border-bottom: 1px solid rgba(0, 0, 0, 0.1);
 box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
 transition: all 0.3s ease;
}

.navbar.scrolled {
 background-color: rgba(255, 248, 231, 0.95);
 box-shadow: 0 6px 30px rgba(0, 0, 0, 0.5);
}

.navbar-nav {
 align-items: center;
}

.navbar .nav-link {
 font-family: var(--font-menu);
 color: var(--charcoal);
 transition: all 0.3s ease;
 padding: 0.5rem 1rem;
 position: relative;
 border-radius: 8px;
}

.navbar .nav-link::after {
 content: '';
 position: absolute;
 bottom: 0;
 left: 50%;
 width: 0;
 height: 2px;
 background: linear-gradient(45deg, var(--teal), var(--aqua));
 transition: all 0.3s ease;
 transform: translateX(-50%);
 border-radius: 2px;
}

.navbar .nav-link:hover {
 color: var(--teal);
 transform: translateY(-2px);
 background: rgba(0, 128, 128, 0.08);
}

.navbar .nav-link:hover::after { 
 width: 70%;
}

.custom-toggler {
 width: 40px;
 height: 40px;
 perspective: 1000px;
 cursor: none;
 z-index: 1100;
 margin-left: 1rem;
}

.custom-toggler .flipper {
 position: relative;
 width: 100%;
 height: 100%;
 transition: transform 0.6s;
 transform-style: preserve-3d;
}

.custom-toggler .flipper.flipped {
 transform: rotateY(180deg);
}

