 $(document).ready(function() {
 // Scroll Animation Logic
 function checkVisibility() {
 $('.fade-in').each(function() {
 var elementTop = $(this).offset().top;
 var windowBottom = $(window).scrollTop() + $(window).height();

 // Add visible class when element scrolls into view
 if (elementTop < windowBottom - 50) {
 $(this).addClass('visible');
 }
 });
 }

 // Trigger animation check on scroll and initial load
 $(window).on('scroll', checkVisibility);
 checkVisibility();

 // Countdown Timer Logic
 var countDownDate = new Date("Aug 14, 2026 10:30:00").getTime();

 var x = setInterval(function() {
 var now = new Date().getTime();
 var distance = countDownDate - now;

 var days = Math.floor(distance / (1000 * 60 * 60 * 24));
 var hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
 var minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
 var seconds = Math.floor((distance % (1000 * 60)) / 1000);

 $('#days').text(days < 10 ? '0' + days : days);
 $('#hours').text(hours < 10 ? '0' + hours : hours);
 $('#minutes').text(minutes < 10 ? '0' + minutes : minutes);
 $('#seconds').text(seconds < 10 ? '0' + seconds : seconds);

 if (distance < 0) {
 clearInterval(x);
 $("#countdown").html("<div style='color: var(--accent-gold); font-size: 1.5rem; font-family: Playfair Display, serif;'>The celebration has begun!</div>");
 }
 }, 1000);

 // Basic Ajax setup just in case you expand into RSVP form routing later
 $.ajaxSetup({ cache: false });
 });
 </script>
