 /**
 * Modern Vanilla JS Frontend for MCP Studio
 */

let currentTools = [];
let currentToolId = null;
let parameters = {}; 
let testPassed = false;

document.addEventListener('DOMContentLoaded', () => {
 fetchTools();

 // Listen for form edits to invalidate the test state
 const form = document.getElementById('tool-form');
 form.addEventListener('input', handleFormChange);
 form.addEventListener('change', handleFormChange);
});

// Resets Publish button if inputs change
function handleFormChange(e) {
 // Ignore changes within the test arguments area itself
 if (e.target.closest('#test-inputs-container')) return;

 testPassed = false;
 document.getElementById('btn-publish').disabled = true;
 renderTestFields();
}

// --- Toast Notification System ---
function showToast(message, type = "success") {
 const toastEl = document.getElementById('liveToast');
 const toastBody = document.getElementById('toast-body');

 // Map types to bootstrap colors
 const colorClass = {
 'success': 'bg-success',
 'danger': 'bg-danger',
 'warning': 'bg-warning text-dark',
 'info': 'bg-info text-dark'
 }[type] || 'bg-primary';

 toastEl.className = `toast align-items-center border-0 shadow-lg ${colorClass}`;
 toastBody.innerHTML = message;

 const toast = new bootstrap.Toast(toastEl, { delay: 4000 });
 toast.show();
}

// --- API Calls ---

async function fetchTools() {
 try {
 const res = await fetch('/api/tools');
 if (!res.ok) throw new Error('Network response was not ok');
 const data = await res.json();
 currentTools = data.tools || [];
 renderSidebar();
 } catch (e) {
 showToast('<i class="fa-solid fa-triangle-exclamation me-2"></i>Failed to load tools from server', 'danger');
 console.error(e);
 }
}

async function importCurl() {
 const curlStr = document.getElementById('curl-input').value;
 const btn = document.getElementById('btn-curl-import');

 if(!curlStr.trim()) {
 showToast("Please paste a cURL command", "warning");
 return;
 }

 const originalText = btn.innerHTML;
 btn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Parsing...';
 btn.disabled = true;

 try {
 const res = await fetch('/api/curl/parse', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({curl_cmd: curlStr})
 });
 const data = await res.json();

 if (res.ok) {
 loadToolIntoForm(data, true);
 bootstrap.Modal.getInstance(document.getElementById('curlModal')).hide();
 document.getElementById('curl-input').value = ""; // clear
 showToast('<i class="fa-solid fa-check-circle me-2"></i>cURL imported successfully!', 'success');

 // Expand core & params accordion for visibility
 new bootstrap.Collapse(document.getElementById('collapseParams'), {toggle: false}).show();
 } else {
 showToast(data.detail, 'danger');
 }
 } catch (e) {
 showToast('<i class="fa-solid fa-triangle-exclamation me-2"></i>Error parsing cURL', 'danger');
 } finally {
 btn.innerHTML = originalText;
 btn.disabled = false;
 }
}

// --- UI Rendering: Sidebar ---

function renderSidebar() {
 const pubList = document.getElementById('published-list');
 const draftList = document.getElementById('drafts-list');
 pubList.innerHTML = '';
 draftList.innerHTML = '';

 // Sort alphabetically
 currentTools.sort((a,b) => (a.name || "").localeCompare(b.name || ""));

 currentTools.forEach(tool => {
 const li = document.createElement('li');
 li.className = 'nav-item';

 const a = document.createElement('a');
 a.className = `nav-link tool-item ${tool.id === currentToolId ? 'active' : ''}`;
 a.href = '#';
 a.onclick = (e) => {
 e.preventDefault();
 loadToolIntoForm(tool);
 // Update active state in sidebar
 document.querySelectorAll('.tool-item').forEach(el => el.classList.remove('active'));
 a.classList.add('active');
 };

 if (tool.status === 'published') {
 a.innerHTML = `<i class="fa-solid fa-circle text-success status-dot me-2"></i>${tool.name}`;
 pubList.appendChild(li);
 } else {
 a.innerHTML = `<i class="fa-solid fa-circle text-warning status-dot me-2"></i>${tool.name}`;
 draftList.appendChild(li);
 }
 li.appendChild(a);
 });

 if(pubList.children.length === 0) pubList.innerHTML = '<li class="px-4 py-2 text-muted small">No published tools</li>';
 if(draftList.children.length === 0) draftList.innerHTML = '<li class="px-4 py-2 text-muted small">No drafts</li>';
}

function createNewTool() {
 document.querySelectorAll('.tool-item').forEach(el => el.classList.remove('active'));
 loadToolIntoForm({
 name: "", description: "", 
 metadata: {risk_level: "low", impact_area: "read", requires_auth: false, risk_description: ""},
 config: {endpoint: "", method: "GET", timeout: 120}, 
 parameters: {}
 });
 document.getElementById('form-title').textContent = "Create New Tool";

 // Reset accordions to default
 new bootstrap.Collapse(document.getElementById('collapseCore'), {toggle: false}).show();
}

function loadToolIntoForm(tool, isNewImport = false) {
 currentToolId = isNewImport ? null : tool.id;
 document.getElementById('form-title').textContent = isNewImport ? "Imported Tool (Unsaved)" : `Editing: ${tool.name}`;

 // Core
 document.getElementById('f_name').value = tool.name || "";
 document.getElementById('f_method').value = tool.config?.method || "GET";
 document.getElementById('f_endpoint').value = tool.config?.endpoint || "";
 document.getElementById('f_desc').value = tool.description || "";
 document.getElementById('f_timeout').value = tool.config?.timeout || 120;

 // Governance
 const meta = tool.metadata || {};
 document.getElementById('f_risk').value = meta.risk_level || "low";
 document.getElementById('f_impact').value = meta.impact_area || "read";
 document.getElementById('f_auth').checked = meta.requires_auth || false;
 document.getElementById('f_risk_desc').value = meta.risk_description || "";

 // Parameters
 parameters = tool.parameters ? JSON.parse(JSON.stringify(tool.parameters)) : {}; // deep copy

