 // Use textarea for json/array, input for others
 const defInputHtml = (p.type === 'array' || p.type === 'json') 
 ? `<textarea class="form-control form-control-sm bg-light" rows="2" onchange="updateParam('${key}', 'default', this.value)" placeholder="[] or {}">${defValue}</textarea>`
 : `<input type="text" class="form-control form-control-sm bg-light" value='${defValue}' onchange="updateParam('${key}', 'default', this.value)">`;

 tr.innerHTML = `
 <td>
 <input type="text" class="form-control form-control-sm border-0 fw-medium" value="${key}" 
 onchange="updateParamKey('${key}', this.value)" placeholder="param_name">
 </td>
 <td>
 <select class="form-select form-select-sm border-0 bg-light" onchange="updateParam('${key}', 'type', this.value)">
 ${optionsHtml}
 </select>
 </td>
 <td>
 <input type="text" class="form-control form-control-sm border-0" value="${p.description || ''}" 
 onchange="updateParam('${key}', 'description', this.value)" placeholder="Description for AI...">
 </td>
 <td>${defInputHtml}</td>
 <td class="text-end">
 <button type="button" class="btn btn-sm btn-light text-danger" onclick="deleteParam('${key}')" title="Delete Parameter">
 <i class="fa-solid fa-trash"></i>
 </button>
 </td>
 `;
 tbody.appendChild(tr);
 });
}

function addParameterRow() {
 const baseName = "new_param";
 let name = baseName;
 let i = 1;
 while(parameters[name]) { name = `${baseName}_${i++}`; }

 parameters[name] = { type: "string", description: "", default: "" };
 renderParamsTable();
 renderTestFields();
}

function updateParamKey(oldKey, newKey) {
 newKey = newKey.trim();
 if (oldKey === newKey || !newKey) return;

 // Prevent overwriting existing key
 if (parameters[newKey]) {
 showToast("Parameter name already exists", "warning");
 renderParamsTable(); // reset view
 return;
 }

 parameters[newKey] = parameters[oldKey];
 delete parameters[oldKey];
 renderParamsTable();
 renderTestFields();
}

function updateParam(key, field, value) {
 parameters[key][field] = value;
 if(field === 'type') {
 // Clear default if switching between complex/simple types to avoid parsing errors
 parameters[key].default = ""; 
 renderParamsTable(); // Re-render to swap input type (textarea vs text)
 }
 renderTestFields();
}

function deleteParam(key) {
 delete parameters[key];
 renderParamsTable();
 renderTestFields();
}

// --- Testing Logic ---

function renderTestFields() {
 const container = document.getElementById('test-inputs-container');
 const fieldsDiv = document.getElementById('test-fields');
 fieldsDiv.innerHTML = '';

 const keys = Object.keys(parameters);
 if (keys.length === 0) {
 container.classList.add('d-none');
 return;
 }

 container.classList.remove('d-none');
 keys.forEach(key => {
 const p = parameters[key];
 const col = document.createElement('div');
 col.className = 'col-md-6 mb-2';

 let inputHtml = '';
 let defVal = p.default || '';
 if(p.type === 'array' || p.type === 'json') {
 defVal = typeof defVal === 'object' ? JSON.stringify(defVal) : defVal;
 }

 if (p.type === 'boolean') {
 inputHtml = `
 <div class="form-check mt-4">
 <input type="checkbox" class="form-check-input test-input shadow-sm" id="test_${key}" data-key="${key}" data-type="boolean" ${defVal === 'true' || defVal === true ? 'checked' : ''}>
 <label class="form-check-label fw-medium" for="test_${key}">${key}</label>
 </div>`;
 } else if (p.type === 'number') {
 inputHtml = `
 <label class="form-label mb-1">${key} <span class="badge bg-secondary ms-1">number</span></label>
 <input type="number" class="form-control test-input shadow-sm" data-key="${key}" data-type="number" value="${defVal}">`;
 } else if (p.type === 'array' || p.type === 'json') {
 inputHtml = `
 <label class="form-label mb-1">${key} <span class="badge bg-info text-dark ms-1">${p.type}</span></label>
 <textarea class="form-control test-input shadow-sm font-monospace" rows="2" data-key="${key}" data-type="${p.type}">${defVal}</textarea>`;
 } else {
 // string / file
 let badge = p.type === 'file' ? 'bg-warning text-dark' : 'bg-light text-dark border';
 inputHtml = `
 <label class="form-label mb-1">${key} <span class="badge ${badge} ms-1">${p.type}</span></label>
 <input type="text" class="form-control test-input shadow-sm" data-key="${key}" data-type="${p.type}" value='${defVal}'>`;
 }

 col.innerHTML = inputHtml;
 fieldsDiv.appendChild(col);
 });
}

function getFormData() {
 // Reconstruct Parameter objects ensuring strict types for backend
 let cleanedParams = {};
 Object.keys(parameters).forEach(k => {
 let p = {...parameters[k]};
 if (p.default !== "" && p.default !== null) {
 if (p.type === 'number') p.default = parseFloat(p.default) || 0;
 if (p.type === 'boolean') p.default = (p.default === 'true' || p.default === true);
 if (p.type === 'array' || p.type === 'json') {
 try { p.default = JSON.parse(p.default); } catch(e) {} // Keep as string if parsing fails
 }
 } else {
 delete p.default;
 }
 cleanedParams[k] = p;
 });

 return {
 id: currentToolId,
 status: "draft", 
 name: document.getElementById('f_name').value.trim(),
 description: document.getElementById('f_desc').value.trim(),
 metadata: {
 risk_level: document.getElementById('f_risk').value,
 impact_area: document.getElementById('f_impact').value,
 requires_auth: document.getElementById('f_auth').checked,
 risk_description: document.getElementById('f_risk_desc').value.trim()
 },
 config: {
 endpoint: document.getElementById('f_endpoint').value.trim(),
 method: document.getElementById('f_method').value,
 timeout: parseFloat(document.getElementById('f_timeout').value) || 120
 },
 parameters: cleanedParams
 };
}

async function runTest() {
 const config = getFormData();

 // Basic Form Validation before testing
 if (!config.name || !config.config.endpoint || !config.description) {
 showToast("Name, Endpoint, and Description are required to test.", "warning");
 return;
 }

 const btn = document.getElementById('btn-test');
 const originalBtnHtml = btn.innerHTML;
 btn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Running...';
 btn.disabled = true;

 // Gather Test Args
 let testArgs = {};
 document.querySelectorAll('.test-input').forEach(input => {
 const key = input.dataset.key;
 const type = input.dataset.type;
 if (type === 'boolean') {
 testArgs[key] = input.checked;
 } else if (type === 'number') {
 testArgs[key] = parseFloat(input.value) || 0;
 } else if (type === 'array' || type === 'json') {
 try { 
 testArgs[key] = JSON.parse(input.value || "null"); 
 } catch(e) { 
 testArgs[key] = input.value; 
 }
 } else {
 testArgs[key] = input.value;
 }
 });

 const consoleDiv = document.getElementById('test-console');
 const consoleText = document.getElementById('test-console-text');
 consoleDiv.classList.remove('d-none');
 consoleText.innerHTML = '<span class="sys-text">> Registering dynamic handler...</span><br><span class="sys-text">> Executing MCP call...</span><br>';

 try {
 const res = await fetch('/api/tools/test', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify({ config: config, test_args: testArgs })
 });
 const data = await res.json();

 if (data.success) {
 let prettyOut = typeof data.output === 'object' ? JSON.stringify(data.output, null, 2) : data.output;
 consoleText.innerHTML += `<br><span class="text-success fw-bold">[200 OK] SUCCESS</span><br><pre class="mt-2 text-light">${prettyOut}</pre>`;
 testPassed = true;
 document.getElementById('btn-publish').disabled = false;
 showToast('<i class="fa-solid fa-circle-check me-2"></i>Test passed! Ready to publish.', 'success');
 } else {
 let prettyErr = typeof data.output === 'object' ? JSON.stringify(data.output, null, 2) : (data.output || data.detail);
 consoleText.innerHTML += `<br><span class="error-text fw-bold">[ERROR] FAILED</span><br><pre class="mt-2 text-light">${prettyErr}</pre>`;
 showToast('Test failed. Review the console output.', 'danger');
 }
 } catch (e) {
 consoleText.innerHTML += `<br><span class="error-text fw-bold">[FATAL] Network Error contacting backend.</span>`;
 showToast('Network error during test.', 'danger');
 } finally {
 btn.innerHTML = originalBtnHtml;
 btn.disabled = false;
 }
}

async function saveTool(status) {
 if (status === 'published' && !testPassed) {
 showToast("You must run a successful test before publishing.", "warning");
 return;
 }

 const config = getFormData();
 config.status = status;

 if (!config.name) {
 showToast("Tool name is required.", "warning");
 return;
 }

 const btnId = status === 'published' ? 'btn-publish' : 'btn-save';
 const btn = document.getElementById(btnId);
 const originalBtnHtml = btn.innerHTML;
 btn.innerHTML = `<span class="spinner-border spinner-border-sm me-2"></span>Saving...`;
 btn.disabled = true;

 try {
 const res = await fetch('/api/tools/save', {
 method: 'POST',
 headers: {'Content-Type': 'application/json'},
 body: JSON.stringify(config)
 });
 const data = await res.json();

 if (res.ok) {
 showToast(`<i class="fa-solid fa-check me-2"></i>${data.message}`, "success");
 await fetchTools(); // Refresh sidebar

 // If it was a new tool, assign the ID so subsequent saves overwrite instead of duplicating
 if (!currentToolId) {
 const newToolObj = currentTools.find(t => t.name === config.name);
 if(newToolObj) currentToolId = newToolObj.id;
 }
 } else {
 showToast(`<i class="fa-solid fa-triangle-exclamation me-2"></i>${data.detail || "Error saving tool"}`, "danger");
 }
 } catch (e) {
 showToast("Network error saving tool.", "danger");
 } finally {
 btn.innerHTML = originalBtnHtml;
 btn.disabled = false;
 }
}

To make the Studio interface cleaner, I have moved the cURL Importer inside the Tool Definition expander as a nested, minimal option. This allows you to quickly bootstrap a new tool definition without cluttering the main flow. 

 Here is the updated studio.py : 

 """
Streamlit UI for authoring JSON-defined dynamic MCP tools.

Single flow: define → test on MCP (required) → save draft or publish.
"""

from __future__ import annotations

import asyncio
import hashlib
import json
import os
import sys
import shlex
from urllib.parse import urlparse, parse_qsl
from typing import Any

import streamlit as st

ROOT_DIR = os.path.dirname(os.path.abspath(__file__))
CONFIG_DIR = os.path.join(ROOT_DIR, "tools", "dynamic_configs")
if ROOT_DIR not in sys.path:
 sys.path.insert(0, ROOT_DIR)

NEW_TOOL_LABEL = "— New tool —"
PARAM_TYPES = ["string", "file", "number", "boolean", "array", "json"]
SESSION_PARAMS = "studio_params"
SESSION_PREV_SEL = "_studio_prev_tool_select"
SESSION_FORM_GEN = "studio_form_generation"
SESSION_BOOTSTRAP = "studio_bootstrap"
SESSION_VERIFIED_FP = "studio_verified_cfg_fingerprint"

st.set_page_config(page_title="Dynamic Tool Studio", layout="wide")
st.title("Zero-Code Dynamic Tool Studio")
st.caption(
 "Workflow: choose a tool → expand **2** to define → **3** to test → **4** to save or publish. "
 "Publish stays locked until a test succeeds for the **current** definition."
)

# --- Utility Functions ---

def get_all_tool_configs() -> list[dict]:
 if not os.path.isdir(CONFIG_DIR):
 return []
 out: list[dict] = []
 for name in sorted(os.listdir(CONFIG_DIR)):
 if not name.endswith(".json"):
 continue
 path = os.path.join(CONFIG_DIR, name)
 try:
 with open(path, encoding="utf-8") as fp:
 out.append(json.load(fp))
 except Exception:
 continue
 return out

def config_filename_for_tool(tool_name: str) -> str:
 parts: list[str] = []
 for char in tool_name:
 if char.isalnum() or char in ("-", "_"):
 parts.append(char)
 else:
 parts.append("_")
 safe = "".join(parts)
 return f"{safe or 'tool'}.json"

def save_config(cfg: dict, filename: str | None = None) -> str:
 os.makedirs(CONFIG_DIR, exist_ok=True)
 fn = filename or config_filename_for_tool(str(cfg.get("name", "tool")))
 path = os.path.join(CONFIG_DIR, fn)
 with open(path, "w", encoding="utf-8") as fp:
 json.dump(cfg, fp, indent=4)
 return path

def parse_curl_command(curl_cmd: str) -> dict | None:
 """Parses a cURL command string into a Studio bootstrap dictionary."""
 if not curl_cmd.strip():
 return None
 curl_cmd = curl_cmd.replace('\\\n', ' ').replace('\\\r', ' ')
 try:
 tokens = shlex.split(curl_cmd)
 except ValueError as e:
 st.error(f"Failed to parse cURL syntax: {e}")
 return None

 method, url, headers, body, has_data_flag = "GET", "", {}, None, False
 it = iter(tokens)
 for token in it:
 if token.startswith("http"): url = token
 elif token in ("-X", "--request"): method = next(it, "GET").upper()
 elif token in ("-H", "--header"):
 h = next(it, "")
 if ":" in h:
 k, v = h.split(":", 1)
 headers[k.strip().lower()] = v.strip()
 elif token in ("-d", "--data", "--data-raw", "--data-binary", "--data-urlencode"):
 body = next(it, "")
 has_data_flag = True

 if not url:
 st.error("No URL found in cURL command.")
 return None
 if has_data_flag and method == "GET": method = "POST"

 req_auth = "authorization" in headers or "x-api-key" in headers
 impact = "write" if method in ("POST", "PUT", "PATCH") else ("delete" if method == "DELETE" else "read")
 risk = "medium" if impact in ("write", "delete") else "low"

 rows = []
 parsed_url = urlparse(url)
 base_endpoint = f"{parsed_url.scheme}://{parsed_url.netloc}{parsed_url.path}"
 for k, v in parse_qsl(parsed_url.query):
 rows.append({"name": k, "type": "string", "description": f"Query: {k}", "default": v})

 if body:
 try:
 pb = json.loads(body)
 if isinstance(pb, dict):
 for k, v in pb.items():
 pt = "string"
 if isinstance(v, bool): pt = "boolean"
 elif isinstance(v, (int, float)): pt = "number"
 elif isinstance(v, list): pt = "array"
 elif isinstance(v, dict): pt = "json"
 rows.append({
 "name": k, "type": pt, "description": f"Body: {k}",
 "default": json.dumps(v) if pt in ("array", "json") else v
 })
 else: rows.append({"name": "raw_body", "type": "string", "description": "Raw body", "default": body})
 except json.JSONDecodeError:
 rows.append({"name": "raw_data", "type": "string", "description": "Raw data", "default": body})

 path_parts = [p for p in parsed_url.path.split("/") if p]
 tool_name = f"{method.lower()}_{path_parts[-1].replace('-', '_') if path_parts else 'api'}"

 return {
 "name": tool_name, "description": f"Auto-generated tool for {method} {base_endpoint}",
 "endpoint": base_endpoint, "method": method, "timeout": 120.0, "id": None,
 "parameters_rows": rows, "risk_level": risk, "impact_area": impact,
 "requires_auth": req_auth, "risk_description": "Auto-imported from cURL.",
 }

def bootstrap_for_selection(sel: str, all_tools: list[dict], custom_bootstrap: dict | None = None) -> dict[str, Any]:
 if custom_bootstrap: return custom_bootstrap
 if sel == NEW_TOOL_LABEL:
 return {
 "name": "", "description": "", "endpoint": "", "method": "GET", "timeout": 120.0, "id": None,
 "parameters_rows": [], "risk_level": "low", "impact_area": "read", "requires_auth": False, "risk_description": "",
 }
 loaded = next((t for t in all_tools if t.get("name") == sel), None)
 if loaded is None: return bootstrap_for_selection(NEW_TOOL_LABEL, all_tools)
 api, meta = loaded.get("config", {}), loaded.get("metadata", {})
 rows = [{"name": n, "type": i.get("type", "string"), "description": i.get("description", ""), "default": i.get("default", "")} 
 for n, i in (loaded.get("parameters") or {}).items() if isinstance(i, dict)]
 return {
 "name": loaded.get("name", ""), "description": loaded.get("description", ""),
 "endpoint": api.get("endpoint", ""), "method": api.get("method", "GET"),
 "timeout": float(api.get("timeout", 120)), "id": loaded.get("id"), "parameters_rows": rows,
 "risk_level": meta.get("risk_level", "low"), "impact_area": meta.get("impact_area", "read"),
 "requires_auth": meta.get("requires_auth", False), "risk_description": meta.get("risk_description", ""),
 }

def parameters_dict_from_rows(rows: list[dict]) -> dict[str, Any]:
 parameters = {}
 for p in rows:
 name = (p.get("name") or "").strip()
 if not name: continue
 entry = {"type": p["type"], "description": p.get("description", "")}
 dv = p.get("default", "")
 if dv not in (None, ""):
 if p["type"] == "number":
 try: entry["default"] = float(dv)
 except: entry["default"] = 0.0
 elif p["type"] == "boolean":
 entry["default"] = str(dv).lower() in ("true", "1", "yes")
 elif p["type"] in ("array", "json"):
 try:
 parsed = json.loads(str(dv).strip())
 entry["default"] = parsed if (p["type"] == "array" and isinstance(parsed, list)) or (p["type"] == "json" and isinstance(parsed, dict)) else parsed
 except:
 entry["default"] = [x.strip() for x in str(dv).split(",") if x.strip()] if p["type"] == "array" else {}
 else: entry["default"] = dv
 parameters[name] = entry
 return parameters

def build_cfg(**kwargs) -> dict[str, Any]:
 name = kwargs.get("name", "")
 cfg_id = kwargs.get("existing_id") or f"tool_{name.strip() or 'unnamed'}"
 return {
 "id": cfg_id, "status": kwargs.get("status"), "name": name.strip(), "description": kwargs.get("description"),
 "metadata": {
 "risk_level": kwargs.get("risk_level"), "impact_area": kwargs.get("impact_area"),
 "requires_auth": kwargs.get("requires_auth"), "risk_description": kwargs.get("risk_description")
 },
 "config": {"endpoint": kwargs.get("endpoint", "").strip(), "method": kwargs.get("method"), "timeout": kwargs.get("timeout")},
 "parameters": kwargs.get("parameters"),
 }

def cfg_fingerprint(cfg: dict[str, Any]) -> str:
 c = json.loads(json.dumps(cfg, default=str))
 c.pop("status", None)
 return hashlib.sha256(json.dumps(c, sort_keys=True, default=str).encode("utf-8")).hexdigest()

def mcp_call_looks_successful(res: Any) -> bool:
 if res is None: return False
 if isinstance(res, list) and len(res) > 0:
 text = str(getattr(res[0], "text", "")).strip()
 try:
 data = json.loads(text)
 if isinstance(data, dict) and data.get("error"): return False
 except: pass
 return True

def remove_param_at(index: int) -> None:
 rows = st.session_state.get(SESSION_PARAMS, [])
 if 0 <= index < len(rows):
 rows.pop(index)
 st.session_state[SESSION_PARAMS] = rows

# --- Sidebar: Tool Library ---
st.sidebar.header("Tool library")
all_tools = get_all_tool_configs()
if not all_tools:
 st.sidebar.info("No tools found.")
else:
 for status, icon in [("published", "🟢"), ("draft", "🟡")]:
 st.sidebar.subheader(status.title())
 matches = [t for t in all_tools if t.get("status") == status]
 if not matches: st.sidebar.caption("None")
 for t in matches: st.sidebar.write(f"{icon} {t.get('name', '?')}")

# --- Main Logic ---

load_choice = st.selectbox(
 "1. Create new or open existing tool",
 [NEW_TOOL_LABEL] + [t.get("name", "") for t in all_tools if t.get("name")],
 key="studio_tool_choice_widget",
)

if SESSION_PREV_SEL not in st.session_state: st.session_state[SESSION_PREV_SEL] = load_choice
if SESSION_FORM_GEN not in st.session_state: st.session_state[SESSION_FORM_GEN] = 0

if st.session_state[SESSION_PREV_SEL] != load_choice:
 st.session_state[SESSION_FORM_GEN] += 1
 st.session_state[SESSION_BOOTSTRAP] = bootstrap_for_selection(load_choice, all_tools)
 st.session_state[SESSION_PARAMS] = list(st.session_state[SESSION_BOOTSTRAP].get("parameters_rows", []))
 st.session_state[SESSION_VERIFIED_FP] = None
 st.session_state[SESSION_PREV_SEL] = load_choice

if SESSION_BOOTSTRAP not in st.session_state:
 st.session_state[SESSION_BOOTSTRAP] = bootstrap_for_selection(load_choice, all_tools)
 st.session_state[SESSION_PARAMS] = list(st.session_state[SESSION_BOOTSTRAP].get("parameters_rows", []))

bootstrap = st.session_state[SESSION_BOOTSTRAP]
gen = st.session_state[SESSION_FORM_GEN]

with st.expander("2. Tool definition — name, endpoint, method, parameters", expanded=False):
 # --- Minimal cURL Importer inside definition ---
 with st.expander("✨ Quick Fill: Import from cURL", expanded=False):
 c_input = st.text_area("Paste cURL command", placeholder="curl -X POST...", height=60, key=f"curl_in_{gen}")
 if st.button("Parse & Auto-fill", key=f"curl_btn_{gen}"):
 imp = parse_curl_command(c_input)
 if imp:
 st.session_state[SESSION_FORM_GEN] += 1
 st.session_state[SESSION_BOOTSTRAP] = bootstrap_for_selection(NEW_TOOL_LABEL, all_tools, custom_bootstrap=imp)
 st.session_state[SESSION_PARAMS] = list(imp.get("parameters_rows", []))
 st.session_state[SESSION_PREV_SEL] = NEW_TOOL_LABEL
 st.rerun()

 col_a, col_b = st.columns(2)
 with col_a:
 name = st.text_input("Tool name", value=bootstrap["name"], key=f"fld_name_{gen}")
 method = st.selectbox("HTTP method", ["GET", "POST", "PUT", "PATCH", "DELETE"], 
 index=["GET", "POST", "PUT", "PATCH", "DELETE"].index(bootstrap["method"]) if bootstrap["method"] in ["GET", "POST", "PUT", "PATCH", "DELETE"] else 0,
 key=f"fld_method_{gen}")
 with col_b:
 endpoint = st.text_input("Endpoint URL", value=bootstrap["endpoint"], key=f"fld_endpoint_{gen}")
 description = st.text_input("Description", value=bootstrap["description"], key=f"fld_desc_{gen}")

 timeout = st.number_input("Timeout (s)", min_value=1.0, value=float(bootstrap["timeout"]), key=f"fld_timeout_{gen}")

 # Governance
 st.markdown("---")
 st.caption("Governance & Security")
 c1, c2, c3 = st.columns(3)
 risk_level = c1.selectbox("Risk", ["low", "medium", "high"], index=["low", "medium", "high"].index(bootstrap["risk_level"]), key=f"fld_risk_{gen}")
 impact_area = c2.selectbox("Impact", ["read", "write", "delete", "execute"], index=["read", "write", "delete", "execute"].index(bootstrap["impact_area"]), key=f"fld_impact_{gen}")
 requires_auth = c3.checkbox("Auth Required", value=bootstrap["requires_auth"], key=f"fld_auth_{gen}")
 risk_description = st.text_area("Risk Notes", value=bootstrap["risk_description"], key=f"fld_risk_desc_{gen}", height=60)

 # Parameters
 st.markdown("---")
 st.markdown("**Parameters**")
 params_rows = st.session_state[SESSION_PARAMS]
 for i, p in enumerate(params_rows):
 with st.expander(f"Param: {p.get('name') or 'unnamed'}", expanded=False):
 h1, h2, h3 = st.columns([2, 2, 1])
 p["name"] = h1.text_input("Name", value=p.get("name", ""), key=f"pname_{gen}_{i}")
 p["type"] = h2.selectbox("Type", PARAM_TYPES, index=PARAM_TYPES.index(p["type"]) if p["type"] in PARAM_TYPES else 0, key=f"ptype_{gen}_{i}")
 if h3.button("🗑️", key=f"pdel_{gen}_{i}"): 
 remove_param_at(i)
 st.rerun()
 p["description"] = st.text_input("Description", value=p.get("description", ""), key=f"pdesc_{gen}_{i}")

 if p["type"] in ("array", "json"):
 dv_raw = p.get("default", "")
 p["default"] = st.text_area("Default (JSON)", value=json.dumps(dv_raw) if isinstance(dv_raw, (list, dict)) else str(dv_raw), key=f"pdef_{gen}_{i}", height=60)
 else:
 p["default"] = st.text_input("Default", value=str(p.get("default", "")), key=f"pdef_{gen}_{i}")

 if st.button("➕ Add Parameter"):
 st.session_state[SESSION_PARAMS].append({"name": "", "type": "string", "description": "", "default": ""})
 st.rerun()

# --- Section 3 & 4: Testing & Saving ---
params = parameters_dict_from_rows(st.session_state.get(SESSION_PARAMS, []))
cfg_idnt = build_cfg(name=name, description=description, endpoint=endpoint, method=method, timeout=timeout, 
 parameters=params, status="draft", existing_id=bootstrap.get("id") if load_choice != NEW_TOOL_LABEL else None,
 risk_level=risk_level, impact_area=impact_area, requires_auth=requires_auth, risk_description=risk_description)
fp_curr = cfg_fingerprint(cfg_idnt)

mcp = None
try:
 from mcp_server_refactored import mcp as _mcp
 mcp = _mcp
