@font-face {
 font-family: 'Insignia';
 src: url('assets/Insignia LT W04 Regular.ttf') format('truetype');
 font-weight: normal;
 font-style: normal;
}

:root {
 --amber: #FFBF00;
 --charcoal: #36454F;
 --teal: #008080;
 --aqua: #00A9A9;
 --ivory: #FFF8E7;
 --graphite: #1C1C1C;
 --gold: #FFD700;
 --font-heading: 'JetBrains Mono', monospace;
 --font-subheading: 'IBM Plex Mono', monospace;
 --font-body: 'Recursive', monospace;
 --font-note: 'Fira Code', monospace;
 --font-menu: 'Space Mono', monospace;
 --font-logo: 'Insignia', serif;
}

body {
 background-color: var(--ivory);
 color: var(--charcoal);
 font-family: var(--font-body);
 padding-top: 70px;
 cursor: none;
}

a,
button,
.service-card {
 cursor: none;
}

.cursor-dot {
 width: 8px;
 height: 8px;
 background-color: var(--teal);
 position: fixed;
 top: 50%;
 left: 50%;
 transform: translate(-50%, -50%);
 border-radius: 50%;
 pointer-events: none;
 z-index: 9999;
 transition: transform 0.1s ease-out;
}

.cursor-circle {
 width: 40px;
 height: 40px;
 border: 2px solid var(--teal);
 position: fixed;
 top: 50%;
 left: 50%;
 transform: translate(-50%, -50%);
 border-radius: 50%;
 pointer-events: none;
 z-index: 9999;
 transition: transform 0.2s ease-out, width 0.3s, height 0.3s, opacity 0.3s;
}

.cursor-grow {
 transform: translate(-50%, -50%) scale(1.5);
 opacity: 0.5;
}

.fade-in-section,
.fade-in-card {
 opacity: 0;
 transform: translateY(30px);
 transition: opacity 0.6s ease-out, transform 0.6s ease-out;
}

.fade-in-section.visible,
.fade-in-card.visible {
 opacity: 1;
 transform: translateY(0);
}

.service-card.fade-in-card {
 transition-delay: calc(var(--card-index) * 100ms);
}

h1,
h2,
h3,
h4,
h5,
h6 {
 font-family: var(--font-heading);
 font-weight: 700;
 color: var(--charcoal);
}

.section-heading {
 font-family: var(--font-heading);
}

.section-subheading {
 font-family: var(--font-subheading);
 font-size: 1.1rem;
 line-height: 1.6;
}

.navbar {
 background-color: rgba(255, 248, 231, 0.85);
 backdrop-filter: blur(10px);
 border-bottom: 1px solid rgba(0, 0, 0, 0.1);
}

.navbar .nav-link {
 font-family: var(--font-menu);
 color: var(--charcoal);
 transition: color 0.3s;
}

.navbar .nav-link:hover {
 color: var(--teal);
}

.hero-section {
 background-color: var(--amber);
 height: 90vh;
 display: flex;
 align-items: center;
 justify-content: center;
 padding: 2rem;
}

.hero-logo {
 max-width: 150px;
}

.logo-text {
 font-family: var(--font-logo);
 font-size: 2.5rem;
 font-weight: normal;
 color: var(--charcoal);
 line-height: 0.85;
 text-decoration: none;
 display: flex;
 flex-direction: column;
}

.logo-text span {
 display: block;
 visibility: hidden;
}

.logo-text:hover {
 color: var(--charcoal);
 text-decoration: none;
}

.navbar .logo-text {
 font-size: 1.8rem;
}

.hero-logo-text {
 font-family: var(--font-logo);
 font-size: 4rem;
 font-weight: normal;
 color: var(--graphite);
 line-height: 1;
 margin-bottom: 1rem;
}

.hero-section .tagline {
 font-size: 3rem;
 color: var(--graphite);
}

.hero-section .elevator-pitch {
 font-family: var(--font-subheading);
 color: var(--charcoal);
 max-width: 600px;
 margin: 1rem auto 2rem;
}

.about-points {
 margin-top: 2rem;
}

