}

/* === Timeline Section === */
.timeline-section {
 background: linear-gradient(90deg, #50727B 0%, #78A083 100%);
 padding: 6rem 0;
}
.timeline {
 position: relative;
 max-width: 1200px;
 margin: 0 auto;
}
.timeline::after {
 content: '';
 position: absolute;
 width: 6px;
 background-color: var(--secondary-color);
 top: 0;
 bottom: 0;
 left: 50%;
 margin-left: -3px;
}
.timeline-item {
 padding: 10px 40px;
 position: relative;
 background-color: inherit;
 width: 50%;
}
.timeline-item.left {
 left: 0;
}
.timeline-item.right {
 left: 50%;
}
.timeline-icon {
