def _normalize_mcp_urls(configured_url: str) -> Dict[str, str]:
 """
 Normalize various MCP URL forms to consistent endpoints.
 Returns a dict with:
 - server_root: base app root (e.g., http://host:8001)
 - mcp_base: MCP base path (e.g., http://host:8001/mcp)
 - sse_url: full SSE endpoint (e.g., http://host:8001/mcp/sse)
 """
 url = configured_url.strip()
 # Remove trailing /sse if provided directly
 if url.endswith('/sse'):
 url = url[:-4]
 # Ensure mcp base suffix
 if not url.rstrip('/').endswith('/mcp'):
 url = url.rstrip('/') + '/mcp'
 # Compute roots
 server_root = url.rsplit('/mcp', 1)[0]
 sse_url = server_root.rstrip('/') + '/mcp/sse'
 return {
 "server_root": server_root,
 "mcp_base": url,
 "sse_url": sse_url,
 }

def _cache_key(name: str, payload: Dict[str, Any]) -> str:
 try:
 return f"{name}:{json.dumps(payload, sort_keys=True)}"
 except Exception:
 return f"{name}:{str(payload)}"

def get_agent_memory(agent_id: str, session_id: str, max_history: int = 10) -> ChatMemory:
 """
 Get or create a memory store for an agent and session.

 Args:
 agent_id (str): ID of the agent
 session_id (str): ID of the user session
 max_history (int): Maximum number of messages to keep in history

 Returns:
 ChatMemory: The agent's memory store for this session
 """
 if agent_id not in agent_memories:
 agent_memories[agent_id] = {}

 if session_id not in agent_memories[agent_id]:
 agent_memories[agent_id][session_id] = ChatMemory(max_history=max_history)

 return agent_memories[agent_id][session_id]

def log_agent_step(agent_output, db: Session, transaction_id: uuid.UUID, agent_id: uuid.UUID, tool_usage: List[Dict], session_id: str=None):
 """
 Callback function to log agent-tool interactions to the database using ToolExecutionLog.
 Called after each step of an agent.

 :param agent_output: The output from the agent's step
 :param db: SQLAlchemy database session
 :param transaction_id: UUID of the current transaction
 :param agent_id: UUID of the agent
 :param tool_usage: List of dictionaries to track tool usage information
 """

 try:
 # Check if the step involved a tool call
 if hasattr(agent_output, 'tool'):
 tool_name = agent_output.tool
 tool_input = agent_output.tool_input
 tool_output = agent_output.result

 # Get tool_id from the database
 tool = db.query(Tool).filter(Tool.name == tool_name).first()
 if not tool:
 logger.warning(f"Tool {tool_name} not found in database")
 return

 # Create tool execution log entry
 tool_log = ToolExecutionLog(
 transaction_id=transaction_id,
 agent_id=agent_id,
 tool_id=tool.id,
 start_time=datetime.now(),
 end_time=datetime.now(),
 duration_ms=0,
 input_data=tool_input,
 output_data=json.dumps(str(tool_output)),
 error_message=None
 )

 db.add(tool_log)
 db.commit()
 logger.info(f"Logged tool interaction: Agent used tool '{tool_name}'")

 # Add tool usage information to the list
 tool_usage.append({
 "tool_id": str(tool.id),
 "tool_name": tool_name,
 "start_time": tool_log.start_time,
 "end_time": tool_log.end_time,
 "duration_ms": tool_log.duration_ms,
 "input": tool_input,
 "output": str(tool_output)
 })

 elif hasattr(agent_output, 'is_error') and agent_output.is_error:
 # Log error case
 tool_log = ToolExecutionLog(
 transaction_id=transaction_id,
 agent_id=agent_id,
 start_time=datetime.now(),
 end_time=datetime.now(),
 duration_ms=0,
 input_data=json.dumps({"error": True}),
 output_data=None,
 error_message=str(agent_output.error)
 )

 db.add(tool_log)
 db.commit()
 logger.error(f"Logged error in agent step: {str(agent_output.error)}")

 except Exception as e:
 logger.error(f"Error logging to database: {e}")
 logger.exception("Full traceback:")
 db.rollback()

def _initialize_llm(config: Dict[str, Any]) -> ChatOpenAI:
 """
 Initialize the appropriate LLM based on configuration.

 :param config: Dictionary containing LLM configuration
 :return: Initialized ChatOpenAI instance
 """
 llms_config = config.get('llms', {})
 logger.info(f"Initializing LLM with config: {llms_config}")

 # Check for OpenAI configuration
 if 'openai' in llms_config:
 api_key = llms_config['openai'].get('api_key')
 if not api_key:
 api_key = os.getenv("OPENAI_API_KEY")
 if not api_key:
 raise ValueError("OpenAI API key not found in config or environment variables")
 os.environ["OPENAI_API_KEY"] = api_key
 return ChatOpenAI(
 api_key=api_key,
 model_name=llms_config['openai'].get('model', 'gpt-4'),
 temperature=llms_config['openai'].get('temperature', 0.7),
 max_tokens=llms_config['openai'].get('max_tokens', 2000)
 )

 # Check for DeepSeek configuration
 elif 'deepseek' in llms_config:
 DEEPSEEK_URL = os.getenv("DEEPSEEK_URL")
 llm = CustomLLM(
 model=f"deepseek/{llms_config['deepseek'].get('model', 'default')}", # deepseek/default
 base_url=llms_config['deepseek'].get('endpoint', DEEPSEEK_URL),
 api_key=llms_config['deepseek'].get('api_key', "EMPTY"),
 temperature=llms_config['deepseek'].get('temperature', 0.3),
 max_tokens=llms_config['deepseek'].get('max_tokens', 1024)
 )
 print("Deepseek LLM", llm)
 return llm

 elif 'qwen' in llms_config:
 QWEN_URL = os.getenv("QWEN_URL")
 llm = CustomLLM(
 name="qwen",
 model=f"openai/Qwen/{llms_config['qwen'].get('model', 'Qwen3-32B')}", # huggingface/qwen/qwen3-32b
 base_url=llms_config['qwen'].get('endpoint', QWEN_URL),
 api_key=llms_config['qwen'].get('api_key', "None"),
 temperature=llms_config['qwen'].get('temperature', 0.3),
 max_tokens=llms_config['qwen'].get('max_tokens', 1024)
 )
 return llm

 # Check for Ollama configuration
 elif 'ollama' in llms_config:
 return ChatOpenAI(
 api_key='EMPTY',
 model_name=llms_config['ollama'].get('model', 'llama2'),
 temperature=llms_config['ollama'].get('temperature', 0.7),
 base_url='http://localhost:11434/v1'
 )

 # Check for Local configuration
 elif 'local' in llms_config:
 endpoint = llms_config['local'].get('endpoint')
 if not endpoint:
 raise ValueError("Local endpoint is required in config")

 return ChatOpenAI(
 api_key='EMPTY',
 model_name=llms_config['local'].get('model', 'local-model'),
 temperature=llms_config['local'].get('temperature', 0.7),
 base_url=endpoint
 )

 else:
 raise ValueError("No valid LLM configuration found in config")

