 )

 # Create and run crew with step callback
 crew = Crew(
 agents=[agent],
 tasks=[task],
 verbose=True,
 step_callback=lambda x: log_agent_step(x, db, transaction_id, uuid.UUID(agent_id), tool_usage, session_id),
 memory=False,
 cache=False
 )
 # crew.reset_memories('all')
 # Execute the crew workflow
 logger.info("Starting Crew workflow...")
 result = crew.kickoff()
 logger.info("Crew workflow finished")

 # Prefer last tool output if available; fall back to model text result
 result_text = str(result)
 tool_execution_log = db.query(ToolExecutionLog).filter(
 ToolExecutionLog.transaction_id == transaction_id,
 ToolExecutionLog.agent_id == uuid.UUID(agent_id)
 ).order_by(ToolExecutionLog.id.desc()).first()
 if tool_execution_log and tool_execution_log.output_data:
 result_text = str(tool_execution_log.output_data)

 # Add agent response to memory
 memory.add_message('assistant', result_text)

 create_interaction(db, {
 "session_id": session_id,
 "sender": "user",
 "message": query,
 "timestamp": datetime.now(),
 "agent_id": uuid.UUID(agent_id),
 "message_metadata": {}
 })

 create_interaction(db, {
 "session_id": session_id,
 "sender": "assistant",
 "message": result_text,
 "timestamp": datetime.now(),
 "agent_id": uuid.UUID(agent_id),
 "message_metadata": {}
 })

 # If we had a tool output, also log it as a separate interaction for transparency
 if tool_execution_log and tool_execution_log.output_data:
 logger.info(f"Creating interaction for tool output : {agent_db.name}")
 create_interaction(db, {
 "session_id": session_id,
 "sender": "assistant",
 "message": str(tool_execution_log.output_data),
 "timestamp": datetime.now(),
 "agent_id": uuid.UUID(agent_id),
 "message_metadata": {}
 })
 memory.add_message('assistant', str(tool_execution_log.output_data))

 end_time = datetime.now()
 duration_ms = int((end_time - start_time).total_seconds() * 1000)

 # Update LLM usage with end time
 llm_usage["end_time"] = end_time
 llm_usage["duration_ms"] = duration_ms

 # Convert datetime objects to ISO format strings
 llm_usage = {k: _serialize_datetime(v) for k, v in llm_usage.items()}

 # Serialize datetime objects in tool_usage
 serialized_tool_usage = []
 for tool in tool_usage:
 serialized_tool = {
 "tool_id": tool["tool_id"],
 "tool_name": tool["tool_name"],
 "start_time": _serialize_datetime(tool["start_time"]),
 "end_time": _serialize_datetime(tool["end_time"]),
 "duration_ms": tool["duration_ms"],
 "input": tool["input"],
 "output": tool["output"]
 }
 serialized_tool_usage.append(serialized_tool)

 # Create LLM usage log
 create_llm_usage_log(db, {
 "transaction_id": transaction_id,
 "agent_id": uuid.UUID(agent_id),
 "start_time": llm_usage.get("start_time"),
 "end_time": llm_usage.get("end_time"),
 "duration_ms": llm_usage.get("duration_ms"),
 "model_name": llm_usage.get("model_name"),
 "model_provider": llm_usage.get("model_provider"), # Use the one already set
 "temperature": llm_usage.get("temperature"),
 "max_tokens": llm_usage.get("max_tokens"),
 "total_tokens_used": llm_usage.get("total_tokens", 0),
 "response_latency_ms": llm_usage.get("latency_ms", 0),
 "input_data": {"query": query},
 "output_data": {"result": str(result)}
 })

 # Return result with usage information and chat history
 return {
 "result": result_text,
 "tool_usage": serialized_tool_usage,
 "llm_usage": llm_usage,
 "total_duration_ms": duration_ms,
 "total_tools_used": len(serialized_tool_usage),
 "chat_history": memory.get_history()
 }

 except Exception as e:
 logger.error(f"Error running crew agent: {str(e)}")
 raise
 finally:
 # Cleanup MCP clients
 if mcp_server_adapter:
 mcp_server_adapter.stop()
 logger.info("MCP server adapter stopped.")
 if general_mcp_client:
 general_mcp_client.stop() # Assuming .stop() is available or performing cleanup
 logger.info("General MCP client stopped and cleaned up.")
 except Exception as e:
 logger.error(f"Error in get_and_run_crew_agent: {str(e)}")
 raise

