@st.cache_data(ttl=600)
def get_distinct_agents(_client, start_time=None, end_time=None):
 try:
 base_query = "SELECT DISTINCT SpanAttributes['gen_ai.agent.name'] as agent FROM otel_traces WHERE mapContains(SpanAttributes, 'gen_ai.agent.name')"
 where_clauses = []
 if start_time:
 where_clauses.append(f"Timestamp >= '{start_time.strftime('%Y-%m-%d %H:%M:%S')}'")
 if end_time:
 where_clauses.append(f"Timestamp <= '{end_time.strftime('%Y-%m-%d %H:%M:%S')}'")
 if where_clauses:
 base_query += " AND " + " AND ".join(where_clauses)
 base_query += " ORDER BY agent ASC"
 df = _client.query_df(base_query)
 agents = [a for a in df['agent'].dropna().unique().tolist() if isinstance(a, str) and a.strip()]
 return agents
 except Exception as e:
 st.warning(f"Could not fetch agents: {e}")
 return []

def get_distinct_trace_ids(_client, start_time=None, end_time=None, agent_name=None):
 try:
 base_query = "SELECT TraceId FROM otel_traces"
 where_clauses = []
 if start_time:
 where_clauses.append(f"Timestamp >= '{start_time.strftime('%Y-%m-%d %H:%M:%S')}'")
 if end_time:
 where_clauses.append(f"Timestamp <= '{end_time.strftime('%Y-%m-%d %H:%M:%S')}'")
 if agent_name:
 escaped = escape_single_quotes(agent_name)
 where_clauses.append("mapContains(SpanAttributes, 'gen_ai.agent.name')")
 where_clauses.append(f"SpanAttributes['gen_ai.agent.name'] = '{escaped}'")
 if where_clauses:
 base_query += " WHERE " + " AND ".join(where_clauses)
 query = base_query + " GROUP BY TraceId ORDER BY max(Timestamp) DESC"
 result = _client.query(query)
 return [row[0] for row in result.result_rows]
 except Exception as e:
 st.error(f"Error fetching Trace IDs: {e}")
 return []

def search_traces_by_text(_client, search_term, start_time=None, end_time=None, agent_name=None):
 if not search_term:
 return []
 try:
 search_clause = f"""
 (
 (mapContains(SpanAttributes, 'gen_ai.prompt') AND SpanAttributes['gen_ai.prompt'] LIKE '%{search_term}%') OR
 (mapContains(SpanAttributes, 'gen_ai.completion') AND SpanAttributes['gen_ai.completion'] LIKE '%{search_term}%')
 )
 """
 where_clauses = [search_clause]
 if start_time:
 where_clauses.append(f"Timestamp >= '{start_time.strftime('%Y-%m-%d %H:%M:%S')}'")
 if end_time:
 where_clauses.append(f"Timestamp <= '{end_time.strftime('%Y-%m-%d %H:%M:%S')}'")
 if agent_name:
 escaped = escape_single_quotes(agent_name)
 where_clauses.append("mapContains(SpanAttributes, 'gen_ai.agent.name')")
 where_clauses.append(f"SpanAttributes['gen_ai.agent.name'] = '{escaped}'")

 query = "SELECT TraceId, SpanAttributes['gen_ai.prompt'] as prompt FROM otel_traces WHERE "
 query += " AND ".join(where_clauses)
 query += " GROUP BY TraceId, prompt ORDER BY max(Timestamp) DESC"

 candidate_traces = _client.query_df(query)
 final_trace_ids = []
 for _, row in candidate_traces.iterrows():
 trace_id = row['TraceId']
 prompt = row['prompt']
 if prompt and isinstance(prompt, str):
 match = re.search(r"Current Task:\s*(.*?)(?:\n\nThis is the expected criteria|Final Answer:|$)", prompt, re.DOTALL)
 if not match:
 match = re.search(r"Current Task:\s*(.*)", prompt, re.DOTALL)
 if match:
 current_task_text = match.group(1)
 if search_term.lower() in current_task_text.lower():
 if trace_id not in final_trace_ids:
 final_trace_ids.append(trace_id)
 return final_trace_ids
 except Exception as e:
 st.error(f"Error during text search: {e}")
 return []

@st.cache_data(ttl=600)
def get_trace_summaries(_client, trace_ids):
 if not trace_ids:
 return {}
 summaries = {trace_id: "No summary available" for trace_id in trace_ids}
 try:
 trace_ids_str = ", ".join([f"'{tid}'" for tid in trace_ids])
 query = f"""
 SELECT TraceId, SpanAttributes['gen_ai.prompt'] as prompt, SpanAttributes['gen_ai.completion'] as completion
 FROM otel_traces
 WHERE TraceId IN ({trace_ids_str})
 AND (mapContains(SpanAttributes, 'gen_ai.prompt') OR mapContains(SpanAttributes, 'gen_ai.completion'))
 ORDER BY Timestamp ASC
 """
 result = _client.query_df(query)
 if result.empty:
 return summaries
 trace_data = {}
 for _, row in result.iterrows():
 tid = row['TraceId']
 if tid not in trace_data:
 trace_data[tid] = {'input': None, 'output': None}
 if row['prompt'] and not trace_data[tid]['input']:
 match = re.search(r"Current Task:\s*(.*?)(?:\n\nThis is the expected criteria|Final Answer:)", row['prompt'], re.DOTALL)
 if match:
 trace_data[tid]['input'] = match.group(1).strip()
 else:
 match = re.search(r"Current Task:\s*(.*)", row['prompt'], re.DOTALL)
 if match:
 trace_data[tid]['input'] = match.group(1).strip()
 if row['completion']:
 parsed = parse_llm_completion(row['completion'])
 if parsed.get('final_answer'):
 trace_data[tid]['output'] = parsed.get('final_answer')
 for tid, data in trace_data.items():
 summary_text = ""
 if data['input']:
 summary_text = f"Input: {data['input']}"
 elif data['output']:
 summary_text = f"Output: {data['output'][:70]}..."
 if summary_text:
 summaries[tid] = summary_text.replace("\n", " ")
 return summaries
 except Exception as e:
 st.warning(f"Could not fetch summaries: {e}")
 return summaries

@st.cache_data
def get_table_schema(_client, table_name):
