 start_time_local = datetime.combine(from_date, from_time)
 end_time_local = datetime.combine(to_date, to_time)
 start_time_utc = start_time_local - ist_offset
 end_time_utc = end_time_local - ist_offset
 elif filter_options.get(selected_filter) is not None:
 start_time_utc = now_utc - filter_options[selected_filter]
 end_time_utc = now_utc

 return start_time_utc, end_time_utc

def display_agent_filter(client, start_time_utc, end_time_utc):
 agents = get_distinct_agents(client, start_time_utc, end_time_utc)
 agent_options = ["All Agents"] + sorted(agents)
 selected_agent = st.selectbox("Select an agent:", options=agent_options, index=0)
 return None if selected_agent == "All Agents" else selected_agent

