import streamlit as st
import pandas as pd
import re
from utils import _escape_single_quotes

def get_distinct_trace_ids(_client, start_time=None, end_time=None, agent_name=None):
 try:
 base_query = "SELECT TraceId FROM otel_traces"
 where_clauses = []
 if start_time:
 where_clauses.append(f"Timestamp >= '{start_time.strftime('%Y-%m-%d %H:%M:%S')}'")
 if end_time:
 where_clauses.append(f"Timestamp <= '{end_time.strftime('%Y-%m-%d %H:%M:%S')}'")
 if agent_name:
 escaped = _escape_single_quotes(agent_name)
 where_clauses.append("mapContains(SpanAttributes, 'gen_ai.agent.name')")
 where_clauses.append(f"SpanAttributes['gen_ai.agent.name'] = '{escaped}'")
 if where_clauses:
 base_query += " WHERE " + " AND ".join(where_clauses)
 query = base_query + " GROUP BY TraceId ORDER BY max(Timestamp) DESC"
 result = _client.query(query)
 return [row[0] for row in result.result_rows]
 except Exception as e:
 st.error(f"Error fetching Trace IDs: {e}")
 return []

def search_traces_by_text(_client, search_term, start_time=None, end_time=None, agent_name=None):
 if not search_term:
 return []
 try:
 search_clause = f"((mapContains(SpanAttributes, 'gen_ai.prompt') AND SpanAttributes['gen_ai.prompt'] LIKE '%{search_term}%') OR (mapContains(SpanAttributes, 'gen_ai.completion') AND SpanAttributes['gen_ai.completion'] LIKE '%{search_term}%'))"
 where_clauses = [search_clause]
 if start_time:
 where_clauses.append(f"Timestamp >= '{start_time.strftime('%Y-%m-%d %H:%M:%S')}'")
 if end_time:
 where_clauses.append(f"Timestamp <= '{end_time.strftime('%Y-%m-%d %H:%M:%S')}'")
 if agent_name:
 escaped = _escape_single_quotes(agent_name)
 where_clauses.append("mapContains(SpanAttributes, 'gen_ai.agent.name')")
 where_clauses.append(f"SpanAttributes['gen_ai.agent.name'] = '{escaped}'")

 query = "SELECT TraceId, SpanAttributes['gen_ai.prompt'] as prompt FROM otel_traces WHERE " + " AND ".join(where_clauses) + " GROUP BY TraceId, prompt ORDER BY max(Timestamp) DESC"
 candidate_traces = _client.query_df(query)

 final_trace_ids = []
 for _, row in candidate_traces.iterrows():
 trace_id, prompt = row['TraceId'], row['prompt']
 if prompt and isinstance(prompt, str):
 match = re.search(r"Current Task:\s*(.*?)(?:\n\nThis is the expected criteria|Final Answer:|$)", prompt, re.DOTALL) or re.search(r"Current Task:\s*(.*)", prompt, re.DOTALL)
 if match and search_term.lower() in match.group(1).lower() and trace_id not in final_trace_ids:
 final_trace_ids.append(trace_id)
 return final_trace_ids
 except Exception as e:
 st.error(f"Error during text search: {e}")
 return []

@st.cache_data(ttl=600)
def get_trace_summaries(_client, trace_ids):
 if not trace_ids: return {}
 summaries = {trace_id: "No summary available" for trace_id in trace_ids}
 try:
 trace_ids_str = ", ".join([f"'{tid}'" for tid in trace_ids])
 query = f"SELECT TraceId, SpanAttributes['gen_ai.prompt'] as prompt, SpanAttributes['gen_ai.completion'] as completion FROM otel_traces WHERE TraceId IN ({trace_ids_str}) AND (mapContains(SpanAttributes, 'gen_ai.prompt') OR mapContains(SpanAttributes, 'gen_ai.completion')) ORDER BY Timestamp ASC"
 result = _client.query_df(query)
 if result.empty: return summaries
 trace_data = {}
 for _, row in result.iterrows():
 tid = row['TraceId']
 if tid not in trace_data: trace_data[tid] = {'input': None, 'output': None}
 if row['prompt'] and not trace_data[tid]['input']:
 match = re.search(r"Current Task:\s*(.*?)(?:\n\nThis is the expected criteria|Final Answer:|$)", row['prompt'], re.DOTALL) or re.search(r"Current Task:\s*(.*)", row['prompt'], re.DOTALL)
 if match: trace_data[tid]['input'] = match.group(1).strip()
 if row['completion']:
 parsed = parse_llm_completion(row['completion'])
 if parsed.get('final_answer'): trace_data[tid]['output'] = parsed.get('final_answer')
 for tid, data in trace_data.items():
 summary_text = f"Input: {data['input']}" if data['input'] else (f"Output: {data['output'][:70]}..." if data['output'] else "")
 if summary_text: summaries[tid] = summary_text.replace("\n", " ")
 return summaries
 except Exception as e:
 st.warning(f"Could not fetch summaries: {e}")
 return summaries

def get_trace_details(_client, trace_id):
 try:
 query = f"SELECT TraceId, SpanId, ParentSpanId, SpanName, SpanKind, Duration, Timestamp, SpanAttributes FROM otel_traces WHERE TraceId = '{trace_id}' ORDER BY Timestamp ASC"
 return _client.query(query).result_rows
 except Exception as e:
 st.error(f"An error occurred while querying data: {e}")
 return []

def parse_llm_completion(text):
 if not isinstance(text, str): return {}
 patterns = {
 'thought': r"Thought:(.*?)(?:\nAction:|\nFinal Answer:|$)",
 'action': r"Action:(.*?)(?:\nAction Input:|$)",
 'action_input': r"Action Input:(.*?)(?:\nObservation:|$)",
 'final_answer': r"Final Answer:(.*)"
 }
 data = {key: (match.group(1).strip() if (match := re.search(pattern, text, re.DOTALL)) else None) for key, pattern in patterns.items()}
 if not any(data.values()) and text:
 if (match := re.search(r"Thought:(.*?)(\nFinal Answer:)", text, re.DOTALL)): data['thought'] = match.group(1).strip()
 elif "Final Answer:" not in text and "Action:" not in text: data['final_answer'] = text.strip()
 return {k: v for k, v in data.items() if v is not None}

def display_span_recursively(span, span_tree):
 expander_label = f"{span['SpanName']} | ⏱️ {span['Duration'] / 1_000_000:.2f} ms"
 is_expanded = st.session_state.get('expand_all', False)
 with st.expander(expander_label, expanded=is_expanded):
 attrs = span.get('SpanAttributes', {})
 if span['SpanName'] == "invoke_agent crew":
 st.markdown(f"##### 🚀 Transaction Start\n**Total Duration:** {span['Duration'] / 1_000_000:.2f} ms\n\n**Timestamp:** {span['Timestamp']}")
 elif span['SpanName'] == "Crew Created":
 st.markdown("##### 👥 Crew Assembly")
 st.write(f"**Crew ID:** `{attrs.get('crew_id', 'N/A')}`")
 c1, c2 = st.columns(2)
 c1.metric("Agents Configured", attrs.get('crew_number_of_agents', 'N/A'))
 c2.metric("Tasks Assigned", attrs.get('crew_number_of_tasks', 'N/A'))
 for key in ['crew_agents', 'crew_tasks']:
 if key in attrs:
 with st.expander(f"View {key.replace('_', ' ').title()} Details"): st.json(attrs[key])
 elif span['SpanName'].startswith("invoke_agent"):
 st.markdown(f"##### 🤖 Agent Running: `{attrs.get('gen_ai.agent.name', 'Unknown Agent')}`")
 if 'gen_ai.agent.tools' in attrs: st.write("**Available Tools:**"); st.info(attrs['gen_ai.agent.tools'])
 elif span['SpanName'].startswith("chat"):
 st.markdown("##### 🧠 LLM Call")
 parsed = parse_llm_completion(attrs.get('gen_ai.completion'))
 if parsed.get('thought'): st.markdown("**Thought Process:**"); st.info(parsed['thought'])
 if parsed.get('action'): st.markdown(f"**Action Taken:** `{parsed['action']}`")
 if parsed.get('action_input'): st.markdown("**Action Input:**"); st.code(parsed['action_input'], language='json')
 if parsed.get('final_answer'): st.markdown("##### 📝 Final Answer"); st.success(parsed['final_answer'])
 with st.expander("View Full Prompt and Details"):
 st.write(f"**Output Tokens:** {attrs.get('gen_ai.usage.output_tokens', 'N/A')}")
 st.write("**Model:**", attrs.get('gen_ai.request.model', 'N/A'))
 st.text_area("Full Prompt", value=attrs.get('gen_ai.prompt', 'Not available.'), height=250, disabled=True)
 children = span_tree.get(span['SpanId'], [])
 if children:
 _, col = st.columns([0.05, 0.95])
 with col:
 for child in sorted(children, key=lambda s: s['Timestamp']):
 display_span_recursively(child, span_tree)

def display_trace_flow(traces_data):
 if not traces_data:
 st.info("No trace data available to display.")
 return
 cols = ['TraceId', 'SpanId', 'ParentSpanId', 'SpanName', 'SpanKind', 'Duration', 'Timestamp', 'SpanAttributes']
 spans = [dict(zip(cols, span_tuple)) for span_tuple in traces_data]
 span_tree = {s['SpanId']: [] for s in spans}
 root_spans = []
 all_spans = {s['SpanId']: s for s in spans}
 for span in spans:
 parent_id = span.get('ParentSpanId')
 if parent_id and parent_id in all_spans:
 span_tree[parent_id].append(span)
 else:
 root_spans.append(span)
 for root_span in sorted(root_spans, key=lambda s: s['Timestamp']):
 display_span_recursively(root_span, span_tree)

