 # dashboard.py

import streamlit as st
from config import DASHBOARD_NAME, DASHBOARD_TAGLINE
from utils import get_clickhouse_client
from filters import display_time_filter, display_agent_filter
from traces import get_distinct_trace_ids, search_traces_by_text, get_trace_summaries, get_trace_details, display_trace_flow
from ui_components import display_about_section, display_database_schema_viewer

def initialize_session_state():
 defaults = {
 'page': 'trace_explorer',
 'trace_id_input': '',
 'active_trace_id': ''
 }
 for key, value in defaults.items():
 if key not in st.session_state:
 st.session_state[key] = value

def render_sidebar(client):
 with st.sidebar:
 def set_page(page_name):
 st.session_state.page = page_name

 col1, col2 = st.columns(2)
 with col1:
 st.button("Trace Explorer", use_container_width=True, type="primary" if st.session_state.page == 'trace_explorer' else "secondary", on_click=set_page, args=('trace_explorer',))
 with col2:
 st.button("About & Contact", use_container_width=True, type="primary" if st.session_state.page == 'about' else "secondary", on_click=set_page, args=('about',))

 if st.session_state.page == 'trace_explorer':
 start_time, end_time = display_time_filter()
 selected_agent = display_agent_filter(client, start_time, end_time)

 st.header("Find Traces")
 search_query = st.text_input("Search by input or output text:", placeholder="e.g., verify aadhar...")

 if search_query:
 trace_ids = search_traces_by_text(client, search_query, start_time, end_time, selected_agent)
 else:
 trace_ids = get_distinct_trace_ids(client, start_time, end_time, selected_agent)

 if not trace_ids:
 st.warning("No traces found for the selected criteria.")
 else:
 with st.spinner("Loading trace summaries..."):
 summaries = get_trace_summaries(client, trace_ids)
 st.subheader("Select a Trace")
 for tid in trace_ids:
 summary = summaries.get(tid, "No summary available")
 with st.expander(f"**ID:** {tid}"):
 st.info(summary)
 if st.button("Select this Trace", key=f"select_{tid}", use_container_width=True):
 st.session_state.trace_id_input = tid
 st.session_state.active_trace_id = tid
 st.rerun()

def render_main_content(client):
 st.title(f"{DASHBOARD_NAME}: Trace Flow Visualizer")
 st.text_input("Enter Trace ID or select one from the sidebar", key="trace_id_input")

 if st.button("Get Trace Flow", type="primary", use_container_width=True):
 st.session_state.active_trace_id = st.session_state.trace_id_input or None

 active_id = st.session_state.get('active_trace_id')
 if active_id:
 if st.session_state.trace_id_input != active_id:
 st.info("A new Trace ID is in the text box. Click 'Get Trace Flow' to load it.")
 else:
 st.markdown(f"--- \n ### Flow for Trace ID: `{active_id}`")
 st.checkbox("Expand All Steps", key="expand_all")
 with st.spinner("Fetching trace details..."):
 traces = get_trace_details(client, active_id)
 display_trace_flow(traces)

 display_database_schema_viewer(client)

def main():
 st.set_page_config(layout="wide", page_title=f"{DASHBOARD_NAME} - {DASHBOARD_TAGLINE}")
 initialize_session_state()
 client = get_clickhouse_client()
 if not client:
 return

 render_sidebar(client)

 main_content = st.container()
 with main_content:
 if st.session_state.page == 'trace_explorer':
 render_main_content(client)
 elif st.session_state.page == 'about':
 st.title(f"{DASHBOARD_NAME}: About and Contact")
 display_about_section()

if __name__ == "__main__":
 main()

