 "system_command": system_command,
 "context": {"source": "project_management", "summary": f"Project '{new_project_name}' created with basic {technology} setup; .env updated."}
 }
 else:
 return {
 "action": "error",
 "command": f"Failed to create project directory for '{new_project_name}', Sir. Please check permissions or disk space.",
 "context": {"source": "project_management", "summary": "Project directory creation failed"}
 }
 else:
 return {
 "action": "error",
 "command": f"Project directory '{new_project_name}' already exists, Sir. Please choose a different name or open the existing project.",
 "context": {"source": "project_management", "summary": "Project directory already exists"}
 }

 # Default to Gemini command execution for other queries
 response = gemini.invoke([HumanMessage(content=prompt)])
 return parse_response(response.content)

def handle_response(response):
 """Handles parsed JSON responses, executes system commands, and provides user feedback via voice and console."""
 action = response.get('action')
 command_text = response.get('command', "No specific command from assistant.")
 system_command_list = response.get('system_command', [])
 context_summary = response.get('context', {}).get('summary', "No context provided.")

 if action == 'weather':
 speak(f"Weather update: {context_summary}")

 elif action == 'news':
 speak("Today's top headlines:")
 if isinstance(context_summary, list):
 for item in context_summary:
 speak(item)
 else:
 speak(context_summary)

 elif action == 'calendar':
 speak(f"Calendar events: {command_text}")
 if system_command_list:
 for cmd in system_command_list:
 try:
 subprocess.run(cmd, shell=True, check=True)
 except subprocess.CalledProcessError as e:
 speak(f"Error executing calendar command, Sir: {e}")

 elif action == 'open_app':
 if system_command_list:
 for cmd in system_command_list:
 try:
 subprocess.run(cmd, shell=True, check=True)
 except subprocess.CalledProcessError as e:
 speak(f"Error opening application, Sir: {e}")
 speak(command_text)

 elif action == 'work_project':
 if system_command_list:
 for cmd in system_command_list:
 try:
 subprocess.run(cmd, shell=True, check=True)
 except subprocess.CalledProcessError as e:
 speak(f"Error setting up project environment, Sir: {e}")
 speak(command_text)

 elif action == 'create_project':
 speak(command_text)
 if "create it" in command_text.lower() or "create a new project directory" in command_text.lower():
 project_name_match = re.search(r"project directory for '([^']+)'", command_text.lower())
 if project_name_match:
 project_name = project_name_match.group(1)
 technology = "python" # Default to Python for simplicity
 default_project_parent_dir = os.path.expanduser("~/Documents/")
 new_project_path = os.path.join(default_project_parent_dir, project_name)

 if create_project_directory(new_project_path):
 updated_projects = load_projects_from_env()
 updated_projects[project_name] = new_project_path
 update_projects_in_env(updated_projects)

 system_command = [
 f"code '{new_project_path}'",
 f"open -a Terminal '{new_project_path}'"
 ]
 if technology == 'python':
 system_command.extend([
 "touch main.py",
 f"echo '# Basic Python project for {project_name}' > main.py"
 ])

 handle_response({
 "action": "work_project",
 "command": f"Creating project '{project_name}' and setting up a basic Python environment, Sir.",
 "system_command": system_command,
 "context": {"source": "project_management", "summary": f"Project '{project_name}' created with basic Python setup; .env updated."}
 })
 else:
 speak(f"Error creating project directory for '{project_name}', Sir.")
 else:
 speak("Apologies, Sir, I encountered an issue creating the project. Could you please try again?")
 else:
 speak("Understood, Sir. We shall not create a new project at this time.")

 elif action == 'system':
 # Handle system commands such as opening Terminal
 for cmd in system_command_list:
 # Map known commands to macOS-compatible commands
 if cmd.lower() in ["terminal", "gnome-terminal"]:
 cmd = "open -a Terminal"
 try:
 subprocess.run(cmd, shell=True, check=True)
 except subprocess.CalledProcessError as e:
 speak(f"Error executing system command, Sir: {e}")
 speak(command_text)

 elif action == 'search':
 speak(f"Search results: {command_text}. {context_summary}")

 elif action == 'email':
 speak(f"Email summary: {command_text}. {context_summary}")

 elif action == 'error':
 speak(f"Assistant Error, Sir: {command_text}")

 else:
 speak("I'm afraid I'm not quite sure how to handle that, Sir.")

def speak(text):
 """
 Uses edge-tts (HumanLikeTTS class) to speak the given text aloud with voice output and prints to console.
 """
 print(f"JARVIS: {text}")
 tts_engine.speak(text)

def main():
 """Main loop for the personal assistant with voice and project management."""
 speak("Greetings, Sir. Jarvis is online and ready to manage your projects and assist you with voice output enabled.")
 while True:
 try:
 query = input("You: ")
 except (EOFError, KeyboardInterrupt):
 speak("Goodbye, Sir. Jarvis signing off. Wishing you a productive session!")
 break
 if query.lower() in ["exit", "quit", "bye", "goodbye", "see you later"]:
 speak("Goodbye, Sir. Jarvis signing off. Wishing you a productive session!")
 break

 try:
 response = execute_command(query)
 handle_response(response)
 except Exception as e:
 speak(f"Unexpected error, Sir: {e}")
 speak("Perhaps we could try that again, or rephrase your instructions?")

if __name__ == "__main__":
 main()

