 import requests
import time
import os
import psutil
from typing import Dict, Any, Optional
from .core import Netra, HealthPulse

# --- SHARED HELPER WITH DEEP INSPECTION ---
def _perform_health_check(agent_id: str, url: str, headers: Dict[str, str], timeout: int = 8) -> HealthPulse:
 start = time.time()
 process = psutil.Process(os.getpid())

 # 1. Hardware Telemetry
 cpu_usage = psutil.cpu_percent(interval=None) 
 ram_usage = process.memory_info().rss / (1024 * 1024) # MB

 status = "down"
 score = 0
 tokens_rem = None
 reset_time = None

 try:
 response = requests.get(url, headers=headers, timeout=timeout)
 latency = (time.time() - start) * 1000

 # 2. Extract Token Intelligence (Standard Headers)
 # OpenAI/Groq/Anthropic usually use x-ratelimit headers
 tokens_rem = response.headers.get("x-ratelimit-remaining-tokens") or \
 response.headers.get("x-ratelimit-remaining-requests")

 reset_time = response.headers.get("x-ratelimit-reset-tokens") or \
 response.headers.get("x-ratelimit-reset-requests")

 # 3. Status Determination
 if response.status_code == 200:
 status = "healthy"
 score = 100
 elif response.status_code == 429:
 status = "degraded"
 score = 30 # Rate Limit Hit
 print(f"⚠️ SAKSH ALERT: {agent_id} is Rate Limited (429)")
 elif response.status_code == 401:
 status = "down"
 score = 0
 print(f"⚠️ SAKSH ALERT: {agent_id} Auth Failed (401)")
 else:
 status = "degraded"
 score = 50

 except Exception:
 status = "down"
 score = 0
 latency = (time.time() - start) * 1000

 # 4. Vitality Algorithm v1.1
 if status == "healthy":
 # Latency Penalty
 if latency > 1200: score -= 15
 if latency > 3000: score -= 40

 # CPU Penalty (Swarm Overload)
 if cpu_usage > 85: score -= 20

 # Token Scarcity Penalty
 if tokens_rem and tokens_rem.isdigit() and int(tokens_rem) < 1000:
 score -= 15

 return HealthPulse(
 agent_id=agent_id,
 status=status,
 latency_ms=round(latency, 2),
 vitality_score=max(0, score),
 cpu_percent=cpu_usage,
 ram_mb=round(ram_usage, 2),
 tokens_remaining=int(tokens_rem) if tokens_rem and tokens_rem.isdigit() else None,
 rate_limit_reset=int(reset_time) if reset_time and reset_time.isdigit() else None
 )

