 async def dynamic_code_tool(args: ToolModel, ctx: Context, cfg=cfg):
 local_vars = {"args": args.model_dump(), "result": None}
 try:
 exec(cfg['code'], {}, local_vars)
 return local_vars.get("result", "Code executed but 'result' variable was not set.")
 except Exception as e:
 return {"error": f"Execution failed: {str(e)}"}

 dynamic_code_tool.__doc__ = cfg['description']
 logger.info(f"✅ Registered Python Tool: {cfg['name']}")

 elif 'endpoint' in cfg:
 # 🌐 REGISTER AN API TOOL (Your existing logic)
 @mcp.tool(name=cfg['name'])
