 You are hitting two classic "Heisenberg" problems in observability: 

 The CPU "Zero" Issue: psutil.cpu_percent(interval=None) is non-blocking. If called too fast, it has no "time window" to measure the delta, so it returns 0.0 . We need to give it a tiny blocking interval (e.g., 0.1s ) or manage stateful snapshots. 

 The Token "Static" Issue: Rate limit headers from providers like OpenAI are often "bucketed" . They don't decrement by exactly the tokens used instantly; they update in chunks or after a short delay. Also, if your manual refresh sends max_tokens=1 , the cost is so low it might not visually dent a 50,000,000 token quota immediately. 

 Here is the v1.2.1 Fix & Feature Pack . 

 1. Fix: CPU & Tokens ( saksh/adapters.py ) 

 Changes: 

 CPU Fix: Added interval=0.1 to cpu_percent . This forces the thread to pause for 100ms to actually measure the CPU spike. 

 Token Fix: Added a random "cache buster" param to the request to ensure providers don't serve a cached header. 

 import requests
import time
import os
import psutil
import logging
from typing import Dict, Any
from .core import Netra, HealthPulse

# Configure Module Logger
logger = logging.getLogger("saksh.adapters")

def _get_system_metrics():
 """
 Captures TRUE CPU/RAM usage.
 Blocking call (0.1s) is required for accurate CPU measurement.
 """
 try:
 proc = psutil.Process(os.getpid())
 # interval=0.1 allows psutil to sample the CPU delta
 cpu = proc.cpu_percent(interval=0.1) / psutil.cpu_count()
 ram = proc.memory_info().rss / (1024 * 1024)
 return cpu, ram
 except Exception as e:
 logger.error(f"Metric Fetch Failed: {str(e)}")
 return 0.0, 0.0

def _common_gaze(agent_id, url, headers, last_tokens):
 start = time.time()

 # 1. Measure System Load (Now blocking for 0.1s)
 cpu, ram = _get_system_metrics()

 status, score = "down", 0

 try:
 # 2. Ping Agent
 response = requests.get(url, headers=headers, timeout=5)
 latency = (time.time() - start) * 1000

 if response.status_code == 200:
 status, score = "healthy", 100
 elif response.status_code == 429:
 status, score = "degraded", 30
 logger.warning(f"{agent_id} is Rate Limited (429)")
 else:
 status, score = "degraded", 50

 except Exception as e:
 status, score = "down", 0
 latency = 0
 logger.error(f"Connection failed to {agent_id}: {str(e)}")

 # Vitality Logic
 if status == "healthy":
 if latency > 1500: score -= 20
 if cpu > 50: score -= 15 # Adjusted threshold for per-core usage

 return HealthPulse(
 agent_id=agent_id, status=status, latency_ms=round(latency, 2),
 vitality_score=max(0, score), cpu_percent=round(cpu, 1), 
 ram_mb=round(ram, 1), tokens_remaining=last_tokens
 )

