# --- LOGGING SETUP ---
# Clear existing handlers to avoid duplicates
root_logger = logging.getLogger()
if root_logger.handlers:
 for handler in root_logger.handlers:
 root_logger.removeHandler(handler)

logging.basicConfig(
 level=logging.INFO,
 format="%(asctime)s [%(levelname)s] %(message)s",
 handlers=[
 logging.FileHandler("saksh_session.log", mode='w'), # Overwrite on restart
 logging.StreamHandler()
 ]
)
logger = logging.getLogger("saksh.core")

# --- SCHEMAS ---
class HealthPulse(BaseModel):
 agent_id: str
 status: Literal["healthy", "degraded", "down"]
 latency_ms: float
 timestamp: datetime = Field(default_factory=datetime.now)
 vitality_score: int
 cpu_percent: float = 0.0
 ram_mb: float = 0.0
 tokens_remaining: str = "N/A"
 rate_limit_reset: str = "N/A"

class Netra(abc.ABC):
 def __init__(self, agent_id: str):
 self.agent_id = agent_id
 self.last_known_tokens = "N/A"

 @abc.abstractmethod
 def gaze(self) -> HealthPulse: pass

 @abc.abstractmethod
 def scan_tokens(self) -> Dict[str, str]: pass

class Saksh:
 _instance = None 

 def __new__(cls, *args, **kwargs):
 if not cls._instance:
 cls._instance = super(Saksh, cls).__new__(cls)
 return cls._instance

 def __init__(self, start_dashboard=True, port=2604):
 if hasattr(self, '_initialized'): return
 self._thousand_eyes: Dict[str, Netra] = {}
 self._initialized = True
 logger.info("Saksh Observer Initialized")

 if start_dashboard:
 self._start_dashboard_thread(port)

 def open_eye(self, adapter: Netra):
 self._thousand_eyes[adapter.agent_id] = adapter
 logger.info(f"Registered Agent: {adapter.agent_id}")

 def refresh_agent_tokens(self, agent_id: str):
 if agent_id in self._thousand_eyes:
 return self._thousand_eyes[agent_id].scan_tokens()
 return {"error": "Agent not found"}

 def observe(self) -> Dict[str, Any]:
 report = {
 "total": len(self._thousand_eyes),
 "status": "stable",
 "timestamp": datetime.now().isoformat(),
 "eyes": []
 }

 for agent_id, eye in self._thousand_eyes.items():
 pulse = eye.gaze()
 if pulse.tokens_remaining == "N/A":
 pulse.tokens_remaining = eye.last_known_tokens

 report["eyes"].append(pulse.dict())
 if pulse.status == "down":
 report["status"] = "critical"
 return report

 def _start_dashboard_thread(self, port):
 def run_server():
 app = FastAPI(title="Saksh Mission Control v1.2.1")
 app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_methods=["*"], allow_headers=["*"])

 @app.get("/api/status")
 def get_status(): return self.observe()

 @app.post("/api/refresh/{agent_id}")
 def refresh_tokens(agent_id: str):
 return self.refresh_agent_tokens(agent_id)

 @app.get("/api/logs")
 def get_logs():
 """Reads the log file and returns lines as a list."""
 try:
 if os.path.exists("saksh_session.log"):
 with open("saksh_session.log", "r") as f:
 # Return last 50 lines reversed (newest first)
 lines = f.readlines()
 return {"logs": lines[-50:][::-1]}
 return {"logs": []}
 except Exception as e:
 return {"logs": [f"Error reading logs: {str(e)}"]}

 current_dir = os.path.dirname(os.path.abspath(__file__))
 static_dir = os.path.join(current_dir, "dashboard", "static")
 if os.path.exists(static_dir):
 app.mount("/", StaticFiles(directory=static_dir, html=True), name="static")

 logger.info(f"Dashboard Online at http://localhost:{port}")
 config = uvicorn.Config(app, host="0.0.0.0", port=port, log_level="critical")
 uvicorn.Server(config).run()

 threading.Thread(target=run_server, daemon=True).start()

