import secrets
import hashlib
import base64
from fastapi import FastAPI, HTTPException, Form
from pydantic import BaseModel

app = FastAPI()

# In-memory databases
clients_db = {}
codes_db = {}
tokens_db = set()

class ClientRegistration(BaseModel):
 redirect_uris: list[str]
 client_name: str

# Spec #3: Authorization Server Metadata
@app.get("/.well-known/oauth-authorization-server")
def auth_metadata():
 return {
 "issuer": "http://localhost:8001",
 "authorization_endpoint": "http://localhost:8001/authorize",
 "token_endpoint": "http://localhost:8001/token",
 "registration_endpoint": "http://localhost:8001/register",
 "code_challenge_methods_supported": ["S256"]
 }

# Spec #4: Dynamic Client Registration
@app.post("/register")
def register(client: ClientRegistration):
 client_id = secrets.token_hex(16)
 clients_db[client_id] = client.model_dump()
 return {
 "client_id": client_id,
 "client_secret": secrets.token_hex(32), 
 "client_id_issued_at": 1234567890
 }

# Spec #1: OAuth 2.0 Authorization Endpoint
@app.post("/authorize")
def authorize(client_id: str, code_challenge: str):
 if client_id not in clients_db:
 raise HTTPException(status_code=400, detail="Invalid client")

 # In a real app, you would validate the user session here.
 # We skip to issuing the auth code.
 code = secrets.token_urlsafe(32)
 codes_db[code] = {
 "client_id": client_id,
 "code_challenge": code_challenge
 }
 return {"code": code}

# Spec #5: Token Exchange with PKCE
@app.post("/token")
def token(
 grant_type: str = Form(...),
 code: str = Form(...),
 client_id: str = Form(...),
 code_verifier: str = Form(...)
):
 if grant_type != "authorization_code":
 raise HTTPException(status_code=400, detail="Unsupported grant type")

 auth_data = codes_db.get(code)
 if not auth_data or auth_data["client_id"] != client_id:
 raise HTTPException(status_code=400, detail="Invalid code")

 # PKCE Verification
 digest = hashlib.sha256(code_verifier.encode()).digest()
 challenge = base64.urlsafe_b64encode(digest).decode().rstrip("=")

 if challenge != auth_data["code_challenge"]:
 raise HTTPException(status_code=400, detail="PKCE verification failed")

 access_token = secrets.token_urlsafe(32)
 tokens_db.add(access_token)

 # Remove used code
 del codes_db[code]

 return {
 "access_token": access_token,
 "token_type": "Bearer",
 "expires_in": 3600
 }

@app.get("/verify/{token}")
def verify_token(token: str):
 if token in tokens_db:
 return {"active": True}
 raise HTTPException(status_code=401, detail="Invalid token")

if __name__ == "__main__":
 import uvicorn
 uvicorn.run(app, host="0.0.0.0", port=8001)

