import streamlit as st
import httpx
import secrets
import hashlib
import base64

st.set_page_config(page_title="MCP OAuth Client", layout="wide")
st.title("MCP Client with OAuth & PKCE")

# Session State Initialization
if "access_token" not in st.session_state:
 st.session_state.access_token = None
if "auth_server" not in st.session_state:
 st.session_state.auth_server = None
if "client_data" not in st.session_state:
 st.session_state.client_data = None

def get_pkce():
 """Generates a code verifier and challenge for PKCE."""
 verifier = secrets.token_urlsafe(32)
 digest = hashlib.sha256(verifier.encode()).digest()
 challenge = base64.urlsafe_b64encode(digest).decode().rstrip("=")
 return verifier, challenge

def discover_and_auth():
 try:
 status_container = st.empty()
 status_container.info("Step 1: Discovering Resource Metadata...")

 # Spec 2: Discovery - Ask the Resource Server where the Auth Server is
 resource_resp = httpx.get("http://localhost:8000/.well-known/oauth-protected-resource")
 if resource_resp.status_code != 200:
 st.error("Could not discover resource metadata.")
 return

 auth_server_url = resource_resp.json()["authorization_servers"][0]
 status_container.info(f"Step 2: Found Auth Server at {auth_server_url}. Fetching Metadata...")

 # Spec 3: Auth Server Metadata - Ask Auth Server for endpoints
 meta_resp = httpx.get(f"{auth_server_url}/.well-known/oauth-authorization-server")
 metadata = meta_resp.json()
 st.session_state.auth_server = metadata

 status_container.info("Step 3: Registering Client Dynamically...")

 # Spec 4: Dynamic Registration - Register ourselves
 reg_resp = httpx.post(
 metadata["registration_endpoint"],
 json={"redirect_uris": ["http://localhost:8501"], "client_name": "Streamlit App"}
 )
 client_data = reg_resp.json()
 st.session_state.client_data = client_data

 status_container.info("Step 4: Performing PKCE Authorization...")

 # Spec 5: PKCE Flow
 verifier, challenge = get_pkce()

 # 1. Authorize (Get Code)
 auth_resp = httpx.post(
 metadata["authorization_endpoint"],
 params={"client_id": client_data["client_id"], "code_challenge": challenge}
 )
 if auth_resp.status_code != 200:
 st.error("Authorization request failed")
 return

 code = auth_resp.json()["code"]

 # 2. Token Exchange (Get Token)
 token_resp = httpx.post(
 metadata["token_endpoint"],
 data={
 "grant_type": "authorization_code",
 "code": code,
 "client_id": client_data["client_id"],
 "code_verifier": verifier
 }
 )

 if token_resp.status_code == 200:
 st.session_state.access_token = token_resp.json()["access_token"]
 status_container.success("Authentication Complete! Token Acquired.")
 else:
 status_container.error(f"Token exchange failed: {token_resp.text}")

 except Exception as e:
 st.error(f"An error occurred: {e}")

col1, col2 = st.columns(2)

with col1:
 st.subheader("1. Connection")
 st.markdown("Click below to start the OAuth discovery and handshake process.")

 if st.button("Connect to Secure MCP Server"):
 discover_and_auth()

 if st.session_state.access_token:
 st.success("CONNECTED")
 st.code(f"Bearer {st.session_state.access_token}", language="text")

with col2:
 st.subheader("2. Use Tool")
 revenue = st.number_input("Revenue", value=1000)
 cost = st.number_input("Cost", value=400)

 if st.button("Calculate Profit"):
 if not st.session_state.access_token:
 st.warning("Please authenticate first.")
 else:
 headers = {"Authorization": f"Bearer {st.session_state.access_token}"}
 try:
 # We call the tool endpoint directly for this POC.
 # FastMCP usually exposes tools at /tool_name or /tools/tool_name depending on version.
 # Since we mounted mcp at root "/", the tool is likely at "/calculate_growth" or check /tools

 # Note: FastMCP is primarily SSE, but often enables HTTP for tools. 
 # If this fails, the Auth is working, but we need to check the FastMCP route structure.
 # We'll try the standard FastMCP HTTP invocation pattern.

 payload = {"revenue": revenue, "cost": cost}

 # Try calling the tool directly (standard FastMCP HTTP wrapper)
 res = httpx.post(
 "http://localhost:8000/calculate_growth", # Default FastMCP route
 json=payload,
 headers=headers
 )

 if res.status_code == 200:
 st.write("### Result from Server:")
 st.write(res.json())
 elif res.status_code == 404:
 st.warning("Tool endpoint not found. The Auth worked, but the tool route might differ.")
 else:
 st.error(f"Server Error ({res.status_code}): {res.text}")

 except Exception as e:
 st.error(f"Request failed: {e}")

