 C. Add New Animation Rules 
Add this new block of CSS to your style.css file (e.g., right after the block you just replaced). This controls the text shadow, glare, and sparkle animations. 

 /* ADD this new block for the sparkle/glare animation */
.cta-button-group a span {
 display: inline-block;
 font-weight: 700;
 transition: all 0.2s;
 text-decoration: none;
 text-shadow:
 calc(var(--hover) * -1px) calc(var(--hover) * 1px) var(--shadow),
 calc(var(--hover) * -2px) calc(var(--hover) * 2px) var(--shadow),
 calc(var(--hover) * -3px) calc(var(--hover) * 3px) var(--shadow),
 calc(var(--hover) * -4px) calc(var(--hover) * 4px) var(--shadow);
 transform: translate(calc(var(--hover) * 4px), calc(var(--hover) * -4px));
}

.cta-button-group a span i {
 font-style: normal; /* Prevents <i> from italicizing */
 display: inline-block;
}

.btn-group-main span {
 font-size: 1rem; /* Adjust as needed */
 position: relative;
 z-index: 2;
}

.btn-group-linkedin span {
 font-size: 1.3rem; /* Match your old icon size */
 position: relative;
 z-index: 2;
 /* Vertically align icon */
 display: flex; 
 align-items: center;
 justify-content: center;
}

.cta-button-group a span:last-of-type {
 position: absolute;
 background: linear-gradient(
 108deg,
 transparent 0 55%,
 var(--glare) 55% 60%,
 transparent 60% 70%,
 var(--glare) 70% 85%,
 transparent 85%
 ) calc(var(--pos) * -200%) 0% / 200% 100%, var(--color);
 -webkit-background-clip: text;
 background-clip: text;
 color: transparent;
 z-index: 2;
 text-shadow: none;
}

/* Position the glare text on top */
.btn-group-main span:last-of-type {
 inset: 15px 35px;
}
.btn-group-linkedin span:last-of-type {
 inset: 15px 20px;
}

.cta-button-group a span:last-of-type {
 transition: transform 0.2s, background-position 0s;
}

.cta-button-group a:hover span:last-of-type {
 transition: transform 0.2s, background-position calc(var(--hover) * 1.5s) calc(var(--hover) * 0.25s);
}

.cta-button-group a:active {
 --hover: 0;
}

.cta-button-group a:active span:last-of-type {
 --hover: 0;
 --pos: 1;
}

.cta-button-group a svg {
 position: absolute;
 z-index: 3;
 width: 0.6em; /* Scale sparkle with font size */
 aspect-ratio: 1;
 top: calc(var(--y, 50) * 1%);
 left: calc(var(--x, 0) * 1%);
 transform: translate(-50%, -50%) scale(0);
}

.cta-button-group a svg path {
 fill: var(--glare);
}

.cta-button-group a:hover svg {
 animation: sparkle 0.75s calc((var(--delay-step) * var(--d)) * 1s) both;
}

.cta-button-group a svg {
