This is an excellent new feature that will streamline your workflow significantly. Building a dedicated UI to compose and save multi-agent crews is the natural next step. 

 To implement this, we'll need to do three things: 

 Update the Database ( models.py ) : We'll add new tables to formally define a "Crew" and its members. 

 Update the Backend ( web_interface.py ) : We'll create a new endpoint to handle the creation of these crews. 

 Create the Frontend UI ( crew_management.html ) : We'll build the new page with the form to create a crew. 

 Here is the complete implementation. 

 ### 1. Update Your Database Model ( db/models.py ) 

 First, we need to add tables to your database to store the crews and the relationships between crews and agents. 

 Add these two new classes to your db/models.py file: 

 # Add this at the top of models.py
from sqlalchemy.orm import relationship

# ... (keep all your existing model classes) ...

class Crew(Base):
 __tablename__ = "crews"
 id = Column(UUID(as_uuid=True), primary_key=True, default=uuid.uuid4)
 name = Column(String, unique=True, nullable=False)
 description = Column(Text)

 # This creates the relationship to the agents in the crew
 members = relationship("CrewAgent", back_populates="crew", cascade="all, delete-orphan")

class CrewAgent(Base):
 __tablename__ = "crew_agents"
 id = Column(UUID(as_uuid=True), primary_key=True, default=uuid.uuid4)
 crew_id = Column(UUID(as_uuid=True), ForeignKey("crews.id"), nullable=False)
 agent_id = Column(UUID(as_uuid=True), ForeignKey("agents.id"), nullable=False)
 role = Column(String, nullable=False) # e.g., 'manager', 'specialist'

 crew = relationship("Crew", back_populates="members")
 agent = relationship("Agent")

 After adding these, you'll need to run your database migration tool (like Alembic) to create these new tables in your database. 

 ### 2. Update Your Backend ( web_interface.py ) 

 Now, we'll add the new endpoint to create the crew and a helper endpoint to list existing agents for the UI. 

 Add these new functions and Pydantic models to your web_interface.py file: 

 # Add these imports at the top
from db.crud.crew import create_crew_with_agents, CrewCreate, CrewAgentCreate

# Add these new Pydantic models
class NewAgentData(BaseModel):
 name: str
 description: str
 config: Dict[str, Any]
 llm_used: str

class SpecialistData(BaseModel):
 type: str # 'new' or 'existing'
 agent_data: Optional[NewAgentData] = None
 agent_id: Optional[str] = None

class CreateCrewPayload(BaseModel):
 crew_name: str
 crew_description: str
 manager: NewAgentData
 specialists: List[SpecialistData]

# Add this new endpoint to your web_interface.py
@app.post("/create-crew")
async def handle_create_crew(payload: CreateCrewPayload):
 db = next(get_db())
 try:
 # 1. Create the Manager Agent
 manager_create = AgentCreate(
 name=payload.manager.name,
 type="chat_agent",
 description=payload.manager.description,
 llm_used=payload.manager.llm_used,
 prompt_template="",
 output_format="",
 config=payload.manager.config
 )
 manager_agent = create_agent(db, manager_create)

 # 2. Prepare Specialist Agent data
 specialist_members = []
 for spec_data in payload.specialists:
 if spec_data.type == 'new':
 specialist_create = AgentCreate(
 name=spec_data.agent_data.name,
 type="chat_agent",
 description=spec_data.agent_data.description,
 llm_used=spec_data.agent_data.llm_used,
 prompt_template="",
 output_format="",
 config=spec_data.agent_data.config
 )
 new_specialist_agent = create_agent(db, specialist_create)
 specialist_members.append(CrewAgentCreate(agent_id=new_specialist_agent.id, role="specialist"))
 elif spec_data.type == 'existing' and spec_data.agent_id:
 specialist_members.append(CrewAgentCreate(agent_id=uuid.UUID(spec_data.agent_id), role="specialist"))

 # 3. Create the Crew and link all agents
 crew_data = CrewCreate(
 name=payload.crew_name,
 description=payload.crew_description
 )

 new_crew = create_crew_with_agents(
 db=db, 
 crew=crew_data, 
 manager_id=manager_agent.id, 
 specialists=specialist_members
 )

 return JSONResponse(
 content={"status": "success", "message": f"Crew '{new_crew.name}' created successfully.", "crew_id": str(new_crew.id)},
 status_code=201
 )
 except Exception as e:
 logger.error(f"Error creating crew: {e}", exc_info=True)
 raise HTTPException(status_code=500, detail="An internal error occurred while creating the crew.")

# Also add a new route for the management page
