 You'll also need a new CRUD function in a file like db/crud/crew.py to handle the database logic. 

 New file: db/crud/crew.py 

 from sqlalchemy.orm import Session
import uuid
from db.models import Crew, CrewAgent, Agent
from pydantic import BaseModel
from typing import List

class CrewCreate(BaseModel):
 name: str
 description: str

class CrewAgentCreate(BaseModel):
 agent_id: uuid.UUID
 role: str

def create_crew_with_agents(db: Session, crew: CrewCreate, manager_id: uuid.UUID, specialists: List[CrewAgentCreate]) -> Crew:
 db_crew = Crew(name=crew.name, description=crew.description)
 db.add(db_crew)
 db.flush()

 # Add manager
 manager_link = CrewAgent(crew_id=db_crew.id, agent_id=manager_id, role="manager")
 db.add(manager_link)

 # Add specialists
 for specialist in specialists:
 specialist_link = CrewAgent(crew_id=db_crew.id, agent_id=specialist.agent_id, role=specialist.role)
 db.add(specialist_link)

 db.commit()
 db.refresh(db_crew)
 return db_crew

