 </div>

 <div class="card mb-4">
 <div class="card-header"><h4>Specialist Agents</h4></div>
 <div class="card-body">
 <h5>Added Specialists</h5>
 <ul id="specialistList" class="list-group mb-3">
 </ul>
 <hr>
 <h5>Add a Specialist</h5>
 <div class="input-group mb-3">
 <select class="form-select" id="specialistTypeSelector">
 <option value="existing" selected>Add an Existing Agent</option>
 <option value="new">Create a New Agent</option>
 </select>
 <button class="btn btn-success" type="button" id="addSpecialistBtn">Add to Crew</button>
 </div>

 <div id="existingAgentForm">
 <select class="form-select" id="existingAgentSelect">
 <option value="">Select an existing agent...</option>
 {% for agent_id, agent_info in agents.items() %}
 <option value="{{ agent_id }}">{{ agent_info.name }}</option>
 {% endfor %}
 </select>
 </div>

 <div id="newAgentForm" style="display: none;">
 <input type="text" class="form-control mb-2" id="newAgentName" placeholder="New Agent Name">
 <textarea class="form-control mb-2" id="newAgentDescription" placeholder="New Agent Description (e.g., Expert in verifying bank accounts)"></textarea>
 <input type="text" class="form-control mb-2" id="newAgentLlm" value="gpt-4o" placeholder="LLM Used (e.g., gpt-4o)">
