<script>
 const specialistTypeSelector = document.getElementById('specialistTypeSelector');
 const existingAgentForm = document.getElementById('existingAgentForm');
 const newAgentForm = document.getElementById('newAgentForm');
 const addSpecialistBtn = document.getElementById('addSpecialistBtn');
 const specialistList = document.getElementById('specialistList');
 const createCrewForm = document.getElementById('createCrewForm');

 let addedSpecialists = [];

 specialistTypeSelector.addEventListener('change', () => {
 if (specialistTypeSelector.value === 'existing') {
 existingAgentForm.style.display = 'block';
 newAgentForm.style.display = 'none';
 } else {
 existingAgentForm.style.display = 'none';
 newAgentForm.style.display = 'block';
 }
 });

 addSpecialistBtn.addEventListener('click', () => {
 const type = specialistTypeSelector.value;
 if (type === 'existing') {
 const select = document.getElementById('existingAgentSelect');
 if (!select.value) return;
 const agentId = select.value;
 const agentName = select.options[select.selectedIndex].text;
 addedSpecialists.push({ type: 'existing', agent_id: agentId });
 addSpecialistToList(agentName, 'Existing');
 } else {
 const name = document.getElementById('newAgentName').value;
 const description = document.getElementById('newAgentDescription').value;
 const llm = document.getElementById('newAgentLlm').value;
 if (!name || !description) return;

 addedSpecialists.push({ 
 type: 'new',
 agent_data: { 
 name: name, 
 description: description, 
 llm_used: llm,
 config: {"mcp": {"enabled": true}} // Default config
 }
 });
 addSpecialistToList(name, 'New');
 document.getElementById('newAgentName').value = '';
 document.getElementById('newAgentDescription').value = '';
 }
 });

 function addSpecialistToList(name, type) {
 const li = document.createElement('li');
 li.className = 'list-group-item';
 li.textContent = `${name} (${type})`;
 specialistList.appendChild(li);
 }

 createCrewForm.addEventListener('submit', async (e) => {
 e.preventDefault();

 const payload = {
 crew_name: document.getElementById('crewName').value,
 crew_description: document.getElementById('crewDescription').value,
 manager: {
 name: document.getElementById('managerName').value,
 description: document.getElementById('managerDescription').value,
 llm_used: document.getElementById('managerLlm').value,
 config: JSON.parse(document.getElementById('managerConfig').value)
 },
 specialists: addedSpecialists
 };

 try {
 const response = await fetch('/create-crew', {
 method: 'POST',
 headers: { 'Content-Type': 'application/json' },
 body: JSON.stringify(payload)
 });

 if (response.ok) {
 const data = await response.json();
 alert(data.message);
 window.location.href = '/';
 } else {
 const error = await response.json();
 alert('Error: ' + error.detail);
 }
 } catch (err) {
 console.error('Submission error:', err);
 alert('An unexpected error occurred.');
 }
 });
</script>
</body>
</html>

