 <style>
 /* =========================================
 MINIMALIST THEME
 ========================================= */
 :root {
 --bg-color: #fcfcfc;
 --card-bg: #ffffff;
 --accent-color: #000000;
 --border-light: #e5e5e5;
 --border-dark: #000000;
 --text-main: #111111;
 --text-muted: #737373;
 }

 .text-muted {
 color: var(--text-muted) !important;
 }

 body {
 background-color: var(--bg-color);
 color: var(--text-main);
 font-family: 'Poppins', sans-serif;
 padding-bottom: 90px;
 overflow-x: hidden;
 -webkit-tap-highlight-color: transparent;
 }

 h1,
 h2,
 h3,
 h4,
 h5,
 h6,
 .brand-font {
 font-family: 'Syncopate', sans-serif;
 text-transform: uppercase;
 font-weight: 700;
 letter-spacing: -0.5px;
 }

 /* Stark, solid black logo */
 .brand-logo {
 font-size: 1.5rem;
 color: var(--accent-color);
 letter-spacing: 2px;
 }

 /* Clean Header */
 .dashboard-header {
 padding: 20px 0;
 display: flex;
 justify-content: space-between;
 align-items: center;
 border-bottom: 1px solid var(--border-light);
 margin-bottom: 30px;
 background: rgba(252, 252, 252, 0.9);
 position: sticky;
 top: 0;
 z-index: 100;
 backdrop-filter: blur(8px);
 }

 /* Barebones Icon Buttons */
 .btn-action {
 background: transparent;
 border: 1px solid transparent;
 color: var(--text-main);
 border-radius: 4px;
 font-size: 1rem;
 padding: 6px 12px;
 transition: all 0.2s ease;
 display: flex;
 align-items: center;
 justify-content: center;
 }

 .btn-action:hover,
 .btn-action:active {
 border: 1px solid var(--border-light);
 background: var(--card-bg);
 }

 #voiceToggle.active i {
 color: var(--accent-color);
 }

 /* Minimalist Workout Cards */
 .workout-card {
 background-color: var(--card-bg);
 border-radius: 0px;
 /* Sharp corners for Brutalist/Minimal feel */
 border: 1px solid var(--border-light);
 margin-bottom: 15px;
 padding: 20px;
 transition: all 0.3s ease;
 }

 .workout-card.completed-card {
 background-color: #fafafa;
 border-color: var(--border-light);
 opacity: 0.6;
 /* Fades out softly when done */
 }

 .ex-header {
 display: flex;
 justify-content: space-between;
 align-items: flex-start;
 margin-bottom: 15px;
 }

 .ex-title {
 font-size: 1.1rem;
 color: var(--text-main);
 margin: 0;
 font-weight: 600;
 }

 .badge.bg-dark {
 background: #fff !important;
 color: #000 !important;
 border: 1px solid #000 !important;
 border-radius: 0;
 font-weight: 600;
 padding: 5px 8px;
 font-family: monospace;
 /* Technical feel */
 }

 /* Strict Set Bubbles */
 .set-container {
 display: flex;
 gap: 10px;
 margin-top: 15px;
 flex-wrap: wrap;
 }

 .set-bubble {
 width: 40px;
 height: 40px;
 border-radius: 0;
 /* Square buttons */
 border: 1px solid var(--border-light);
 display: flex;
 align-items: center;
 justify-content: center;
 font-weight: 600;
 font-size: 1rem;
 cursor: pointer;
 background: var(--card-bg);
 color: var(--text-muted);
 transition: all 0.15s ease;
 }

 .set-bubble.active {
 background: var(--accent-color);
 border-color: var(--accent-color);
 color: #ffffff;
 transform: translateY(-2px);
 box-shadow: 2px 2px 0px rgba(0, 0, 0, 0.1);
 }

 /* Finisher Checkbox */
 .finisher-label {
 display: flex;
 align-items: center;
 width: 100%;
 cursor: pointer;
 font-size: 1rem;
 font-weight: 600;
 }

 .finisher-checkbox {
 width: 1.5em;
 height: 1.5em;
 background-color: var(--card-bg);
 border: 1px solid var(--border-dark);
 border-radius: 0;
 margin-right: 15px;
 appearance: none;
 cursor: pointer;
 transition: all 0.1s;
 }

 .finisher-checkbox:checked {
 background-color: var(--accent-color);
 position: relative;
 }

 .finisher-checkbox:checked::after {
 content: '✓';
 position: absolute;
 color: #fff;
 font-size: 1rem;
 font-weight: 400;
 left: 50%;
 top: 50%;
 transform: translate(-50%, -50%);
 }

 /* Raw Text Toggles */
 .anatomy-toggle {
 font-size: 0.8rem;
 color: var(--text-muted);
 cursor: pointer;
 margin-top: 20px;
 display: inline-block;
 font-weight: 600;
 border-bottom: 1px dashed var(--text-muted);
 transition: all 0.2s;
 }

 .anatomy-toggle:hover {
 color: var(--accent-color);
 border-color: var(--accent-color);
 }

 .anatomy-content {
 display: none;
 font-size: 0.85rem;
 color: var(--text-muted);
 margin-top: 12px;
 padding: 0 0 0 15px;
 border-left: 2px solid var(--accent-color);
 line-height: 1.6;
 }

 .machine-alt {
 font-size: 0.8rem;
 color: var(--text-muted);
 margin-top: 15px;
 display: block;
 font-family: monospace;
 }

 /* Minimal Progress Bar */
 .progress {
 height: 4px;
 background-color: var(--border-light);
 border-radius: 0;
 overflow: visible;
 margin-bottom: 40px;
 }

 .progress-bar {
 background-color: var(--accent-color);
 border-radius: 0;
 transition: width 0.4s ease;
 }

 /* Line-Art Media Cards */
 .media-card {
 border: 1px solid var(--border-light);
 background: var(--card-bg);
 padding: 20px;
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 font-weight: 600;
 font-size: 1rem;
 color: var(--text-main) !important;
 width: 100%;
 transition: all 0.2s;
 border-radius: 0;
 }

 .media-card:hover,
 .media-card:active {
 border-color: var(--border-dark);
 background: #f9f9f9;
 }

 /* Brutalist Floating Timer */
 #floatingTimer {
 position: fixed;
 bottom: 85px;
 left: 50%;
 transform: translateX(-50%) translateY(200%);
 background: var(--card-bg);
 border: 2px solid var(--border-dark);
 color: var(--text-main);
 padding: 10px 25px;
 border-radius: 0;
 font-family: monospace;
 font-weight: 700;
 font-size: 1.5rem;
 z-index: 999;
 transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
 display: flex;
 align-items: center;
 gap: 15px;
 cursor: pointer;
 box-shadow: 4px 4px 0px rgba(0, 0, 0, 1);
 /* Hard shadow */
 }

 #floatingTimer.show {
 transform: translateX(-50%) translateY(0);
 }

 #floatingTimer.done {
 background: var(--accent-color);
 color: #fff;
 box-shadow: none;
 }

 /* Modals */
 .modal-content {
 background-color: var(--card-bg);
 border-radius: 0;
 border: 1px solid var(--border-dark);
 box-shadow: 8px 8px 0px rgba(0, 0, 0, 0.1);
 }

 .modal-header,
 .modal-footer {
 border-color: var(--border-light);
 }

 .audio-list-item {
 border: 1px solid var(--border-light);
 padding: 15px;
 margin-bottom: 10px;
 display: flex;
 align-items: center;
 text-decoration: none;
 color: var(--text-main);
 transition: all 0.2s;
 background: var(--card-bg);
 }

 .audio-list-item:hover {
 border-color: var(--border-dark);
 }

 .btn-collapse {
 background: transparent;
 color: var(--text-main);
 border: 1px solid var(--border-light);
 padding: 8px 24px;
 font-weight: 600;
 border-radius: 0;
 transition: all 0.2s;
 font-size: 0.85rem;
 }

 .btn-collapse:active {
 background: #f0f0f0;
 }

 footer {
 position: fixed;
 bottom: 0;
 width: 100%;
 background: rgba(252, 252, 252, 0.95);
 border-top: 1px solid var(--border-light);
 padding: 15px 0;
 text-align: center;
 font-size: 0.8rem;
 z-index: 1000;
 font-family: monospace;
 }

 footer a {
 color: var(--text-main);
 text-decoration: underline;
 font-weight: 700;
 }

 .footer-avatar {
 width: 24px;
 height: 24px;
 border-radius: 0;
 vertical-align: middle;
 margin-right: 8px;
 filter: grayscale(100%);
 }
 </style>
</head>

<body>

 <div class="container mx-auto px-3" style="max-width: 600px;">

 <header class="dashboard-header animate__animated animate__fadeInDown">
