 [data-theme="clay"] .progress { box-shadow: var(--shadow-pressed); border: none; }
 [data-theme="clay"] .progress-bar { box-shadow: var(--shadow-inner), 0 0 10px var(--accent-glow); }
 [data-theme="clay"] .progress-bar.complete { background-color: #ffb300; box-shadow: var(--shadow-inner), 0 0 15px rgba(255,179,0,0.6); }
 [data-theme="clay"] #progressText.complete { color: var(--text-main); }

 [data-theme="neo"] .progress { border-radius: 0; box-shadow: var(--shadow-bubble); }
 [data-theme="neo"] .progress-bar { border-right: 4px solid #000; }
 [data-theme="neo"] .progress-bar.complete { background-color: var(--accent-yellow); box-shadow: none; }
 [data-theme="neo"] #progressText.complete { background: var(--accent); color: #000; border: 2px solid #000; padding: 0 5px; }

 [data-theme="minimal"] .progress { border: none; box-shadow: none; margin-bottom: 30px; }
 [data-theme="minimal"] .progress-bar.complete { background-color: #e5e5e5; box-shadow: none; }
 [data-theme="minimal"] #progressText.complete { color: #111; }

 /* Floating Timer */
 #floatingTimer {
 position: fixed; bottom: 85px; left: 50%; transform: translateX(-50%) translateY(200%);
 background: var(--timer-bg); color: var(--timer-color); border: var(--timer-border); box-shadow: var(--timer-shadow);
 padding: 12px 30px; border-radius: 30px; font-weight: 700; font-size: 1.5rem; font-family: var(--font-mono);
 z-index: 999; transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1), background 0.3s; display: flex; align-items: center; gap: 10px; cursor: pointer;
 }
 #floatingTimer.show { transform: translateX(-50%) translateY(0); }
 #floatingTimer.done { background: var(--accent); color: var(--bg-color); border-color: transparent; }

 [data-theme="clay"] #floatingTimer.done { box-shadow: 0 10px 40px var(--accent-glow), inset 4px 4px 8px rgba(255,255,255,0.5); }
 [data-theme="neo"] #floatingTimer { border-radius: 0; font-weight: 800; font-size: 2rem; }
 [data-theme="neo"] #floatingTimer.done { background: var(--accent-red); color: #fff; animation: shake 0.5s infinite; border-color: #000; }
 [data-theme="minimal"] #floatingTimer { border-radius: 0; box-shadow: 4px 4px 0 rgba(0,0,0,1); }

 @keyframes shake { 0% {transform: translateX(-50%) rotate(0deg);} 25% {transform: translateX(-52%) rotate(-2deg);} 50% {transform: translateX(-50%) rotate(0deg);} 75% {transform: translateX(-48%) rotate(2deg);} 100% {transform: translateX(-50%) rotate(0deg);} }

 /* Media Cards */
 .media-card {
 border-radius: var(--radius-card); padding: 20px; display: flex; flex-direction: column; align-items: center; justify-content: center;
 font-weight: 700; font-size: 1.1rem; color: var(--text-main) !important; border: var(--border-card); width: 100%; box-shadow: var(--shadow-card); transition: all 0.2s; background: var(--card-bg);
 }
 .media-card:active { transform: scale(0.95); }

 [data-theme="flat"] .bg-spotify { background: linear-gradient(135deg, #1db954, #128238); color: #fff !important; }
 [data-theme="flat"] .bg-podcast { background: linear-gradient(135deg, #8e44ad, #5e2a75); color: #fff !important; }

 [data-theme="clay"] .media-card { box-shadow: var(--shadow-card), var(--shadow-inner); color: #fff !important; border: none; }
 [data-theme="clay"] .media-card:active { box-shadow: var(--shadow-pressed); }
 [data-theme="clay"] .bg-spotify { background: #1db954; }
 [data-theme="clay"] .bg-podcast { background: #8e44ad; }

 [data-theme="neo"] .media-card { border-radius: 0; border: 4px solid #000; box-shadow: 6px 6px 0 #000; color: #000 !important; font-weight: 800; text-transform: uppercase; }
 [data-theme="neo"] .media-card:active { transform: translate(6px, 6px); box-shadow: 0 0 0 #000; }
 [data-theme="neo"] .bg-spotify { background: var(--accent); }
 [data-theme="neo"] .bg-podcast { background: var(--accent-blue); }

 [data-theme="minimal"] .media-card { border-radius: 0; }
 [data-theme="minimal"] .media-card:active { border-color: #000; background: #f9f9f9; }

 /* Modals & Footer */
 .modal-content { background: var(--card-bg); border-radius: var(--radius-card); border: var(--border-card); box-shadow: 0 10px 30px rgba(0,0,0,0.5); }
 .modal-header, .modal-footer { border-color: rgba(128,128,128,0.2); }
 .btn-close { filter: invert(1) grayscale(100%) brightness(200%); }

 [data-theme="clay"] .modal-content { box-shadow: 0 20px 50px rgba(163, 177, 198, 0.8), var(--shadow-inner); border: none; }
 [data-theme="clay"] .btn-close, [data-theme="neo"] .btn-close, [data-theme="minimal"] .btn-close { filter: none; }

 [data-theme="neo"] .modal-content { border-radius: 0; border: 4px solid #000; box-shadow: 12px 12px 0 #000; }
 [data-theme="neo"] .modal-header { background: var(--accent-yellow); border-bottom: 4px solid #000; }

 [data-theme="minimal"] .modal-content { border-radius: 0; border: 1px solid #000; box-shadow: 8px 8px 0 rgba(0,0,0,0.1); }

 .audio-list-item { background: rgba(128,128,128,0.05); border-radius: var(--radius-btn); padding: 15px; margin-bottom: 12px; display: flex; align-items: center; text-decoration: none; color: var(--text-main); font-weight: 600; border: var(--border-card); }
 [data-theme="clay"] .audio-list-item { background: #d1d9e6; box-shadow: var(--shadow-pressed); border: none; }
 [data-theme="neo"] .audio-list-item { background: #fff; border: 2px solid #000; box-shadow: 3px 3px 0 #000; font-family: var(--font-mono); border-radius: 0; }
 [data-theme="neo"] .audio-list-item:active { transform: translate(3px,3px); box-shadow: 0 0 0 #000; background: var(--accent); }
 [data-theme="minimal"] .audio-list-item { border-radius: 0; background: #fff; border: 1px solid #e5e5e5; }

 footer { position: fixed; bottom: 0; width: 100%; background: var(--header-bg); backdrop-filter: blur(10px); border-top: var(--header-border); padding: 15px 0; text-align: center; font-size: 0.85rem; z-index: 1000; transition: all 0.3s ease; }
 footer a { color: var(--accent); text-decoration: none; font-weight: 700; }
 .footer-avatar { width: 24px; height: 24px; border-radius: 50%; vertical-align: middle; margin-right: 8px; }

 [data-theme="neo"] footer { background: #fff; border-top: 4px solid #000; font-family: var(--font-mono); font-weight: 800; }
 [data-theme="neo"] footer a { color: var(--accent-blue); text-transform: uppercase; }
 [data-theme="neo"] .footer-avatar { border-radius: 0; }
 [data-theme="minimal"] footer { font-family: var(--font-mono); }
 [data-theme="minimal"] footer a { color: #111; text-decoration: underline; }
 [data-theme="minimal"] .footer-avatar { border-radius: 0; filter: grayscale(100%); }

 </style>
</head>

<body>

 <div class="container mx-auto px-3" style="max-width: 600px;">

 <header class="dashboard-header px-1 animate__animated animate__fadeInDown">
 <div class="brand-logo">FITFORGE</div>
 <div class="d-flex gap-2 align-items-center">
 <button class="btn-action" id="voiceToggle" onclick="toggleVoice()"><i class="fa-solid fa-volume-xmark"></i></button>
 <button class="btn-action" onclick="shareApp()"><i class="fa-solid fa-share-nodes"></i></button>

 <div class="dropdown d-inline-block">
 <button class="btn-action" type="button" data-bs-toggle="dropdown" aria-expanded="false">
 <i class="fa-solid fa-palette"></i>
 </button>
 <ul class="dropdown-menu dropdown-menu-end shadow-sm">
 <li><button class="dropdown-item" onclick="setTheme('flat')"><i class="fa-solid fa-moon me-2"></i> Flat Dark</button></li>
 <li><button class="dropdown-item" onclick="setTheme('clay')"><i class="fa-solid fa-cloud me-2"></i> White Clay</button></li>
 <li><button class="dropdown-item" onclick="setTheme('neo')"><i class="fa-solid fa-shapes me-2"></i> Neo Brutal</button></li>
 <li><button class="dropdown-item" onclick="setTheme('minimal')"><i class="fa-solid fa-minus me-2"></i> Minimalist</button></li>
 </ul>
 </div>
 </div>
 </header>

 <div class="mb-4 animate__animated animate__fadeIn" id="dateHeaderContainer">
 <h6 class="text-uppercase text-muted" style="letter-spacing: 2px; font-size: 0.8rem; font-weight: 700;">// <span id="currentDay"></span></h6>
 <h2 class="brand-font mt-1 mb-0" id="focusArea" style="font-size: 1.6rem; color: var(--text-main);">LOADING...</h2>
 </div>

 <div class="mb-5 animate__animated animate__fadeIn" id="progressContainer" style="display:none;">
 <div class="d-flex justify-content-between mb-2" style="font-size: 0.85rem; font-weight: 700; text-transform: uppercase; font-family: var(--font-mono);">
 <span class="text-muted">Progress</span>
 <span id="progressText" style="color: var(--accent);">0%</span>
 </div>
 <div class="progress">
 <div class="progress-bar" id="workoutProgress" role="progressbar" style="width: 0%"></div>
 </div>
 </div>

 <div id="workoutContent"></div>

 <h5 class="mt-5 mb-4 brand-font text-center animate__animated animate__fadeIn" id="audioHeader" style="font-size: 1.1rem; color: var(--text-main);">🎧 THE ZONE</h5>
 <div class="row g-3 mb-5 pb-4 animate__animated animate__fadeInUp">
 <div class="col-6"><button class="media-card bg-spotify" onclick="openAudioModal('playlists')"><i class="fa-brands fa-spotify fa-2x mb-2"></i><span>Music</span></button></div>
 <div class="col-6"><button class="media-card bg-podcast" onclick="openAudioModal('podcasts')"><i class="fa-solid fa-podcast fa-2x mb-2"></i><span>Podcasts</span></button></div>
 </div>
 </div>

 <div id="floatingTimer" onclick="dismissTimer()"><i class="fa-solid fa-stopwatch me-2"></i> <span id="timerDisplay">00:00</span></div>

 <div class="modal fade" id="weeklyModal" tabindex="-1" aria-hidden="true">
 <div class="modal-dialog modal-dialog-centered modal-dialog-scrollable">
 <div class="modal-content">
 <div class="modal-header"><h5 class="modal-title brand-font fs-6">PROTOCOL OVERVIEW</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div>
 <div class="modal-body" id="weeklyContent" style="font-size: 0.95rem; line-height: 1.6; font-family: var(--font-mono);"></div>
 </div>
 </div>
 </div>

 <div class="modal fade" id="audioModal" tabindex="-1" aria-hidden="true">
 <div class="modal-dialog modal-dialog-centered modal-dialog-scrollable">
 <div class="modal-content">
 <div class="modal-header d-flex flex-column align-items-start">
 <div class="d-flex justify-content-between w-100 mb-3"><h5 class="modal-title brand-font fs-6" id="audioModalTitle">AUDIO</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div>
 <div class="w-100 p-2" style="background: rgba(128,128,128,0.1); border: var(--border-card); border-radius: var(--radius-btn);">
 <div class="btn-group w-100" role="group" id="deviceToggleGroup" style="background: var(--card-bg);">
 <input type="radio" class="btn-check" name="deviceToggle" id="btnIphone" value="ios" checked><label class="btn btn-outline-secondary btn-sm" style="border-color: var(--border-bubble);" for="btnIphone"><i class="fa-brands fa-apple"></i> iOS</label>
 <input type="radio" class="btn-check" name="deviceToggle" id="btnAndroid" value="android"><label class="btn btn-outline-secondary btn-sm" style="border-color: var(--border-bubble);" for="btnAndroid"><i class="fa-brands fa-android"></i> Android</label>
 <input type="radio" class="btn-check" name="deviceToggle" id="btnWeb" value="web"><label class="btn btn-outline-secondary btn-sm" style="border-color: var(--border-bubble);" for="btnWeb"><i class="fa-solid fa-globe"></i> Web</label>
 </div>
 </div>
 </div>
 <div class="modal-body" id="audioModalList" style="background: var(--bg-color);"></div>
 </div>
 </div>
 </div>

 <footer>
 <div class="container d-flex justify-content-center align-items-center">
 <img src="Personality.svg" alt="Avatar" class="footer-avatar" onerror="this.style.display='none'">
 <span>DEV: <a href="https://bikkina.vercel.app" target="_blank">ITSMERAMC</a></span>
 </div>
 </footer>

 <script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
 <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>

 <script>
 // --- 1. THEME ENGINE ---
 const themeMeta = document.getElementById('themeColorMeta');
 let currentTheme = localStorage.getItem('fitforge_theme') || 'flat';

 function setTheme(theme) {
 currentTheme = theme;
 document.body.setAttribute('data-theme', theme);
 localStorage.setItem('fitforge_theme', theme);

 // Update Meta Color for mobile notch
 let metaColor = '#0a0a0a';
 if(theme === 'clay') metaColor = '#e0e5ec';
 if(theme === 'neo') metaColor = '#f4f0ea';
 if(theme === 'minimal') metaColor = '#fcfcfc';
 themeMeta.setAttribute('content', metaColor);

 // Re-trigger progress bar coloring to snap to new theme CSS classes
 calculateProgress(false); 
 applyThemeHacks(theme);
 }

 // Tiny JS structural adjustments needed for specific themes
 function applyThemeHacks(theme) {
 const dateContainer = $('#dateHeaderContainer');
 const audioHeader = $('#audioHeader');
 if(theme === 'neo') {
 dateContainer.attr('style', 'border: 4px solid #000; background: #fff; padding: 15px; box-shadow: 6px 6px 0 #000; margin-bottom: 30px !important;');
 $('#currentDay').attr('style', 'background: #000; color: #fff; padding: 2px 6px;');
 audioHeader.attr('style', 'font-size: 1.2rem; background: #000; color: #fff; padding: 10px; border: 4px solid #000; transform: rotate(-1deg); box-shadow: 6px 6px 0 var(--accent-red);');
 } else {
 dateContainer.attr('style', '');
 $('#currentDay').attr('style', '');
 audioHeader.attr('style', 'font-size: 1.1rem; color: var(--text-main);');
 }
 }

 setTheme(currentTheme); // Initialize Theme

 // --- 2. CORE LOGIC ---
 if ('serviceWorker' in navigator) { window.addEventListener('load', () => { navigator.serviceWorker.register('sw.js').catch(e => console.log('SW fail')); }); }

 let appData = null; let currentAudioType = 'playlists'; let totalTasks = 0; let timerInterval;
 const todayDateStr = new Date().toDateString();
 let savedState = JSON.parse(localStorage.getItem('fitforge_state')) || {};

 if (savedState.date !== todayDateStr || !savedState.checkedSets) {
 let existingVoice = savedState.voiceEnabled || false;
 savedState = { date: todayDateStr, checkedSets: {}, finisherDone: false, hasCelebrated: false, voiceEnabled: existingVoice };
 localStorage.setItem('fitforge_state', JSON.stringify(savedState));
 }

 $(document).ready(function () {
 if (savedState.voiceEnabled) { $('#voiceToggle').addClass('active').find('i').removeClass('fa-volume-xmark').addClass('fa-volume-high'); }
 fetch('data.json').then(res => res.json()).then(data => { appData = data; initApp(); }).catch(err => { $('#workoutContent').html(`<div class="alert alert-danger font-monospace">Server/Vercel required to fetch data.json</div>`); });
 $('input[name="deviceToggle"]').on('change', function () { if (appData) renderAudioList(currentAudioType); });

 $(document).on('click', '.set-bubble', function () {
 let exId = $(this).data('ex'); let setIdx = $(this).data('set'); let restTime = $(this).data('rest');
 let $card = $(this).closest('.workout-card');

 if ($(this).hasClass('active')) {
 $(this).removeClass('active'); savedState.checkedSets[exId] = savedState.checkedSets[exId].filter(s => s !== setIdx);
 } else {
 $(this).addClass('active'); savedState.checkedSets[exId].push(setIdx); startRestTimer(restTime);
 }

 if (savedState.checkedSets[exId].length === $card.find('.set-bubble').length) { $card.addClass('completed-card'); } else { $card.removeClass('completed-card'); }
 calculateProgress(true);
 });

 $(document).on('change', '#finisherToggle', function () {
 savedState.finisherDone = this.checked;
 if (this.checked) { $('#card-finisher').addClass('completed-card'); } else { $('#card-finisher').removeClass('completed-card'); }
 calculateProgress(true);
 });
 });

 function toggleVoice() {
 savedState.voiceEnabled = !savedState.voiceEnabled; localStorage.setItem('fitforge_state', JSON.stringify(savedState));
 const $icon = $('#voiceToggle i');
 if (savedState.voiceEnabled) {
 $('#voiceToggle').addClass('active'); $icon.removeClass('fa-volume-xmark').addClass('fa-volume-high');
 let speech = new SpeechSynthesisUtterance(""); window.speechSynthesis.speak(speech);
 } else {
 $('#voiceToggle').removeClass('active'); $icon.removeClass('fa-volume-high').addClass('fa-volume-xmark');
 }
 }

 function buildCardHTML(ex, exId, index, bubblesHtml, isExComplete, isOptional) {
 let optBadge = isOptional ? `<span class="badge bg-dark me-2" style="background:var(--text-muted)!important; color:var(--bg-color)!important;">OPT</span>` : '';
 return `
 <div class="workout-card animate__animated animate__fadeInUp ${isExComplete ? 'completed-card' : ''}" id="card-${exId}" style="animation-delay: ${index * 0.1}s;">
 <div class="ex-header"><h3 class="ex-title">${optBadge}${ex.name}</h3><span class="badge bg-dark">${ex.sets}x${ex.reps}</span></div>
 <div class="set-container">${bubblesHtml}</div>
 <div class="anatomy-toggle" onclick="$(this).next('.anatomy-content').slideToggle(150);"><i class="fa-solid fa-dna me-2"></i> SCIENCE</div>
 <div class="anatomy-content">${ex.anatomy_pov}</div>
 <div class="machine-alt"><i class="fa-solid fa-repeat me-1"></i> ALT: ${ex.machine_alternative}</div>
 </div>
 `;
 }

 function initApp() {
 const daysProper = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
 const todayName = daysProper[new Date().getDay()];
 $('#currentDay').text(todayName);

 const todaysPlan = appData.schedule.find(day => day.day_of_week === todayName);
 $('#focusArea').text(todaysPlan.focus);
 const $content = $('#workoutContent');

 if (todaysPlan.is_rest_day) {
 $content.append(`<div class="workout-card text-center py-5 animate__animated animate__zoomIn"><i class="fa-solid fa-battery-half fa-4x mb-4" style="color: var(--accent);"></i><h3 class="brand-font mb-3">RECOVERY</h3><p class="px-3 mb-0" style="font-weight: 600; font-family: var(--font-mono);">${todaysPlan.notes}</p></div>`);
 } else {
 $('#progressContainer').show();
 totalTasks = 0;

 todaysPlan.exercises.forEach((ex, index) => {
 let exId = `ex${index}`;
 if (!savedState.checkedSets[exId]) savedState.checkedSets[exId] = [];
 let isExComplete = savedState.checkedSets[exId].length === ex.sets;

 let bubblesHtml = '';
 for (let s = 0; s < ex.sets; s++) {
 totalTasks++;
 let isActive = savedState.checkedSets[exId].includes(s) ? 'active' : '';
 bubblesHtml += `<div class="set-bubble ${isActive}" data-ex="${exId}" data-set="${s}" data-rest="${ex.rest_seconds || 60}">${s + 1}</div>`;
 }
 $content.append(buildCardHTML(ex, exId, index, bubblesHtml, isExComplete, false));
 });

 if (todaysPlan.optional_exercises && todaysPlan.optional_exercises.length > 0) {
 $content.append(`
 <div class="text-center mt-5 mb-4 animate__animated animate__fadeInUp" style="animation-delay: 0.3s;">
 <button class="btn-action mx-auto" style="font-size: 0.95rem; font-family: var(--font-mono);" type="button" data-bs-toggle="collapse" data-bs-target="#optionalWorkouts">
 OPTIONAL VOLUME <i class="fa-solid fa-chevron-down ms-2"></i>
 </button>
 </div>
 <div class="collapse" id="optionalWorkouts"></div>
 `);

 const $optionalContainer = $('#optionalWorkouts');
 todaysPlan.optional_exercises.forEach((ex, index) => {
 let exId = `opt${index}`;
 if (!savedState.checkedSets[exId]) savedState.checkedSets[exId] = [];
 let isExComplete = savedState.checkedSets[exId].length === ex.sets;

 let bubblesHtml = '';
 for (let s = 0; s < ex.sets; s++) {
 let isActive = savedState.checkedSets[exId].includes(s) ? 'active' : '';
 bubblesHtml += `<div class="set-bubble ${isActive}" data-ex="${exId}" data-set="${s}" data-rest="${ex.rest_seconds || 60}">${s + 1}</div>`;
 }
 $optionalContainer.append(buildCardHTML(ex, exId, index, bubblesHtml, isExComplete, true));
 });
 }

 if (todaysPlan.finisher) {
 totalTasks++;
 let isChecked = savedState.finisherDone ? 'checked' : '';
 $content.append(`
 <div class="workout-card animate__animated animate__fadeInUp ${savedState.finisherDone ? 'completed-card' : ''} mt-4" id="card-finisher" style="animation-delay: 0.5s;">
 <h5 class="text-uppercase mb-4" style="font-size: 1.1rem; font-weight: 800;"><i class="fa-solid fa-fire me-2" style="color: #ff5252;"></i> BURNOUT FINISHER</h5>
 <label class="finisher-label"><input type="checkbox" class="finisher-checkbox" id="finisherToggle" ${isChecked}><span class="flex-grow-1">${todaysPlan.finisher.name}</span><span class="badge bg-dark">${todaysPlan.finisher.duration_minutes ? todaysPlan.finisher.duration_minutes + ' MIN' : todaysPlan.finisher.sets + 'x' + todaysPlan.finisher.reps}</span></label>
 <div class="machine-alt mt-4">ALT: ${todaysPlan.finisher.machine_alternative}</div>
 </div>
 `);
 }
 calculateProgress(false);
 }

 const $weekly = $('#weeklyContent');
 appData.schedule.forEach(day => {
 let isToday = day.day_of_week === todayName ? '<span class="badge bg-dark ms-2" style="font-size:0.6rem;">TODAY</span>' : '';
 let dayHtml = `<div class="mb-4 pb-3" style="border-bottom: 1px solid rgba(128,128,128,0.2);"><strong class="d-block mb-2" style="font-size:1.1rem;">${day.day_of_week} ${isToday}<br><span style="color: var(--accent); font-size: 0.9rem;">${day.focus}</span></strong>`;
 if (day.is_rest_day) {
 dayHtml += `<span style="font-size: 0.85rem; font-weight:700; background:var(--text-main); color:var(--bg-color); padding:2px 5px;">REST</span>`;
 } else {
 let optText = day.optional_exercises ? ` <span style="color:#ff5252;">(+${day.optional_exercises.length} OPT)</span>` : '';
 dayHtml += `<span style="font-size: 0.85rem; font-weight:600; color:var(--text-muted);">${day.exercises.map(ex => ex.name).join(', ')}${optText}</span>`;
 }
 $weekly.append(dayHtml + `</div>`);
 });
 }

 function calculateProgress(triggerAnimation) {
 let completedSetsCount = 0;
 for (const exId in savedState.checkedSets) { completedSetsCount += savedState.checkedSets[exId].length; }
 if (savedState.finisherDone) completedSetsCount++;
 let percentage = totalTasks === 0 ? 0 : Math.min(100, Math.round((completedSetsCount / totalTasks) * 100));

 $('#workoutProgress').css('width', percentage + '%');

 // Pure CSS Class Swapping for Theming
 if (percentage === 100) {
 if (triggerAnimation && !savedState.hasCelebrated) { triggerConfetti(); savedState.hasCelebrated = true; }
 $('#workoutProgress').addClass('complete');
 $('#progressText').text("DONE 🏆").addClass('complete');
 } else {
 savedState.hasCelebrated = false;
 $('#workoutProgress').removeClass('complete');
 $('#progressText').text(percentage + '%').removeClass('complete');
 }
 localStorage.setItem('fitforge_state', JSON.stringify(savedState));
 }

 function startRestTimer(seconds) {
 clearInterval(timerInterval);
 const $timer = $('#floatingTimer'); const $display = $('#timerDisplay');
 $timer.removeClass('done').addClass('show');
 let timeLeft = seconds;

 let initM = Math.floor(timeLeft / 60).toString().padStart(2, '0'); let initS = (timeLeft % 60).toString().padStart(2, '0');
 $display.text(`${initM}:${initS}`);

 timerInterval = setInterval(() => {
 timeLeft--;
 let m = Math.floor(timeLeft / 60).toString().padStart(2, '0'); let s = (timeLeft % 60).toString().padStart(2, '0');
 $display.text(`${m}:${s}`);

 if (timeLeft <= 0) {
 clearInterval(timerInterval); $timer.addClass('done'); $display.text("LIFT!");
 if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
 if (savedState.voiceEnabled && 'speechSynthesis' in window) {
 let speech = new SpeechSynthesisUtterance("Rest is over. Let's get back to your next rep.");
 let voices = window.speechSynthesis.getVoices();
