 <label class="finisher-label"><input type="checkbox" class="finisher-checkbox" id="finisherToggle" ${isChecked}><span class="flex-grow-1">${todaysPlan.finisher.name}</span><span class="badge bg-dark text-white">${todaysPlan.finisher.duration_minutes ? todaysPlan.finisher.duration_minutes + ' Min' : todaysPlan.finisher.sets + 'x' + todaysPlan.finisher.reps}</span></label>
 <div class="machine-alt mt-4"><i class="fa-solid fa-repeat me-2"></i> Alt: ${todaysPlan.finisher.machine_alternative}</div>
 </div>
 `);
 }

 calculateProgress(false);
 }

 const $weekly = $('#weeklyContent');
 appData.schedule.forEach(day => {
 let isToday = day.day_of_week === todayName ? '<span class="badge bg-success ms-3" style="font-size:0.7rem;">TODAY</span>' : '';
 let dayHtml = `<div class="mb-4 pb-3" style="border-bottom: 1px solid rgba(255,255,255,0.05);"><strong class="d-block text-white mb-2" style="font-size:1.1rem; letter-spacing:0.5px;">${day.day_of_week} ${isToday}<br><span style="color: var(--accent-color); font-size: 0.9rem;">${day.focus}</span></strong>`;
 if (day.is_rest_day) { dayHtml += `<span class="text-muted" style="font-size: 0.85rem;">Active Recovery</span>`; } else { let optText = day.optional_exercises ? ` <span style="color:#888;">(+${day.optional_exercises.length} Opt)</span>` : ''; dayHtml += `<span class="text-white" style="font-size: 0.85rem; opacity:0.8;">${day.exercises.map(ex => ex.name).join(', ')}${optText}</span>`; }
 $weekly.append(dayHtml + `</div>`);
 });
 }

 function calculateProgress(triggerAnimation) {
 let completedSetsCount = 0;
 for (const exId in savedState.checkedSets) { completedSetsCount += savedState.checkedSets[exId].length; }
 if (savedState.finisherDone) completedSetsCount++;
 let percentage = totalTasks === 0 ? 0 : Math.min(100, Math.round((completedSetsCount / totalTasks) * 100));

 $('#workoutProgress').css('width', percentage + '%');

 if (percentage === 100) {
 if (triggerAnimation && !savedState.hasCelebrated) { triggerConfetti(); savedState.hasCelebrated = true; }
 $('#progressText').text("PROTOCOL COMPLETE 🏆").css('color', '#fff');

 if(currentTheme === 'clay') {
 $('#workoutProgress').css('background-color', '#ffb300').css('box-shadow', 'inset 4px 4px 8px rgba(255,255,255,0.4), inset -4px -4px 8px rgba(0,0,0,0.2), 0 0 15px rgba(255,179,0,0.6)');
 } else {
 $('#workoutProgress').css('background-color', '#ffb300').css('box-shadow', '0 0 20px #ffb300');
 }
 } else {
 savedState.hasCelebrated = false;
 $('#progressText').text(percentage + '%').css('color', 'var(--accent-color)');
 if(currentTheme === 'clay') {
 $('#workoutProgress').css('background-color', 'var(--accent-color)').css('box-shadow', 'var(--clay-active-inner), 0 0 15px var(--accent-glow)');
 } else {
 $('#workoutProgress').css('background-color', 'var(--accent-color)').css('box-shadow', '0 0 15px var(--accent-glow)');
 }
 }
 localStorage.setItem('fitforge_state', JSON.stringify(savedState));
 }

 function startRestTimer(seconds) {
 clearInterval(timerInterval);
 const $timer = $('#floatingTimer'); const $display = $('#timerDisplay');
 $timer.removeClass('done').addClass('show');
 let timeLeft = seconds;

 let initM = Math.floor(timeLeft / 60).toString().padStart(2, '0'); let initS = (timeLeft % 60).toString().padStart(2, '0');
 $display.text(`${initM}:${initS}`);

 timerInterval = setInterval(() => {
