 <script>
 let appData = null;
 let currentAudioType = 'playlists';
 let totalTasks = 0;
 let timerInterval;

 // --- LOCAL STORAGE SETUP ---
 const todayDateStr = new Date().toDateString(); // e.g., "Fri Mar 13 2026"
 let savedState = JSON.parse(localStorage.getItem('fitforge_state')) || {};

 // Reset state if it's a new day
 if (savedState.date !== todayDateStr) {
 savedState = { date: todayDateStr, checkedIds: [], hasCelebrated: false };
 localStorage.setItem('fitforge_state', JSON.stringify(savedState));
 }

 $(document).ready(function () {
 fetch('data.json').then(res => res.json()).then(data => { appData = data; initApp(); })
 .catch(err => {
 $('#focusArea').text("Data Error");
 $('#workoutContent').html(`<div class="alert alert-danger">Could not load data.json. Viewing locally? Must use a server/Vercel.</div>`);
 });

 $('input[name="deviceToggle"]').on('change', function () { if (appData) renderAudioList(currentAudioType); });
 });

 function initApp() {
 const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
 const todayName = days[new Date().getDay()];
 $('#currentDay').text(todayName);

 const todaysPlan = appData.schedule.find(day => day.day_of_week === todayName);
 $('#focusArea').text(todaysPlan.focus);
 const $content = $('#workoutContent');

 if (todaysPlan.is_rest_day) {
 $content.append(`
 <div class="text-center py-5 animate__animated animate__zoomIn">
 <i class="fa-solid fa-battery-half fa-3x mb-3" style="color: var(--accent-color);"></i>
 <h4 class="brand-font text-white">Recovery Mode</h4>
 <p class="text-muted mt-2 px-3">${todaysPlan.notes}</p>
 </div>`);
 } else {
 $('#progressContainer').show();

 todaysPlan.exercises.forEach((ex, index) => {
 totalTasks++;
 let exId = `ex${index}`;
 let isChecked = savedState.checkedIds.includes(exId) ? 'checked' : '';
 let isDoneClass = isChecked ? 'exercise-done' : '';
 let cardDoneClass = isChecked ? 'completed-card' : '';

 $content.append(`
 <div class="workout-card animate__animated animate__fadeInUp ${cardDoneClass}" style="animation-delay: ${index * 0.1}s">
 <div class="form-check d-flex align-items-center mb-1">
 <input class="form-check-input task-checkbox" type="checkbox" id="${exId}" ${isChecked}>
 <label class="form-check-label flex-grow-1 ${isDoneClass}" for="${exId}">
 ${ex.name} <span class="badge bg-dark border border-secondary float-end text-white">${ex.sets}x${ex.reps}</span>
 </label>
 </div>
 <div class="anatomy-toggle" onclick="$(this).next('.anatomy-content').slideToggle(200);"><i class="fa-solid fa-dna me-2"></i> Muscle Science</div>
 <div class="anatomy-content">${ex.anatomy_pov}</div>
 <div class="machine-alt"><i class="fa-solid fa-repeat me-1"></i> Alt: ${ex.machine_alternative}</div>
 </div>
 `);
 });

 if (todaysPlan.finisher) {
 totalTasks++;
 let exId = `finisher`;
 let isChecked = savedState.checkedIds.includes(exId) ? 'checked' : '';
 let isDoneClass = isChecked ? 'exercise-done' : '';

 $content.append(`
 <div class="workout-card animate__animated animate__fadeInUp" style="animation-delay: 0.5s; border-left: 3px solid #ff3b30;">
 <h6 class="text-uppercase text-muted mb-2" style="font-size: 0.75rem; letter-spacing: 1px;"><i class="fa-solid fa-fire text-danger me-1"></i> Burnout Finisher</h6>
 <div class="form-check d-flex align-items-center mb-1">
 <input class="form-check-input task-checkbox" type="checkbox" id="${exId}" ${isChecked}>
