 <div class="machine-alt mt-2"><i class="fa-solid fa-repeat me-1"></i> Alt: ${todaysPlan.finisher.machine_alternative}</div>
 </div>
 `);
 }

 // Initial Progress Calc on load
 calculateProgress(false);

 // Checkbox Event Listener
 $('.task-checkbox').on('change', function () {
 const $label = $(this).siblings('label');
 const $card = $(this).closest('.workout-card');

 if(this.checked) {
 $label.addClass('exercise-done');
 $card.addClass('completed-card');
 startRestTimer(60); // START 60 SECOND REST
 } else {
 $label.removeClass('exercise-done');
 $card.removeClass('completed-card');
 }
 calculateProgress(true);
 });
 }

 // Populate Weekly Modal
 const $weekly = $('#weeklyContent');
 appData.schedule.forEach(day => {
 let isToday = day.day_of_week === todayName ? '<span class="badge bg-success ms-2">Today</span>' : '';
