<!-- Scripts -->
<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js"></script>
<script src="https://code.jquery.com/jquery-3.7.1.min.js"></script>
<script src="https://unpkg.com/aos@2.3.4/dist/aos.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.4/gsap.min.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.4/ScrollTrigger.min.js"></script>

<script>
// ─── INIT ───────────────────────────────────────────────────────
document.addEventListener('DOMContentLoaded', function () {

 // Hide loader
 setTimeout(() => {
 document.getElementById('loader').classList.add('hidden');
 }, 1800);

 // Init AOS
 AOS.init({
 duration: 900,
 easing: 'ease-out-cubic',
 once: false,
 offset: 80
 });

 // GSAP + ScrollTrigger registration
 gsap.registerPlugin(ScrollTrigger);

 // ── Hero GSAP timeline
 const heroTl = gsap.timeline({ delay: 2 });
 heroTl
 .from('.hero-frame', { opacity: 0, scale: 0.9, duration: 1.2, ease: 'power2.out' })
 .from('.frame-corner', { opacity: 0, stagger: 0.1, duration: 0.3 }, '-=0.5');

 // ── Section titles
 gsap.utils.toArray('.section-title').forEach(el => {
 gsap.from(el, {
 scrollTrigger: { trigger: el, start: 'top 80%' },
 y: 30, opacity: 0, duration: 0.8, ease: 'power2.out'
 });
 });

 // ── Event cards GSAP entrance
 gsap.utils.toArray('.event-card').forEach((card, i) => {
 const dir = i % 2 === 0 ? -60 : 60;
 gsap.from(card, {
 scrollTrigger: { trigger: card, start: 'top 80%' },
 x: dir, opacity: 0, duration: 0.9, ease: 'back.out(1.2)'
 });
 });

 // ── Profile cards
 gsap.utils.toArray('.profile-card').forEach((card, i) => {
 gsap.from(card, {
 scrollTrigger: { trigger: card, start: 'top 75%' },
 y: 50, opacity: 0, duration: 1, ease: 'power3.out', delay: i * 0.1
 });
 });

 // ─── NAVBAR scroll behavior
 $(window).scroll(function () {
 if ($(this).scrollTop() > 80) {
 $('#mainNav').addClass('scrolled');
 $('#scrollTop').addClass('visible');
 } else {
 $('#mainNav').removeClass('scrolled');
 $('#scrollTop').removeClass('visible');
 }
 });

 // ─── COUNTDOWN
 countdownTimer();
 setInterval(countdownTimer, 1000);

 // ─── MUSIC
 const musicBtn = document.getElementById('musicBtn');
 const bgMusic = document.getElementById('bgMusic');
 const musicNote = document.getElementById('musicNote');
 bgMusic.volume = 0.25;

 musicBtn.addEventListener('click', function () {
 if (bgMusic.paused) {
 bgMusic.play().then(() => {
 musicBtn.classList.add('playing');
 musicBtn.innerHTML = '<i class="fas fa-pause"></i>';
 musicNote.classList.add('show');
 setTimeout(() => musicNote.classList.remove('show'), 2500);
 }).catch(() => {});
 } else {
 bgMusic.pause();
 musicBtn.classList.remove('playing');
 musicBtn.innerHTML = '<i class="fas fa-music"></i>';
 }
 });

 // ─── Smooth nav scrolling
 $('a[href^="#"]').on('click', function (e) {
 e.preventDefault();
 const target = $(this.getAttribute('href'));
 if (target.length) {
 $('html, body').animate({ scrollTop: target.offset().top - 70 }, 700);
 }
 });
});

// ─── COUNTDOWN TIMER ─────────────────────────────────────────────
function countdownTimer() {
 const muhurtham = new Date('2026-08-24T10:45:00+05:30').getTime();
 const now = new Date().getTime();
 const diff = muhurtham - now;

 if (diff <= 0) {
 document.getElementById('days').textContent = '000';
 document.getElementById('hours').textContent = '00';
 document.getElementById('minutes').textContent = '00';
 document.getElementById('seconds').textContent = '00';
 return;
 }

 const days = Math.floor(diff / (1000 * 60 * 60 * 24));
 const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
 const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
 const seconds = Math.floor((diff % (1000 * 60)) / 1000);

 const pad = (n, len = 2) => String(n).padStart(len, '0');

 animateNumber('days', pad(days, 3));
 animateNumber('hours', pad(hours));
 animateNumber('minutes', pad(minutes));
 animateNumber('seconds', pad(seconds));
}

const prevValues = {};
function animateNumber(id, val) {
 const el = document.getElementById(id);
 if (prevValues[id] !== val) {
 el.style.transform = 'translateY(-10px)';
 el.style.opacity = '0.5';
 setTimeout(() => {
 el.textContent = val;
 el.style.transform = 'translateY(0)';
 el.style.opacity = '1';
 }, 200);
 prevValues[id] = val;
 }
}

// ─── GALLERY LIGHTBOX ────────────────────────────────────────────
const galleryImgs = Array.from(document.querySelectorAll('.gallery-item img')).map(img => img.src);
let currentLightboxIdx = 0;

function openLightbox(idx) {
 currentLightboxIdx = idx;
 const lb = document.getElementById('lightbox');
 const img = document.getElementById('lightboxImg');
 img.src = galleryImgs[idx] || '';
 lb.classList.add('active');
 document.body.style.overflow = 'hidden';
}

function closeLightbox() {
 document.getElementById('lightbox').classList.remove('active');
 document.body.style.overflow = '';
}

function closeLightboxOutside(e) {
 if (e.target.id === 'lightbox') closeLightbox();
}

function prevImage(e) {
 e.stopPropagation();
 currentLightboxIdx = (currentLightboxIdx - 1 + galleryImgs.length) % galleryImgs.length;
 document.getElementById('lightboxImg').src = galleryImgs[currentLightboxIdx] || '';
}

function nextImage(e) {
 e.stopPropagation();
 currentLightboxIdx = (currentLightboxIdx + 1) % galleryImgs.length;
 document.getElementById('lightboxImg').src = galleryImgs[currentLightboxIdx] || '';
}

document.addEventListener('keydown', e => {
 if (document.getElementById('lightbox').classList.contains('active')) {
 if (e.key === 'Escape') closeLightbox();
 if (e.key === 'ArrowLeft') prevImage(e);
 if (e.key === 'ArrowRight') nextImage(e);
 }
});

// ─── RSVP FORM ───────────────────────────────────────────────────
function submitRSVP(e) {
 e.preventDefault();
 showToast('🙏 శుభాకాంక్షలు! Your RSVP has been noted. We look forward to celebrating with you!');
 e.target.reset();
}

function showToast(msg) {
