 font-size: 1.2rem;
 letter-spacing: 4px;
 text-transform: uppercase;
 color: var(--text-light);
 margin-bottom: 1rem;
}

.couple-names {
 font-size: 6rem; /* Huge for impact */
 color: var(--primary-accent);
 /* Gold Texture on Text */
 background: linear-gradient(to right, var(--primary-accent), #a00000, var(--primary-accent));
 -webkit-background-clip: text;
 background-clip: text;
 /* Fallback color if clip fails */
 -webkit-text-fill-color: transparent;
 color: var(--primary-accent);
 text-shadow: 2px 2px 4px rgba(0,0,0,0.1);
}

.date-location {
 font-size: 1.5rem;
 font-weight: 600;
 color: var(--text-color);
 margin-top: 1rem;
 border-top: 1px solid var(--luxury-gold);
 border-bottom: 1px solid var(--luxury-gold);
 padding: 10px 30px;
 display: inline-block;
}

/* =========================================
 4. MUHURTHAM COUNTDOWN
========================================== */
.countdown-section {
 background-color: var(--primary-accent);
 padding: 4rem 0;
 color: var(--primary-base);
}

.timer-box {
 display: flex;
 justify-content: center;
 gap: 2rem;
 flex-wrap: wrap;
}

.time-unit {
 text-align: center;
 background: rgba(0,0,0,0.2);
 border: 1px solid var(--luxury-gold);
 padding: 1.5rem;
 min-width: 120px;
 border-radius: 8px;
 position: relative;
}

.time-unit h3 {
 font-size: 3rem;
 margin: 0;
 color: var(--luxury-gold);
 font-family: var(--font-heading);
}

.time-unit p {
 margin: 0;
 font-size: 0.9rem;
 text-transform: uppercase;
 letter-spacing: 1px;
 color: var(--primary-base);
}

/* =========================================
 5. COUPLE SECTION (JHARKOHA STYLE)
========================================== */
.couple-card {
 text-align: center;
 padding: 2rem;
 transition: var(--ease-smooth);
}

.couple-img-frame {
 width: 280px;
 height: 350px;
 margin: 0 auto 2rem;
 position: relative;
 overflow: hidden;
 /* Arch Shape (Jharokha Style) */
 border-radius: 150px 150px 20px 20px; 
 border: 5px solid var(--luxury-gold);
 box-shadow: 0 10px 20px rgba(0,0,0,0.15);
}

.couple-img-frame img {
 width: 100%;
 height: 100%;
 object-fit: cover;
 transition: transform 0.5s ease;
}

.couple-card:hover .couple-img-frame img {
 transform: scale(1.1);
}

.couple-name {
 font-size: 2.5rem;
 color: var(--primary-accent);
}

.couple-bio {
 font-style: italic;
 color: var(--text-light);
 max-width: 80%;
 margin: 0 auto;
}

/* =========================================
 6. EVENTS TIMELINE (VERTICAL)
========================================== */
.timeline-section {
 position: relative;
 padding: 5rem 0;
}

/* Vertical Line */
.timeline-section::before {
 content: '';
 position: absolute;
 left: 50%;
 top: 0;
 bottom: 0;
 width: 2px;
 background: var(--luxury-gold);
 transform: translateX(-50%);
}

.event-card {
 background: #fff;
 border: 1px solid var(--luxury-gold);
 padding: 2rem;
 margin-bottom: 3rem;
 position: relative;
 box-shadow: 0 5px 15px rgba(0,0,0,0.05);
 border-radius: 8px;
}

/* Connector Dot */
.event-card::after {
 content: '🕉️'; /* Om Symbol or Dot */
 position: absolute;
 top: 50%;
 font-size: 1.5rem;
 background: var(--primary-base);
 border: 2px solid var(--luxury-gold);
 border-radius: 50%;
 width: 40px;
 height: 40px;
 display: flex;
 justify-content: center;
 align-items: center;
 transform: translateY(-50%);
 z-index: 2;
}

/* Left Side Events */
.timeline-left .event-card { margin-right: 50px; text-align: right; }
.timeline-left .event-card::after { right: -72px; }

/* Right Side Events */
.timeline-right .event-card { margin-left: 50px; text-align: left; }
.timeline-right .event-card::after { left: -72px; }

.event-title {
 color: var(--primary-accent);
 font-size: 2rem;
}

.event-time {
 color: var(--luxury-gold);
 font-weight: bold;
 font-size: 1.2rem;
 display: block;
 margin-bottom: 1rem;
}

/* =========================================
 7. FOOTER & UTILITIES
========================================== */
footer {
 background-color: #3e2723; /* Very Dark Brown */
 color: var(--luxury-gold);
 text-align: center;
 padding: 3rem 0;
}

.footer-om {
 font-size: 3rem;
 opacity: 0.5;
 margin-bottom: 1rem;
 display: block;
}

.btn-rsvp {
 background-color: var(--primary-accent);
 color: var(--primary-base);
 border: 1px solid var(--primary-accent);
 padding: 12px 30px;
 font-family: var(--font-heading);
 letter-spacing: 2px;
 text-transform: uppercase;
 transition: var(--ease-smooth);
}

.btn-rsvp:hover {
 background-color: transparent;
 color: var(--primary-accent);
}

/* =========================================
 8. MOBILE RESPONSIVE TWEAKS
========================================== */
@media (max-width: 768px) {
 .curtain-panel {
 background-size: 200% 100%; /* Larger folds on mobile */
 }

 .couple-names {
 font-size: 3.5rem; /* Smaller hero text */
 }

 /* Timeline Fix for Mobile: Stack everything */
 .timeline-section::before { left: 20px; } /* Move line to left */

 .timeline-left .event-card, 
 .timeline-right .event-card {
 margin: 0 0 2rem 50px; /* Push all cards right */
 text-align: left;
 }

 .timeline-left .event-card::after, 
 .timeline-right .event-card::after {
 left: -52px; /* Align dots to left line */
 right: auto;
 }

 .timer-box {
 gap: 1rem;
 }

 .time-unit {
 min-width: 80px;
 padding: 1rem;
 }

 .time-unit h3 { font-size: 2rem; }
}

