$(document).ready(function() {

 // =========================================
 // THE GRAND CURTAIN REVEAL
 // =========================================
 $('#enter-btn').on('click', function() {

 // Optional: Play Audio
 // var audio = new Audio('assets/music/wedding-shenai.mp3');
 // audio.play();

 // Create a GSAP timeline for sequenced animation
 var tl = gsap.timeline();

 // Step 1: Animate the Stamp Out smoothly
 tl.to(".royal-stamp", {
 scale: 0.7,
 opacity: 0,
 duration: 0.6,
 ease: "back.in(1.5)"
 });

 // Step 2: The Realistic Curtain Pull (Simultaneous)
 // Using 'expo.inOut' for a very satisfying, luxurious "swoop" motion.

 // Left Curtain
 tl.to(".curtain-left", {
 xPercent: -100, // Move completely off-screen left
 scaleX: 0.3, // Bunch up tightly
 rotation: -6, // Slight outward swing at bottom
 borderBottomRightRadius: "80% 120vh", // The deep curve shape
 duration: 3, // Long duration for grandeur
 ease: "expo.inOut" // The "satisfying" ease curve
 }, "<+=0.1"); // Start 0.1s after stamp vanishes

 // Right Curtain (Mirror of Left)
 tl.to(".curtain-right", {
 xPercent: 100, // Move completely off-screen right
 scaleX: 0.3, // Bunch up tightly
 rotation: 6, // Slight outward swing at bottom
 borderBottomLeftRadius: "80% 120vh", // The deep curve shape
 duration: 3,
 ease: "expo.inOut"
 }, "<"); // Start at exact same time as left curtain

 // Step 3: Cleanup & Hero Reveal
 tl.add(function() {
 // Hide overlay so it doesn't block interaction
 $('#curtain-overlay').css('visibility', 'hidden');
 $('body').removeClass('overflow-hidden');
 });

 // Step 4: Animate Hero Text Elements (Overlapping with end of curtain pull)
 tl.from(".sub-heading", { opacity: 0, y: 20, duration: 1, ease: "power2.out" }, "-=1.5");
 tl.from(".couple-names", { opacity: 0, scale: 0.9, y: 30, duration: 1.5, ease: "power3.out" }, "-=1.2");
 tl.from(".telugu-text", { opacity: 0, scale: 0.8, duration: 1, ease: "back.out(1.7)" }, "-=1.0");
 tl.from(".date-location", { opacity: 0, width: 0, duration: 1, ease: "power2.inOut" }, "-=0.8");
 });

 // =========================================
 // INITIALIZE OTHER PLUGINS (Countdown, etc.)
 // =========================================
 // (We will add countdown logic here later)

});

