 function getRandomCurve() {{ return Math.random() < 0.5 ? 1 : -1; }}

 function initPieces() {{
 pieces = [];
 let hEdges = Array(ROWS).fill().map(() => Array(COLS).fill(0)); 
 let vEdges = Array(ROWS).fill().map(() => Array(COLS).fill(0));

 for(let r=0; r<ROWS; r++) {{
 for(let c=0; c<COLS; c++) {{
 let top = (r === 0) ? 0 : hEdges[r-1][c] * -1;
 let right = (c === COLS-1) ? 0 : getRandomCurve();
 let bottom = (r === ROWS-1) ? 0 : getRandomCurve();
 let left = (c === 0) ? 0 : vEdges[r][c-1] * -1;

 hEdges[r][c] = bottom; 
 vEdges[r][c] = right;

 const tx = boardX + (c * pieceWidth);
 const ty = boardY + (r * pieceHeight);

 // Scatter anywhere
 const rx = Math.random() * (canvas.width - pieceWidth);
 const ry = Math.random() * (canvas.height - pieceHeight);

 pieces.push({{
 id: r + "-" + c,
 r: r, c: c,
 correctX: tx, correctY: ty,
 x: rx, y: ry,
 shape: {{ top, right, bottom, left }},
 isLocked: false,
 w: pieceWidth, h: pieceHeight
 }});
