 // --- Updated Draw Path: Classic Square with Plugs ---
 function drawPath(ctx, x, y, w, h, shape) {{
 // This draws a "classic" puzzle shape:
 // 1. Sharp corners (square feel)
 // 2. Straight lines for the "shoulders"
 // 3. Smooth bezier "plugs" (tabs)

 const sz = Math.min(w, h);
 const tabSize = sz * 0.22; // Size of the tab sticking out/in
 const neckW = tabSize * 0.8; // Width of the neck of the tab

 ctx.beginPath();
 ctx.moveTo(x, y);

 // --- TOP EDGE ---
 if (shape.top !== 0) {{
 const sgn = shape.top;
 // Straight line to the "shoulder" of the tab
 ctx.lineTo(x + w * 0.5 - neckW, y);
 // The Plug (Bezier)
 ctx.bezierCurveTo(
 x + w * 0.5 - neckW, y - sgn * tabSize, 
 x + w * 0.5 + neckW, y - sgn * tabSize, 
 x + w * 0.5 + neckW, y
 );
 }}
 ctx.lineTo(x + w, y); // Finish edge to sharp corner

 // --- RIGHT EDGE ---
 if (shape.right !== 0) {{
 const sgn = shape.right;
 ctx.lineTo(x + w, y + h * 0.5 - neckW);
 ctx.bezierCurveTo(
 x + w + sgn * tabSize, y + h * 0.5 - neckW, 
 x + w + sgn * tabSize, y + h * 0.5 + neckW, 
 x + w, y + h * 0.5 + neckW
 );
 }}
 ctx.lineTo(x + w, y + h); // Finish edge to sharp corner

 // --- BOTTOM EDGE ---
 if (shape.bottom !== 0) {{
 const sgn = shape.bottom;
 ctx.lineTo(x + w * 0.5 + neckW, y + h);
 ctx.bezierCurveTo(
 x + w * 0.5 + neckW, y + h + sgn * tabSize, 
 x + w * 0.5 - neckW, y + h + sgn * tabSize, 
 x + w * 0.5 - neckW, y + h
 );
 }}
 ctx.lineTo(x, y + h); // Finish edge to sharp corner

 // --- LEFT EDGE ---
 if (shape.left !== 0) {{
 const sgn = shape.left;
 ctx.lineTo(x, y + h * 0.5 + neckW);
 ctx.bezierCurveTo(
 x - sgn * tabSize, y + h * 0.5 + neckW, 
 x - sgn * tabSize, y + h * 0.5 - neckW, 
 x, y + h * 0.5 - neckW
 );
 }}
 ctx.lineTo(x, y); // Close path to start

 ctx.closePath();
 }}

