 x - sgn * tabSize * 0.5, y + h - shoulderH,
 x - sgn * tabSize * 1.5, y + h * 0.5 + tabSize * 0.5,
 x - sgn * tabSize, y + h * 0.5
 );
 // Top In/Out Curve
 ctx.bezierCurveTo(
 x - sgn * tabSize * 1.5, y + h * 0.5 - tabSize * 0.5,
 x - sgn * tabSize * 0.5, y + shoulderH,
 x, y + shoulderH
 );
 }}
 ctx.lineTo(x, y); // Finish left edge and close path

 ctx.closePath();
 }}

 function draw() {{
 ctx.clearRect(0, 0, canvas.width, canvas.height);

 // --- 1. Draw Guide/Board ---
 if (SHOW_GUIDE) {{
 ctx.globalAlpha = 0.2;
 ctx.drawImage(img, boardX, boardY, img.width * scale, img.height * scale);
 ctx.globalAlpha = 1.0;

 // Faint border when guide is on
 ctx.strokeStyle = "rgba(0,0,0,0.2)";
 ctx.lineWidth = 2;
 ctx.strokeRect(boardX, boardY, img.width * scale, img.height * scale);
 }} else {{
 // STRICT NO GUIDE MODE: Just the border frame, no grid lines.
 ctx.strokeStyle = "rgba(0,0,0,0.15)";
 ctx.lineWidth = 3;

 // Draw dashed border to indicate drop zone
 ctx.save();
 ctx.setLineDash([10, 10]);
 ctx.strokeRect(boardX, boardY, img.width * scale, img.height * scale);
 ctx.restore();
 }}

 // --- 2. Draw Pieces ---

 // Sort pieces so held piece is on top, and free pieces are above locked pieces
 const sortedPieces = [...pieces].sort((a, b) => {{
 if (a === selectedPiece) return 1;
 if (b === selectedPiece) return -1;
 if (a.isLocked && !b.isLocked) return -1;
 if (!a.isLocked && b.isLocked) return 1;
 return 0;
 }});

 const renderPiece = (p) => {{
 ctx.save();

 // Shadow Logic
 if (!p.isLocked) {{
 ctx.shadowColor = "rgba(0, 0, 0, 0.4)";
 ctx.shadowBlur = p === selectedPiece ? 15 : 4;
 ctx.shadowOffsetX = p === selectedPiece ? 4 : 2;
 ctx.shadowOffsetY = p === selectedPiece ? 4 : 2;
 }}

 // Create Path
 drawPath(ctx, p.x, p.y, p.w, p.h, p.shape);

 // Fill White (background for transparency)
 ctx.fillStyle = "#fff"; 
 ctx.fill(); 

 // Clip & Draw Image
 ctx.save();
 ctx.clip();

 const imgW = img.width * scale;
 const imgH = img.height * scale;

 const pieceRelX = p.c * p.w;
 const pieceRelY = p.r * p.h;

 // The standard clip handles this, but the drawImage placement must be precise.
 ctx.drawImage(img, p.x - pieceRelX, p.y - pieceRelY, imgW, imgH);
 ctx.restore(); // End Clip

 // Bevel / Stroke (3D Effect)
 ctx.shadowColor = "transparent";
 ctx.lineWidth = 2;
 ctx.lineJoin = "round";
 ctx.strokeStyle = "rgba(255, 255, 255, 0.6)"; // Highlight
 ctx.stroke();

 ctx.lineWidth = 1;
 ctx.strokeStyle = "rgba(0, 0, 0, 0.4)"; // Outline
 ctx.stroke();

 ctx.restore();
 }};

 sortedPieces.forEach(p => renderPiece(p));
 }}

