 function getPieceAt(mx, my) {{
 // Check reverse order to get top pieces first
 for (let i = pieces.length - 1; i >= 0; i--) {{
 const p = pieces[i];
 if (p.isLocked) continue;

 // Add a little buffer for the tabs
 const buffer = p.w * 0.3; // Increased buffer for tabs
 if (mx >= p.x - buffer && mx <= p.x + p.w + buffer &&
 my >= p.y - buffer && my <= p.y + p.h + buffer) {{
 return p;
 }}
 }}
 return null;
 }}

 function onDown(x, y) {{
