@app.post("/ask")
async def ask_agent(request: Request):
 db = next(get_db())
 transaction_id_str = None 
 try:
 body = await request.json()
 print("Request body:", body)

 if not body.get("query"):
 raise HTTPException(status_code=400, detail="Query is required")
 if not body.get("agent"):
 raise HTTPException(status_code=400, detail="Agent ID is required")

 if body.get("session_id") is None:
 session_id = uuid.uuid4()
 # user_id can be enhanced with real user data if you have authentication
 user_id = "web_user" 
 session = Session(id=session_id, user_id=user_id, start_time=datetime.now(), status="active")
 db.add(session)
 db.commit()
 body["session_id"] = str(session_id)

 query = QueryRequest(
 query=body["query"],
 agent=body["agent"],
 session_id=body["session_id"]
 )

 agent_id_for_log = query.agent.split(',')[0].strip() if "," in query.agent else query.agent
 transaction_id_str = await log_transaction(db, query, None, agent_id_for_log)
 transaction_id_uuid = uuid.UUID(transaction_id_str)

 result = None
 try:
 # Check if a multi-agent crew is requested
 if "," in query.agent:
 agent_ids = [agent_id.strip() for agent_id in query.agent.split(',')]
 result = await get_and_run_crew_with_agents(db, agent_ids, query.query, transaction_id_uuid)
 else:
 # --- SINGLE AGENT LOGIC ---
 if query.agent in AVAILABLE_AGENTS:
 from interactions.agent_communication import AgentCommunicator
 communicator = AgentCommunicator()

 if query.agent == "crew":
 result = communicator.execute_crew(query.query)
 elif query.agent == "rag_combined":
 result = communicator.rag_combined_query(query.query)
 else:
 result = communicator.query(query.agent, query.query, query.session_id)
 else:
 agent_db = get_agent_by_id(db, query.agent)
 if not agent_db:
 raise HTTPException(status_code=404, detail=f"Agent with ID {query.agent} not found") 
 result = await get_and_run_crew_agent(db, query.agent, query.query, transaction_id_uuid)

 if result is None:
 raise HTTPException(status_code=500, detail="Agent returned no result")

 # --- Update Transaction on Success---
 transaction = db.query(Transaction).filter(Transaction.id == transaction_id_uuid).first()
 if transaction:
 transaction.final_output = result
 transaction.status = "completed"
 transaction.end_time = datetime.now()
 db.commit()

 return {
 "session_id": query.session_id,
 "transaction_id": transaction_id_str,
 "result": result
 }

 except Exception as e:
 # --- Update Transaction on Failure---
 if transaction_id_str:
 transaction = db.query(Transaction).filter(Transaction.id == transaction_id_uuid).first()
 if transaction:
 transaction.status = "failed"
 transaction.end_time = datetime.now()
 transaction.final_output = {"error": str(e)}
 db.commit()
 raise # Re-raise the exception to be caught by outer handlers

 except HTTPException:
 raise # Let FastAPI handle its own exceptions
 except Exception as e:
 print("Error:", str(e))
 # This is a general fallback
 raise HTTPException(status_code=500, detail=str(e))

