 ### 2. Updated web_interface.py 

 This version unifies the logic into the /ask and /ask-crew endpoints, allowing them to handle the framework parameter you select in the UI. 

 import os
from fastapi import FastAPI, Request, Form, HTTPException
from fastapi.responses import HTMLResponse, JSONResponse
from fastapi.templating import Jinja2Templates
from typing import Dict, List, Optional, Any
import json
from datetime import datetime
from db.config import SessionLocal
from db.crud.agent import list_agents, create_agent, AgentCreate, get_agent_by_id
from agents.crew_agent import get_and_run_crew_agent, get_and_run_crew_with_agents
from agents.langgraph_agent import get_and_run_langgraph_agent, get_and_run_langgraph_with_agents
from pydantic import BaseModel
from utils.logging_utils import get_logger
from db.models import Transaction, Session as DBSession
import uuid
from db.crud.interaction import get_agent_sessions_and_interactions

logger = get_logger('web_interface')
api_dir = os.path.dirname(__file__)
app = FastAPI()
templates = Jinja2Templates(directory=os.path.join(api_dir, "templates"))

def get_db():
 db = SessionLocal()
 try:
 yield db
 finally:
 db.close()

def get_available_agents():
 db = next(get_db())
 agents = list_agents(db)
 return {str(agent.id): {"description": agent.description, "name": agent.name, "config": agent.config, "llm_used": agent.llm_used} for agent in agents}

class QueryRequest(BaseModel):
 query: str
 agent: str
 session_id: Optional[str] = None
 framework: Optional[str] = "langgraph"

class CrewRequest(BaseModel):
 query: str
 agent_ids: List[str]
 session_id: Optional[str] = None
 framework: Optional[str] = "langgraph"

@app.get("/", response_class=HTMLResponse)
async def chat_interface(request: Request):
 return templates.TemplateResponse("chat.html", {"request": request, "agents": get_available_agents()})

@app.post("/ask")
async def ask_agent(query_request: QueryRequest, request: Request):
 db = next(get_db())
 session_id_str = query_request.session_id
 if not session_id_str:
 session_id_obj = uuid.uuid4()
 db.add(DBSession(id=session_id_obj, user_id="web_user", start_time=datetime.now(), status="active"))
 db.commit()
 session_id_str = str(session_id_obj)

 transaction = Transaction(
 user_id="web_user", task_description=query_request.query, status="running",
 start_time=datetime.now(), input_data=query_request.model_dump(), session_id=uuid.UUID(session_id_str)
 )
 db.add(transaction)
 db.commit()

 try:
 if query_request.framework == "crewai":
 logger.info(f"Running SINGLE-AGENT query with CrewAI for agent {query_request.agent}")
 result = await get_and_run_crew_agent(db, query_request.agent, query_request.query, transaction.id)
 else:
 logger.info(f"Running SINGLE-AGENT query with LangGraph for agent {query_request.agent}")
 result = await get_and_run_langgraph_agent(db, query_request.agent, query_request.query, transaction.id)

 transaction.final_output = result
 transaction.status = "completed"
 transaction.end_time = datetime.now()
 db.commit()
 return {"session_id": session_id_str, "transaction_id": str(transaction.id), "result": result}
 except Exception as e:
 logger.error(f"Agent execution failed: {e}", exc_info=True)
 transaction.status = "failed"; transaction.end_time = datetime.now(); transaction.final_output = {"error": str(e)}
 db.commit()
 raise HTTPException(status_code=500, detail=str(e))

