def _serialize_datetime(obj: Any) -> Any:
 """Convert datetime objects to ISO format strings for JSON serialization."""
 if isinstance(obj, datetime):
 return obj.isoformat()
 return obj

async def log_transaction(db: Session, query: QueryRequest, result: str, agent_id: str) -> str:
 """
 Log the transaction and its associated logs in the database.
 Returns the transaction ID.
 """
 try:
 current_time = datetime.now()

 # Handle session_id - convert string to UUID if needed
 session_id = None
 if query.session_id:
 try:
 # Try to convert existing session_id to UUID
 session_id = uuid.UUID(query.session_id)

 # Check if session exists, if not create it
 existing_session = db.query(Session).filter(Session.id == session_id).first()
 if not existing_session:
 new_session = Session(
 id=session_id,
 user_id="web_user", # You might want to get this from authentication
 start_time=current_time,
 status="active"
 )
 db.add(new_session)
 db.flush()
 logger.info(f"Created new session with ID: {session_id}")
 except ValueError:
 # If conversion fails, generate a new UUID
 session_id = uuid.uuid4()
 # Create new session
 new_session = Session(
 id=session_id,
 user_id="web_user", # You might want to get this from authentication
 start_time=current_time,
 status="active"
 )
 db.add(new_session)
 db.flush()
 logger.info(f"Generated new session with ID: {session_id}")

 # Create main transaction
 transaction = Transaction(
 id=uuid.uuid4(),
 user_id="web_user", # You might want to get this from authentication
 task_description=query.query,
 status="completed",
 start_time=current_time,
 end_time=current_time,
 input_data={"query": query.query, "agent": query.agent},
 final_output={"result": result},
 session_id=session_id
 )
 db.add(transaction)
 db.flush() # Flush to get the transaction ID

 # Create agent execution log
 agent_log = AgentExecutionLog(
 transaction_id=transaction.id,
 agent_id=uuid.UUID(agent_id),
 start_time=current_time,
 end_time=current_time,
 input_data={"query": query.query},
 output_data={"result": result}
 )
 db.add(agent_log)

 # If the result contains tool usage information, log it
 if isinstance(result, dict) and "tool_usage" in result:
 for tool_usage in result["tool_usage"]:
 # Convert datetime objects to ISO format strings
 tool_usage = {k: _serialize_datetime(v) for k, v in tool_usage.items()}
 tool_log = ToolExecutionLog(
 transaction_id=transaction.id,
 agent_id=uuid.UUID(agent_id),
 start_time=tool_usage.get("start_time", current_time),
 end_time=tool_usage.get("end_time", current_time),
 tool_id=uuid.UUID(tool_usage["tool_id"]) if "tool_id" in tool_usage else None,
 input_data=tool_usage.get("input", {}),
 output_data=tool_usage.get("output", {})
 )
 db.add(tool_log)

 # If the result contains LLM usage information, log it
 if isinstance(result, dict) and "llm_usage" in result:
 llm_usage = result["llm_usage"]
 # Convert datetime objects to ISO format strings
 llm_usage = {k: _serialize_datetime(v) for k, v in llm_usage.items()}
 llm_log = LLMUsageLog(
 transaction_id=transaction.id,
 agent_id=uuid.UUID(agent_id),
 start_time=llm_usage.get("start_time", current_time),
 end_time=llm_usage.get("end_time", current_time),
 model_name=llm_usage.get("model_name"),
 model_provider=llm_usage.get("model_provider"),
 temperature=llm_usage.get("temperature"),
 max_tokens=llm_usage.get("max_tokens"),
 total_tokens_used=llm_usage.get("total_tokens"),
 response_latency_ms=llm_usage.get("latency_ms"),
 prompt=llm_usage.get("prompt"),
 response=llm_usage.get("response")
 )
 db.add(llm_log)

 db.commit()
 return str(transaction.id)

 except Exception as e:
 db.rollback()
 logger.error(f"Error logging transaction: {str(e)}")
 raise

@app.post("/ask")
async def ask_agent(request: Request):
 db = next(get_db())
 try:
 # Parse the request body manually
 body = await request.json()
 print("Request body:", body)

 # Validate required fields
 if not body.get("query"):
 raise HTTPException(status_code=400, detail="Query is required")
 if not body.get("agent"):
 raise HTTPException(status_code=400, detail="Agent ID is required")

 # Get framework with default to langgraph
 framework = body.get("framework", "langgraph")

 if body.get("session_id") is None:
 session_id = uuid.uuid4()
 user_id = request.query_params.get("user_id", "web_user")
 session = Session(id=session_id, user_id=user_id, start_time=datetime.now(), status="active")
 db.add(session)
 db.commit()
 body["session_id"] = session_id
 else:
 session_id = body.get("session_id")

 # Create QueryRequest instance with framework
 query = QueryRequest(
 query=body["query"],
 agent=body["agent"],
 session_id=str(session_id) if session_id else None,
 framework=framework # Add this
 )

 result = None

 # Validate agent exists if it's a database agent
 if query.agent not in AVAILABLE_AGENTS:
 agent = get_agent_by_id(db, query.agent)
 if not agent:
 raise HTTPException(
 status_code=404,
 detail=f"Agent with ID {query.agent} not found"
 )

 # Create transaction first
 transaction_id = await log_transaction(db, query, None, query.agent)

 try:
 # Check if it's a hardcoded agent
 if query.agent in AVAILABLE_AGENTS:
 # Handle hardcoded agents (unchanged)
 from interactions.agent_communication import AgentCommunicator
 communicator = AgentCommunicator()

 if query.agent == "crew":
 result = communicator.execute_crew(query.query)
 elif query.agent == "rag_combined":
 result = communicator.rag_combined_query(query.query)
 else:
 result = communicator.query(query.agent, query.query, query.session_id)
 else:
 # Handle database agents with selected framework
 if query.framework == "crew":
 result = await get_and_run_crew_agent(db, query.agent, query.query, uuid.UUID(transaction_id))
 else: # Default to langgraph
 result = await get_and_run_langgraph_agent(db, query.agent, query.query, uuid.UUID(transaction_id))


 if result is None:
 raise HTTPException(status_code=500, detail="Agent returned no result")

 # Update the transaction with the result
 transaction = db.query(Transaction).filter(Transaction.id == uuid.UUID(transaction_id)).first()
 if transaction:
 transaction.final_output = result
 transaction.status = "completed"
 transaction.end_time = datetime.now()
 db.commit()

 return {
 "session_id": query.session_id,
 "transaction_id": transaction_id,
 "result": result
 }

 except Exception as e:
 # Update transaction status to failed
 transaction = db.query(Transaction).filter(Transaction.id == uuid.UUID(transaction_id)).first()
 if transaction:
 transaction.status = "failed"
 transaction.end_time = datetime.now()
 transaction.final_output = {"error": str(e)}
 db.commit()
 raise

 except ValueError as e:
 raise HTTPException(status_code=422, detail=str(e))
 except HTTPException:
 raise
 except Exception as e:
 print("Error:", str(e))
 raise HTTPException(status_code=500, detail=str(e))

