 <script>
 $(document).ready(function() {
 // Add parameter button
 $('#addParamBtn').click(function() {
 const paramRow = `
 <div class="custom-param-row">
 <div class="row g-2">
 <div class="col-md-5">
 <input type="text" class="form-control param-key" placeholder="Parameter name">
 </div>
 <div class="col-md-5">
 <input type="text" class="form-control param-value" placeholder="Parameter value">
 </div>
 <div class="col-md-2">
 <button type="button" class="btn btn-outline-danger w-100 remove-param"><i class="bi bi-trash"></i></button>
 </div>
 </div>
 </div>`;
 $('#customParamsContainer').append(paramRow);
 updateCurlCommand();
 });

 // Remove parameter button
 $(document).on('click', '.remove-param', function() {
 $(this).closest('.custom-param-row').remove();
 updateCurlCommand();
 });

 // Update curl command on input change
 $('form').on('input', function() {
 updateCurlCommand();
 });

 // Form submission
 $('#textGenForm').submit(function(e) {
 e.preventDefault();
 generateContent();
 });

 // Copy button
 $('#copyBtn').click(function() {
 const content = $('#resultContent').text();
 navigator.clipboard.writeText(content);

 // Show feedback
 const originalText = $(this).html();
 $(this).html('<i class="bi bi-check2 me-1"></i>Copied!');
 setTimeout(() => {
 $(this).html(originalText);
 }, 2000);
 });

 // Download button
 $('#downloadBtn').click(function() {
 const content = $('#resultContent').text();
 const format = $('#output_format').val();
 const filename = `generated_content.${format.toLowerCase()}`;

 const blob = new Blob([content], { type: 'text/plain' });
 const url = URL.createObjectURL(blob);

 const a = document.createElement('a');
 a.href = url;
 a.download = filename;
 document.body.appendChild(a);
 a.click();
 document.body.removeChild(a);
 URL.revokeObjectURL(url);
 });

 // Initialize curl command
 updateCurlCommand();
 updateAudioCurlCommand();

 function updateCurlCommand() {
 const instruction = $('#instruction').val().replace(/"/g, '\\"');
 const output_format = $('#output_format').val();
 const num_records = $('#num_records').val();
 const language_style = $('#language_style').val().replace(/"/g, '\\"');
 const text_length = $('#text_length').val().replace(/"/g, '\\"');
 const structured = $('#structured').is(':checked') ? 'true' : 'false';
 const sample_data = $('#sample_data').val().replace(/"/g, '\\"');

 let curl = `curl --location 'http://localhost:8000/generate-text' \\\n`;
 curl += `--form 'instruction="${instruction}"' \\\n`;
 curl += `--form 'output_format="${output_format}"' \\\n`;
 curl += `--form 'num_records="${num_records}"' \\\n`;
 curl += `--form 'language_style="${language_style}"' \\\n`;
 curl += `--form 'text_length="${text_length}"' \\\n`;
 curl += `--form 'structured="${structured}"' \\\n`;
 curl += `--form 'sample_data="${sample_data}"' \\\n`;

 // Add custom parameters
 $('.custom-param-row').each(function() {
 const key = $(this).find('.param-key').val();
 const value = $(this).find('.param-value').val();
 if (key && value) {
 curl += `--form '${key}="${value.replace(/"/g, '\\"')}"' \\\n`;
 }
 });

 // Remove trailing backslash and newline
 curl = curl.trim();

 $('#curlCommand').text(curl);
 }

 function generateContent() {
 // Show loading spinner
 $('#generateSpinner').removeClass('d-none');
 $('#generateText').text('Generating...');
 $('#generateBtn').prop('disabled', true);
 $('#resultContent').html('<div class="text-center py-4"><div class="spinner-border text-primary" role="status"></div><p class="mt-2">Generating content...</p></div>');

 // Collect form data
 const formData = new FormData();
 formData.append('instruction', $('#instruction').val());
 formData.append('output_format', $('#output_format').val());
 formData.append('num_records', $('#num_records').val());
 formData.append('language_style', $('#language_style').val());
 formData.append('text_length', $('#text_length').val());
 formData.append('structured', $('#structured').is(':checked') ? 'true' : 'false');
 formData.append('sample_data', $('#sample_data').val());

 // Add custom parameters
 $('.custom-param-row').each(function() {
 const key = $(this).find('.param-key').val();
 const value = $(this).find('.param-value').val();
 if (key && value) {
 formData.append(key, value);
 }
 });

 // Make API call
 fetch('https://core-data-generation-dev.datashot.ai/generate-text', {
 method: 'POST',
 body: formData,
 mode: 'cors' // Explicitly enable CORS mode
 })
 .then(response => {
 if (!response.ok) {
 throw new Error('API request failed');
 }
 return response.text();
 })
 .then(data => {
 // Display results
 const format = $('#output_format').val();
 let displayData = data;

 if (format === 'JSON') {
 try {
 displayData = JSON.stringify(JSON.parse(data), null, 2);
 } catch (e) {
 // If not valid JSON, display as-is
 }
 }

 $('#resultContent').text(displayData);
 $('#copyBtn, #downloadBtn').prop('disabled', false);
 })
 .catch(error => {
 $('#resultContent').html(`<div class="alert alert-danger">${error.message || 'Error generating content'}</div>`);
 })
 .finally(() => {
 // Hide loading spinner
 $('#generateSpinner').addClass('d-none');
 $('#generateText').text('Generate Content');
 $('#generateBtn').prop('disabled', false);
 });
 }

 // ===== Audio: events =====
 $('#audioForm').on('input change', function() {
 updateAudioCurlCommand();
 });

 $('#audioForm').submit(function(e) {
 e.preventDefault();
 generateAudio();
 });

 $('#audioCopyBtn').click(function() {
 const content = $('#audioResultContent').text();
 navigator.clipboard.writeText(content);
 const originalText = $(this).html();
 $(this).html('<i class="bi bi-check2 me-1"></i>Copied!');
 setTimeout(() => { $(this).html(originalText); }, 2000);
 });

 $('#audioDownloadBtn').click(function() {
 const content = $('#audioResultContent').text();
 const filename = 'transcripts.json';
 const blob = new Blob([content], { type: 'application/json' });
 const url = URL.createObjectURL(blob);
 const a = document.createElement('a');
 a.href = url;
 a.download = filename;
 document.body.appendChild(a);
 a.click();
 document.body.removeChild(a);
 URL.revokeObjectURL(url);
 });

 function updateAudioCurlCommand() {
 const filePlaceholder = $('#audio_file')[0].files[0]?.name || '/path/to/audio.wav';
 const dataset_name = $('#dataset_name').val();
 const audio_instruction = $('#audio_instruction').val();
 const number_of_clips = $('#number_of_clips').val();
 const clip_duration = $('#clip_duration').val();
 const select_format = $('#select_format').val();
 const audio_type = $('#audio_type').val();
 const download_type = $('#download_type').val();

 let curl = `curl --location 'http://localhost:8000/generate-audio' \\\n+--form 'file=@${filePlaceholder}'`;

 if (dataset_name) curl += ` \\\n+--form 'dataset_name="${dataset_name.replace(/"/g, '\\"')}"'`;
 if (audio_instruction) curl += ` \\\n+--form 'instruction="${audio_instruction.replace(/"/g, '\\"')}"'`;
 if (number_of_clips) curl += ` \\\n+--form 'number_of_clips="${number_of_clips}"'`;
 if (clip_duration) curl += ` \\\n+--form 'clip_duration="${clip_duration}"'`;
 if (select_format) curl += ` \\\n+--form 'select_format="${select_format}"'`;
 if (audio_type) curl += ` \\\n+--form 'audio_type="${audio_type.replace(/"/g, '\\"')}"'`;
 if (download_type) curl += ` \\\n+--form 'download_type="${download_type.replace(/"/g, '\\"')}"'`;

 $('#audioCurlCommand').text(curl);
 }

 function generateAudio() {
 $('#audioSpinner').removeClass('d-none');
 $('#generateAudioText').text('Generating...');
 $('#audioGenerateBtn').prop('disabled', true);
 $('#audioResultContent').text('Processing...');

 const formData = new FormData();
 const file = $('#audio_file')[0].files[0];
 if (!file) {
 $('#audioResultContent').text('Please select a file.');
 $('#audioSpinner').addClass('d-none');
 $('#generateAudioText').text('Generate Transcript');
 $('#audioGenerateBtn').prop('disabled', false);
 return;
 }
 formData.append('file', file);

 const kv = [
 ['dataset_name', $('#dataset_name').val()],
 ['instruction', $('#audio_instruction').val()],
 ['number_of_clips', $('#number_of_clips').val()],
 ['clip_duration', $('#clip_duration').val()],
 ['select_format', $('#select_format').val()],
 ['audio_type', $('#audio_type').val()],
 ['download_type', $('#download_type').val()],
 ];
 kv.forEach(([k,v]) => { if (v) formData.append(k, v); });

 fetch('https://core-data-generation-dev.datashot.ai/generate-audio', {
 method: 'POST',
 body: formData,
 mode: 'cors'
 })
 .then(response => {
 if (!response.ok) throw new Error('API request failed');
 return response.json();
 })
 .then(data => {
 const pretty = JSON.stringify(data, null, 2);
 $('#audioResultContent').text(pretty);
 $('#audioCopyBtn, #audioDownloadBtn').prop('disabled', false);
 })
 .catch(error => {
 $('#audioResultContent').text(error.message || 'Error generating transcript');
 })
 .finally(() => {
 $('#audioSpinner').addClass('d-none');
 $('#generateAudioText').text('Generate Transcript');
 $('#audioGenerateBtn').prop('disabled', false);
 });
 }
 });
 </script>
