 cardTools.innerHTML = '';
 if(!cb.checked) return;

 let tools = [];
 if (cb.dataset.config) {
 try{
 const cfg = JSON.parse(cb.dataset.config);
 const t = (cfg.mcp && Array.isArray(cfg.mcp.tools)) ? cfg.mcp.tools : [];
 tools = t.filter(Boolean).map(x=>x.name).filter(Boolean);
 }catch(e){}
 }
 tools.forEach(name=>{
 const item = document.createElement('div');
 item.className = 'list-group-item py-1 px-2 my-1';
 item.textContent = name;
 cardTools.appendChild(item);
 });
 });
 }

 function initNetwork(container, autorefresh=true){
 const dsN = new vis.DataSet([]);
 const dsE = new vis.DataSet([]);
 const data = { nodes: dsN, edges: dsE };
 const options = {
 autoResize: true,
 nodes:{ shape:'box', margin:8, font:{ size:12 } },
 edges:{ arrows:{ to:{ enabled:true } }, smooth:{ type:'cubicBezier' } },
 layout:{ hierarchical:{ enabled:true, direction:'UD', sortMethod:'directed', nodeSpacing:110, levelSeparation:130 } },
 physics:false,
 interaction:{ dragNodes:true, hover:true }
 };
 const net = new vis.Network(container, data, options);
 if(autorefresh){
 const ro = new ResizeObserver(()=> net.fit({ animation:false }));
 ro.observe(container);
 }
 return { dsN, dsE, net };
 }

 let sending = false;
 async function sendMessage(){
 if (sending) return;
 const input = document.getElementById('userInput');
 const message = input.value.trim();
 const selected = Array.from(document.querySelectorAll('.agent-toggle:checked'));
 const frameworkSelect = document.getElementById('frameworkSelect');
 const frameworkType = frameworkSelect ? frameworkSelect.value : 'langgraph';

 if(!message) return;
 if(selected.length === 0){ alert('Please toggle ON at least one agent'); return; }

 const agentIds = selected.map(cb => cb.value).join(',');
 sending = true;

 input.disabled = true; 
 document.getElementById('sendButton').disabled = true;
 document.querySelectorAll('.agent-toggle').forEach(cb => cb.disabled = true);

 try{
 addMessage(message, true);
 input.value = ''; autoResizeTextarea(input);

 const resp = await fetch('/ask', {
 method: 'POST',
 headers: { 'Content-Type':'application/json' },
 body: JSON.stringify({ query: message, agent: agentIds, session_id: sessionId || null, framework_type: frameworkType })
 });

 if(!resp.ok){
 let err = 'Failed to get response from agent';
 try{ const j = await resp.json(); err = j.detail || err; }catch{}
 throw new Error(err);
 }

 const data = await resp.json();
 if(!sessionId) sessionId = data.session_id;

 let responseText = data.result;
 if(typeof responseText === 'object'){
 responseText = responseText.result || JSON.stringify(responseText, null, 2);
 }
 addMessage(responseText);
 }catch(e){
 addMessage('Error: ' + e.message);
 }finally{
 sending = false;
 input.disabled = false;
 document.getElementById('sendButton').disabled = false;
 document.querySelectorAll('.agent-toggle:not(:checked)').forEach(cb => cb.disabled = false);
 const checkedAndDisabled = document.querySelectorAll('.agent-toggle:checked[disabled]');
 checkedAndDisabled.forEach(cb => {
 const config = JSON.parse(cb.dataset.config || '{}');
 if (!config || !config.crew_members) {
 cb.disabled = false;
 }
 });
 input.focus();
 }
 }

 function addMessage(content, isUser=false){
 const chat = document.getElementById('chatContainer');
 const el = document.createElement('div');
 el.className = `message ${isUser ? 'user-message' : 'agent-message'}`;
 const time = document.createElement('span'); time.className = 'message-time'; time.textContent = new Date().toLocaleTimeString();
 const body = document.createElement('div'); body.textContent = content;
 el.appendChild(time); el.appendChild(body);
 chat.appendChild(el); chat.scrollTop = chat.scrollHeight;
 }

 function autoResizeTextarea(el){ el.style.height='auto'; el.style.height = Math.min(el.scrollHeight, 220)+'px'; }

 document.addEventListener('DOMContentLoaded', () => {
 const tooltipTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]'));
 tooltipTriggerList.map(el => new bootstrap.Tooltip(el, { boundary: document.body }));

 document.getElementById('sendButton').addEventListener('click', sendMessage);
 const userInput = document.getElementById('userInput');
 userInput.addEventListener('input', function(){ autoResizeTextarea(this); });
 userInput.addEventListener('keydown', function(e){ if(e.key==='Enter' && !e.shiftKey){ e.preventDefault(); sendMessage(); } });

 try {
 const main = initNetwork(document.getElementById('agentNetwork')); nodesDS = main.dsN; edgesDS = main.dsE; network = main.net;
 } catch (e) { console.error('Wireflow init error:', e); }

 const modalEl = document.getElementById('wireflowModal');
 if (modalEl) {
 modalEl.addEventListener('shown.bs.modal', () => {
 if(!networkFull){
 const full = initNetwork(document.getElementById('agentNetworkFull')); nodesFull = full.dsN; edgesFull = full.dsE; networkFull = full.net;
 }
 renderWireflow();
 networkFull.fit({ animation: { duration: 200 } });
 });
 modalEl.addEventListener('hidden.bs.modal', () => { renderWireflow(); });
 }

 document.querySelectorAll('.agent-toggle').forEach(cb => {
 cb.addEventListener('change', () => {
 const agentId = cb.value;
 const detailsEl = document.getElementById('details_' + agentId);
 const cardEl = cb.closest('.agent-item');

 if (!detailsEl || !cardEl) return;

 const collapseInstance = bootstrap.Collapse.getOrCreateInstance(detailsEl);

 if (cb.checked) {
 cardEl.classList.add('is-selected');
 collapseInstance.show();
 } else {
 cardEl.classList.remove('is-selected');
 collapseInstance.hide();
 }

 const configStr = cb.dataset.config;
 if (configStr) {
 try {
 const config = JSON.parse(configStr);
 if (config && config.crew_members && Array.isArray(config.crew_members)) {
 config.crew_members.forEach(memberId => {
 const memberCheckbox = document.getElementById(`agent_${memberId}`);
 if (memberCheckbox) {
 memberCheckbox.checked = cb.checked;
 memberCheckbox.disabled = cb.checked;
 memberCheckbox.dispatchEvent(new Event('change', { bubbles: true }));
 }
 });
 }
 } catch (e) {
 console.error("Failed to parse agent config JSON:", e);
 }
 }

 renderWireflow();
 });
 });

 autoResizeTextarea(userInput);
 renderWireflow();
 });
 </script>
