This is a common "last-minute" bug with MCP over STDIO . 

 The Request timed out error is likely happening because your print statements are sending text to stdout . In MCP, stdout is reserved strictly for JSON messages. When your code prints 🚀 Loaded Tool , it "pollutes" the communication channel, causing the Inspector to get confused and eventually time out. 

 The "5-Minute POC" Fix 

 Remove all print statements (use logger instead, which goes to stderr ). 

 Increase the MCP timeout even further. 

 Fix the Pydantic call to model_dump() to ensure it's V2 compatible. 

 Update your server.py with this "Silent" version: 

 import os
import yaml
import httpx
import logging
import sys
from mcp.server.fastmcp import FastMCP
from pydantic import create_model

# ALL logs must go to stderr so they don't break the MCP protocol
logging.basicConfig(level=logging.INFO, stream=sys.stderr)
logger = logging.getLogger("DynamoServer")

# Increase default timeout to 300 seconds for the POC
mcp = FastMCP("DynamoAudioServer", default_timeout=300)

async def call_api(url, method, payload, config):
 # Use a very long timeout for the audio API
 async with httpx.AsyncClient(timeout=120.0) as client: 
 files = {}
 data = {}
 params_cfg = config.get('parameters', {})

 for key, value in payload.items():
 if params_cfg.get(key, {}).get('type') == 'file':
 clean_path = str(value).strip('"').strip("'")
 if os.path.exists(clean_path):
 files[key] = (os.path.basename(clean_path), open(clean_path, 'rb'))
 logger.info(f"📂 Attaching file: {clean_path}")
 else:
 return {"error": f"File not found: {clean_path}"}
 else:
 data[key] = str(value)

 try:
 if method.upper() == "POST":
 resp = await client.post(url, data=data, files=files) if files else await client.post(url, json=data)
 else:
 resp = await client.get(url, params=data)

 for _, f_tuple in files.items(): f_tuple[1].close()

 try:
 return resp.json()
 except:
 return {"status": resp.status_code, "raw_response": resp.text}
 except Exception as e:
 return {"error": str(e)}

def load_tools():
 # REPLACED PRINT WITH LOGGER
 logger.info("🔎 Loading tools...")
 tools_dir = "./tools"
 if not os.path.exists(tools_dir): return

 for filename in os.listdir(tools_dir):
 if filename.endswith(".yaml"):
 with open(os.path.join(tools_dir, filename)) as f:
 cfg = yaml.safe_load(f)

 field_definitions = {name: (str, info.get('default', ...)) for name, info in cfg.get('parameters', {}).items()}
 ToolModel = create_model(f"{cfg['name']}Model", **field_definitions)

 # Set tool-specific timeout to match the server
 @mcp.tool(name=cfg['name'], timeout=300)
 async def dynamic_tool(args: ToolModel, cfg=cfg):
 # Pydantic V2 use model_dump()
 return await call_api(cfg['endpoint'], cfg['method'], args.model_dump(), cfg)

 dynamic_tool.__doc__ = cfg['description']
 logger.info(f"✅ Registered: {cfg['name']}")

load_tools()

if __name__ == "__main__":
 # Explicitly use stdio
 mcp.run(transport="stdio")

