assistant:
This is the Saksh v1.1.0 "Enterprise Sidecar" update. It integrates deep system telemetry (CPU/RAM), token limit awareness, and a high-density UI. 

 1. Core System: saksh/core.py 

 We've updated the HealthPulse schema to handle hardware and token data. 

 import threading
import uvicorn
import os
import abc
from typing import List, Dict, Any, Literal, Optional
from datetime import datetime
from pydantic import BaseModel, Field
from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware
from fastapi.staticfiles import StaticFiles

class HealthPulse(BaseModel):
 agent_id: str
 status: Literal["healthy", "degraded", "down"]
 latency_ms: float
 timestamp: datetime = Field(default_factory=datetime.now)
 vitality_score: int
 # --- New v1.1.0 Intelligence ---
 cpu_percent: float = 0.0
 ram_mb: float = 0.0
 tokens_remaining: Optional[int] = None
 rate_limit_reset: Optional[int] = None

class Netra(abc.ABC):
 def __init__(self, agent_id: str):
 self.agent_id = agent_id

 @abc.abstractmethod
 def gaze(self) -> HealthPulse:
 pass

class Saksh:
 _instance = None 

 def __new__(cls, *args, **kwargs):
 if not cls._instance:
 cls._instance = super(Saksh, cls).__new__(cls)
 return cls._instance

 def __init__(self, start_dashboard=True, port=2604):
 if hasattr(self, '_initialized'): return
 self._thousand_eyes: List[Netra] = []
 self._initialized = True
 if start_dashboard:
 self._start_dashboard_thread(port)

 def open_eye(self, adapter: Netra):
 self._thousand_eyes.append(adapter)

 def observe(self) -> Dict[str, Any]:
 report = {"total": len(self._thousand_eyes), "status": "stable", "eyes": [], "ts": datetime.now().isoformat()}
 for eye in self._thousand_eyes:
 pulse = eye.gaze()
 report["eyes"].append(pulse.dict())
 if pulse.status == "down": report["status"] = "critical"
 return report

 def _start_dashboard_thread(self, port):
 def run_server():
 app = FastAPI(title="Saksh v1.1.0")
 app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_methods=["*"], allow_headers=["*"])

 @app.get("/api/status")
 def get_status(): return self.observe()

 # Robust Path Finding
 base_path = os.path.dirname(__file__)
 static_dir = os.path.join(base_path, "dashboard", "static")

 if os.path.exists(static_dir):
 app.mount("/", StaticFiles(directory=static_dir, html=True), name="static")

 config = uvicorn.Config(app, host="0.0.0.0", port=port, log_level="error")
 uvicorn.Server(config).run()

 threading.Thread(target=run_server, daemon=True).start()

 2. Intelligence Layer: saksh/adapters.py 

 Now includes psutil for hardware monitoring and header parsing for tokens. 

 import requests
import time
import os
import psutil
from typing import Dict, Any
from .core import Netra, HealthPulse

def _perform_health_check(agent_id: str, url: str, headers: Dict[str, str]) -> HealthPulse:
 start = time.time()
 process = psutil.Process(os.getpid())

 # Heartbeat: Resource Usage
 cpu = psutil.cpu_percent(interval=None)
 ram = process.memory_info().rss / (1024 * 1024)

 status, score = "down", 0
 tokens, reset = None, None

 try:
 response = requests.get(url, headers=headers, timeout=8)
 latency = (time.time() - start) * 1000

 # Token Intelligence
 tokens = response.headers.get("x-ratelimit-remaining-tokens")
 reset = response.headers.get("x-ratelimit-reset-tokens")

 if response.status_code == 200:
 status, score = "healthy", 100
 elif response.status_code == 429:
 status, score = "degraded", 35
 else:
 status, score = "degraded", 55

 except Exception:
 status, score = "down", 0
 latency = (time.time() - start) * 1000

 # Vitality Logic
 if status == "healthy":
 if latency > 1200: score -= 15
 if latency > 2500: score -= 30
 if cpu > 85: score -= 20

 return HealthPulse(
 agent_id=agent_id, status=status, latency_ms=round(latency, 2),
 vitality_score=max(0, score), cpu_percent=cpu, ram_mb=round(ram, 2),
 tokens_remaining=int(tokens) if tokens and tokens.isdigit() else None,
 rate_limit_reset=int(reset) if reset and reset.isdigit() else None
 )

class CrewAINetra(Netra):
 def __init__(self, agent, agent_id: str):
 super().__init__(agent_id)
 llm = agent.llm
 self.url = getattr(llm, 'base_url', "https://api.openai.com/v1") or "https://api.openai.com/v1"
 self.key = getattr(llm, 'api_key', os.getenv("OPENAI_API_KEY"))

 def gaze(self) -> HealthPulse:
 path = "/models" if "v1" in self.url else "/v1/models"
 check_url = self.url.rstrip("/") + path
 headers = {"Authorization": f"Bearer {self.key}"} if self.key else {}
 return _perform_health_check(self.agent_id, check_url, headers)

class LangGraphNetra(Netra):
 def __init__(self, graph, agent_id: str, url="https://api.openai.com/v1", key=None):
 super().__init__(agent_id)
 self.url = url
 self.key = key or os.getenv("OPENAI_API_KEY")

 def gaze(self) -> HealthPulse:
 check_url = self.url.rstrip("/") + "/models"
 headers = {"Authorization": f"Bearer {self.key}"} if self.key else {}
 return _perform_health_check(self.agent_id, check_url, headers)

