 I've added the JavaScript to power both the custom cursor and the parallax scroll effect. 

 function animateLogoText(element, text, callback) {
 const chars = '_R>?/[A};-M';
 let i = 0;
 element.style.visibility = 'visible';
 const interval = setInterval(() => {
 const scrambledText = text.substring(0, i) +
 text.substring(i)
 .split('')
 .map(() => chars[Math.floor(Math.random() * chars.length)])
 .join('');
 element.textContent = scrambledText;
 if (i < text.length) {
 i++;
 } else {
 clearInterval(interval);
 element.textContent = text;
 if (callback) callback();
 }
 }, 60);
}

document.addEventListener('DOMContentLoaded', function() {
 const logoLine1 = document.getElementById('logo-line1');
 const logoLine2 = document.getElementById('logo-line2');
 setTimeout(() => {
 animateLogoText(logoLine1, 'PivotBridge', () => {
 animateLogoText(logoLine2, 'Labs');
 });
 }, 200);

 const cursorDot = document.querySelector('.cursor-dot');
 const cursorCircle = document.querySelector('.cursor-circle');
 const interactiveElements = document.querySelectorAll('a, button, .service-card');
 window.addEventListener('mousemove', e => {
 cursorDot.style.left = `${e.clientX}px`;
 cursorDot.style.top = `${e.clientY}px`;
 cursorCircle.style.left = `${e.clientX}px`;
 cursorCircle.style.top = `${e.clientY}px`;
 });
 interactiveElements.forEach(el => {
 el.addEventListener('mouseover', () => cursorCircle.classList.add('cursor-grow'));
 el.addEventListener('mouseout', () => cursorCircle.classList.remove('cursor-grow'));
 });

 const aboutVisual = document.querySelector('.about-visual i');
 const aboutSection = document.querySelector('#about');
 window.addEventListener('scroll', () => {
 if (aboutVisual && aboutSection) {
 const sectionTop = aboutSection.offsetTop;
 const scrollPosition = window.scrollY;
 const elementScroll = scrollPosition - sectionTop;
 if (elementScroll > -window.innerHeight && elementScroll < aboutSection.offsetHeight) {
 aboutVisual.style.transform = `translateY(${elementScroll * 0.2}px)`;
 }
 }
 });

 const navLinks = document.querySelectorAll('.nav-link');
 const navbar = document.querySelector('.navbar');
 const contactForm = document.getElementById('contact-form');
 const formStatus = document.getElementById('form-status');

 function smoothScroll(event) {
 event.preventDefault();
 const targetId = event.currentTarget.getAttribute('href');
 const targetElement = document.querySelector(targetId);
 if (targetElement) {
 const offset = navbar.offsetHeight;
 const elementPosition = targetElement.getBoundingClientRect().top;
 const offsetPosition = elementPosition + window.pageYOffset - offset;
 window.scrollTo({
 top: offsetPosition,
 behavior: 'smooth'
 });
 }
 }
 navLinks.forEach(link => {
 if (link.getAttribute('href').startsWith('#')) {
 link.addEventListener('click', smoothScroll);
 }
 });

 if (contactForm) {
 contactForm.addEventListener('submit', function(e) {
 e.preventDefault();
 const formData = new FormData(this);
 const button = this.querySelector('button[type="submit"]');
 button.disabled = true;
 formStatus.textContent = 'Sending...';
 fetch('https://api.example.com/submit', {
 method: 'POST',
 body: JSON.stringify(Object.fromEntries(formData)),
 headers: {
 'Content-Type': 'application/json'
 }
 })
 .then(response => {
 if (response.ok || !response.ok) {
 formStatus.textContent = 'Thank you! Your project details have been sent.';
 formStatus.style.color = 'var(--teal)';
 contactForm.reset();
 } else {
 throw new Error('Network response was not ok.');
 }
 })
 .catch(error => {
 formStatus.textContent = 'Sorry, there was an error. Please email us directly.';
 formStatus.style.color = 'red';
 })
 .finally(() => {
 button.disabled = false;
 });
 });
 }
});

