<script>
 const bookContainer = document.getElementById('book-container');
 const book = document.getElementById('book');
 const mainContent = document.getElementById('main-content');
 const audio = document.getElementById('background-music');
 const audioControl = document.getElementById('audio-control');

 function openBook() {
 book.classList.add('open');
 setTimeout(() => {
 bookContainer.style.zIndex = -1;
 mainContent.classList.add('visible');
 audioControl.classList.add('visible');
 }, 1500);
 }

 function toggleMute() {
 audio.muted = !audio.muted;
 audioControl.innerHTML = audio.muted ? '<i class="fas fa-volume-mute"></i>' : '<i class="fas fa-volume-high"></i>';
 }

 // Countdown Timer Logic
 const weddingDate = new Date("2026-01-25T10:30:00").getTime();
 const countdownInterval = setInterval(function() {
 const now = new Date().getTime();
 const distance = weddingDate - now;

 const days = Math.floor(distance / (1000 * 60 * 60 * 24));
 const hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
 const minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
 const seconds = Math.floor((distance % (1000 * 60)) / 1000);

 document.getElementById("days").innerText = days < 10 ? "0" + days : days;
 document.getElementById("hours").innerText = hours < 10 ? "0" + hours : hours;
 document.getElementById("minutes").innerText = minutes < 10 ? "0" + minutes : minutes;
 document.getElementById("seconds").innerText = seconds < 10 ? "0" + seconds : seconds;

 if (distance < 0) {
 clearInterval(countdownInterval);
 document.getElementById("countdown").innerHTML = "<div class='text-center'>The Big Day is Here!</div>";
 }
 }, 1000);
</script>

 </body>
