 <script>
 $(document).ready(function() {

 // --- CUSTOMIZE YOUR EVENT DETAILS HERE ---
 const eventDetails = {
 title: "Wedding of Aayush & Priya",
 date: "2025-12-21T11:30:00", // YYYY-MM-DDTHH:MM:SS
 endDate: "2025-12-21T15:00:00",
 location: "Taj Krishna, Hyderabad, Telangana, India",
 description: "Join us for the wedding ceremony of Aayush and Priya, followed by lunch. We look forward to celebrating with you!"
 };
 // -----------------------------------------

 // Countdown Timer Logic
 const countdownDate = new Date(eventDetails.date).getTime();
 const countdownFunction = setInterval(function() {
 const now = new Date().getTime();
 const distance = countdownDate - now;

 const days = Math.floor(distance / (1000 * 60 * 60 * 24));
 const hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
 const minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
 const seconds = Math.floor((distance % (1000 * 60)) / 1000);

 $('#days').text(days < 10 ? '0' + days : days);
 $('#hours').text(hours < 10 ? '0' + hours : hours);
 $('#minutes').text(minutes < 10 ? '0' + minutes : minutes);
 $('#seconds').text(seconds < 10 ? '0' + seconds : seconds);

 if (distance < 0) {
 clearInterval(countdownFunction);
 $('#countdown').html("<h4>The big day is here!</h4>");
 }
 }, 1000);

 // Add to Calendar Logic
 function generateCalendarLinks() {
 const startDate = new Date(eventDetails.date).toISOString().replace(/-|:|\.\d\d\d/g, "");
 const endDate = new Date(eventDetails.endDate).toISOString().replace(/-|:|\.\d\d\d/g, "");

 // Google Calendar Link
 const googleLink = `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent(eventDetails.title)}&dates=${startDate}/${endDate}&details=${encodeURIComponent(eventDetails.description)}&location=${encodeURIComponent(eventDetails.location)}`;
 $('#google-cal').attr('href', googleLink);

 // Apple & Outlook (.ics) file link
 const icsContent = [
 "BEGIN:VCALENDAR",
 "VERSION:2.0",
 "BEGIN:VEVENT",
 `URL:${document.URL}`,
 `DTSTART:${startDate}`,
 `DTEND:${endDate}`,
 `SUMMARY:${eventDetails.title}`,
 `DESCRIPTION:${eventDetails.description}`,
 `LOCATION:${eventDetails.location}`,
 "END:VEVENT",
 "END:VCALENDAR"
 ].join("\n");

 const icsLink = `data:text/calendar;charset=utf8,${encodeURIComponent(icsContent)}`;
 $('#apple-cal').attr('href', icsLink).attr('download', 'wedding-invitation.ics');
 $('#outlook-cal').attr('href', icsLink).attr('download', 'wedding-invitation.ics');
 }

 generateCalendarLinks();

 // Scroll Animation Logic
 function handleScrollAnimations() {
 $('.animate-on-scroll').each(function() {
 const elementTop = $(this).offset().top;
 const windowBottom = $(window).scrollTop() + $(window).height();
 if (elementTop < windowBottom - 50) {
 $(this).addClass('visible');
 }
 });
 }

 $(window).on('scroll', handleScrollAnimations);
 handleScrollAnimations(); // Trigger on load
 });
 </script>

</body>
