from typing import Any, Dict, Optional
from pydantic import BaseModel, Field, validator
import openai

# ─── 1. CONFIG MODEL ─────────────────────────────────────────────────
class TextGenConfig(BaseModel):
 output_format: str = Field(..., description="TXT | JSON | CSV | XML")
 num_records: int = Field(1, ge=1, le=1000)
 language_style: str = Field("English, Formal")
 text_length: str = Field("50-200 words")
 structured: bool = Field(True, description="Return strictly structured output")
 sample_data: Optional[str]= Field(None, description="Optional sample to guide style")

 @validator("output_format")
 def check_format(cls, v):
 allowed = {"TXT", "JSON", "CSV", "XML"}
 uv = v.upper()
 if uv not in allowed:
 raise ValueError(f"output_format must be one of {allowed}")
 return uv

# ─── 2. PROMPT BUILDER ────────────────────────────────────────────────
def build_prompt(cfg: TextGenConfig, instruction: str) -> str:
 parts = [
 f"Generate {cfg.num_records} text record"
 f"{'s' if cfg.num_records>1 else ''}.",
 f"Each record should be {cfg.text_length}, in {cfg.language_style}.",
 f"Return output in {cfg.output_format} format.",
 "No explanations or internal thoughts."
 ]
 if cfg.structured:
 parts.append("Return strictly valid structured output without extra commentary.")
 if cfg.sample_data:
 parts.append(f"Style guide example: {cfg.sample_data}")
 parts.append(f"Instruction: {instruction.strip()}")
 return "\n".join(parts)

# ─── 3. OPENAI CLIENT SETUP ───────────────────────────────────────────
BASE_URL = os.getenv("DS_BASE_URL", "http://34.16.183.154:40000/v1")
client = openai.Client(base_url=BASE_URL, api_key="None")

def call_model(prompt: str, max_tokens: int = 10000, temperature: float = 0.0) -> str:
 resp = client.chat.completions.create(
 model="Deepseek-0528",
 messages=[{"role":"user", "content": prompt}],
 temperature=temperature,
 max_tokens=max_tokens,
 )
 return resp.choices[0].message.content

# ─── 4. POST-PROCESSING ──────────────────────────────────────────────
def post_process(raw: str, cfg: TextGenConfig) -> bytes:
 raw = raw.strip()
 if cfg.output_format == "TXT":
 return raw.encode("utf-8")
 try:
 parsed = json.loads(raw)
 except json.JSONDecodeError:
 parsed = {"text": raw}
 if cfg.output_format == "JSON":
 return json.dumps(parsed, indent=2).encode("utf-8")
 if cfg.output_format == "CSV":
 # Parse JSON or wrap raw text
 try:
 parsed = json.loads(raw)
 except json.JSONDecodeError:
 parsed = [{"text": raw}]

 rows = parsed if isinstance(parsed, list) else [parsed]
 fieldnames = sorted({k for row in rows for k in row.keys()})

 # ← Use a StringIO instead of a list here
 buf = io.StringIO()
 writer = csv.DictWriter(buf, fieldnames=fieldnames)
 writer.writeheader()
 for row in rows:
 writer.writerow(row)

 return buf.getvalue().encode("utf-8")
 if cfg.output_format == "XML":
 def to_xml(tag,d): return (
 f"<{tag}>{''.join(f'<{k}>{v}</{k}>' for k,v in d.items())}</{tag}>"
 )
 items = parsed if isinstance(parsed, list) else [parsed]
 return f"<records>{''.join(to_xml('record',it) for it in items)}</records>".encode("utf-8")
 return raw.encode("utf-8")

# ─── 5. ENTRYPOINT ───────────────────────────────────────────────────
def generate_text_data(
 instruction: str,
 config_payload: Dict[str, Any],
) -> bytes:
 cfg = TextGenConfig(**config_payload)
 prompt = build_prompt(cfg, instruction)
 raw = call_model(prompt)
 # Remove any stray <think>…</think> tags
 cleaned= re.sub(r"<think>.*?</think>", "", raw, flags=re.DOTALL).strip()
 return post_process(cleaned, cfg)

