source venv/bin/activate # or .\venv\Scripts\activate on Windows
pip install Flask requests psutil flasgger matplotlib pandas # pandas for easier data handling
mkdir snapshots # Directory to store the snapshot files

 Create the Flask app ( memory_profiler.py ): 

 import os
import time
import json
import requests
import datetime
import pandas as pd
from flask import Flask, request, jsonify, send_file
from flasgger import Swagger, swag_from # For Swagger UI
import matplotlib.pyplot as plt
import io # For sending plot images

app = Flask(__name__)
# Configure Flasgger
swagger_config = {
 "headers": [],
 "specs": [
 {
 "endpoint": 'apispec_1',
 "route": '/apispec_1.json',
 "rule_filter": lambda rule: True, # all in
 "model_filter": lambda tag: True, # all in
 }
 ],
 "static_url_path": "/flasgger_static",
 # "static_folder": "static", # must be set by user
 "swagger_ui": True,
 "specs_route": "/apidocs/" # URL for Swagger UI
}
swagger = Swagger(app, config=swagger_config)

SNAPSHOT_DIR = "snapshots"
if not os.path.exists(SNAPSHOT_DIR):
 os.makedirs(SNAPSHOT_DIR)

# --- API Endpoints ---

@app.route('/take_snapshot', methods=['POST'])
@swag_from({
 'tags': ['Snapshots'],
 'description': 'Connects to the target Service X and takes a memory snapshot, saving it locally.',
 'parameters': [
 {
 'name': 'body',
 'in': 'body',
 'required': True,
 'schema': {
 'id': 'SnapshotRequest',
 'required': ['target_url', 'snapshot_label'],
 'properties': {
 'target_url': {
 'type': 'string',
 'description': 'Full URL of the Service X /debug/memory_stats endpoint (e.g., http://<ip>:<port>/debug/memory_stats).',
 'example': 'http://10.0.0.5:5000/debug/memory_stats'
 },
 'snapshot_label': {
 'type': 'string',
 'description': 'A descriptive label for this snapshot (e.g., "before_load", "3hr_mark", "final"). Avoid spaces/special chars.',
 'example': 'before_load_test'
 },
 'secret_key': {
 'type': 'string',
 'description': '(Optional) Secret key if Service X endpoint requires X-Debug-Secret header.',
 'example': 'YOUR_SECRET_KEY_HERE'
 }
 }
 }
 }
 ],
 'responses': {
 200: {
 'description': 'Snapshot taken successfully.',
 'schema': {
 'properties': {
 'message': {'type': 'string'},
 'filename': {'type': 'string'}
 }
 }
 },
 400: {'description': 'Bad request (e.g., missing parameters)'},
 500: {'description': 'Failed to connect to Service X or save snapshot'}
 }
})
def take_snapshot():
 """Takes a memory snapshot from the target service."""
 data = request.get_json()
 if not data or 'target_url' not in data or 'snapshot_label' not in data:
 return jsonify({"error": "Missing target_url or snapshot_label in request body"}), 400

 target_url = data['target_url']
 label = data['snapshot_label'].replace(" ", "_").lower() # Sanitize label
 secret_key = data.get('secret_key') # Optional secret key

 headers = {}
 if secret_key:
 headers['X-Debug-Secret'] = secret_key

 try:
 print(f"Attempting to fetch stats from: {target_url}")
 response = requests.get(target_url, headers=headers, timeout=20) # 20 second timeout
 response.raise_for_status() # Raise HTTPError for bad responses (4xx or 5xx)
 stats_data = response.json()

 except requests.exceptions.RequestException as e:
 print(f"Error connecting to {target_url}: {e}")
 return jsonify({"error": f"Failed to connect to Service X: {e}"}), 500
 except json.JSONDecodeError:
 print(f"Error decoding JSON response from {target_url}")
 return jsonify({"error": "Received invalid JSON response from Service X"}), 500

 timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
 filename = f"snapshot_{label}_{timestamp}.json"
 filepath = os.path.join(SNAPSHOT_DIR, filename)

 try:
 with open(filepath, 'w') as f:
 json.dump(stats_data, f, indent=4)
 print(f"Snapshot saved to: {filepath}")
 return jsonify({"message": "Snapshot taken successfully", "filename": filename}), 200
 except IOError as e:
 print(f"Error saving snapshot file {filepath}: {e}")
 return jsonify({"error": f"Failed to save snapshot file: {e}"}), 500

@app.route('/list_snapshots', methods=['GET'])
@swag_from({
 'tags': ['Snapshots'],
 'description': 'Lists available snapshots stored locally.',
 'responses': {
 200: {
 'description': 'List of snapshot filenames.',
 'schema': {
 'type': 'array',
 'items': {'type': 'string'}
 }
 }
 }
})
def list_snapshots():
 """Lists available snapshot files."""
 try:
 files = [f for f in os.listdir(SNAPSHOT_DIR) if f.endswith('.json')]
 return jsonify(sorted(files))
 except OSError as e:
 return jsonify({"error": f"Could not read snapshots directory: {e}"}), 500

def load_snapshot_data(filename):
 """Helper to load snapshot data from a file."""
 filepath = os.path.join(SNAPSHOT_DIR, filename)
 if not os.path.exists(filepath):
 return None
 try:
 with open(filepath, 'r') as f:
 return json.load(f)
 except (IOError, json.JSONDecodeError):
 return None # Or raise specific error

@app.route('/compare', methods=['GET'])
@swag_from({
 'tags': ['Analysis'],
 'description': 'Compares two snapshot files and returns a textual summary of differences.',
 'parameters': [
 {'name': 'snapshot1', 'in': 'query', 'required': True, 'type': 'string', 'description': 'Filename of the first snapshot.'},
 {'name': 'snapshot2', 'in': 'query', 'required': True, 'type': 'string', 'description': 'Filename of the second snapshot.'}
 ],
 'responses': {
 200: {'description': 'Comparison report.', 'schema': {'type': 'object'}}, # Define schema later if needed
 400: {'description': 'Invalid snapshot filenames provided.'},
 404: {'description': 'One or both snapshot files not found.'}
 }
 })
def compare_snapshots():
 """Compares two snapshots textually."""
 snap1_fname = request.args.get('snapshot1')
 snap2_fname = request.args.get('snapshot2')

 if not snap1_fname or not snap2_fname:
 return jsonify({"error": "Missing snapshot1 or snapshot2 query parameters"}), 400

 data1 = load_snapshot_data(snap1_fname)
 data2 = load_snapshot_data(snap2_fname)

 if not data1 or not data2:
 missing = []
 if not data1: missing.append(snap1_fname)
 if not data2: missing.append(snap2_fname)
 return jsonify({"error": f"Snapshot file(s) not found: {', '.join(missing)}"}), 404

 # --- Perform Comparison ---
 comparison = {
 "metadata": {
 "snapshot1": snap1_fname,
 "snapshot2": snap2_fname,
 "timestamp1": data1.get("timestamp"),
 "timestamp2": data2.get("timestamp"),
 "time_diff_seconds": data2.get("timestamp", 0) - data1.get("timestamp", 0)
 },
 "os_level_diff": {},
 "process_level_diff": {},
 "python_level_diff": {}
 }

 # OS Level Comparison
 for key in data1.get("os_level", {}):
 val1 = data1["os_level"].get(key, 0)
 val2 = data2["os_level"].get(key, 0)
 if isinstance(val1, (int, float)) and isinstance(val2, (int, float)):
 comparison["os_level_diff"][f"{key}_delta"] = val2 - val1
 else:
 comparison["os_level_diff"][f"{key}_1"] = val1 # Handle non-numeric or missing
 comparison["os_level_diff"][f"{key}_2"] = val2

 # Process Level Comparison
 for key in data1.get("process_level", {}):
 val1 = data1["process_level"].get(key, 0)
 val2 = data2["process_level"].get(key, 0)
 if isinstance(val1, (int, float)) and isinstance(val2, (int, float)):
 comparison["process_level_diff"][f"{key}_delta_mb"] = val2 - val1
 else:
 comparison["process_level_diff"][f"{key}_1"] = val1
 comparison["process_level_diff"][f"{key}_2"] = val2

 # Python Level Comparison (Tracemalloc)
 py1 = data1.get("python_code_level", {})
 py2 = data2.get("python_code_level", {})
 comparison["python_level_diff"]["total_allocated_by_top_n_kb_delta"] = py2.get("total_allocated_by_top_n_kb", 0) - py1.get("total_allocated_by_top_n_kb", 0)
 comparison["python_level_diff"]["total_blocks_tracked_delta"] = py2.get("total_blocks_tracked", 0) - py1.get("total_blocks_tracked", 0)

 # Compare top allocations (simple presence/absence and size change)
 alloc1 = {f"{d['filename']}:{d['lineno']}": d for d in py1.get("top_allocations", [])}
 alloc2 = {f"{d['filename']}:{d['lineno']}": d for d in py2.get("top_allocations", [])}

 changed_allocations = []
 new_allocations = []
 disappeared_allocations = []

 all_keys = set(alloc1.keys()) | set(alloc2.keys())

 for key in all_keys:
 item1 = alloc1.get(key)
 item2 = alloc2.get(key)
 if item1 and item2:
 delta_kb = item2['size_kb'] - item1['size_kb']
 delta_count = item2['count'] - item1['count']
 if abs(delta_kb) > 0.1 or delta_count != 0: # Only report if changed significantly
 changed_allocations.append({
 "location": key,
 "size_kb_1": item1['size_kb'], "size_kb_2": item2['size_kb'], "size_kb_delta": delta_kb,
 "count_1": item1['count'], "count_2": item2['count'], "count_delta": delta_count
 })
 elif item2: # Exists in 2 but not 1
 new_allocations.append(item2)
 elif item1: # Exists in 1 but not 2
 disappeared_allocations.append(item1)

 comparison["python_level_diff"]["changed_top_allocations"] = sorted(changed_allocations, key=lambda x: x['size_kb_delta'], reverse=True)
 comparison["python_level_diff"]["new_top_allocations_in_snap2"] = new_allocations
 comparison["python_level_diff"]["disappeared_top_allocations_from_snap1"] = disappeared_allocations

 return jsonify(comparison)

@app.route('/visualize_leak', methods=['GET'])
@swag_from({
 'tags': ['Analysis'],
 'description': 'Generates plots visualizing memory usage across multiple snapshots.',
