 }
})
def visualize_leak():
 """Generates plots for memory trends across snapshots."""
 snapshot_fnames_str = request.args.get('snapshots')
 if not snapshot_fnames_str:
 return jsonify({"error": "Missing 'snapshots' query parameter"}), 400

 snapshot_fnames = [fname.strip() for fname in snapshot_fnames_str.split(',')]
 if len(snapshot_fnames) < 2:
 return jsonify({"error": "Requires at least two snapshots for visualization"}), 400

 all_data = []
 for fname in snapshot_fnames:
 data = load_snapshot_data(fname)
 if not data:
 return jsonify({"error": f"Snapshot file not found: {fname}"}), 404
 all_data.append({"filename": fname, "data": data})

 # --- Prepare Data for Plotting (using Pandas) ---
 try:
 records = []
 for item in all_data:
 ts = datetime.datetime.fromtimestamp(item["data"]["timestamp"])
 records.append({
 "timestamp": ts,
 "label": item["filename"].replace(".json","").replace("snapshot_",""), # Basic label from filename
 "rss_mb": item["data"]["process_level"]["rss_mb"],
 "vms_mb": item["data"]["process_level"]["vms_mb"],
 "os_available_mb": item["data"]["os_level"]["available_mb"],
 "py_top_alloc_kb": item["data"]["python_code_level"]["total_allocated_by_top_n_kb"],
 })

 df = pd.DataFrame(records)
 df = df.sort_values(by="timestamp") # Ensure chronological order
 df['time_elapsed_sec'] = (df['timestamp'] - df['timestamp'].iloc[0]).dt.total_seconds()

 except KeyError as e:
 return jsonify({"error": f"Data missing in one or more snapshots: Key {e} not found."}), 500
 except Exception as e:
 return jsonify({"error": f"Error processing data for plotting: {e}"}), 500

 # --- Generate Plot ---
 plt.style.use('seaborn-v0_8-darkgrid') # Use a nice style
 fig, axes = plt.subplots(3, 1, figsize=(12, 15), sharex=True) # 3 rows, 1 column

 # Plot 1: Process Memory (RSS/VMS)
 axes[0].plot(df['time_elapsed_sec'], df['rss_mb'], marker='o', linestyle='-', label='Process RSS (MB)')
 axes[0].plot(df['time_elapsed_sec'], df['vms_mb'], marker='x', linestyle='--', label='Process VMS (MB)')
 axes[0].set_ylabel('Memory (MB)')
 axes[0].set_title('Service X Process Memory Usage Over Time')
 axes[0].legend()
 axes[0].grid(True)

 # Plot 2: OS Available Memory
 axes[1].plot(df['time_elapsed_sec'], df['os_available_mb'], marker='o', linestyle='-', color='green', label='OS Available Mem (MB)')
 axes[1].set_ylabel('Memory (MB)')
 axes[1].set_title('System Available Memory Over Time')
 axes[1].legend()
 axes[1].grid(True)

 # Plot 3: Python Tracemalloc Top Allocations Total
 axes[2].plot(df['time_elapsed_sec'], df['py_top_alloc_kb'], marker='o', linestyle='-', color='purple', label='Tracemalloc Top N Total (KB)')
 axes[2].set_ylabel('Memory (KB)')
 axes[2].set_title('Python Memory (Tracemalloc Top N Total) Over Time')
 axes[2].set_xlabel(f'Time Elapsed Since First Snapshot (seconds)\nFirst: {df["timestamp"].iloc[0].strftime("%Y-%m-%d %H:%M:%S")}')
 axes[2].legend()
 axes[2].grid(True)

 # Add labels to points (optional, can get cluttered)
 # for i, row in df.iterrows():
 # axes[0].text(row['time_elapsed_sec'], row['rss_mb'], f" {row['label']}", fontsize=8)

 plt.tight_layout(rect=[0, 0.03, 1, 0.97]) # Adjust layout, leave space for title
 fig.suptitle(f'Memory Analysis for {all_data[0]["data"].get("service_name", "Service X")}', fontsize=16)

 # Save plot to a BytesIO object
 img_buffer = io.BytesIO()
 plt.savefig(img_buffer, format='png')
 img_buffer.seek(0)
 plt.close(fig) # Close the figure to free memory

 # Send the image back
 return send_file(img_buffer, mimetype='image/png')

