 ├── 📄 Case_A.json<br>
 └── 📄 Case_B.json
 </div>""", unsafe_allow_html=True)

# --- HELPER FUNCTIONS ---
def generate_curl_string(url, data, files_paths):
 parts = [f"curl --location '{url}'"]
 for k, v in data.items(): 
 parts.append(f"--form '{k}=\"{v}\"'")
 for k, p in files_paths.items(): 
 parts.append(f"--form '{k}=@\"{p}\"'")
 return " \\\n".join(parts)

def show_skeleton(placeholder):
 skeleton_code = '{\n "status": "⌛ processing_request...",\n "hallucination_score": "--",\n "findings": "analyzing_source_document..." \n}'
 placeholder.markdown(f'<div class="skeleton-json"><pre style="color: #666;">{skeleton_code}</pre></div>', unsafe_allow_html=True)

def save_response(response_data, output_dir, filename):
 os.makedirs(output_dir, exist_ok=True)
 out_path = os.path.join(output_dir, f"resp_{filename}.json")
 with open(out_path, 'w') as f: 
 json.dump(response_data, f, indent=4)
 return out_path

def countdown_timer(seconds):
 timer_ph = st.empty()
 for sec in range(seconds, 0, -1):
 timer_ph.warning(f"⏳ Waiting {sec} seconds before next request... (Press 'Stop' in top right to halt)")
 time.sleep(1)
 timer_ph.empty()

# --- REUSABLE BATCH PROCESSOR ---
def run_flexible_batch(doc_dir, json_dir, out_dir, url, payload, file_keys, extra_files=None, headers=None):
 if not os.path.exists(doc_dir) or not os.path.exists(json_dir):
 st.error("Document or JSON directory not found.")
 return

 # Look for both .txt and .docx files dynamically
 all_files = [f for f in os.listdir(doc_dir) if f.lower().endswith(('.txt', '.docx'))]
 st.info(f"Scanning `{doc_dir}`... Found {len(all_files)} compatible files (.txt / .docx).")

 for doc_file in all_files:
 base_name = os.path.splitext(doc_file)[0]
 json_file = f"{base_name}.json"

 doc_path = os.path.join(doc_dir, doc_file)
 json_path = os.path.join(json_dir, json_file)
 expected_out_path = os.path.join(out_dir, f"resp_{base_name}.json")

 if os.path.exists(expected_out_path):
 st.success(f"⏭️ Skipped `{base_name}` - Already processed.")
 continue

 if os.path.exists(json_path):
 with st.expander(f"📦 Processing: {base_name}", expanded=True):
 st.caption(f"Paired: `{doc_file}` & `{json_file}`")

 # Combine primary dynamic files with static extra files (like templates/csvs)
 f_paths = {file_keys['doc']: doc_path, file_keys['json']: json_path}
 if extra_files:
 f_paths.update(extra_files)

 st.code(generate_curl_string(url, payload, f_paths), language="bash")
 res_placeholder = st.empty()
 show_skeleton(res_placeholder)

 try:
 # Dynamically open all required files
 opened_files = {k: open(v, 'rb') for k, v in f_paths.items()}
 res = requests.post(url, data=payload, files=opened_files, headers=headers)

 # Close files to prevent memory leaks in large batches
 for f in opened_files.values(): 
 f.close()

 if res.status_code == 200:
 res_json = res.json()
 save_response(res_json, out_dir, base_name)
 res_placeholder.json(res_json)
 countdown_timer(5)
 else:
 res_placeholder.error(f"API Error {res.status_code}: {res.text}")
 break
 except Exception as e:
 res_placeholder.error(f"Failed to process: {e}")
 break
 else:
 st.warning(f"Skipped `{doc_file}` - No matching `{json_file}` found.")

 play_ping()
 st.success(f"🎉 Batch complete! Outputs saved to `{out_dir}`")

# --- UI LAYOUT ---
st.title("🛡️ LOS Batch Hallucination Tester")
st.markdown("""
