import clickhouse_connect
import json
import datetime

# ClickHouse connection details
HOST = '127.0.0.1'
PORT = 8123
DATABASE = 'openlit'
USERNAME = 'default'
PASSWORD = 'OPENLIT'

def query_and_display_trace_details(client, trace_id):
 """Queries and displays logs, traces, and metrics for a given TraceId."""

 print(f"\n--- Logs for TraceId: {trace_id} ---")
 log_query = f"SELECT Timestamp, Body, ServiceName FROM otel_logs WHERE TraceId = '{trace_id}' ORDER BY Timestamp ASC"
 log_result = client.query(log_query)
 if log_result.result_rows:
 for row in log_result.result_rows:
 print(f" Timestamp: {row[0]}, ServiceName: {row[2]}, Body: {row[1]}")
 else:
 print(f" No logs found for TraceId: {trace_id}")

 print(f"\n--- Traces for TraceId: {trace_id} ---")
 trace_query = f"SELECT TraceId, SpanId, ParentSpanId, SpanName, SpanKind, Duration, Timestamp, SpanAttributes FROM otel_traces WHERE TraceId = '{trace_id}' ORDER BY Timestamp ASC"
 trace_result = client.query(trace_query)
 if trace_result.result_rows:
 for row in trace_result.result_rows:
 span_attributes = json.dumps(row[7], indent=2) if row[7] else '{}'
 print(f" SpanName: {row[3]}\n TraceId: {row[0]}, SpanId: {row[1]}, ParentSpanId: {row[2]}")
 print(f" SpanKind: {row[4]}, Duration: {row[5]}ns, Timestamp: {row[6]}")
 print(f" Attributes: {span_attributes}")
 print("-" * 20)
 else:
 print(f" No traces found for TraceId: {trace_id}")

 print(f"\n--- Metrics (with matching Exemplar TraceId) for TraceId: {trace_id} ---")
 metric_query = f"SELECT MetricName, Value, TimeUnix, Exemplars.TraceId FROM otel_metrics_sum ARRAY JOIN Exemplars WHERE Exemplars.TraceId = '{trace_id}' ORDER BY TimeUnix ASC LIMIT 10"
 metric_result = client.query(metric_query)
 if metric_result.result_rows:
 for row in metric_result.result_rows:
 print(f" MetricName: {row[0]}, Value: {row[1]}, Timestamp: {row[2]}, Exemplar TraceId: {row[3]}")
 else:
 print(f" No metrics with matching exemplars found for TraceId: {trace_id}")

 print(f"\n--- Metrics (Summary, filtering by TraceId in Attributes) for TraceId: {trace_id} ---")
 # Note: Summary metrics are aggregated. This query attempts to find the TraceId within metric attributes.
 metric_summary_attributes_query = f"SELECT MetricName, Count, Sum, ValueAtQuantiles.Quantile, ValueAtQuantiles.Value, TimeUnix, Attributes FROM otel_metrics_summary WHERE mapContains(Attributes, '{trace_id}') OR has(mapValues(Attributes), '{trace_id}') ORDER BY TimeUnix ASC LIMIT 10"
 metric_summary_attributes_result = client.query(metric_summary_attributes_query)
 if metric_summary_attributes_result.result_rows:
 for row in metric_summary_attributes_result.result_rows:
 attributes_json = json.dumps(row[6], indent=2) if row[6] else '{}'
 print(f" MetricName: {row[0]}, Count: {row[1]}, Sum: {row[2]}, Timestamp: {row[5]}")
 print(f" Quantiles: {row[3]} -> {row[4]}")
 print(f" Attributes: {attributes_json}")
 print("-" * 20)
 else:
 print(f" No summary metrics with matching TraceId found in attributes for TraceId: {trace_id}")

def display_table_schema(client, table_name):
 """Displays the schema for a given ClickHouse table."""
 print(f"\n--- Schema for Table: {table_name} ---")
 try:
 description_query = f"DESCRIBE TABLE {table_name}"
 desc_result = client.query(description_query)
 if desc_result.result_rows:
 for row in desc_result.result_rows:
 print(f" {row[0]} ({row[1]})")
 else:
 print(f" No schema found for table: {table_name}")
 except Exception as e:
 print(f" Error describing table {table_name}: {e}")

def list_all_tables(client):
 """Lists all tables in the current ClickHouse database."""
 print("\n--- All Tables in Current Database ---")
 try:
 tables_query = "SHOW TABLES"
 tables_result = client.query(tables_query)
 if tables_result.result_rows:
 for row in tables_result.result_rows:
 print(f" - {row[0]}")
 else:
 print(" No tables found in the database.")
 except Exception as e:
 print(f" Error listing tables: {e}")

def list_distinct_trace_ids(client, limit=None):
 """Lists distinct TraceIds from the otel_traces table, with an optional limit."""
 print("\n--- Distinct Trace IDs ---")
 try:
 query = "SELECT DISTINCT TraceId FROM otel_traces ORDER BY TraceId ASC"
 if limit is not None:
 query += f" LIMIT {int(limit)}"

 trace_ids_result = client.query(query)
 if trace_ids_result.result_rows:
 for i, row in enumerate(trace_ids_result.result_rows):
 print(f" {i+1}. {row[0]}")
 else:
 print(" No distinct Trace IDs found.")
 except Exception as e:
 print(f" Error listing distinct Trace IDs: {e}")

def main():
 client = None
 try:
 client = clickhouse_connect.get_client(
 host=HOST,
 port=PORT,
 database=DATABASE,
 username=USERNAME,
 password=PASSWORD
 )
 print(f"Successfully connected to ClickHouse at {HOST}:{PORT}/{DATABASE}")

 while True:
 print("\n---------------------------------------------------")
 user_input = input("Enter a TraceId (...), type 'schema <table_name>' (...), 'list tables', 'list traces [N]', or 'exit' to quit: ").strip()

 if user_input.lower() == 'exit':
 print("Exiting script.")
 break
 elif user_input.lower() == 'list tables':
 list_all_tables(client)
 elif user_input.lower().startswith('list traces'):
 parts = user_input.lower().split()
 if len(parts) == 2 and parts[1] == 'traces':
 list_distinct_trace_ids(client) # No limit, list all
 elif len(parts) == 3 and parts[1] == 'traces':
 try:
 limit = int(parts[2])
 list_distinct_trace_ids(client, limit)
 except ValueError:
 print("Invalid number for limit. Usage: list traces [N]")
 else:
 print("Invalid list traces command. Usage: list traces [N]")
 elif user_input.lower().startswith('schema '):
 parts = user_input.split(maxsplit=1)
 if len(parts) == 2:
 table_name = parts[1]
 # Dynamically get available tables for schema lookup
 tables_result = client.query("SHOW TABLES")
 available_tables = [row[0] for row in tables_result.result_rows]

 if table_name in available_tables:
 display_table_schema(client, table_name)
 else:
 print(f"Invalid table name. Available tables: {', '.join(available_tables)}")
 else:
 print("Invalid schema command. Usage: schema <table_name>")
 elif user_input:
 query_and_display_trace_details(client, user_input)
 else:
 print("Invalid input. Please try again.")

 except clickhouse_connect.driver.exceptions.OperationalError as e:
 print(f"Error connecting to ClickHouse: {e}")
 print("Please ensure your ClickHouse Docker container is running and accessible from 127.0.0.1:8123.")
 print("You can check its status with: `docker-compose ps`")
 except KeyboardInterrupt:
 print("\nExiting script due to user interruption.")
 except Exception as e:
 print(f"An unexpected error occurred: {e}")
 finally:
 if client:
 client.close()
 print("\nConnection to ClickHouse closed.")

