import re
from collections import defaultdict

def queryAnalyzer(customer_query: str, product_categories: list) -> list:
 normalized_query = re.sub(r'[^a-zA-Z0-9\s]', ' ', customer_query).lower()
 query_words = normalized_query.split()

 category_map = {}
 normalized_categories_set = set()
 for category in product_categories:
 normalized_cat = category.lower()
 if normalized_cat not in category_map:
 category_map[normalized_cat] = category
 normalized_categories_set.add(normalized_cat)

 category_counts = defaultdict(int)
 for word in query_words:
 if word in normalized_categories_set:
 category_counts[word] += 1

 results = []
 for normalized_cat, count in category_counts.items():
 original_cat = category_map[normalized_cat]
 results.append((count, original_cat))

 results.sort(key=lambda x: (-x[0], x[1]))

 return [category for count, category in results]

