 $(document).ready(function() {
 // Flower Petals Effect on Load
 function createPetal() {
 const petal = document.createElement('div');
 const colors = ['#601010', '#C5A059', '#e8b4b8']; 
 const petalColor = colors[Math.floor(Math.random() * colors.length)];

 petal.innerHTML = '&#10047;'; 
 petal.classList.add('petal');

 petal.style.left = Math.random() * 100 + 'vw';
 petal.style.animationDuration = (Math.random() * 3 + 3) + 's'; 
 petal.style.fontSize = (Math.random() * 15 + 10) + 'px';
 petal.style.color = petalColor;

 document.body.appendChild(petal);

 setTimeout(() => {
 petal.remove();
 }, 6000);
 }

 let petalInterval = setInterval(createPetal, 150);

 setTimeout(() => {
 clearInterval(petalInterval);
 }, 4000);

 // Scroll Animation Logic
 function checkVisibility() {
 $('.fade-in').each(function() {
 var elementTop = $(this).offset().top;
 var windowBottom = $(window).scrollTop() + $(window).height();

 if (elementTop < windowBottom - 50) {
 $(this).addClass('visible');
 }
 });
 }

 $(window).on('scroll', checkVisibility);
 checkVisibility(); 

 // Countdown Timer Logic
 var countDownDate = new Date("Aug 14, 2026 10:30:00").getTime();

 var x = setInterval(function() {
 var now = new Date().getTime();
 var distance = countDownDate - now;

 var days = Math.floor(distance / (1000 * 60 * 60 * 24));
 var hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
 var minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
 var seconds = Math.floor((distance % (1000 * 60)) / 1000);

 $('#days').text(days < 10 ? '0' + days : days);
 $('#hours').text(hours < 10 ? '0' + hours : hours);
 $('#minutes').text(minutes < 10 ? '0' + minutes : minutes);
 $('#seconds').text(seconds < 10 ? '0' + seconds : seconds);

 if (distance < 0) {
 clearInterval(x);
 $("#countdown").html("<div style='color: var(--accent-gold); font-size: 1.5rem; font-family: Montserrat, sans-serif; font-weight: 700; text-shadow: 1px 1px 3px rgba(0,0,0,0.1);' class='hover-effect'>The celebration has begun!</div>");
 }
 }, 1000);
 });
 </script>
