 The Engineer's Perspective 

 Because I know you deal with high-concurrency systems, I want to clarify exactly what this file represents. 

 I essentially built a lightweight State Machine inside the browser. The activeOrder object and the moveTicket() function simulate a WebSocket connection between the frontend and the backend database. 

 When you actually build this in React or FastAPI, the logic will be the same, but instead of calling a JavaScript function directly, the Kitchen iPad will make a PATCH /api/orders/{id} request to your database, and your server will push that update to the customer's phone via SSE (Server-Sent Events) or WebSockets to move the progress bar. 

 This is the exact layout you can give her right now. What do you think?

Here is the absolute final, complete codebase for your DynamoMCP project. 

 I have consolidated everything into the four essential files. This stack features the dual-lane "safe/dangerous" graph, hot-reloading MCP tools, the FastAPI WebSocket bridge, and the beautiful Markdown-rendered UI. 

 1. server.py (The MCP Backend) 

 This handles your tool execution, including the Hot-Reloading promote_tool . 

 import os
import yaml
import httpx
import logging
import sys
import asyncio
import shutil
from mcp.server.fastmcp import FastMCP, Context
from pydantic import create_model

logging.basicConfig(level=logging.INFO, stream=sys.stderr, format='%(asctime)s - %(levelname)s - %(message)s', datefmt='%H:%M:%S')
logger = logging.getLogger("DynamoServer")

mcp = FastMCP("DynamoServer")

# --- ADMIN TOOLS (DANGEROUS) ---

@mcp.tool()
async def build_custom_tool(name: str, description: str, python_code: str, parameters: dict = None):
 """Creates a native Python execution tool to the /pending directory."""
 if parameters is None: parameters = {}
 config = {"name": name, "description": description, "parameters": parameters, "code": python_code}
 os.makedirs("./tools/pending", exist_ok=True)
 with open(f"./tools/pending/{name}.yaml", "w") as f:
 yaml.dump(config, f, sort_keys=False, default_flow_style=False)
 return f"✅ Native tool '{name}' drafted to /pending. Ready for sandbox testing."

@mcp.tool()
async def test_tool_sandbox(name: str, test_payload: dict = None):
 """Simulates calling a drafted tool in the /pending directory."""
 if test_payload is None: test_payload = {}
 pending_path = f"./tools/pending/{name}.yaml"
 if not os.path.exists(pending_path): return f"❌ Tool '{name}' not found in pending."

 with open(pending_path) as f: cfg = yaml.safe_load(f)
 if 'code' in cfg:
 logger.info(f"🧪 SANDBOX: Testing {name}...")
 indented_code = "\n".join([f" {line}" for line in cfg['code'].split("\n")])
 wrapper = f"async def _run_sandbox(args):\n{indented_code}"
 namespace = {}
 try:
 exec(wrapper, globals(), namespace)
 func = namespace['_run_sandbox']
 return await func(test_payload)
 except Exception as e:
 return {"error": "Sandbox Execution Error", "details": str(e)}
 return {"error": "Not a python code tool"}

@mcp.tool()
async def promote_tool(name: str):
 """Moves a tool to active directory AND HOT-RELOADS it into the server memory."""
 src = f"./tools/pending/{name}.yaml"
 dest = f"./tools/{name}.yaml"
 if os.path.exists(src):
 shutil.move(src, dest)

 # 🔥 HOT RELOAD LOGIC 🔥
 with open(dest) as f: cfg = yaml.safe_load(f)
 field_definitions = {k: (str, v.get('default', ...)) for k, v in cfg.get('parameters', {}).items()}
 ToolModel = create_model(f"{cfg['name']}Model", **field_definitions)

 @mcp.tool(name=cfg['name'])
 async def dynamic_tool(args: ToolModel, ctx: Context, cfg=cfg):
 if 'code' in cfg:
 indented_code = "\n".join([f" {line}" for line in cfg['code'].split("\n")])
 wrapper = f"async def _run_custom(args):\n{indented_code}"
 namespace = {}
 try:
 exec(wrapper, globals(), namespace)
 func = namespace['_run_custom']
 return await func(args.model_dump())
 except Exception as e: return {"error": "Execution Error", "details": str(e)}

 return f"🚀 Tool '{name}' is LIVE and HOT-RELOADED! You can use it right now without restarting."
 return "❌ Source file not found."

# --- API HELPERS & TOOL LOADER ---

async def call_api(url, method, payload, config):
 async with httpx.AsyncClient(timeout=120.0) as client: 
 files, data = {}, {}
 params_cfg = config.get('parameters', {})
 for key, value in payload.items():
 if params_cfg.get(key, {}).get('type') == 'file':
 clean_path = str(value).strip('"').strip("'")
 if os.path.exists(clean_path): files[key] = (os.path.basename(clean_path), open(clean_path, 'rb'))
 else: return {"error": f"File not found: {clean_path}"}
 else: data[key] = str(value).lower() if isinstance(value, bool) else str(value)
 try:
 resp = await client.post(url, data=data, files=files) if files else await client.post(url, json=data) if method.upper() == "POST" else await client.get(url, params=data)
 for _, f_tuple in files.items(): f_tuple[1].close()
 try: return resp.json()
 except: return {"status": resp.status_code, "raw_response": resp.text}
 except Exception as e: return {"error": "API Error", "details": str(e)}

def load_tools():
 tools_dir = "./tools"
 os.makedirs(tools_dir, exist_ok=True)
 for filename in os.listdir(tools_dir):
 if filename.endswith(".yaml"):
 with open(os.path.join(tools_dir, filename)) as f: cfg = yaml.safe_load(f)
 field_definitions = {name: (str, info.get('default', ...)) for name, info in cfg.get('parameters', {}).items()}
 ToolModel = create_model(f"{cfg['name']}Model", **field_definitions)

 @mcp.tool(name=cfg['name'])
 async def dynamic_tool(args: ToolModel, ctx: Context, cfg=cfg):
 if 'code' in cfg:
 indented_code = "\n".join([f" {line}" for line in cfg['code'].split("\n")])
 wrapper = f"async def _run_custom(args):\n{indented_code}"
 namespace = {}
 try:
 exec(wrapper, globals(), namespace)
 func = namespace['_run_custom']
 return await func(args.model_dump())
 except Exception as e: return {"error": "Execution Error", "details": str(e)}
 elif 'endpoint' in cfg:
 async def heartbeat():
 seconds = 0
 while True:
 await asyncio.sleep(5)
 seconds += 5
 try: await ctx.report_progress(seconds, 120, f"Processing... {seconds}s")
 except: break
 pulse_task = asyncio.create_task(heartbeat())
 try: return await call_api(cfg['endpoint'], cfg['method'], args.model_dump(), cfg)
 finally: pulse_task.cancel()
 dynamic_tool.__doc__ = cfg['description']
 logger.info(f"✅ Registered: {cfg['name']}")

load_tools()

if __name__ == "__main__":
 logger.info("🚀 Starting MCP Server over SSE on port 8000...")
 mcp.run(transport="sse")

 2. main.py (The LangGraph Engine) 

 This defines the AI's logic, separating safe tools from dangerous file-system tools. 

 from langchain_core.messages import SystemMessage
from langgraph.graph import StateGraph, START, END, MessagesState
from langgraph.prebuilt import ToolNode

DANGEROUS_TOOLS = ["build_custom_tool", "test_tool_sandbox", "promote_tool"]

def build_agent(llm, tools, memory):
 llm_with_tools = llm.bind_tools(tools)

 async def call_model(state: MessagesState):
 sys_prompt = SystemMessage(content="""You are an elite AI Tool Engineer.

 CRITICAL LOGIC RULES:
 1. HOT-RELOADING: When you use `promote_tool`, the tool is INSTANTLY LIVE. Do NOT tell the user to restart the server. You can immediately use the new tool.
 2. NEVER GUESS TOOLS: If a user asks to do a task, look at your existing tools. If you lack the exact tool, offer to build it. DO NOT hallucinate tools.
 3. CODE RULE: The `python_code` for `build_custom_tool` MUST end with a `return` statement returning a JSON-serializable dictionary (e.g. `return {"status": "success", "result": ...}`).
 """)
 response = await llm_with_tools.ainvoke([sys_prompt] + state['messages'])
 return {"messages": [response]}

 def should_continue(state: MessagesState):
 last_msg = state['messages'][-1]
 if not hasattr(last_msg, 'tool_calls') or not last_msg.tool_calls:
 return END

 for tc in last_msg.tool_calls:
 if tc['name'] in DANGEROUS_TOOLS:
 return "dangerous_tools"
 return "safe_tools"

 workflow = StateGraph(MessagesState)
 workflow.add_node("agent", call_model)
 workflow.add_node("safe_tools", ToolNode(tools)) 
 workflow.add_node("dangerous_tools", ToolNode(tools)) 

 workflow.add_edge(START, "agent")
 workflow.add_conditional_edges("agent", should_continue, ["safe_tools", "dangerous_tools", END])
 workflow.add_edge("safe_tools", "agent") 
 workflow.add_edge("dangerous_tools", "agent") 

 # HARD BREAKPOINT: Only pause for the dangerous tools!
 return workflow.compile(checkpointer=memory, interrupt_before=["dangerous_tools"])

 3. app.py (The FastAPI Web Server) 

 This connects the LangGraph backend to your web browser via WebSockets. 

 import os
import json
from fastapi import FastAPI, WebSocket, WebSocketDisconnect
from fastapi.responses import HTMLResponse
from dotenv import load_dotenv

from langchain_openai import ChatOpenAI
from langchain_core.messages import ToolMessage
from langgraph.checkpoint.memory import MemorySaver
from mcp import ClientSession
from mcp.client.sse import sse_client
from langchain_mcp_adapters.tools import load_mcp_tools

from main import build_agent, DANGEROUS_TOOLS

load_dotenv()
app = FastAPI()
memory = MemorySaver()

@app.get("/")
async def get_ui():
 with open("index.html", "r") as f:
 return HTMLResponse(f.read())

@app.websocket("/ws/chat")
async def websocket_endpoint(websocket: WebSocket):
 await websocket.accept()
 if not os.getenv("OPENAI_API_KEY"):
 await websocket.send_text(json.dumps({"type": "system", "content": "❌ OPENAI_API_KEY missing from .env!"}))
 return

 llm = ChatOpenAI(model="gpt-4o", temperature=0)
 mcp_url = "http://localhost:8000/sse"

 try:
 async with sse_client(url=mcp_url) as (read, write):
 async with ClientSession(read, write) as session:
 await session.initialize()
 config = {"configurable": {"thread_id": "dynamo_web_final"}}

 await websocket.send_text(json.dumps({"type": "system", "content": "✅ Connected to DynamoMCP. Ready for tasks!"}))
 processed_ids = set() # Tracks messages so they never double-print

 while True:
 data = await websocket.receive_text()
 payload = json.loads(data)
 action = payload.get("action")

 try:
 if action == "chat":
 user_msg = payload.get("message")
 # 🔥 HOT REFRESH: Fetch latest tools EVERY chat so hot-reloads apply instantly
 tools = await load_mcp_tools(session)
 agent = build_agent(llm, tools, memory)
 stream = agent.astream({"messages": [("user", user_msg)]}, config, stream_mode="values")

 elif action == "approve":
 stream = agent.astream(None, config, stream_mode="values")

 elif action == "reject":
 state = agent.get_state(config)
 last_msg = state.values["messages"][-1]
 # Create mock tool responses so the LLM knows the user rejected it
 tool_msgs = [ToolMessage(tool_call_id=tc['id'], name=tc['name'], content="USER REJECTED TOOL EXECUTION.") for tc in last_msg.tool_calls]
 agent.update_state(config, {"messages": tool_msgs})
 await websocket.send_text(json.dumps({"type": "system", "content": "❌ Tool execution cancelled."}))
 stream = agent.astream(None, config, stream_mode="values")

 # Process the LangGraph stream
 async for event in stream:
 latest_msg = event["messages"][-1]

 if latest_msg.id in processed_ids: continue
 processed_ids.add(latest_msg.id)

 if latest_msg.type == "ai":
 if hasattr(latest_msg, 'tool_calls') and latest_msg.tool_calls:
 for tc in latest_msg.tool_calls:
 icon = "⚠️" if tc['name'] in DANGEROUS_TOOLS else "⚡"
 msg = f"<b>{icon} Tool Call:</b> <code>{tc['name']}</code><br><b>Args:</b> <pre>{json.dumps(tc['args'], indent=2)}</pre>"
 await websocket.send_text(json.dumps({"type": "tool_call", "content": msg}))
 elif latest_msg.content:
 await websocket.send_text(json.dumps({"type": "ai_message", "content": latest_msg.content}))

 elif latest_msg.type == "tool":
 await websocket.send_text(json.dumps({"type": "tool_result", "content": f"✅ <b>Finished:</b> {latest_msg.name}"}))

 # Check if we hit the Dangerous Tool Breakpoint
 state = agent.get_state(config)
 if state.next and state.next[0] == "dangerous_tools":
 last_msg = state.values["messages"][-1]
 pending_tools = [tc['name'] for tc in last_msg.tool_calls] if hasattr(last_msg, 'tool_calls') else []
 await websocket.send_text(json.dumps({"type": "pause", "tools": pending_tools}))

 except Exception as e:
 await websocket.send_text(json.dumps({"type": "system", "content": f"❌ Error: {str(e)}"}))

 except WebSocketDisconnect:
 print("Client disconnected.")

