 <script>
 const chatContainer = document.getElementById("chat-container");
 const approvalBox = document.getElementById("approval-box");
 const approvalText = document.getElementById("approval-text");
 const chatBox = document.getElementById("chat-box");
 const messageInput = document.getElementById("message-input");
 const loadingIndicator = document.getElementById("loading-indicator");

 marked.setOptions({ breaks: true, gfm: true });
 const ws = new WebSocket(`ws://${window.location.host}/ws/chat`);

 function appendMessage(content, role) {
 const row = document.createElement("div");
 row.className = `message-row ${role === 'user' ? 'user-row' : (role === 'system' ? '' : 'ai-row')}`;

 if (role === 'system') {
 row.innerHTML = `<div class="sys-msg">${content}</div>`;
 } else {
 const bubble = document.createElement("div");
 bubble.className = `message-bubble ${role === 'user' ? 'user-msg' : (role === 'tool' ? 'tool-msg' : 'ai-msg')}`;

 if (role === 'user') bubble.textContent = content;
 else if (role === 'tool') bubble.innerHTML = content;
 else bubble.innerHTML = marked.parse(content);

 row.appendChild(bubble);
 }
 chatContainer.appendChild(row);
 scrollToBottom();
 }

 ws.onmessage = function(event) {
 loadingIndicator.style.display = "none";
 const data = JSON.parse(event.data);

 if (data.type === "pause") {
 const toolNames = data.tools && data.tools.length > 0 ? data.tools.join(', ') : 'File System Tools';
 approvalText.innerHTML = `⚠️ Approval Required: <code>${toolNames}</code>`;
 approvalBox.style.display = "block";
 chatBox.style.display = "none";
 scrollToBottom();
 return;
 }

 if (data.type === "system") appendMessage(data.content, "system");
 else if (data.type === "ai_message") appendMessage(data.content, "ai");
 else if (data.type === "tool_call") {
 try {
 const parser = new DOMParser();
 const doc = parser.parseFromString(data.content, 'text/html');
 const toolName = doc.querySelector('code').textContent;
 const rawJson = doc.querySelector('pre').textContent;
 const cleanHTML = `
 <div class="fw-bold mb-1">🛠️ Preparing Execution: <span class="text-warning">${toolName}</span></div>
 <details><summary>View Payload & Code</summary><pre><code>${rawJson}</code></pre></details>
 `;
 appendMessage(cleanHTML, "tool");
 } catch (e) { appendMessage(data.content, "tool"); }
 }
 else if (data.type === "tool_result") {
 appendMessage(`<div class="text-success fw-bold">${data.content}</div>`, "tool");
 }
 };

 function sendMessage() {
 const text = messageInput.value.trim();
 if (!text) return;
 appendMessage(text, "user");
 ws.send(JSON.stringify({ action: "chat", message: text }));
 messageInput.value = "";
 loadingIndicator.style.display = "block";
 scrollToBottom();
 }

 function sendAction(actionType) {
 approvalBox.style.display = "none";
 chatBox.style.display = "flex";
 loadingIndicator.style.display = "block";
 ws.send(JSON.stringify({ action: actionType }));
 }

 function handleKeyPress(event) { if (event.key === "Enter") sendMessage(); }
 function scrollToBottom() { chatContainer.scrollTo({ top: chatContainer.scrollHeight, behavior: 'smooth' }); }
 </script>
