 3. The Offline Worker ( sw.js ) 

 Create a new file named sw.js . This Service Worker intercepts network requests and caches your files so the app loads instantly at the gym, even if your connection drops. 

 const CACHE_NAME = 'fitforge-v1';
const ASSETS = [
 '/',
 '/index.html',
 '/data.json',
 '/manifest.json',
 '/Personality.svg'
];

self.addEventListener('install', (e) => {
 e.waitUntil(caches.open(CACHE_NAME).then((cache) => cache.addAll(ASSETS)));
});

self.addEventListener('fetch', (e) => {
 e.respondWith(caches.match(e.request).then((res) => res || fetch(e.request)));
});

