 5. The JavaScript Logic ( js/app.js ) 

 This script handles fetching the JSON files, generating the HTML for each API card dynamically, and managing the copy-to-clipboard actions. 

 document.addEventListener('DOMContentLoaded', () => {
 // Set dynamic year in footer
 document.getElementById('year').textContent = new Date().getFullYear();

 // Toggle Sidebar
 document.getElementById('sidebarCollapse').addEventListener('click', () => {
 document.getElementById('sidebar').classList.toggle('active');
 const content = document.getElementById('content');
 content.style.marginLeft = content.style.marginLeft === '0px' ? '260px' : '0px';
 });
});

// Load Category Data
async function loadCategory(category) {
 const container = document.getElementById('api-container');
 const title = document.getElementById('current-section-title');

 // Show loading state
 container.innerHTML = '<div class="text-center mt-5"><div class="spinner-border text-primary" role="status"></div></div>';

 // Map category slugs to JSON files and friendly names
 const config = {
 'dkyc': { file: 'data/dkyc.json', name: 'Jukshio DKYC APIs' },
 'defrauds': { file: 'data/defrauds.json', name: 'Defraud & Group Analysis' },
 'digilocker': { file: 'data/digilocker.json', name: 'DigiLocker Integration' },
 'verification': { file: 'data/verification.json', name: 'Verification APIs' }
 };

 const current = config[category];
 title.textContent = current.name;

 try {
 const response = await fetch(current.file);
 if (!response.ok) throw new Error('Failed to load data');
 const apis = await response.json();
 renderAPIs(apis);
 } catch (error) {
 container.innerHTML = `<div class="alert alert-danger">Error loading API data: ${error.message}. Ensure JSON files are in the /data folder.</div>`;
 }
}

// Render API Cards
function renderAPIs(apis) {
 const container = document.getElementById('api-container');
 container.innerHTML = ''; // Clear previous content

 apis.forEach((api, index) => {
 const uniqueId = `api-${index}`;

 // Generate Table Rows for Inputs
 let inputRows = '';
 if (api.inputs && api.inputs.length > 0) {
 inputRows = api.inputs.map(input => `
 <tr>
 <td class="fw-bold text-dark">${input.Param}</td>
 <td><span class="badge ${input["M/O"] === 'M' ? 'bg-danger' : 'bg-secondary'}">${input["M/O"]}</span></td>
 <td class="text-muted small">${input.Description}</td>
 </tr>
 `).join('');
 } else {
 inputRows = '<tr><td colspan="3" class="text-center text-muted">No specific parameters required.</td></tr>';
 }

 const html = `
 <div class="api-card">
 <div class="api-header">
 <div>
 <h5 class="mb-1">${api.title}</h5>
 <p class="mb-2 text-muted small">${api.description}</p>
 <div>
 <span class="api-method ${api.method === 'POST' ? 'method-post' : 'method-get'}">${api.method}</span>
 <span class="api-endpoint">${api.endpoint}</span>
 </div>
 </div>
 </div>

 <div class="api-body">
 <ul class="nav nav-tabs mb-3" id="tab-${uniqueId}" role="tablist">
 <li class="nav-item">
 <button class="nav-link active" data-bs-toggle="tab" data-bs-target="#inputs-${uniqueId}">Parameters</button>
 </li>
 <li class="nav-item">
 <button class="nav-link" data-bs-toggle="tab" data-bs-target="#curl-${uniqueId}">cURL</button>
 </li>
 <li class="nav-item">
 <button class="nav-link" data-bs-toggle="tab" data-bs-target="#response-${uniqueId}">Response</button>
 </li>
 </ul>

 <div class="tab-content">
 <div class="tab-pane fade show active" id="inputs-${uniqueId}">
 <div class="table-responsive">
 <table class="table table-hover align-middle">
 <thead class="table-light">
 <tr>
 <th style="width: 30%">Parameter</th>
 <th style="width: 10%">Type</th>
 <th>Description</th>
 </tr>
 </thead>
 <tbody>
 ${inputRows}
 </tbody>
 </table>
 </div>
 </div>

 <div class="tab-pane fade" id="curl-${uniqueId}">
 <div class="code-block">
 <button class="copy-btn" onclick="copyCode(this)">Copy</button>
 <code>${escapeHtml(api.curl)}</code>
 </div>
 </div>

 <div class="tab-pane fade" id="response-${uniqueId}">
 <div class="code-block">
 <code>${JSON.stringify(api.response, null, 2)}</code>
 </div>
 </div>
 </div>
 </div>
 </div>
 `;
 container.insertAdjacentHTML('beforeend', html);
 });
}

// Helper: Escape HTML to prevent XSS in code blocks
function escapeHtml(text) {
 if (!text) return '';
 return text
 .replace(/&/g, "&amp;")
 .replace(/</g, "&lt;")
 .replace(/>/g, "&gt;")
 .replace(/"/g, "&quot;")
 .replace(/'/g, "&#039;");
}

// Helper: Copy to Clipboard
function copyCode(btn) {
 const code = btn.nextElementSibling.innerText;
 navigator.clipboard.writeText(code).then(() => {
 const originalText = btn.innerText;
 btn.innerText = 'Copied!';
 setTimeout(() => btn.innerText = originalText, 2000);
 });
}

 How to Run This 

 Save the files exactly as shown in the folder structure. 

 Since this uses fetch to load JSON files, it must run on a server (browsers block local file fetching via file:// ). 

 To test locally: 

 If you have Python installed:
 cd jukshio-api-nexus
python3 -m http.server

 Then open http://localhost:8000 in your browser. 

 This will give you a smooth, pink-branded, fast-loading API documentation hub.

