 // Configuration: Map titles to JSON files
const DATA_SOURCES = {
 "Defraud & Group Analysis": "data/defrauds.json",
 "Jukshio DKYC (Manappuram)": "data/dkyc.json",
 "DigiLocker Integration": "data/digilocker.json",
 "Verification APIs": "data/verification.json"
};

const navMenu = document.getElementById('nav-menu');
const apiDisplayArea = document.getElementById('api-display-area');
const sectionTitle = document.getElementById('section-title');

// Initialize App
document.addEventListener('DOMContentLoaded', () => {
 renderSidebar();
 // Load first category by default
 loadCategory(Object.keys(DATA_SOURCES)[0]);
});

function renderSidebar() {
 navMenu.innerHTML = '';
 const categoryTitle = document.createElement('div');
 categoryTitle.className = 'nav-category';
 categoryTitle.textContent = 'API Categories';
 navMenu.appendChild(categoryTitle);

 Object.keys(DATA_SOURCES).forEach(key => {
 const item = document.createElement('a');
 item.className = 'nav-item';
 item.textContent = key;
 item.onclick = () => {
 document.querySelectorAll('.nav-item').forEach(el => el.classList.remove('active'));
 item.classList.add('active');
 loadCategory(key);
 };
 navMenu.appendChild(item);
 });

 // Set first active
 document.querySelector('.nav-item').classList.add('active');
}

async function loadCategory(categoryName) {
 sectionTitle.textContent = categoryName;
 apiDisplayArea.innerHTML = '<div class="loading">Loading APIs...</div>';

 const filePath = DATA_SOURCES[categoryName];
 try {
 const response = await fetch(filePath);
 if (!response.ok) throw new Error("Failed to load data");
 const apis = await response.json();
 renderAPIs(apis);
 } catch (error) {
 apiDisplayArea.innerHTML = `<div class="error">⚠️ Error loading data: ${error.message}</div>`;
 }
}

function renderAPIs(apis) {
 apiDisplayArea.innerHTML = '';

 apis.forEach(api => {
 const card = document.createElement('div');
 card.className = 'api-card';

 // Input Table HTML
 let inputTableHtml = '<p class="text-muted">No specific parameters.</p>';
 if (api.inputs && api.inputs.length > 0) {
 const rows = api.inputs.map(input => `
 <tr>
 <td style="font-family: var(--font-code); color: var(--primary-color);">${input.Param}</td>
 <td class="${input['M/O'] === 'M' ? 'required' : ''}">${input['M/O']}</td>
 <td>${input.Description}</td>
 </tr>
 `).join('');

 inputTableHtml = `
 <table>
 <thead><tr><th>Parameter</th><th>M/O</th><th>Description</th></tr></thead>
 <tbody>${rows}</tbody>
 </table>
 `;
 }

 // Output JSON Formatting
 const outputJson = JSON.stringify(api.outputs, null, 2);

 card.innerHTML = `
 <div class="card-header">
 <div class="endpoint-badge">
 <span class="method">${api.method || 'POST'}</span>
 <span class="path">${api.endpoint}</span>
 </div>
 <span class="source-tag">${api.source}</span>
 </div>
 <div class="card-body">
 <h3 style="margin-bottom: 8px;">${api.title}</h3>
 <p class="description">${api.description}</p>

 <div class="io-grid">
 <div class="input-section">
 <span class="section-label">Input Parameters</span>
 ${inputTableHtml}

 <span class="section-label" style="margin-top: 20px;">cURL Request</span>
 <div class="code-block">
 <button class="copy-btn" onclick="copyToClipboard(this)">Copy</button>
 <code>${escapeHtml(api.curl)}</code>
 </div>
 </div>

 <div class="output-section">
 <span class="section-label">200 Success Response</span>
 <div class="code-block">
 <button class="copy-btn" onclick="copyToClipboard(this)">Copy</button>
 <code class="json">${syntaxHighlight(outputJson)}</code>
 </div>
 </div>
 </div>
 </div>
 `;
 apiDisplayArea.appendChild(card);
 });
}

// Utility: Escape HTML for code blocks
function escapeHtml(text) {
 if (!text) return '';
 return text.replace(/&/g, "&amp;")
 .replace(/</g, "&lt;")
 .replace(/>/g, "&gt;")
 .replace(/"/g, "&quot;")
 .replace(/'/g, "&#039;");
}

// Utility: Syntax Highlight JSON
function syntaxHighlight(json) {
 json = json.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
 return json.replace(/("(\\u[a-zA-Z0-9]{4}|\\[^u]|[^\\"])*"(\s*:)?|\b(true|false|null)\b|-?\d+(?:\.\d*)?(?:[eE][+\-]?\d+)?)/g, function (match) {
 let cls = 'number';
 if (/^"/.test(match)) {
 if (/:$/.test(match)) {
 cls = 'key';
 match = match.replace(':', '');
 return `<span style="color: #9cdcfe">${match}</span>:`;
 } else {
 cls = 'string';
 return `<span style="color: #ce9178">${match}</span>`;
 }
 } else if (/true|false/.test(match)) {
 return `<span style="color: #569cd6">${match}</span>`;
 } else if (/null/.test(match)) {
 return `<span style="color: #569cd6">${match}</span>`;
 }
 return `<span style="color: #b5cea8">${match}</span>`;
 });
}

function copyToClipboard(btn) {
 const code = btn.nextElementSibling.innerText;
 navigator.clipboard.writeText(code);
 const originalText = btn.textContent;
 btn.textContent = 'Copied!';
 setTimeout(() => btn.textContent = originalText, 2000);
}

