 autoFlipInterval = setInterval(() => {
 flipper.classList.toggle('flipped');
 }, 4000);
 }

 toggler.addEventListener('click', (e) => {
 e.preventDefault();
 bsCollapse.toggle();
 flipper.classList.toggle('flipped');
 startAutoFlip();
 });

 startAutoFlip();

 if (isDesktop) {
 const navbarNav = document.querySelector('.navbar-nav');
 setTimeout(() => {
 bsCollapse.show();
 navbarNav.classList.add('peek-animation');
 }, 1000);

 navbarNav.addEventListener('animationend', (event) => {
 if(event.animationName === 'peekAndHide') {
 bsCollapse.hide();
 navbarNav.classList.remove('peek-animation');
 }
 });
 }
 }
 setupCustomToggler();

 const navLinks = document.querySelectorAll('.nav-link');
 const navbar = document.querySelector('.navbar');
 navLinks.forEach(link => {
 if (link.getAttribute('href').startsWith('#')) {
 link.addEventListener('click', (event) => {
 event.preventDefault();
 const targetId = link.getAttribute('href');
 const targetElement = document.querySelector(targetId);
 if (targetElement) {
 const offset = navbar.offsetHeight;
 const elementPosition = targetElement.getBoundingClientRect().top;
 const offsetPosition = elementPosition + window.pageYOffset - offset;
 window.scrollTo({ top: offsetPosition, behavior: 'smooth' });

 const navbarCollapse = document.getElementById('navbarNav');

 if (navbarCollapse.classList.contains('show')) {
 const bsCollapse = bootstrap.Collapse.getInstance(navbarCollapse);
 bsCollapse.hide();
 }
 }
 });
 }
 });

 const contactForm = document.getElementById('contact-form');
 if (contactForm) {
 contactForm.addEventListener('submit', function(e) {
 e.preventDefault();
 const formStatus = document.getElementById('form-status');
 const formData = new FormData(contactForm);
 const object = Object.fromEntries(formData);
 const json = JSON.stringify(object);
 const button = contactForm.querySelector('button[type="submit"]');

 formStatus.innerHTML = "Sending...";
 button.disabled = true;

 fetch('https://api.web3forms.com/submit', {
 method: 'POST',
 headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
 body: json
 })
 .then(async (response) => {
 let result = await response.json();
 if (result.success) {
 formStatus.innerHTML = "Success! Your message has been sent.";
 formStatus.style.color = 'var(--teal)';
 contactForm.reset();
 } else {
 formStatus.innerHTML = result.message || "An error occurred.";
 formStatus.style.color = 'red';
 }
 })
 .catch(error => {
 formStatus.innerHTML = "Something went wrong!";
 formStatus.style.color = 'red';
 })
 .finally(() => {
 button.disabled = false;
 setTimeout(() => { formStatus.innerHTML = ''; }, 6000);
 });
 });
 }
