<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/vis-network@9.1.2/dist/dist/vis-network.min.js"></script>

<script>
 let sessionId = null;
 let network = null;

 function getSelectedAgents() {
 return Array.from(document.querySelectorAll('.agent-checkbox:checked'));
 }

 function updateAgentInfo() {
 const selectedCheckboxes = getSelectedAgents();
 const descriptionP = document.getElementById('agentDescription');
 const llmInfoDiv = document.getElementById('llmInfo');
 const llmModelSpan = document.getElementById('llmModel');
 const toolsInfoDiv = document.getElementById('toolsInfo');
 const toolsListDiv = document.getElementById('toolsList');

 if (selectedCheckboxes.length === 0) {
 descriptionP.textContent = 'Select an agent to see details.';
 llmInfoDiv.style.display = 'none';
 toolsInfoDiv.style.display = 'none';
 updateAgentNetwork();
 return;
 }

 let descriptions = [];
 let llmModels = new Set();
 let allTools = new Set();

 selectedCheckboxes.forEach(cb => {
 descriptions.push(`<strong>${cb.labels[0].querySelector('.agent-name').textContent}:</strong> ${cb.dataset.description}`);
 if (cb.dataset.llm) {
 llmModels.add(cb.dataset.llm);
 }
 if (cb.dataset.config) {
 try {
 const config = JSON.parse(cb.dataset.config);
 if (config.mcp && config.mcp.tools) {
 config.mcp.tools.forEach(tool => allTools.add(tool.name));
 }
 } catch (e) {
 console.error("Invalid agent config JSON", e);
 }
 }
 });

 descriptionP.innerHTML = descriptions.join('<br>');

 if (llmModels.size > 0) {
 llmModelSpan.textContent = Array.from(llmModels).join(', ');
 llmInfoDiv.style.display = 'block';
 } else {
 llmInfoDiv.style.display = 'none';
 }

 if (allTools.size > 0) {
 toolsListDiv.innerHTML = Array.from(allTools).map(tool =>
 `<span class="badge bg-secondary">${tool}</span>`
 ).join('');
 toolsInfoDiv.style.display = 'block';
 } else {
 toolsInfoDiv.style.display = 'none';
 }

 updateAgentNetwork();
 }

 function updateAgentNetwork() {
 const selectedCheckboxes = getSelectedAgents();
 const nodes = new vis.DataSet([]);
 const edges = new vis.DataSet([]);

 let masterAgent = selectedCheckboxes.find(cb => cb.value.includes('router') || cb.value.includes('manager'));

 if (masterAgent) {
 const masterId = masterAgent.value;
 const masterName = masterAgent.labels[0].querySelector('.agent-name').textContent;
 nodes.add({ id: masterId, label: masterName, color: '#007bff', font: { color: 'white' } });

 selectedCheckboxes.forEach(cb => {
 if (cb.value !== masterId) {
 const childId = cb.value;
 const childName = cb.labels[0].querySelector('.agent-name').textContent;
 nodes.add({ id: childId, label: childName });
 edges.add({ from: masterId, to: childId });
 }
 });
 } else {
 selectedCheckboxes.forEach(cb => {
 const agentId = cb.value;
 const agentName = cb.labels[0].querySelector('.agent-name').textContent;
 nodes.add({ id: agentId, label: agentName });
 });
 }

 network.setData({ nodes, edges });
 }

 async function sendMessage() {
 const input = document.getElementById('userInput');
 const message = input.value.trim();
 const selectedCheckboxes = getSelectedAgents();

 if (!message) return;
 if (selectedCheckboxes.length === 0) {
 alert('Please select at least one agent first');
 return;
 }

 const agentIds = selectedCheckboxes.map(cb => cb.value).join(',');
 const sendButton = document.getElementById('sendButton');

 input.disabled = true;
 sendButton.disabled = true;
 sendButton.innerHTML = `<span class="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span>`;
 document.querySelectorAll('.agent-checkbox').forEach(cb => cb.disabled = true);

 try {
 addMessage(message, true);
 input.value = '';

 const response = await fetch('/ask', {
 method: 'POST',
 headers: { 'Content-Type': 'application/json' },
 body: JSON.stringify({
 query: message,
 agent: agentIds,
 session_id: sessionId || null
 })
 });

 if (!response.ok) {
 const errorData = await response.json();
 throw new Error(errorData.detail || 'Failed to get response from agent');
 }

 const data = await response.json();

 if (!sessionId) {
 sessionId = data.session_id;
 }

 let responseText = data.result;
 if (typeof responseText === 'object') {
 responseText = responseText.result || JSON.stringify(responseText, null, 2);
 }
 addMessage(responseText);

 } catch (error) {
 console.error('Error:', error);
 addMessage(`Error: ${error.message}`);
 } finally {
 input.disabled = false;
 sendButton.disabled = false;
 sendButton.innerHTML = 'Send';
 document.querySelectorAll('.agent-checkbox').forEach(cb => cb.disabled = false);
 input.focus();
 }
 }

 function addMessage(content, isUser = false) {
 const chatContainer = document.getElementById('chatContainer');
 const messageDiv = document.createElement('div');
 messageDiv.className = `message ${isUser ? 'user-message' : 'agent-message'}`;
 const timestamp = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

 messageDiv.innerHTML = `
 <span class="message-time">${isUser ? 'You' : 'Agent'} at ${timestamp}</span>
 <div>${content}</div>
 `;

 chatContainer.appendChild(messageDiv);
 chatContainer.scrollTop = chatContainer.scrollHeight;
 }

 function initNetwork() {
 const container = document.getElementById('agentNetwork');
 const data = {
 nodes: new vis.DataSet([]),
 edges: new vis.DataSet([])
 };
 const options = {
 nodes: {
 shape: 'box',
 margin: 10,
 font: { size: 14, face: 'Poppins' },
 borderWidth: 1,
 color: {
 border: '#dee2e6',
 background: '#f8f9fa'
 }
 },
 edges: {
 arrows: 'to',
 smooth: { type: 'cubicBezier', roundness: 0.8 },
 color: '#adb5bd'
 },
 layout: {
 hierarchical: {
 direction: 'UD',
 sortMethod: 'directed',
 levelSeparation: 80,
 nodeSpacing: 120
 }
 },
 physics: false
 };
 network = new vis.Network(container, data, options);
 }

 document.querySelectorAll('.agent-checkbox').forEach(cb => {
 cb.addEventListener('change', updateAgentInfo);
 });

 document.getElementById('sendButton').addEventListener('click', sendMessage);
 document.getElementById('userInput').addEventListener('keypress', function (e) {
 if (e.key === 'Enter' && !e.shiftKey) {
 e.preventDefault();
 sendMessage();
 }
 });

 initNetwork();
 updateAgentInfo();
</script>
</body>
</html>

