 print("\n--- All Tables in Current Database ---")
 try:
 tables_query = "SHOW TABLES"
 tables_result = client.query(tables_query)
 if tables_result.result_rows:
 for row in tables_result.result_rows:
 print(f" - {row[0]}")
 return [row[0] for row in tables_result.result_rows] # Return list of tables
 else:
 print(" No tables found in the database.")
 return []
 except Exception as e:
 print(f" Error listing tables: {e}")
 return []

def get_distinct_trace_ids_with_timestamps(client, start_time=None, end_time=None, limit=20):
 """
 Lists distinct TraceIds along with their latest timestamp from the otel_traces table,
 ordered by timestamp descending, with an optional time range and limit.
 """
 print("\n--- Recent Trace IDs ---")
 try:
 base_query = "SELECT TraceId, max(Timestamp) AS LatestTimestamp FROM otel_traces"

 where_clauses = []
 if start_time:
 where_clauses.append(f"LatestTimestamp >= '{start_time.strftime('%Y-%m-%d %H:%M:%S')}'")
 if end_time:
 where_clauses.append(f"LatestTimestamp <= '{end_time.strftime('%Y-%m-%d %H:%M:%S')}'")

 if where_clauses:
 base_query += " WHERE " + " AND ".join(where_clauses)

 query = base_query + f" GROUP BY TraceId ORDER BY LatestTimestamp DESC LIMIT {limit}"

 trace_ids_result = client.query(query)
 if trace_ids_result.result_rows:
 trace_id_list = []
 for i, row in enumerate(trace_ids_result.result_rows):
 trace_id_list.append((row[0], row[1])) # (TraceId, Timestamp)
 print(f" {i+1}. {row[0]} (Last activity: {row[1]})")
 return trace_id_list
 else:
 print(" No distinct Trace IDs found.")
 return []
 except Exception as e:
 print(f" Error listing distinct Trace IDs: {e}")
 return []

# --- New Menu Functions ---

def select_time_range():
 """Prompts the user to select or input a time range."""
 time_options = {
 "1": "Last 1 Minute",
 "2": "Last 5 Minutes",
 "3": "Last 10 Minutes",
 "4": "Last 30 Minutes",
 "5": "Last 1 Hour",
 "6": "Last 5 Hours",
 "7": "Last 1 Day",
 "8": "Custom Range (IST)",
 "0": "All Time"
 }

 start_time_utc, end_time_utc = None, None
 now_utc = datetime.now(timezone.utc)
 # Using India Standard Time (IST) offset
 ist_offset = timedelta(hours=5, minutes=30)
 now_ist = now_utc + ist_offset

 while True:
 print("\nSelect a time range:")
 for key, value in time_options.items():
 print(f" {key}. {value}")

 choice = input("Enter your choice (1-8, 0 for all time): ").strip()

 if choice == "0":
 print("Time filter set to: All Time")
 break
 elif choice in time_options:
 if time_options[choice] == "Custom Range (IST)":
 print("Enter custom date and time range (IST):")
 while True:
 try:
 from_date_str = input("From Date (YYYY-MM-DD, e.g., 2023-01-15): ").strip()
 from_time_str = input("From Time (HH:MM:SS, e.g., 09:30:00): ").strip()
 to_date_str = input("To Date (YYYY-MM-DD, e.g., 2023-01-16): ").strip()
 to_time_str = input("To Time (HH:MM:SS, e.g., 17:00:00): ").strip()

 start_time_local = datetime.strptime(f"{from_date_str} {from_time_str}", "%Y-%m-%d %H:%M:%S")
 end_time_local = datetime.strptime(f"{to_date_str} {to_time_str}", "%Y-%m-%d %H:%M:%S")

 start_time_utc = start_time_local - ist_offset
 end_time_utc = end_time_local - ist_offset
 print(f"Time filter set to: Custom Range (IST: {start_time_local} to {end_time_local})")
 break
 except ValueError:
 print("Invalid date or time format. Please use YYYY-MM-DD and HH:MM:SS.")
 else:
 delta = None
 if time_options[choice] == "Last 1 Minute": delta = timedelta(minutes=1)
 elif time_options[choice] == "Last 5 Minutes": delta = timedelta(minutes=5)
 elif time_options[choice] == "Last 10 Minutes": delta = timedelta(minutes=10)
 elif time_options[choice] == "Last 30 Minutes": delta = timedelta(minutes=30)
 elif time_options[choice] == "Last 1 Hour": delta = timedelta(hours=1)
 elif time_options[choice] == "Last 5 Hours": delta = timedelta(hours=5)
 elif time_options[choice] == "Last 1 Day": delta = timedelta(days=1)

 if delta:
 start_time_utc = now_utc - delta
 end_time_utc = now_utc
 print(f"Time filter set to: {time_options[choice]} (UTC: {start_time_utc.strftime('%Y-%m-%d %H:%M:%S')} to {end_time_utc.strftime('%Y-%m-%d %H:%M:%S')})")

 break
 else:
 print("Invalid choice. Please enter a number from the menu.")
 return start_time_utc, end_time_utc

def view_traces_menu(client):
 """Allows user to select a time range and then a TraceId to view details."""
 print("\n--- View Traces ---")
 start_time, end_time = select_time_range()

 recent_trace_ids = get_distinct_trace_ids_with_timestamps(client, start_time, end_time, limit=50) # Increased limit for better selection

 if not recent_trace_ids:
 print("No traces found for the selected time range. Returning to main menu.")
 input("Press Enter to continue...")
 return

 while True:
 try:
 print("\nSelect a Trace ID to view details:")
 print(" (Enter the number corresponding to the Trace ID, or 'm' for main menu)")
 choice = input("Your choice: ").strip().lower()

 if choice == 'm':
 break

 idx = int(choice) - 1
 if 0 <= idx < len(recent_trace_ids):
 selected_trace_id = recent_trace_ids[idx][0] # Get the TraceId string
 query_and_display_trace_details(client, selected_trace_id)
 input("\nPress Enter to continue...")
 else:
 print("Invalid number. Please choose from the list.")
 except ValueError:
 print("Invalid input. Please enter a number or 'm'.")
 except Exception as e:
 print(f"An error occurred while fetching trace details: {e}")
 input("Press Enter to continue...")

def view_schema_menu(client):
 """Allows user to select a table to view its schema."""
 print("\n--- View Table Schema ---")
 available_tables = list_all_tables(client)

 if not available_tables:
 print("No tables found in the database. Returning to main menu.")
 input("Press Enter to continue...")
 return

 while True:
 try:
 print("\nSelect a table to view its schema:")
 for i, table_name in enumerate(available_tables):
 print(f" {i+1}. {table_name}")
 print(" (Enter the number corresponding to the table, or 'm' for main menu)")
 choice = input("Your choice: ").strip().lower()

 if choice == 'm':
 break

 idx = int(choice) - 1
 if 0 <= idx < len(available_tables):
 selected_table = available_tables[idx]
 display_table_schema(client, selected_table)
 input("\nPress Enter to continue...")
 else:
 print("Invalid number. Please choose from the list.")
 except ValueError:
 print("Invalid input. Please enter a number or 'm'.")
 except Exception as e:
 print(f"An error occurred while fetching schema: {e}")
 input("Press Enter to continue...")

def main():
 client = None
 try:
 client = clickhouse_connect.get_client(
 host=HOST,
 port=PORT,
 database=DATABASE,
 username=USERNAME,
 password=PASSWORD
 )
 print(f"Successfully connected to ClickHouse at {HOST}:{PORT}/{DATABASE}")

 while True:
 print("\n---------------------------------------------------")
 print(" SpanScan Menu ")
 print("---------------------------------------------------")
 print("1. View Traces (Interactive Selection & Time Filter)")
 print("2. View Table Schema")
 print("3. List All Tables")
 print("4. About SpanScan")
 print("0. Exit")
 print("---------------------------------------------------")

 choice = input("Enter your choice: ").strip()

 if choice == '1':
 view_traces_menu(client)
 elif choice == '2':
 view_schema_menu(client)
 elif choice == '3':
 list_all_tables(client)
 input("\nPress Enter to continue...")
 elif choice == '4':
 print("\n--- About SpanScan ---")
 print("SpanScan: Unraveling the Threads of Your Distributed Applications.")
 print("This interactive console tool helps you explore OpenTelemetry data (traces, logs, metrics)")
 print("stored in a ClickHouse database.")
 print("\nDeveloped by Ram Bikkina (ramarao.bikkina@jukshio.com) for Agentic AI Platform data visualization.")
 input("\nPress Enter to continue...")
 elif choice == '0':
 print("Exiting SpanScan. Goodbye!")
 break
 else:
 print("Invalid choice. Please enter a number from the menu.")

 except clickhouse_connect.driver.exceptions.OperationalError as e:
 print(f"Error connecting to ClickHouse: {e}")
 print("Please ensure your ClickHouse Docker container is running and accessible from 127.0.0.1:8123.")
 print("You can check its status with: `docker-compose ps`")
 except KeyboardInterrupt:
 print("\nExiting SpanScan due to user interruption.")
 except Exception as e:
 print(f"An unexpected error occurred: {e}")
 finally:
 if client:
 client.close()
 print("\nConnection to ClickHouse closed.")

if __name__ == "__main__":
 main()

