 <script>
 // --- Preloader Animation (from Design 2 - simpler spinner) ---
 $(window).on('load', function() {
 setTimeout(function() {
 $('.preloader').fadeOut(800);
 }, 1500);
 });

 // --- Three.js Background Animation (from Design 1 - with scroll-based zoom) ---
 let scene, camera, renderer, particles, core;
 let scrollY = 0;
 let targetZ = 15; // Initial camera Z position

 function init3D() {
 const canvas = document.getElementById('bg-canvas');
 scene = new THREE.Scene();
 camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
 renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, alpha: true });
 renderer.setSize(window.innerWidth, window.innerHeight);
 renderer.setClearColor(0x000000, 0); // Transparent background

 // --- AI Core (TorusKnot from Design 1) ---
 const coreGeometry = new THREE.TorusKnotGeometry(1.5, 0.4, 100, 16);
 const coreMaterial = new THREE.MeshBasicMaterial({ 
 color: 0x7a00ff, /* Using accent2 for core */
 wireframe: true,
 transparent: true,
 opacity: 0.5
 });
 core = new THREE.Mesh(coreGeometry, coreMaterial);
 scene.add(core);

 // --- Particle System (from Design 1) ---
 const particlesGeometry = new THREE.BufferGeometry();
 const particlesCount = 7000;
 const posArray = new Float32Array(particlesCount * 3);

 for (let i = 0; i < particlesCount * 3; i++) {
 posArray[i] = (Math.random() - 0.5) * 30;
 }
 particlesGeometry.setAttribute('position', new THREE.BufferAttribute(posArray, 3));

 const particlesMaterial = new THREE.PointsMaterial({
 size: 0.015,
 color: 0x00c6ff, /* Using accent for particles */
 transparent: true,
 blending: THREE.AdditiveBlending
 });
 particles = new THREE.Points(particlesGeometry, particlesMaterial);
 scene.add(particles);

 camera.position.z = targetZ;

 window.addEventListener('resize', onWindowResize, false);
 document.addEventListener('scroll', onScroll, false);
 animate();
 }

 function onWindowResize() {
 camera.aspect = window.innerWidth / window.innerHeight;
 camera.updateProjectionMatrix();
 renderer.setSize(window.innerWidth, window.innerHeight);
 }

 function onScroll() {
 scrollY = window.scrollY;
 // Adjust scroll percentage for the new layout (features section is lighter)
 const scrollPercent = scrollY / (document.body.scrollHeight - window.innerHeight);
 // Adjust targetZ to make the zoom less aggressive or tuned to the new content flow
 targetZ = 15 - (scrollPercent * 10); // Reduced zoom effect
 }

 const clock = new THREE.Clock();
 function animate() {
 requestAnimationFrame(animate);
 const elapsedTime = clock.getElapsedTime();

 // Animate particles and core
 particles.rotation.y = elapsedTime * 0.05;
 core.rotation.x = elapsedTime * 0.1;
 core.rotation.y = elapsedTime * 0.1;
 core.rotation.z = elapsedTime * 0.08;

 // Smoothly interpolate camera position
 camera.position.z += (targetZ - camera.position.z) * 0.05;

 renderer.render(scene, camera);
 }

 init3D();

 // Smooth scrolling for anchor links (from Design 2)
 $('a[href^="#"]').on('click', function(e) {
 // Only prevent default if it's an internal anchor and not a modal trigger
 if (!$(this).data('bs-toggle')) {
 e.preventDefault();
 var target = $(this.getAttribute('href'));
 if(target.length) {
 $('html, body').animate({
 scrollTop: target.offset().top - 80 // Adjust for fixed navbar
 }, 800);
 }
 }
 });

 // --- Web3Forms Integration for Modal Form ---
 const demoForm = document.getElementById('demoForm');
 const demoResult = document.getElementById('result');

 // Dynamically set the Web3Forms access key
 // IMPORTANT: Replace 'YOUR_WEB3FORMS_ACCESS_KEY_HERE' with your actual key.
 // For enhanced security in production, consider fetching this key from a secure API endpoint
 // rather than embedding it directly in client-side JavaScript.
 document.getElementById('web3forms_access_key').value = 'YOUR_WEB3FORMS_ACCESS_KEY_HERE'; 

 demoForm.addEventListener('submit', function(e) {
 e.preventDefault();
 demoResult.innerHTML = "Sending your request... 🚀 Please wait!"; // More engaging message

 const formData = new FormData(demoForm);
 const object = Object.fromEntries(formData);
 const json = JSON.stringify(object);

 fetch('https://api.web3forms.com/submit', {
 method: 'POST',
 headers: {
 'Content-Type': 'application/json',
 'Accept': 'application/json'
 },
 body: json
 })
 .then(async (response) => {
 let jsonResponse = await response.json();
 if (response.status === 200) {
 demoResult.innerHTML = "Awesome! Your demo request is confirmed. We'll be in touch soon! ✨";
 demoResult.style.color = 'var(--accent2)'; // ASTRA's purple for success
 } else {
 console.log(response);
 demoResult.innerHTML = "Uh oh! Something went wrong. Please try again or reach out directly! 😔";
 demoResult.style.color = 'red'; // Error color
 }
 })
 .catch(error => {
 console.log(error);
 demoResult.innerHTML = "Network error. Is your internet connected? Please try again! 📡";
 demoResult.style.color = 'red'; // Error color
 })
 .finally(function() {
 demoForm.reset();
 setTimeout(() => {
 demoResult.innerHTML = ""; // Clear message
 $('#scheduleDemoModal').modal('hide'); // Close modal after submission
 }, 4000); // Give user more time to read the exciting message
 });
 });
 </script>
