 document.addEventListener('DOMContentLoaded', () => {
 // --- Initialize Scenes and Cameras ---
 const heroContainer = document.getElementById('hero-canvas-container');
 const aboutContainer = document.getElementById('about-canvas-container');
 const educationContainer = document.getElementById('education-canvas-container');
 const experienceContainer = document.getElementById('experience-canvas-container');
 const contactContainer = document.getElementById('contact-canvas-container');

 const containers = {
 hero: heroContainer,
 about: aboutContainer,
 education: educationContainer,
 experience: experienceContainer,
 contact: contactContainer
 };

 const scenes = {};
 const cameras = {};
 const renderers = {};
 const sectionMeshes = {}; // Store meshes for each section

 // Initialize scene, camera, renderer for a container
 function initScene(containerId) {
 const container = containers[containerId];
 scenes[containerId] = new THREE.Scene();
 cameras[containerId] = new THREE.PerspectiveCamera(75, container.offsetWidth / container.offsetHeight, 0.1, 1000); // Using hero container width for aspect ratio initially, will resize
 renderers[containerId] = new THREE.WebGLRenderer({ alpha: true, antialias: true });
 renderers[containerId].setSize(container.offsetWidth, container.offsetHeight);
 renderers[containerId].setClearColor(0x000000, 0);
 container.appendChild(renderers[containerId].domElement);
 }

 // Create a mesh for a scene
 function createSectionMesh(containerId, geometry, color) {
 const material = new THREE.MeshStandardMaterial({ color: color, roughness: 0.5, metalness: 0.5 });
 const mesh = new THREE.Mesh(geometry, material);
 scenes[containerId].add(mesh);
 sectionMeshes[containerId] = mesh; // Store the mesh for later animation
 return mesh;
 }

 // Set up lighting for a scene
 function setupLighting(scene) {
 const ambientLight = new THREE.AmbientLight(0xFFFFFF, 0.5);
 scene.add(ambientLight);
 const directionalLight = new THREE.DirectionalLight(0xFFFFFF, 0.5);
 directionalLight.position.set(5, 3, 5);
 scene.add(directionalLight);
 }

 // Initialize all scenes
 initScene('hero');
 initScene('about');
 initScene('education');
 initScene('experience');
 initScene('contact');

 // --- Create Section Specific 3D Meshes and Lighting ---
 // Hero Scene - Torus Knot
 createSectionMesh('hero', new THREE.TorusKnotGeometry(10, 3, 100, 16), 0xAAAAAA);
 cameras.hero.position.z = 50;
 setupLighting(scenes.hero);

 // About Scene - Sphere
 createSectionMesh('about', new THREE.SphereGeometry(15, 32, 32), 0x87CEFA); // Light Sky Blue
 cameras.about.position.z = 50;
 setupLighting(scenes.about);

 // Education Scene - Cone
 createSectionMesh('education', new THREE.ConeGeometry(15, 30, 32), 0x90EE90); // Light Green
 cameras.education.position.z = 70; // Adjusted Z position for cone
 setupLighting(scenes.education);

 // Experience Scene - Cylinder
 createSectionMesh('experience', new THREE.CylinderGeometry(10, 10, 40, 32), 0xFFA07A); // Light Salmon
 cameras.experience.position.z = 70; // Adjusted Z position for cylinder
 setupLighting(scenes.experience);

 // Contact Scene - Box
 createSectionMesh('contact', new THREE.BoxGeometry(30, 30, 30), 0xD3D3D3); // Light Gray
 cameras.contact.position.z = 70; // Adjusted Z position for box
 setupLighting(scenes.contact);

 // --- Animation Loop ---
 function animate() {
 requestAnimationFrame(animate);

 // Rotate meshes in each scene - independent animation
 for (const containerId in sectionMeshes) {
 sectionMeshes[containerId].rotation.x += 0.005;
 sectionMeshes[containerId].rotation.y += 0.005;
 renderers[containerId].render(scenes[containerId], cameras[containerId]);
 }
 }
 animate();

 // --- Scroll Event Listener for Dynamic Animation ---
 document.addEventListener('scroll', () => {
 const heroSection = document.getElementById('hero');
 const aboutSection = document.getElementById('about');
 const educationSection = document.getElementById('education');
 const experienceSection = document.getElementById('experience');
 const contactSection = document.getElementById('contact');

 const heroRect = heroSection.getBoundingClientRect();
 const aboutRect = aboutSection.getBoundingClientRect();
 const educationRect = educationSection.getBoundingClientRect();
 const experienceRect = experienceSection.getBoundingClientRect();
 const contactRect = contactSection.getBoundingClientRect();

 // --- Hero Section Animation ---
 if (heroRect.top <= window.innerHeight && heroRect.bottom >= 0) {
 animateSectionMesh('hero', 0.01, 0.01, 50); // Example animation speed and camera Z
 } else {
 resetSectionAnimation('hero'); // Reset or pause animation when not in view
 }

 // --- About Section Animation ---
 if (aboutRect.top <= window.innerHeight && aboutRect.bottom >= 0) {
 animateSectionMesh('about', 0.02, -0.02, 60); // Different animation for About
 } else {
 resetSectionAnimation('about');
 }

 // --- Education Section Animation ---
 if (educationRect.top <= window.innerHeight && educationRect.bottom >= 0) {
 animateSectionMesh('education', -0.015, 0.015, 80); // Different animation for Education
 } else {
 resetSectionAnimation('education');
 }

 // --- Experience Section Animation ---
 if (experienceRect.top <= window.innerHeight && experienceRect.bottom >= 0) {
 animateSectionMesh('experience', 0.025, 0, 90); // Different animation for Experience
 } else {
 resetSectionAnimation('experience');
 }

 // --- Contact Section Animation ---
 if (contactRect.top <= window.innerHeight && contactRect.bottom >= 0) {
 animateSectionMesh('contact', 0, -0.025, 100); // Different animation for Contact
 } else {
 resetSectionAnimation('contact');
 }
 });

 // --- Animate Section Mesh Function ---
 function animateSectionMesh(containerId, rotationSpeedX, rotationSpeedY, cameraZ) {
 if (sectionMeshes[containerId]) {
 sectionMeshes[containerId].rotation.x += rotationSpeedX;
 sectionMeshes[containerId].rotation.y += rotationSpeedY;
 cameras[containerId].position.z = cameraZ; // Example of dynamic camera Z
 }
 }

 // --- Reset Section Animation Function (or pause) ---
 function resetSectionAnimation(containerId) {
 if (sectionMeshes[containerId]) {
 // Option 1: Stop rotation (pause animation)
 // sectionMeshes[containerId].rotation.set(0, 0, 0);

 // Option 2: Reset to a default rotation or animation state
 sectionMeshes[containerId].rotation.x = 0.005; // Example reset value, can be 0 or another starting rotation
 sectionMeshes[containerId].rotation.y = 0.005;
 cameras[containerId].position.z = 50; // Reset camera Z as well if needed
 }
 }

 // --- Scroll Reveal Animations for Text Content ---
 ScrollReveal().reveal('.content-section h2, .content-section p, .education-entry, .experience-entry, .contact-list li', {
 delay: 200,
 distance: '50px',
 origin: 'bottom',
 easing: 'ease-out',
 duration: 800,
 interval: 150
 });

 ScrollReveal().reveal('.hero-text h1, .hero-text .profession', {
 delay: 500,
 distance: '60px',
 origin: 'top',
 easing: 'ease-out',
 duration: 1000
 });

 // --- Responsive Canvas Size ---
 function onWindowResize() {
 for (const containerId in renderers) {
 cameras[containerId].aspect = containers[containerId].offsetWidth / containers[containerId].offsetHeight;
 cameras[containerId].updateProjectionMatrix();
 renderers[containerId].setSize(containers[containerId].offsetWidth, containers[containerId].offsetHeight);
 }
 }
 window.addEventListener('resize', onWindowResize, false);
});

 Key Changes in script.js : 

 Multiple Scenes and Containers: 

 Instead of one scene, we now have separate scenes, cameras, and renderers for each section ( hero , about , education , experience , contact ). 

 Containers for each scene are defined at the beginning ( heroContainer , aboutContainer , etc.) and stored in the containers object. 

 scenes , cameras , renderers , and sectionMeshes are now objects to hold the respective Three.js elements for each section, keyed by section ID. 

 initScene(containerId) Function: This function initializes a Three.js scene, camera, and renderer for a given container ID. It sets up the basic Three.js elements for each section's canvas. 

 createSectionMesh(containerId, geometry, color) Function: Creates a mesh with specified geometry and color, adds it to the scene of the given container ID, and stores the mesh in the sectionMeshes object for later animation control. 

 setupLighting(scene) Function: Sets up consistent lighting for each scene. 

 Section-Specific 3D Shapes: 

 Different 3D geometries are created for each section to visually differentiate them and potentially tell a story:

 hero : TorusKnotGeometry (complex, intriguing - for introduction) 

 about : SphereGeometry (rounded, holistic - for about me) 

 education : ConeGeometry (pointing upwards, growth - for education) 

 experience : CylinderGeometry (solid, building blocks - for experience) 

 contact : BoxGeometry (structured, grounded - for contact) 

 Different colors are also used to visually distinguish sections. 

 Animation Loop ( animate() ): 

 The animation loop now iterates through all section meshes and renders each scene independently. This allows each section's 3D element to animate continuously, even when not in view. 

 Scroll Event Listener (Dynamic Animation): 

 A scroll event listener is added to the document . 

 It gets the bounding rectangles of each section to determine if they are in the viewport ( rect.top <= window.innerHeight && rect.bottom >= 0 ). 

 animateSectionMesh(containerId, rotationSpeedX, rotationSpeedY, cameraZ) Function: When a section is in view, animateSectionMesh is called to:

 Dynamically adjust the rotation speeds ( rotationSpeedX , rotationSpeedY ) of the mesh in that section. 

 Change the camera's position.z to create a subtle zoom or perspective shift for each section. 

 resetSectionAnimation(containerId) Function: When a section is not in view, resetSectionAnimation is called to reset or pause the animation of that section's mesh. In the current implementation, it resets the rotation speeds to a default value and optionally resets the camera Z position. You can modify this to completely stop rotation or set different "inactive" animation states. 

 Responsive Canvas Size ( onWindowResize() ): 

 The onWindowResize function is updated to iterate through all renderers and cameras, updating their aspect ratios and sizes when the window is resized, ensuring all canvases are responsive. 

 To Use This Code: 

 Replace Files: Replace the content of your index.html , style.css , and script.js files with the updated code provided above. 

 Open index.html : Open index.html in your web browser and scroll through the page. 

 Explanation of Dynamic Animation and Storytelling: 

 Section-Specific Shapes and Colors: Each section now has a distinct 3D shape and color that can be conceptually linked to the section's content (as described above). This provides a visual theme that changes as you scroll. 

 Scroll-Based Animation Changes: As you scroll into each section, the animation of the 3D element in that section changes (rotation speed, camera position). This makes the animation interactive and tied to the user's navigation through the portfolio. 

 Storytelling through Visuals: The sequence of shapes (Torus Knot -> Sphere -> Cone -> Cylinder -> Box) and their changing animations can be interpreted as a visual story of your journey or skills. You can refine this narrative by choosing shapes and animations that more directly relate to your profession and personal story. 

 Customization and Next Steps: 

 Refine the Story: Think more deeply about the story you want to tell with the 3D animations. Choose shapes, colors, and animation styles that better represent your profession and personal brand. 

 More Complex Animations: Instead of just rotation and camera Z, explore more complex animations using Three.js animation features (e.g., morph targets, keyframe animations, or libraries like GSAP for animation sequencing and easing). 

 Interactive Elements: Add interactivity beyond scrolling. For example, make the 3D shapes respond to mouse hover or clicks to reveal more information or trigger different animations. 

 Load 3D Models: Instead of simple geometries, you could load custom 3D models (e.g., in .GLTF format) that are more visually rich and story-driven. 

 Performance: If you add more complex animations or models, monitor performance, especially on mobile devices. Optimize geometries, materials, and animation complexity as needed. 

 This enhanced version makes your portfolio website more engaging and visually dynamic by integrating Three.js animations that respond to scrolling and contribute to a visual narrative of your professional details.

