def _perform_health_check(agent_id: str, url: str, headers: Dict[str, str], timeout: int = 5) -> HealthPulse:
 """
 Internal helper to ping a URL and return a standardized HealthPulse.
 Now includes System Telemetry (CPU/RAM) and Token Header parsing.
 """
 start = time.time()

 # 1. System Telemetry (Hardware Heartbeat)
 try:
 process = psutil.Process(os.getpid())
 cpu_usage = psutil.cpu_percent(interval=None)
 ram_usage = process.memory_info().rss / (1024 * 1024) # MB
 except Exception:
 cpu_usage = 0.0
 ram_usage = 0.0

 status = "down"
 score = 0
 tokens_rem = "N/A"
 reset_time = "N/A"

 try:
 # 2. Network Request
 response = requests.get(url, headers=headers, timeout=timeout)

 # 3. Header Intelligence (Rate Limits)
 # OpenAI/Anthropic/Groq standard headers
 t_rem = response.headers.get("x-ratelimit-remaining-tokens") or \
 response.headers.get("x-ratelimit-remaining-requests")
 if t_rem: tokens_rem = t_rem

 r_reset = response.headers.get("x-ratelimit-reset-tokens") or \
 response.headers.get("x-ratelimit-reset-requests")
 if r_reset: reset_time = r_reset

 # 4. Status Logic
 if response.status_code == 200:
 status = "healthy"
 score = 100
 elif response.status_code == 429:
 status = "degraded" # Rate Limited
 score = 30
 print(f"⚠️ SAKSH WARNING: Agent {agent_id} Rate Limited (429)")
 elif response.status_code == 401:
 status = "down" 
 score = 0
 print(f"⚠️ SAKSH WARNING: Agent {agent_id} Failed Auth (401)")
 else:
 status = "degraded"
 score = 50

 except requests.exceptions.Timeout:
 status = "degraded"
 score = 40
 except Exception:
 status = "down"
 score = 0

 latency = (time.time() - start) * 1000

 # 5. Vitality Formula v1.1
 if status == "healthy":
 # Latency Penalty
 if latency > 1500: score -= 20
 if latency > 3000: score -= 40

 # Hardware Penalty (Is the agent hogging resources?)
 if cpu_usage > 85: score -= 15
 if cpu_usage > 95: score -= 30

 return HealthPulse(
 agent_id=agent_id,
 status=status,
 latency_ms=round(latency, 2),
 vitality_score=max(0, score),
 cpu_percent=round(cpu_usage, 1),
 ram_mb=round(ram_usage, 1),
 tokens_remaining=tokens_rem,
 rate_limit_reset=reset_time
 )

