 import threading
import uvicorn
import os
import abc
from typing import List, Dict, Any, Literal, Optional
from datetime import datetime
from pydantic import BaseModel, Field
from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware
from fastapi.staticfiles import StaticFiles

# --- UPDATED SCHEMA (v1.1.0) ---
class HealthPulse(BaseModel):
 agent_id: str
 status: Literal["healthy", "degraded", "down"]
 latency_ms: float
 timestamp: datetime = Field(default_factory=datetime.now)
 vitality_score: int
 # New Intelligence Fields
 cpu_percent: float = 0.0
 ram_mb: float = 0.0
 tokens_remaining: Optional[str] = "N/A" # String to handle "N/A" or numbers
 rate_limit_reset: Optional[str] = "N/A"

class Netra(abc.ABC):
 def __init__(self, agent_id: str):
 self.agent_id = agent_id

 @abc.abstractmethod
 def gaze(self) -> HealthPulse:
 pass

class Saksh:
 _instance = None 

 def __new__(cls, *args, **kwargs):
 if not cls._instance:
 cls._instance = super(Saksh, cls).__new__(cls)
 return cls._instance

 def __init__(self, start_dashboard=True, port=2604):
 if hasattr(self, '_initialized'): return
 self._thousand_eyes: List[Netra] = []
 self._initialized = True

 if start_dashboard:
 self._start_dashboard_thread(port)

 def open_eye(self, adapter: Netra):
 self._thousand_eyes.append(adapter)

 def observe(self) -> Dict[str, Any]:
 report = {
 "total": len(self._thousand_eyes), 
 "status": "stable", 
 "eyes": [],
 "generated_at": datetime.now().isoformat()
 }
 for eye in self._thousand_eyes:
 pulse = eye.gaze()
 report["eyes"].append(pulse.dict())
 if pulse.status == "down":
 report["status"] = "critical"
 return report

 def _start_dashboard_thread(self, port):
 def run_server():
 app = FastAPI(title="Saksh v1.1.0")

 app.add_middleware(
 CORSMiddleware,
 allow_origins=["*"],
 allow_methods=["*"],
 allow_headers=["*"],
 )

 @app.get("/api/status")
 def get_status():
 return self.observe()

 # Dynamic Static File Pathing
 current_dir = os.path.dirname(os.path.abspath(__file__))
 static_dir = os.path.join(current_dir, "dashboard", "static")

 if os.path.exists(static_dir):
 app.mount("/", StaticFiles(directory=static_dir, html=True), name="static")
 else:
 print(f"⚠️ SAKSH WARNING: Static UI not found at {static_dir}")

 print(f"\n👁️ SAKSH v1.1.0 ONLINE: http://localhost:{port}\n")

 # Run server without blocking main thread signals
 config = uvicorn.Config(app, host="0.0.0.0", port=port, log_level="critical")
 server = uvicorn.Server(config)
 server.run()

 thread = threading.Thread(target=run_server, daemon=True)
 thread.start()

 2. saksh/adapters.py 

 Updated with psutil logic, header parsing, and the new vitality formula. 

 import requests
import time
import os
import psutil
from typing import Dict, Any, Optional
from .core import Netra, HealthPulse

def _perform_health_check(agent_id: str, url: str, headers: Dict[str, str], timeout: int = 10) -> HealthPulse:
 """
 Core logic: Measures Latency, HTTP Status, CPU/RAM, and Token Headers.
 """
 start = time.time()

 # 1. System Telemetry
 try:
 process = psutil.Process(os.getpid())
 cpu_usage = psutil.cpu_percent(interval=None)
 ram_usage = process.memory_info().rss / (1024 * 1024) # MB
 except:
 cpu_usage, ram_usage = 0.0, 0.0

 status = "down"
 score = 0
 tokens_rem = "N/A"
 reset_time = "N/A"

 try:
 # 2. Network Call
 response = requests.get(url, headers=headers, timeout=timeout)
 latency = (time.time() - start) * 1000

 # 3. Header Intelligence (OpenAI/Anthropic standards)
 # We look for common rate limit headers
 t_rem = response.headers.get("x-ratelimit-remaining-tokens") \
 or response.headers.get("x-ratelimit-remaining-requests")
 if t_rem: tokens_rem = t_rem

 r_time = response.headers.get("x-ratelimit-reset-tokens") \
 or response.headers.get("x-ratelimit-reset-requests")
 if r_time: reset_time = r_time

 # 4. Status Logic
 if response.status_code == 200:
 status = "healthy"
 score = 100
 elif response.status_code == 429:
 status = "degraded" # Rate Limited
 score = 30 
 elif response.status_code == 401:
 status = "down" # Auth Failed
 score = 0
 else:
 status = "degraded"
 score = 50

 except Exception:
 status = "down"
 score = 0
 latency = (time.time() - start) * 1000

 # 5. Vitality Formula v1.1
 if status == "healthy":
 # Latency Penalties
 if latency > 1000: score -= 10
 if latency > 2500: score -= 30

 # Resource Penalties
 if cpu_usage > 80: score -= 15 # High CPU load
 if cpu_usage > 95: score -= 30 # Critical CPU load

 return HealthPulse(
 agent_id=agent_id,
 status=status,
 latency_ms=round(latency, 2),
 vitality_score=max(0, score),
 cpu_percent=round(cpu_usage, 1),
 ram_mb=round(ram_usage, 1),
 tokens_remaining=tokens_rem,
 rate_limit_reset=reset_time
 )

class CrewAINetra(Netra):
 def __init__(self, crewai_agent, agent_id: str):
 super().__init__(agent_id)
 self.agent = crewai_agent

 # Extract URL
 if hasattr(crewai_agent.llm, 'base_url') and crewai_agent.llm.base_url:
 self.target_url = crewai_agent.llm.base_url
 self.is_custom = True
 else:
 self.target_url = "https://api.openai.com/v1"
 self.is_custom = False

 # Extract Key
 self.api_key = getattr(crewai_agent.llm, 'api_key', None)
 if not self.api_key and not self.is_custom:
 self.api_key = os.getenv("OPENAI_API_KEY")

 def gaze(self) -> HealthPulse:
 if self.is_custom:
 base = self.target_url.rstrip("/")
 path = "/models" if "v1" in base else "/v1/models"
 check_url = base + path
 else:
 check_url = "https://api.openai.com/v1/models"

 headers = {}
 if self.api_key and self.api_key != "na":
 headers["Authorization"] = f"Bearer {self.api_key}"

 return _perform_health_check(self.agent_id, check_url, headers)

