 2. css/style.css (The Parchment Look) 

 Background: Dark wood texture ( #2c1515 ). 

 The Scroll: A centered container with box-shadow and clip-path (rough edges). 

 Kalava Loader: A red/yellow dashed line animation. 

 Ink Typography: Text uses mix-blend-mode: multiply to look like it's printed on the paper, not floating above it. 

 /* =========================================
 1. VARIABLES & RESET (V3)
========================================== */
:root {
 --paper-bg: #FDFCF0;
 --paper-texture: url('https://www.transparenttextures.com/patterns/cream-paper.png');
 --ink-color: #4B3621;
 --royal-red: #800000;
 --kalava-yellow: #FFC107;
 --kalava-red: #D32F2F;

 --font-heading: 'Rozha One', serif;
 --font-body: 'Playfair Display', serif;
 --font-telugu: 'Ramabhadra', sans-serif;
}

body {
 background-color: #2c1515; /* Dark Wood Background */
 background-image: linear-gradient(rgba(0,0,0,0.5), rgba(0,0,0,0.5)), url('https://www.transparenttextures.com/patterns/wood-pattern.png');
 color: var(--ink-color);
 font-family: var(--font-body);
 overflow-x: hidden;
}

body.overflow-hidden { overflow: hidden; height: 100vh; }

/* =========================================
 2. THE KALAVA LOADER (Sacred Thread)
========================================== */
#loader-overlay {
 position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;
 z-index: 9999;
}

/* Split Backgrounds for Opening Effect */
.loader-bg-top, .loader-bg-bottom {
 position: absolute; left: 0; width: 100%; height: 50%;
 background: #3e1e1e;
 transition: transform 1s ease-in-out;
}
.loader-bg-top { top: 0; transform-origin: top; border-bottom: 1px solid rgba(255,255,255,0.1); }
.loader-bg-bottom { bottom: 0; transform-origin: bottom; border-top: 1px solid rgba(0,0,0,0.3); }

/* The Thread */
.kalava-string {
 position: absolute; top: 50%; left: 0; width: 100%; height: 6px;
 margin-top: -3px;
 background: repeating-linear-gradient(90deg, var(--kalava-red) 0px, var(--kalava-red) 20px, var(--kalava-yellow) 20px, var(--kalava-yellow) 40px);
 box-shadow: 0 5px 10px rgba(0,0,0,0.5);
 z-index: 100;
}

/* The Knot */
.kalava-knot {
 position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
 width: 80px; height: 80px; z-index: 101; cursor: pointer;
 display: flex; flex-direction: column; align-items: center; justify-content: center;
}
.knot-center {
 width: 40px; height: 40px; background: var(--kalava-red);
 border-radius: 50%; border: 4px solid var(--kalava-yellow);
 box-shadow: 0 0 20px rgba(0,0,0,0.5);
 animation: pulse 2s infinite;
}
.knot-text {
 margin-top: 10px; color: #fff; font-size: 0.8rem; text-transform: uppercase; letter-spacing: 1px;
}
@keyframes pulse { 0% { transform: scale(1); } 50% { transform: scale(1.1); } 100% { transform: scale(1); } }

/* =========================================
 3. THE ROYAL SCROLL CONTAINER
========================================== */
.scroll-wrapper {
 display: flex; justify-content: center; padding: 50px 0;
 opacity: 0; /* Hidden initially */
 transform: translateY(50px);
}

.royal-scroll {
 width: 90%; max-width: 800px;
 background-color: var(--paper-bg);
 background-image: var(--paper-texture);
 box-shadow: 0 0 50px rgba(0,0,0,0.7);
 padding: 60px 40px;
 position: relative;

 /* Jagged Paper Edge Effect */
 mask-image: linear-gradient(to bottom, transparent 0%, black 2%, black 98%, transparent 100%);
 -webkit-mask-image: linear-gradient(to bottom, transparent 0%, black 2%, black 98%, transparent 100%);
}

/* Ink Typography Effects */
.ink-om { width: 60px; filter: sepia(1) hue-rotate(-50deg) saturate(3); opacity: 0.8; }
.ink-title { 
 font-family: var(--font-heading); font-size: 4.5rem; color: var(--royal-red);
 text-shadow: 2px 2px 0px rgba(0,0,0,0.1); line-height: 1;
}
.script-intro { font-family: 'Playfair Display', cursive; font-style: italic; font-size: 1.2rem; color: #666; }
.ink-line { height: 2px; background: var(--ink-color); width: 100px; margin: 0 auto; opacity: 0.5; border-radius: 50%; }

.ink-countdown { display: flex; justify-content: center; gap: 20px; font-family: var(--font-heading); color: var(--royal-red); }
.ink-time span { font-size: 2.5rem; display: block; line-height: 1; }
.ink-sep { font-size: 2rem; opacity: 0.3; }

/* Couple Stamps */
.photo-stamp {
 width: 250px; height: 300px; margin: 0 auto;
 border: 10px solid #fff; box-shadow: 2px 2px 10px rgba(0,0,0,0.2);
 transform: rotate(-2deg); transition: transform 0.3s;
}
.col-md-6:last-child .photo-stamp { transform: rotate(2deg); }
.photo-stamp img { width: 100%; height: 100%; object-fit: cover; filter: sepia(0.2); }

/* Events Ink Box */
.event-ink-box {
 border: 2px solid var(--ink-color); padding: 20px; margin: 20px auto; max-width: 400px;
 position: relative;
}
.highlight-ink { border-color: var(--royal-red); color: var(--royal-red); background: rgba(128,0,0,0.05); }
.vertical-ink-line { height: 40px; width: 1px; background: var(--ink-color); margin: 0 auto; opacity: 0.3; }

/* Polaroid Gallery */
.polaroid-img {
 width: 100%; height: 250px; object-fit: cover;
 border: 8px solid #fff; border-bottom: 20px solid #fff;
 box-shadow: 0 4px 8px rgba(0,0,0,0.1);
 filter: contrast(1.1); transition: transform 0.3s;
}
.polaroid-img:hover { transform: scale(1.05) rotate(1deg); z-index: 5; }

/* =========================================
 4. BOOKMARK NAV
========================================== */
.bookmark-nav {
 position: fixed; right: 0; top: 50%; transform: translateY(-50%);
 display: flex; flex-direction: column; gap: 10px; z-index: 500;
}
.book-link {
 background: var(--royal-red); color: var(--kalava-yellow);
 padding: 10px 15px 10px 10px; text-decoration: none;
 font-family: var(--font-heading); font-size: 0.9rem;
 border-radius: 5px 0 0 5px; margin-right: -80px; /* Hide text */
 transition: margin-right 0.3s ease;
 box-shadow: -2px 2px 5px rgba(0,0,0,0.3);
}
.book-link:hover, .book-link.active { margin-right: 0; }

/* Button */
.btn-ink {
 display: inline-block; border: 2px solid var(--royal-red); color: var(--royal-red);
 padding: 10px 30px; text-decoration: none; font-weight: bold; transition: 0.3s;
}
.btn-ink:hover { background: var(--royal-red); color: #fff; }

/* Mobile */
@media (max-width: 768px) {
 .royal-scroll { width: 95%; padding: 40px 20px; }
 .ink-title { font-size: 3rem; }
 .bookmark-nav { display: none; } /* Hide on mobile */
}

 3. js/script.js (The Untying Animation) 

 The Untying Logic: When clicked, the thread splits ( scaleX: 0 ), the backgrounds slide up/down, and the scroll content fades in and moves up ( translateY(0) ). 

 $(document).ready(function() {

 // 1. Init AOS
 AOS.init({ duration: 1000, once: true });

 // 2. KALAVA UNTYING ANIMATION
 $('#enter-btn').on('click', function() {
 var tl = gsap.timeline();

 // A. Pop the Knot
 tl.to(".kalava-knot", { scale: 1.5, opacity: 0, duration: 0.3, ease: "back.in" });

 // B. Snap the String (Split from center)
 tl.to(".kalava-string", { scaleX: 0, duration: 0.5, ease: "power4.in" });

 // C. Open the Backgrounds (Like a shutter)
 tl.to(".loader-bg-top", { y: "-100%", duration: 1, ease: "power2.inOut" }, "-=0.2");
 tl.to(".loader-bg-bottom", { y: "100%", duration: 1, ease: "power2.inOut" }, "<");

 // D. Hide Overlay container
 tl.to("#loader-overlay", { display: "none", duration: 0 });

 // E. Reveal the Scroll (Fade Up)
 tl.to(".scroll-wrapper", { 
 opacity: 1, 
 y: 0, 
 duration: 1.5, 
 ease: "power3.out",
 onStart: function() {
 $('body').removeClass('overflow-hidden');
 }
 });

 // F. Animate Ink Text
 tl.from(".ink-title", { opacity: 0, scale: 0.8, duration: 1, ease: "back.out" }, "-=1");
 });

 // 3. COUNTDOWN
 const weddingDate = new Date("Aug 24, 2026 10:45:00").getTime();
 setInterval(function() {
 const now = new Date().getTime();
 const dist = weddingDate - now;
 $('#days').text(Math.floor(dist / (1000 * 60 * 60 * 24)).toString().padStart(2, '0'));
 $('#hours').text(Math.floor((dist % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60)).toString().padStart(2, '0'));
 $('#minutes').text(Math.floor((dist % (1000 * 60 * 60)) / (1000 * 60)).toString().padStart(2, '0'));
 }, 1000);

 // 4. BOOKMARK ACTIVE STATE
 $(window).scroll(function() {
 var scrollPos = $(document).scrollTop();
 $('.book-link').each(function() {
 var currLink = $(this);
 var refElement = $(currLink.attr("href"));
 if (refElement.position().top <= scrollPos + 300 && refElement.position().top + refElement.height() > scrollPos + 300) {
 $('.book-link').removeClass("active");
 currLink.addClass("active");
 }
 });
 });

});

