function updateAgentInfo() {
 const selectedCheckboxes = document.querySelectorAll('.agent-checkbox:checked');
 const agentInfoCard = document.getElementById('agentInfoCard');
 const descriptionP = document.getElementById('agentDescription');
 const llmInfoDiv = document.getElementById('llmInfo');
 const llmModelSpan = document.getElementById('llmModel');
 const toolsInfoDiv = document.getElementById('toolsInfo');
 const toolsListDiv = document.getElementById('toolsList');

 if (selectedCheckboxes.length === 0) {
 agentInfoCard.style.display = 'none';
 return;
 }

 agentInfoCard.style.display = 'block';
 descriptionP.innerHTML = '';
 llmModelSpan.innerHTML = '';
 toolsListDiv.innerHTML = '';

 let descriptions = new Set();
 let llmModels = new Set();
 let allTools = new Set();

 selectedCheckboxes.forEach(cb => {
 descriptions.add(`<strong>${cb.closest('label').innerText.trim()}:</strong> ${cb.dataset.description}`);
 if (cb.dataset.llm) {
 llmModels.add(cb.dataset.llm);
 }
 if (cb.dataset.config) {
 try {
 const config = JSON.parse(cb.dataset.config);
 if (config && config.mcp && config.mcp.tools) {
 config.mcp.tools.forEach(tool => allTools.add(tool.name));
 }
 } catch (e) {
 console.error("Invalid agent config JSON", e);
 }
 }
 });

 descriptionP.innerHTML = Array.from(descriptions).join('<hr class="my-2">');

 if (llmModels.size > 0) {
 llmModelSpan.textContent = Array.from(llmModels).join(', ');
 llmInfoDiv.style.display = 'block';
 } else {
 llmInfoDiv.style.display = 'none';
 }

 if (allTools.size > 0) {
 toolsListDiv.innerHTML = Array.from(allTools).map(tool =>
 `<span class="badge bg-secondary me-1 mb-1">${tool}</span>`
 ).join('');
 toolsInfoDiv.style.display = 'block';
 } else {
 toolsInfoDiv.style.display = 'none';
 }
}

async function sendMessage() {
 const input = document.getElementById('userInput');
 const sendButton = document.getElementById('sendButton');
 const message = input.value.trim();
 const selectedCheckboxes = document.querySelectorAll('.agent-checkbox:checked');

 if (!message) return;
 if (selectedCheckboxes.length === 0) {
 alert('Please select at least one agent first.');
 return;
 }

 const agentIds = Array.from(selectedCheckboxes).map(cb => cb.value).join(',');

 input.disabled = true;
 sendButton.disabled = true;
 sendButton.innerHTML = '<span class="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span>';
 document.querySelectorAll('.agent-checkbox').forEach(cb => cb.disabled = true);

 addMessage(message, true);
 input.value = '';

 try {
 const response = await fetch('/ask', {
 method: 'POST',
 headers: { 'Content-Type': 'application/json' },
 body: JSON.stringify({
 query: message,
 agent: agentIds,
 session_id: sessionId || null
 })
 });

 if (!response.ok) {
 const errorData = await response.json();
 throw new Error(errorData.detail || 'Failed to get response from agent');
 }

 const data = await response.json();

 if (!sessionId) {
 sessionId = data.session_id;
 }

 let responseText = data.result;
 if (typeof responseText === 'object') {
 responseText = responseText.result || JSON.stringify(responseText, null, 2);
 }
 addMessage(responseText);

 } catch (error) {
 console.error('Error:', error);
 addMessage(`Error: ${error.message}`);
 } finally {
 input.disabled = false;
 sendButton.disabled = false;
 sendButton.innerHTML = '<i class="bi bi-send-fill"></i>';
 document.querySelectorAll('.agent-checkbox').forEach(cb => cb.disabled = false);
 input.focus();
 }
}

function addMessage(content, isUser = false) {
 const chatContainer = document.getElementById('chatContainer');
 const messageDiv = document.createElement('div');
 messageDiv.className = `message ${isUser ? 'user-message' : 'agent-message'}`;

 const timestamp = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
 const contentDiv = document.createElement('div');
 contentDiv.textContent = content;

 const timeSpan = document.createElement('span');
 timeSpan.className = 'message-time';
 timeSpan.textContent = timestamp;

 messageDiv.appendChild(contentDiv);
 messageDiv.appendChild(timeSpan);
 chatContainer.appendChild(messageDiv);
 chatContainer.scrollTop = chatContainer.scrollHeight;
}

document.querySelectorAll('.agent-checkbox').forEach(cb => {
 cb.addEventListener('change', updateAgentInfo);
});
document.getElementById('sendButton').addEventListener('click', sendMessage);
document.getElementById('userInput').addEventListener('keypress', function(e) {
 if (e.key === 'Enter' && !e.shiftKey) {
 e.preventDefault();
 sendMessage();
 }
});

// initNetwork();
updateAgentInfo();
</script>
