 border: '#0d6efd',
 background: '#e2f0ff'
 }
 }
 },
 edges: {
 arrows: 'to',
 smooth: { type: 'cubicBezier', forceDirection: 'vertical', roundness: 0.4 },
 color: '#6c757d'
 },
 layout: {
 hierarchical: {
 direction: 'UD',
 sortMethod: 'directed',
 levelSeparation: 80,
 nodeSpacing: 120
 }
 },
 physics: {
 enabled: false
 }
 };
 network = new vis.Network(container, data, options);
 }

 function updateSelectedAgentsDisplay() {
 const selectedCheckboxes = document.querySelectorAll('.agent-checkbox:checked');
 const agentInfoCard = document.getElementById('agentInfoCard');

 if (selectedCheckboxes.length === 0) {
 agentInfoCard.style.display = 'none';
 agentInfoCard.innerHTML = '';
 network.setData({ nodes: [], edges: [] });
 return;
 }

 let descriptions = [];
 let llmModels = new Set();
 let allTools = new Set();

 selectedCheckboxes.forEach(cb => {
 descriptions.push(`<strong>${cb.labels[0].textContent}:</strong> ${cb.dataset.description}`);
 if (cb.dataset.llm) {
 const llm = JSON.parse(cb.dataset.llm);
 llmModels.add(llm.model);
 }
 if (cb.dataset.tools) {
 const tools = JSON.parse(cb.dataset.tools);
 tools.forEach(tool => allTools.add(tool));
 }
 });

 let cardHTML = '<div class="card-body">';
 cardHTML += '<h5 class="card-title">Agent Details</h5>';
 cardHTML += `<p class="card-text small">${descriptions.join('<br>')}</p>`;

 if (llmModels.size > 0) {
 cardHTML += `<h6 class="card-subtitle mt-3 mb-2 text-muted">LLMs</h6>`;
 cardHTML += `<p class="card-text">${Array.from(llmModels).map(m => `<span class="badge bg-secondary">${m}</span>`).join(' ')}</p>`;
 }

 if (allTools.size > 0) {
 cardHTML += `<h6 class="card-subtitle mt-3 mb-2 text-muted">Tools</h6>`;
 cardHTML += `<div class="d-flex flex-wrap gap-1">${Array.from(allTools).map(t => `<span class="badge bg-info text-dark">${t}</span>`).join(' ')}</div>`;
 }
 cardHTML += '</div>';

 agentInfoCard.innerHTML = cardHTML;
 agentInfoCard.style.display = 'block';

 updateNetworkGraph(selectedCheckboxes);
 }

 function updateNetworkGraph(selectedCheckboxes) {
 const nodes = new vis.DataSet([{ id: 'user', label: 'User', shape: 'circle', color: '#0d6efd', font: {color: 'white'} }]);
 const edges = new vis.DataSet([]);
 let masterAgent = null;

 const agents = Array.from(selectedCheckboxes).map(cb => ({
 id: cb.value,
 label: cb.labels[0].textContent
 }));

 masterAgent = agents.find(agent => agent.id.includes('crew') || agent.id.includes('manager') || agent.id.includes('router'));

 if (masterAgent) {
 nodes.add({ id: masterAgent.id, label: masterAgent.label, color: '#198754', font: {color: 'white'} });
 edges.add({ from: 'user', to: masterAgent.id });
 agents.forEach(agent => {
 if (agent.id !== masterAgent.id) {
 nodes.add({ id: agent.id, label: agent.label });
 edges.add({ from: masterAgent.id, to: agent.id });
 }
 });
 } else {
 agents.forEach(agent => {
 nodes.add({ id: agent.id, label: agent.label });
 edges.add({ from: 'user', to: agent.id });
 });
 }
 network.setData({ nodes, edges });
 }

 async function sendMessage() {
 const message = userInput.value.trim();
 const selectedCheckboxes = document.querySelectorAll('.agent-checkbox:checked');

 if (!message) return;
 if (selectedCheckboxes.length === 0) {
 alert('Please select at least one agent.');
 return;
 }

 const agentIds = Array.from(selectedCheckboxes).map(cb => cb.value);

 setLoadingState(true);
 addMessage(message, true);
 userInput.value = '';

 try {
 const response = await fetch('/ask', {
 method: 'POST',
 headers: { 'Content-Type': 'application/json' },
 body: JSON.stringify({
 query: message,
 agents: agentIds,
 session_id: sessionId
 })
 });

 if (!response.ok) {
 const errorData = await response.json();
 throw new Error(errorData.detail || 'The request failed.');
 }

 const data = await response.json();
 sessionId = data.session_id || sessionId;

 const responseText = (typeof data.result === 'object') 
 ? JSON.stringify(data.result, null, 2) 
 : data.result;

 addMessage(responseText, false);

 } catch (error) {
 addMessage(`Error: ${error.message}`, false);
 } finally {
 setLoadingState(false);
 }
 }

 function setLoadingState(isLoading) {
 userInput.disabled = isLoading;
 sendButton.disabled = isLoading;
 document.getElementById('sendIcon').style.display = isLoading ? 'none' : 'inline';
 document.getElementById('loadingSpinner').style.display = isLoading ? 'inline-block' : 'none';
