<body>
 <div class="p-3 d-flex justify-content-between align-items-center" style="background-color: var(--bg-panel); border-bottom: 1px solid var(--border-color);">
 <h5 class="mb-0 fw-bold text-light">⚡ DynamoMCP <span class="badge bg-primary ms-2" style="font-size: 0.6em;">v2.0</span></h5>
 <small class="text-muted">HITL Architecture</small>
 </div>

 <div id="workspace">
 <div id="chat-section">
 <div id="chat-container"></div>

 <div id="input-area">
 <div id="approval-box">
 <h5 class="text-warning mb-2" id="approval-text">⚠️ Approval Required</h5>
 <p class="text-light text-opacity-75 mb-4 text-sm">The agent requires permission to execute file-system commands. Review the payload.</p>
 <button class="btn btn-success px-4 py-2 me-3 fw-bold" onclick="sendAction('approve')">✅ Approve</button>
 <button class="btn btn-outline-danger px-4 py-2 fw-bold" onclick="sendAction('reject')">❌ Reject</button>
 </div>

 <div class="input-group mt-2" id="chat-box">
 <input type="text" id="message-input" class="form-control" placeholder="Instruct the agent..." onkeypress="handleKeyPress(event)">
 <button class="btn btn-primary px-4 fw-bold" onclick="sendMessage()">Send</button>
 </div>
 </div>
 </div>

 <div id="sandbox-section">
 <div class="sandbox-header">
 <h6 class="mb-0 fw-bold text-warning">🛠️ Manual Sandbox Playground</h6>
 <span class="badge bg-secondary" id="active-tool-badge">No Tool Loaded</span>
 </div>

 <div class="editor-container">
 <label class="form-label text-muted small fw-bold">Python Code (Editable)</label>
 <textarea id="sandbox-code" class="code-textarea" spellcheck="false" placeholder="# Agent code will load here..."></textarea>

 <label class="form-label text-muted small fw-bold">Test Payload (JSON Args)</label>
 <textarea id="sandbox-payload" class="payload-textarea" spellcheck="false" placeholder='{ "input_string": "test" }'></textarea>

 <div class="d-flex gap-2 mb-3">
 <button class="btn btn-outline-light flex-grow-1" onclick="executeManualTest()">▶️ Run Local Test</button>
 </div>

 <label class="form-label text-muted small fw-bold">Test Result</label>
