 Once the test passes, sync the fixed code back to the agent for deployment.
 </div>
 <button class="btn btn-success w-100 fw-bold" onclick="syncAndPromote()">🚀 Sync & Tell Agent to Promote</button>
 </div>
 </div>
 </div>

 <script>
 const chatContainer = document.getElementById("chat-container");
 const approvalBox = document.getElementById("approval-box");
 const approvalText = document.getElementById("approval-text");
 const chatBox = document.getElementById("chat-box");
 const messageInput = document.getElementById("message-input");

 // Sandbox elements
 const sandboxCode = document.getElementById("sandbox-code");
 const sandboxPayload = document.getElementById("sandbox-payload");
 const sandboxResult = document.getElementById("sandbox-result");
 const activeToolBadge = document.getElementById("active-tool-badge");
 let currentToolName = "";

 marked.setOptions({ breaks: true, gfm: true });
 const ws = new WebSocket(`ws://${window.location.host}/ws/chat`);

 function appendMessage(content, role) {
 const row = document.createElement("div");
 row.className = `message-row ${role === 'user' ? 'user-row' : (role === 'system' ? '' : 'ai-row')}`;

 if (role === 'system') {
 row.innerHTML = `<div class="sys-msg">${content}</div>`;
 } else {
 const bubble = document.createElement("div");
 bubble.className = `message-bubble ${role === 'user' ? 'user-msg' : (role === 'tool' ? 'tool-msg' : 'ai-msg')}`;

 if (role === 'user') bubble.textContent = content;
 else if (role === 'tool') bubble.innerHTML = content;
 else bubble.innerHTML = marked.parse(content);

 row.appendChild(bubble);
 }
 chatContainer.appendChild(row);
 chatContainer.scrollTo({ top: chatContainer.scrollHeight, behavior: 'smooth' });
 }

 ws.onmessage = function(event) {
 const data = JSON.parse(event.data);

 if (data.type === "pause") {
 const toolNames = data.tools && data.tools.length > 0 ? data.tools.join(', ') : 'File System Tools';
 approvalText.innerHTML = `⚠️ Approval Required: <code>${toolNames}</code>`;
 approvalBox.style.display = "block";
 chatBox.style.display = "none";
 chatContainer.scrollTo({ top: chatContainer.scrollHeight, behavior: 'smooth' });
 return;
 }

 if (data.type === "system") appendMessage(data.content, "system");
 else if (data.type === "ai_message") appendMessage(data.content, "ai");
 else if (data.type === "tool_call") {
 try {
 const parser = new DOMParser();
 const doc = parser.parseFromString(data.content, 'text/html');
 const toolName = doc.querySelector('code').textContent;
 const rawJsonStr = doc.querySelector('pre').textContent;

 // --- NEW: Intercept 'build_custom_tool' to populate Sandbox ---
 if (toolName === 'build_custom_tool') {
 const parsedData = JSON.parse(rawJsonStr);
 if (parsedData.name && parsedData.python_code) {
 currentToolName = parsedData.name;
 activeToolBadge.textContent = currentToolName;
 sandboxCode.value = parsedData.python_code;

 // Create a template payload based on parameters
 let dummyPayload = {};
 if (parsedData.parameters) {
 for (const [key, val] of Object.entries(parsedData.parameters)) {
 dummyPayload[key] = val.type === "string" ? "sample_text" : 0;
 }
 }
 sandboxPayload.value = JSON.stringify(dummyPayload, null, 2);
 sandboxResult.innerHTML = `<span class="text-muted">Draft loaded. Ready to test.</span>`;
 }
 }

 const cleanHTML = `
 <div class="fw-bold mb-1">🛠️ Preparing Execution: <span class="text-warning">${toolName}</span></div>
 <details><summary>View Payload & Code</summary><pre><code>${rawJsonStr}</code></pre></details>
 `;
 appendMessage(cleanHTML, "tool");
 } catch(e) { appendMessage(data.content, "tool"); }
 }
 else if (data.type === "tool_result") {
 let formattedContent = data.content;
 try {
 const parsed = JSON.parse(data.content);
 formattedContent = JSON.stringify(parsed, null, 2);
 } catch(e) {} 
 const isError = formattedContent.toLowerCase().includes("error");
 const cleanHTML = `
 <div class="${isError ? "text-danger" : "text-success"} fw-bold mb-1">
 ${isError ? "❌" : "✅"} Output: <span class="text-warning">${data.name}</span></div>
 <details><summary>View Result Data</summary><pre><code>${formattedContent}</code></pre></details>
 `;
 appendMessage(cleanHTML, "tool");
 }
 };

 function sendMessage() {
 const text = messageInput.value.trim();
 if (!text) return;
 appendMessage(text, "user");
 ws.send(JSON.stringify({ action: "chat", message: text }));
 messageInput.value = "";
 }

 function sendAction(actionType) {
 approvalBox.style.display = "none";
 chatBox.style.display = "flex";
 ws.send(JSON.stringify({ action: actionType }));
 }

 function handleKeyPress(event) { if (event.key === "Enter") sendMessage(); }

 // --- NEW: Sandbox Logic ---
 async function executeManualTest() {
 sandboxResult.innerHTML = '<span class="text-warning">Running test...</span>';
 try {
 const payloadObj = JSON.parse(sandboxPayload.value);
 const response = await fetch('/api/test-manual', {
 method: 'POST',
 headers: { 'Content-Type': 'application/json' },
 body: JSON.stringify({
 name: currentToolName || "manual_test",
 code: sandboxCode.value,
 test_payload: payloadObj
 })
 });

 const data = await response.json();
 if (data.status === 'error') {
 sandboxResult.innerHTML = `<span class="text-danger fw-bold">❌ Error: ${data.error_type}</span>\n<span class="text-danger">${data.details}</span>`;
 } else {
 sandboxResult.innerHTML = `<span class="text-success fw-bold">✅ Success</span>\n\n${JSON.stringify(data.result, null, 2)}`;
 }
 } catch (error) {
 sandboxResult.innerHTML = `<span class="text-danger fw-bold">❌ JSON Parse Error in Payload</span>\nMake sure your test payload is valid JSON.`;
 }
 }

 function syncAndPromote() {
 if (!currentToolName) {
 alert("No tool loaded to sync!");
 return;
 }
 const code = sandboxCode.value;
 const msg = `I have manually tested and corrected the code for '${currentToolName}'. Please execute 'build_custom_tool' using EXACTLY this python code, and then immediately run 'promote_tool' to make it live.\n\n\`\`\`python\n${code}\n\`\`\``;

 appendMessage("Sending fixed code back to agent for promotion...", "user");
 ws.send(JSON.stringify({ action: "chat", message: msg }));
 }
 </script>
</body>
</html>

 The New Workflow in Action 

 Draft: You ask the agent for a tool (e.g., "Build a URL parser"). 

 Intercept: The agent calls build_custom_tool . The UI automatically detects this, extracts the Python code, and dumps it into your right-hand Manual Sandbox . It also auto-generates a dummy JSON payload based on the parameters. 

 Approve Draft: Click ✅ Approve on the left side to let the tool hit the /pending folder. 

 Edit & Test: On the right side, you run the code. If it fails (like the Base62 bug), you can fix the Python directly in the text area and hit ▶️ Run Local Test until it works perfectly. 

 Sync: Once the code is green, click 🚀 Sync & Tell Agent to Promote . This automatically formats a message to the agent feeding it your perfect code and instructing it to finalize the build and promote it. 

 Would you like me to suggest any structural changes to the main.py LangGraph logic to further optimize this new editing flow?

