You are absolutely right. Seeing a giant wall of raw JSON with escaped newline characters ( \n ) is terrible UX. 

 Furthermore, because the UI wasn't showing the Outputs of the Sandbox, you couldn't see that the AI actually ran the test without any test arguments the first two times! A good UI doesn't just look pretty; it exposes what the AI is actually doing so you can guide it. 

 We are going to upgrade the frontend to parse these tool calls intelligently. 

 Collapsible Details: Giant blocks of JSON will be hidden behind native HTML <details> toggles. 

 Code Extraction: The UI will detect if the AI wrote python_code and format it in a clean, readable code block, separating it from the rest of the arguments. 

 Result Tracking: The backend will now send the actual output of the tool (success, error, or data) to the frontend, rather than just a "Finished" tag. 

 Here are the updated app.py and index.html files. (Your server.py and main.py remain the same!) 

 1. Update app.py (The Backend) 

 We are updating the WebSocket sender. Instead of formatting HTML on the server, it will send clean JSON objects so the Javascript can render them beautifully. 

 Replace your WebSocket loop in app.py with this: 

 import os
import json
from fastapi import FastAPI, WebSocket, WebSocketDisconnect
from fastapi.responses import HTMLResponse
from dotenv import load_dotenv

from langchain_openai import ChatOpenAI
from langchain_core.messages import ToolMessage
from langgraph.checkpoint.memory import MemorySaver
from mcp import ClientSession
from mcp.client.sse import sse_client
from langchain_mcp_adapters.tools import load_mcp_tools

from main import build_agent, DANGEROUS_TOOLS

load_dotenv()
app = FastAPI()
memory = MemorySaver()

@app.get("/")
async def get_ui():
 with open("index.html", "r") as f:
 return HTMLResponse(f.read())

@app.websocket("/ws/chat")
async def websocket_endpoint(websocket: WebSocket):
 await websocket.accept()
 llm = ChatOpenAI(model="gpt-4o", temperature=0)
 mcp_url = "http://localhost:8000/sse"

 try:
 async with sse_client(url=mcp_url) as (read, write):
 async with ClientSession(read, write) as session:
 await session.initialize()
 config = {"configurable": {"thread_id": "dynamo_web_2"}}

 await websocket.send_text(json.dumps({"type": "system", "content": "✅ Connected to DynamoMCP. Ready for tasks!"}))
 processed_ids = set()

 while True:
 data = await websocket.receive_text()
 payload = json.loads(data)
 action = payload.get("action")

 try:
 if action == "chat":
 user_msg = payload.get("message")
 tools = await load_mcp_tools(session)
 agent = build_agent(llm, tools, memory)
 stream = agent.astream({"messages": [("user", user_msg)]}, config, stream_mode="values")

 elif action == "approve":
 stream = agent.astream(None, config, stream_mode="values")

 elif action == "reject":
 state = agent.get_state(config)
 last_msg = state.values["messages"][-1]
 tool_msgs = [ToolMessage(tool_call_id=tc['id'], name=tc['name'], content="USER REJECTED TOOL EXECUTION.") for tc in last_msg.tool_calls]
 agent.update_state(config, {"messages": tool_msgs})

 await websocket.send_text(json.dumps({"type": "system", "content": "❌ Action cancelled by user."}))
 stream = agent.astream(None, config, stream_mode="values")

 async for event in stream:
 latest_msg = event["messages"][-1]

 if latest_msg.id in processed_ids: continue
 processed_ids.add(latest_msg.id)

 if latest_msg.type == "ai":
 if hasattr(latest_msg, 'tool_calls') and latest_msg.tool_calls:
 for tc in latest_msg.tool_calls:
 # SEND STRUCTURED TOOL CALL DATA
 await websocket.send_text(json.dumps({
 "type": "tool_call", 
 "name": tc['name'],
 "args": tc['args'],
 "is_dangerous": tc['name'] in DANGEROUS_TOOLS
 }))
 elif latest_msg.content:
 await websocket.send_text(json.dumps({"type": "ai_message", "content": latest_msg.content}))

 elif latest_msg.type == "tool":
 # SEND ACTUAL TOOL RESULT DATA
 await websocket.send_text(json.dumps({
 "type": "tool_result", 
 "name": latest_msg.name,
 "content": str(latest_msg.content)
 }))

 state = agent.get_state(config)
 if state.next and state.next[0] == "dangerous_tools":
 await websocket.send_text(json.dumps({"type": "pause"}))

 except Exception as e:
 await websocket.send_text(json.dumps({"type": "system", "content": f"❌ Error: {str(e)}"}))

 except WebSocketDisconnect:
 print("Client disconnected.")

