<body>

 <div class="container mx-auto px-3" style="max-width: 600px;">

 <header class="dashboard-header animate__animated animate__fadeInDown">
 <div class="brand-logo">FITFORGE</div>
 <div>
 <button class="btn btn-weekly btn-sm me-2" onclick="shareApp()"><i class="fa-solid fa-share-nodes"></i></button>
 <button class="btn btn-weekly btn-sm" data-bs-toggle="modal" data-bs-target="#weeklyModal"><i class="fa-solid fa-calendar-week me-1"></i> Week</button>
