 <div class="modal-content">
 <div class="modal-header d-flex flex-column align-items-start">
 <div class="d-flex justify-content-between w-100 mb-3"><h5 class="modal-title brand-font fs-6" id="audioModalTitle">Audio</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div>
 <div class="w-100 p-2 rounded" style="background: rgba(255,255,255,0.05);">
 <label class="text-muted" style="font-size: 0.8rem; display:block; margin-bottom:5px;">Open links using:</label>
 <div class="btn-group w-100" role="group" id="deviceToggleGroup">
 <input type="radio" class="btn-check" name="deviceToggle" id="btnIphone" value="ios" checked><label class="btn btn-outline-secondary btn-sm" for="btnIphone"><i class="fa-brands fa-apple"></i> iOS</label>
 <input type="radio" class="btn-check" name="deviceToggle" id="btnAndroid" value="android"><label class="btn btn-outline-secondary btn-sm" for="btnAndroid"><i class="fa-brands fa-android"></i> Android</label>
 <input type="radio" class="btn-check" name="deviceToggle" id="btnWeb" value="web"><label class="btn btn-outline-secondary btn-sm" for="btnWeb"><i class="fa-solid fa-globe"></i> Web</label>
 </div>
