<body>

 <h2>PDF Content Extraction & AI Formatting</h2>

 <div class="card">
 <label for="pdfInput"><strong>1. Select a PDF:</strong></label><br><br>
 <input type="file" id="pdfInput" accept="application/pdf" />

 <div id="status">Waiting for PDF...</div>

 <div id="controls" class="hidden" style="margin-top: 20px; display: flex; align-items: center; gap: 10px;">
 <label for="pageSelector"><strong>Page:</strong></label>
 <input type="number" id="pageSelector" min="1" value="1">
 <span id="pageRange"></span>
 <button id="sendBtn">Process Page</button>
 </div>
 </div>

 <div id="responseContainer" class="hidden" style="margin-top: 20px;">
 <h3>Processed Pages Log</h3>
 <div id="responseArea"></div>
 </div>

 <script>
 // --- CONFIGURATION ---
