Here is the complete codebase to get EDITH up and running. This Proof of Concept (POC) connects your Bootstrap frontend to FastAPI, stores your updates locally using ChromaDB, and uses LangGraph to query your local Gemma model. 

 Before running the code, make sure you have pulled your embedding and LLM models via Ollama in your terminal:
 ollama pull nomic-embed-text 
 ollama pull gemma (or whichever specific Gemma 4 tag you are using locally) 

 1. models.py (The Data Contract) 

 This ensures EDITH knows exactly what an update looks like. 

 from pydantic import BaseModel, Field
from datetime import datetime
from typing import List, Optional

class WorkUpdate(BaseModel):
 summary: str = Field(..., description="The core work performed")
 repos: str = Field(default="", description="Comma-separated repo names (e.g., sleuth, rati)")
 links: str = Field(default="", description="Comma-separated links")
 tags: str = Field(default="", description="Comma-separated tags (e.g., python, fastapi)")

class QueryResponse(BaseModel):
 answer: str

 2. helpers.py (The Toolkit & Aesthetics) 

 This gives your FastAPI console output that premium, readable format. 

 import logging
from rich.logging import RichHandler
from rich.console import Console

console = Console()

def setup_logging():
 logging.basicConfig(
 level="INFO",
 format="%(message)s",
 datefmt="[%X]",
 handlers=[RichHandler(rich_tracebacks=True, console=console, markup=True)]
 )
 return logging.getLogger("EDITH")

log = setup_logging()

 3. pipeline.py (The Memory Muscle) 

 This handles embedding your text and saving it to a local ChromaDB folder. 

 import chromadb
from langchain_ollama import OllamaEmbeddings
from models import WorkUpdate
from helpers import log
from datetime import datetime

# Initialize ChromaDB persistently on disk
chroma_client = chromadb.PersistentClient(path="./chroma_db")
collection = chroma_client.get_or_create_collection(name="edith_memory")

# Fast, local embeddings perfect for M1
embeddings_model = OllamaEmbeddings(model="nomic-embed-text")

def save_to_memory(update: WorkUpdate):
 log.info(f"Saving update to EDITH memory: {update.summary[:30]}...")

 # Generate vector embedding
 vector = embeddings_model.embed_query(update.summary)

 # Store with metadata for future filtering
 doc_id = f"log_{datetime.now().strftime('%Y%m%d%H%M%S')}"

 collection.add(
 ids=[doc_id],
 embeddings=[vector],
 documents=[update.summary],
 metadatas=[{
 "date": datetime.now().strftime("%Y-%m-%d"),
 "repos": update.repos,
 "links": update.links,
 "tags": update.tags
 }]
 )
 return True

def search_memory(query: str, n_results: int = 3):
 log.info(f"Searching memory for: {query}")
 query_vector = embeddings_model.embed_query(query)

 results = collection.query(
 query_embeddings=[query_vector],
 n_results=n_results
 )

 if not results['documents'][0]:
 return "No relevant memories found."

 # Combine found documents into a context string
 context = "\n".join(results['documents'][0])
 return context

 4. agent.py (The Brain) 

 This LangGraph setup retrieves context from ChromaDB and passes it to Gemma to formulate an intelligent response. 

 from typing import TypedDict
from langgraph.graph import StateGraph, END
from langchain_ollama import ChatOllama
from langchain_core.prompts import PromptTemplate
from pipeline import search_memory
from helpers import log

# Initialize Gemma via Ollama
llm = ChatOllama(model="gemma", temperature=0.2)

class AgentState(TypedDict):
 query: str
 context: str
 answer: str

def retrieve_node(state: AgentState):
 log.info("Agent: Retrieving context from database...")
 context = search_memory(state["query"])
 return {"context": context}

def generate_node(state: AgentState):
 log.info("Agent: Generating response using Gemma...")
 prompt_template = PromptTemplate(
 input_variables=["context", "query"],
 template=(
 "You are EDITH, a highly capable AI work assistant.\n"
 "Use the following memory logs to answer the user's query.\n"
 "If the answer is not in the logs, say you don't have a record of it.\n\n"
 "Memory Logs:\n{context}\n\n"
 "Query: {query}\n\n"
 "Answer:"
 )
 )
 prompt = prompt_template.format(context=state["context"], query=state["query"])
 response = llm.invoke(prompt)
 return {"answer": response.content}

# Build EDITH's reasoning graph
workflow = StateGraph(AgentState)
workflow.add_node("retrieve", retrieve_node)
workflow.add_node("generate", generate_node)

workflow.set_entry_point("retrieve")
workflow.add_edge("retrieve", "generate")
workflow.add_edge("generate", END)

edith_app = workflow.compile()

def ask_edith(query: str):
 result = edith_app.invoke({"query": query, "context": "", "answer": ""})
 return result["answer"]

 5. app.py (The Bridge) 

 The FastAPI server that ties the frontend to the backend. 

 from fastapi import FastAPI, Request
from fastapi.templating import Jinja2Templates
from fastapi.staticfiles import StaticFiles
from models import WorkUpdate, QueryResponse
from pipeline import save_to_memory
from agent import ask_edith
from helpers import log

app = FastAPI(title="EDITH Work Intelligence Hub")

# Mount static and templates
app.mount("/static", StaticFiles(directory="static"), name="static")
templates = Jinja2Templates(directory="templates")

@app.get("/")
async def home(request: Request):
 return templates.TemplateResponse("index.html", {"request": request})

@app.post("/api/log")
async def log_update(update: WorkUpdate):
 success = save_to_memory(update)
 return {"status": "success", "message": "Memory synchronized."}

@app.get("/api/query", response_model=QueryResponse)
async def query_memory(q: str):
 log.info(f"Received query: {q}")
 answer = ask_edith(q)
 return QueryResponse(answer=answer)

if __name__ == "__main__":
 import uvicorn
 log.info("Waking up EDITH...")
 uvicorn.run("app:app", host="0.0.0.0", port=8000, reload=True)

