 4. app.js (The Engine) 

 Save this as app.js . This is where the magic happens: it fetches your data, injects the HTML dynamically, and handles instant search and category clicks. 

 document.addEventListener('DOMContentLoaded', () => {
 const productGrid = document.getElementById('productGrid');
 const searchInput = document.getElementById('searchInput');
 const filterButtons = document.querySelectorAll('.btn-filter');
 const noResults = document.getElementById('noResults');

 let allProducts = [];

 // 1. Fetch Data
 fetch('products.json')
 .then(response => response.json())
 .then(data => {
 allProducts = data;
 renderProducts(allProducts);
 })
 .catch(error => {
 console.error('Error loading products:', error);
 productGrid.innerHTML = '<p class="text-danger text-center w-100">Failed to load products. Please try again later.</p>';
 });

 // 2. Render Products Function
 function renderProducts(products) {
 productGrid.innerHTML = ''; // Clear current grid

 if (products.length === 0) {
 noResults.classList.remove('d-none');
 } else {
 noResults.classList.add('d-none');

 products.forEach(product => {
 // Constructing the HTML structure for each card
 const cardHTML = `
 <div class="col">
 <div class="card product-card shadow-sm">
 <div class="card-img-wrapper">
 <span class="product-tag">${product.tags}</span>
 <img src="${product.image_url}" class="card-img-top" alt="${product.product_name}" loading="lazy">
 </div>
 <div class="card-body d-flex flex-column">
 <h5 class="card-title product-title">${product.product_name}</h5>
 <div class="mt-auto d-flex justify-content-between align-items-center mb-3">
 <span class="price">${product.price}</span>
 <small class="text-muted">${product.platform}</small>
 </div>
 <a href="${product.affiliate_url}" target="_blank" rel="noopener noreferrer" class="btn btn-cta">
 View Deal ↗
 </a>
 </div>
 </div>
 </div>
 `;
 productGrid.insertAdjacentHTML('beforeend', cardHTML);
 });
 }
 }

 // 3. Filtering Logic (Combined Search + Category)
 function applyFilters() {
 const searchTerm = searchInput.value.toLowerCase();
 const activeCategoryBtn = document.querySelector('.btn-filter.active');
 const categoryFilter = activeCategoryBtn ? activeCategoryBtn.getAttribute('data-filter') : 'All';

 const filteredProducts = allProducts.filter(product => {
 // Check Search
 const matchesSearch = product.product_name.toLowerCase().includes(searchTerm) || 
 product.category.toLowerCase().includes(searchTerm);

 // Check Category
 const matchesCategory = categoryFilter === 'All' || 
 (categoryFilter === 'Under ₹499' && parseInt(product.price.replace('₹', '')) < 499) ||
 product.category === categoryFilter;

 return matchesSearch && matchesCategory;
 });

 renderProducts(filteredProducts);
 }

 // 4. Event Listeners
 // Search input (fires on every keystroke)
 searchInput.addEventListener('input', applyFilters);

 // Category buttons
 filterButtons.forEach(button => {
 button.addEventListener('click', (e) => {
 // Remove active class from all buttons
 filterButtons.forEach(btn => btn.classList.remove('active'));
 // Add active class to clicked button
 e.target.classList.add('active');

 applyFilters();
 });
 });
});

