 // --- DOM Elements ---
const startScreen = document.getElementById('start-screen');
const endScreen = document.getElementById('end-screen');
const startBtn = document.getElementById('start-btn');
const restartBtn = document.getElementById('restart-btn');
const endTitle = document.getElementById('end-title');
const endMessage = document.getElementById('end-message');

let game;

// --- Phaser Game Scene ---
class GameScene extends Phaser.Scene {
 constructor() { super({ key: 'GameScene' }); }

 create() {
 this.gameActive = true;
 this.isImmune = false;
 this.speed = 300; // Speed of the road and cops
 this.progress = 0; // 0 to 100%
 this.goalDistance = 100;

 // 1. Draw the Road
 this.add.rectangle(400, 300, 800, 200, 0x333333); // Road surface
 this.add.rectangle(400, 200, 800, 10, 0x7f8c8d); // Top curb
 this.add.rectangle(400, 400, 800, 10, 0x7f8c8d); // Bottom curb

 // Road lines (scrolling effect)
 this.roadLines = this.add.group();
 for(let i = 0; i < 5; i++) {
 let line = this.add.rectangle(i * 200, 300, 100, 10, 0xffffff);
 this.roadLines.add(line);
 }

 // 2. The Player (Bike Emoji)
 this.playerAura = this.add.circle(150, 300, 40, 0x3498db, 0.5); // Blue aura, hidden initially
 this.playerAura.setVisible(false);

 this.player = this.add.text(150, 300, '🏍️', { fontSize: '50px' }).setOrigin(0.5);
 this.physics.add.existing(this.player);
 this.player.body.setSize(40, 40); // Hitbox

 // 3. Obstacles (Cops Group)
 this.cops = this.physics.add.group();

 // Spawn cops every 1.5 to 3 seconds
 this.time.addEvent({
 delay: 2000,
 callback: this.spawnCop,
 callbackScope: this,
 loop: true
 });

 // 4. UI Elements (In-Game)
 this.add.rectangle(400, 30, 800, 60, 0x000000, 0.8); // Top UI bar
 this.progressText = this.add.text(20, 20, '📍 Maa Hotel [ ] 🏟️ JSCA', { font: '16px "Press Start 2P"', fill: '#f1c40f' });
 this.statusText = this.add.text(400, 70, '', { font: '20px "Press Start 2P"', fill: '#2ecc71' }).setOrigin(0.5);

 // 5. Input
 this.cursors = this.input.keyboard.createCursorKeys();
 }

 update(time, delta) {
 if (!this.gameActive) return;

 // Animate Road Lines
 this.roadLines.getChildren().forEach(line => {
 line.x -= (this.speed * delta) / 1000;
 if (line.x < -100) line.x = 900; // Loop back
 });

 // Move Cops
 this.cops.getChildren().forEach(cop => {
 cop.x -= (this.speed * delta) / 1000;
 if (cop.x < -50) cop.destroy(); // Remove off-screen cops
 });

 // Update Progress
 this.progress += (delta / 1000) * 5; // Takes ~20 seconds to reach 100
 this.updateProgressBar();

 if (this.progress >= this.goalDistance) {
 this.gameWin();
 }

 // Wide Call Mechanic (Spacebar)
 if (Phaser.Input.Keyboard.JustDown(this.cursors.space) && !this.isImmune) {
 this.triggerWideCall();
 }

 // Check Collisions
 this.physics.overlap(this.player, this.cops, this.hitCop, null, this);
 }

 updateProgressBar() {
 let bars = Math.floor(this.progress / 10); // 10 bars total
 let barString = '='.repeat(bars) + '🏍️' + ' '.repeat(10 - bars);
 this.progressText.setText(`📍 Maa Hotel [${barString}] 🏟️ JSCA`);
 }

 triggerWideCall() {
 this.isImmune = true;
 this.playerAura.setVisible(true); // Show blue aura
 this.statusText.setText("THALA AURA ACTIVE!");

 // Aura lasts for 1 second
 this.time.delayedCall(1000, () => {
 this.isImmune = false;
 this.playerAura.setVisible(false);
 this.statusText.setText("");
 });
 }

 spawnCop() {
 if (!this.gameActive) return;
 // Randomize Y position slightly on the road
 let spawnY = Phaser.Math.Between(250, 350);
 let cop = this.add.text(850, spawnY, '👮', { fontSize: '50px' }).setOrigin(0.5);
 this.physics.add.existing(cop);
 cop.body.setSize(30, 30); // Hitbox
 this.cops.add(cop);
 }

 hitCop(player, cop) {
 if (this.isImmune) {
 // Dodge successful! Show floating text and remove cop safely
 this.showFloatingText("THALA FOR A REASON!", cop.x, cop.y);
 cop.destroy();
 } else {
 // Hit!
 this.gameOver();
 }
 }

 showFloatingText(msg, x, y) {
 let t = this.add.text(x, y - 40, msg, { font: '12px "Press Start 2P"', fill: '#f1c40f' }).setOrigin(0.5);
 this.tweens.add({
 targets: t,
 y: y - 80,
 alpha: 0,
 duration: 1000,
 onComplete: () => t.destroy()
 });
 }

 gameOver() {
 this.gameActive = false;
 this.scene.pause();
 endTitle.innerText = "CHALLAN ISSUED!";
 endTitle.style.color = "#e74c3c";
 endMessage.innerText = "You forgot to do the Wide Call stretch!";
 endScreen.classList.remove('hidden');
 }

 gameWin() {
 this.gameActive = false;
 this.scene.pause();
 endTitle.innerText = "DELIVERY SUCCESS!";
 endTitle.style.color = "#2ecc71";
 endMessage.innerText = "The parcel has reached JSCA Stadium. Legend.";
 endScreen.classList.remove('hidden');
 }
}

