 import httpx
import uvicorn
import logging
import random
from fastapi import FastAPI, Request, Response
from pydantic import BaseModel

# Configure Logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - [MCP SERVER] - %(message)s')
logger = logging.getLogger("mcp_server")

# --- Data Models ---
class GrowthRequest(BaseModel):
 revenue: int
 cost: int

class AuditLogRequest(BaseModel):
 user_action: str
 severity: str

# --- 1. Define Tool Logic ---
def calculate_growth_logic(revenue: int, cost: int) -> dict:
 profit = revenue - cost
 margin = (profit / revenue) * 100 if revenue > 0 else 0
 return {"profit": profit, "margin_percent": round(margin, 2)}

# --- 2. Create Standard FastAPI App ---
app = FastAPI(title="Secure MCP POC")

# --- 3. Add Security Middleware ---
@app.middleware("http")
async def oauth_middleware(request: Request, call_next):
 logger.info(f"INCOMING REQUEST: {request.method} {request.url.path}")

 # Public paths
 public_paths = ["/.well-known/oauth-protected-resource", "/docs", "/openapi.json"]
 if request.url.path in public_paths:
 logger.info(" > Public Endpoint - Access Granted")
 return await call_next(request)

 # Auth Check
 auth_header = request.headers.get("Authorization")

 # ❌ SCENARIO 1: No Token
 if not auth_header:
 logger.warning(" > BLOCKED: No Authorization Header present.")
 return Response(
 status_code=401,
 content="Missing Authentication Token",
 headers={"WWW-Authenticate": 'Bearer realm="http://localhost:8000"'}
 )

 token = auth_header.split(" ")[1]

 # ❌ SCENARIO 2: Verify Token with Auth Server
 async with httpx.AsyncClient() as client:
 try:
 resp = await client.get(f"http://localhost:8001/verify/{token}")
 if resp.status_code == 200:
 logger.info(" > SUCCESS: Token Verified.")
 else:
 logger.warning(f" > BLOCKED: Invalid Token (Auth Server returned {resp.status_code})")
 return Response(status_code=403, content="Invalid or Expired Token")
 except Exception:
 return Response(status_code=500, content="Auth Server Unavailable")

 return await call_next(request)

# --- 4. Metadata Endpoint ---
@app.get("/.well-known/oauth-protected-resource")
def resource_metadata():
 return {
 "resource": "http://localhost:8000",
 "authorization_servers": ["http://localhost:8001"],
 "bearer_methods_supported": ["header"]
 }

# --- 5. Tool Endpoints ---

# Tool 1: Calculate Profit (Math Tool)
@app.post("/tools/calculate_growth")
def tool_growth(data: GrowthRequest):
 return calculate_growth_logic(data.revenue, data.cost)

# Tool 2: System Status (Read-Only Tool)
@app.get("/tools/system_status")
def tool_status():
 return {
 "status": "operational", 
 "server_load": f"{random.randint(10, 40)}%", 
 "active_connections": random.randint(100, 500)
 }

# Tool 3: Audit Log (Write Tool)
@app.post("/tools/audit_log")
def tool_audit(data: AuditLogRequest):
 # Simulate writing to a secure database
 log_id = random.randint(10000, 99999)
 return {
 "success": True, 
 "log_id": log_id, 
 "message": f"Recorded action '{data.user_action}' with severity '{data.severity}'"
 }

if __name__ == "__main__":
 uvicorn.run(app, host="0.0.0.0", port=8000)

