 import streamlit as st
import httpx
import secrets
import hashlib
import base64

st.set_page_config(page_title="MCP OAuth Lab", layout="wide")
st.title("🛡️ MCP OAuth Security Lab")

# --- Session State Management ---
keys = [
 "step", "auth_server_meta", "client_id", "verifier", 
 "challenge", "auth_code", "access_token"
]
for k in keys:
 if k not in st.session_state:
 st.session_state[k] = None
if st.session_state.step is None:
 st.session_state.step = 1

# --- Helper Functions ---
def get_pkce():
 verifier = secrets.token_urlsafe(32)
 digest = hashlib.sha256(verifier.encode()).digest()
 challenge = base64.urlsafe_b64encode(digest).decode().rstrip("=")
 return verifier, challenge

def reset():
 for k in keys:
 st.session_state[k] = None
 st.session_state.step = 1

# --- TABS ---
tab1, tab2 = st.tabs(["🔐 Authentication Handshake (Learn)", "🛠️ Tool Testing (Experiment)"])

# ==============================================================================
# TAB 1: THE AUTH HANDSHAKE (Original Flow)
# ==============================================================================
with tab1:
 col_ctrl, col_flow = st.columns([1, 4])

 with col_ctrl:
 st.info(f"**Step {st.session_state.step}/5**")
 if st.button("🔄 Reset Flow"):
 reset()
 st.rerun()

 if st.session_state.access_token:
 st.success("AUTHENTICATED")
 st.caption(f"Token: `{st.session_state.access_token[:6]}...`")
 else:
 st.warning("NOT AUTHENTICATED")

 with col_flow:
 # STEP 1
 st.markdown("#### 1️⃣ Discovery & Registration")
 if st.session_state.step == 1:
 st.write("Locate Auth Server and get a Client ID.")
 if st.button("🔍 Discover & Register", key="btn_s1"):
 try:
