 auth_url = res.json()["authorization_servers"][0]
 meta = httpx.get(f"{auth_url}/.well-known/oauth-authorization-server").json()
 st.session_state.auth_server_meta = meta
 reg = httpx.post(
 meta["registration_endpoint"],
 json={"redirect_uris": ["http://localhost"], "client_name": "Manual Client"}
 )
 st.session_state.client_id = reg.json()["client_id"]
 st.session_state.step = 2
 st.rerun()
 except Exception as e:
 st.error(f"Failed: {e}")
 elif st.session_state.step > 1:
 st.success(f"✅ Registered. Client ID: `{st.session_state.client_id}`")

 st.divider()

 # STEP 2
 st.markdown("#### 2️⃣ Generate PKCE Keys")
 if st.session_state.step == 2:
 st.write("Generate secret Verifier and public Challenge locally.")
 if st.button("🎲 Generate Keys", key="btn_s2"):
 v, c = get_pkce()
 st.session_state.verifier = v
 st.session_state.challenge = c
 st.session_state.step = 3
 st.rerun()
 elif st.session_state.step > 2:
 st.success("✅ Keys Generated.")
 st.code(f"Verifier (Hidden): {st.session_state.verifier[:10]}... \nChallenge (Public): {st.session_state.challenge}", language="text")

 st.divider()

 # STEP 3
 st.markdown("#### 3️⃣ Request Authorization")
 if st.session_state.step == 3:
 st.write("Send Client ID + Challenge to get an Auth Code.")
 if st.button("🚀 Send Request", key="btn_s3"):
 endpoint = st.session_state.auth_server_meta["authorization_endpoint"]
 resp = httpx.post(
 endpoint,
 params={
 "client_id": st.session_state.client_id, 
 "code_challenge": st.session_state.challenge
 }
 )
 st.session_state.auth_code = resp.json()["code"]
 st.session_state.step = 4
 st.rerun()
 elif st.session_state.step > 3:
 st.success(f"✅ Auth Code Received: `{st.session_state.auth_code[:15]}...`")

 st.divider()

 # STEP 4
 st.markdown("#### 4️⃣ Exchange for Token")
 if st.session_state.step == 4:
 st.write("Send Auth Code + Verifier (Proof) to get Token.")
 if st.button("💰 Exchange Token", key="btn_s4"):
 endpoint = st.session_state.auth_server_meta["token_endpoint"]
 resp = httpx.post(
 endpoint,
 data={
 "grant_type": "authorization_code",
 "code": st.session_state.auth_code,
 "client_id": st.session_state.client_id,
 "code_verifier": st.session_state.verifier
 }
 )
 st.session_state.access_token = resp.json()["access_token"]
 st.session_state.step = 5
 st.rerun()
 elif st.session_state.step > 4:
 st.success("✅ Access Token Acquired!")

# ==============================================================================
