 resp = await client.get(f"http://localhost:8001/verify/{token}")
 if resp.status_code != 200:
 logger.warning(f"⛔ BLOCKED: Invalid token used for {request.url.path}")
 return Response(status_code=403, content="Invalid Token")
 except Exception:
 return Response(status_code=500, content="Auth Server Unavailable")

 logger.info(f"✅ ALLOWED: Authorized access to {request.url.path}")
 return await call_next(request)

# --- 4. Metadata Endpoint ---
@app.get("/.well-known/oauth-protected-resource")
def resource_metadata():
 return {
 "resource": "http://localhost:8000",
 "authorization_servers": ["http://localhost:8001"],
 "bearer_methods_supported": ["header"]
 }

# --- 5. Tool Endpoints ---

@app.post("/calculate_growth")
def tool_growth(data: GrowthRequest):
 return calculate_growth_logic(data.revenue, data.cost)

@app.post("/analyze_sentiment")
def tool_sentiment(data: SentimentRequest):
 return analyze_sentiment_logic(data.text)

@app.get("/system_status")
def tool_status():
 return {"status": "operational", "version": "1.0.5", "load": "low"}

if __name__ == "__main__":
 uvicorn.run(app, host="0.0.0.0", port=8000)

