Here are the three files updated and fixed. 

 The Key Fix: We inverted the server structure in server.py . Instead of trying to force the MCP library to "wrap" FastAPI (which caused the version error), we create a standard FastAPI app first, add our security middleware to it, and then mount the MCP server inside it. 

 1. auth.py (Authorization Server) 

 Run on Port 8001 . This handles keys, tokens, and verification. 

 import secrets
import hashlib
import base64
from fastapi import FastAPI, HTTPException, Form
from pydantic import BaseModel

app = FastAPI()

# In-memory databases
clients_db = {}
codes_db = {}
tokens_db = set()

class ClientRegistration(BaseModel):
 redirect_uris: list[str]
 client_name: str

# Spec #3: Authorization Server Metadata
@app.get("/.well-known/oauth-authorization-server")
def auth_metadata():
 return {
 "issuer": "http://localhost:8001",
 "authorization_endpoint": "http://localhost:8001/authorize",
 "token_endpoint": "http://localhost:8001/token",
 "registration_endpoint": "http://localhost:8001/register",
 "code_challenge_methods_supported": ["S256"]
 }

# Spec #4: Dynamic Client Registration
@app.post("/register")
def register(client: ClientRegistration):
 client_id = secrets.token_hex(16)
 clients_db[client_id] = client.model_dump()
 return {
 "client_id": client_id,
 "client_secret": secrets.token_hex(32), 
 "client_id_issued_at": 1234567890
 }

# Spec #1: OAuth 2.0 Authorization Endpoint
@app.post("/authorize")
def authorize(client_id: str, code_challenge: str):
 if client_id not in clients_db:
 raise HTTPException(status_code=400, detail="Invalid client")

 # In a real app, you would validate the user session here.
 # We skip to issuing the auth code.
 code = secrets.token_urlsafe(32)
 codes_db[code] = {
 "client_id": client_id,
 "code_challenge": code_challenge
 }
 return {"code": code}

# Spec #5: Token Exchange with PKCE
@app.post("/token")
def token(
 grant_type: str = Form(...),
 code: str = Form(...),
 client_id: str = Form(...),
 code_verifier: str = Form(...)
):
 if grant_type != "authorization_code":
 raise HTTPException(status_code=400, detail="Unsupported grant type")

 auth_data = codes_db.get(code)
 if not auth_data or auth_data["client_id"] != client_id:
 raise HTTPException(status_code=400, detail="Invalid code")

 # PKCE Verification
 digest = hashlib.sha256(code_verifier.encode()).digest()
 challenge = base64.urlsafe_b64encode(digest).decode().rstrip("=")

 if challenge != auth_data["code_challenge"]:
 raise HTTPException(status_code=400, detail="PKCE verification failed")

 access_token = secrets.token_urlsafe(32)
 tokens_db.add(access_token)

 # Remove used code
 del codes_db[code]

 return {
 "access_token": access_token,
 "token_type": "Bearer",
 "expires_in": 3600
 }

@app.get("/verify/{token}")
def verify_token(token: str):
 if token in tokens_db:
 return {"active": True}
 raise HTTPException(status_code=401, detail="Invalid token")

if __name__ == "__main__":
 import uvicorn
 uvicorn.run(app, host="0.0.0.0", port=8001)

 2. server.py (MCP Resource Server) 

 Run on Port 8000 . We now use a parent FastAPI app to handle the security middleware, ensuring no conflicts with FastMCP internals. 

 import httpx
from fastapi import FastAPI, Request, Response
from fastmcp import FastMCP

# 1. Create the FastMCP instance and define tools
# We do NOT mount anything here yet.
mcp = FastMCP("secure-mcp")

@mcp.tool()
def calculate_growth(revenue: int, cost: int) -> str:
 """Calculates profit margin."""
 profit = revenue - cost
 margin = (profit / revenue) * 100 if revenue > 0 else 0
 return f"Profit: ${profit}, Margin: {margin:.2f}%"

# 2. Create the Parent FastAPI Application
app = FastAPI()

# 3. Add Security Middleware
@app.middleware("http")
async def oauth_middleware(request: Request, call_next):
 # Allow public access to metadata and docs
 public_paths = [
 "/.well-known/oauth-protected-resource", 
 "/docs", 
 "/openapi.json"
 ]

 # Check if path is public
 if request.url.path in public_paths:
 return await call_next(request)

 # For all other paths (MCP tools, SSE, etc), require Authentication
 auth_header = request.headers.get("Authorization")
 if not auth_header:
 # Spec #2: Return 401 with location of metadata
 return Response(
 status_code=401,
 headers={"WWW-Authenticate": 'Bearer realm="http://localhost:8000/.well-known/oauth-protected-resource"'}
 )

 token = auth_header.split(" ")[1]

 # Verify token against the Auth Server
 async with httpx.AsyncClient() as client:
 try:
 resp = await client.get(f"http://localhost:8001/verify/{token}")
 if resp.status_code != 200:
 return Response(status_code=403, content="Invalid Token")
 except Exception:
 return Response(status_code=500, content="Auth Server Unavailable")

 response = await call_next(request)
 return response

# 4. Spec #2: Protected Resource Metadata Endpoint
@app.get("/.well-known/oauth-protected-resource")
def resource_metadata():
 return {
 "resource": "http://localhost:8000",
 "authorization_servers": ["http://localhost:8001"],
 "bearer_methods_supported": ["header"]
 }

# 5. Mount the MCP server
# This makes the MCP endpoints (like /sse and tools) available under the root URL
app.mount("/", mcp)

if __name__ == "__main__":
 import uvicorn
 uvicorn.run(app, host="0.0.0.0", port=8000)

