Excellent! The log shows that the main problem is solved. This line is the key: 

 Session ID captured: 3a5ebf35a9924b7e926ad97c82794c52 

 This means the client is now successfully connecting to the server and establishing a valid session. 

 The reason you're not seeing the responses is a simple race condition . The main part of your client script sends the requests and then immediately finishes. When the main script exits, it shuts down the background listener thread before the server has had time to process the requests and send the responses back. 

 ## The Solution 

 The fix is to simply add a short delay at the end of the main function in client.py . This will keep the script alive long enough for the listener thread to receive and print the messages from the server. 

 ## Final client.py 

 This version just adds one line at the end of the main function. 

 import requests
import json
import sseclient
import threading
import time

SERVER_URL = "http://127.0.0.1:8000/mcp/"

SESSION_STATE = {"id": None}
SESSION_READY = threading.Event()

def listen_for_events(client):
 try:
 print("Listener thread started. Waiting for session ID...")
 iterator = iter(client)
 first_event = next(iterator)

 session_id = None
 if 'session_id=' in first_event.data:
 session_id = first_event.data.split('session_id=')[-1]

 if session_id:
 print(f"Session ID captured: {session_id}")
 SESSION_STATE["id"] = session_id
 SESSION_READY.set()
 else:
 print("Warning: Could not find session_id in the first event.")

 for event in iterator:
 if event.data:
 try:
 print("\n--- Response Received ---")
 parsed_data = json.loads(event.data)
 print(json.dumps(parsed_data, indent=2))
 print("-------------------------")
 except json.JSONDecodeError:
 pass

 except StopIteration:
 print("Listener thread: Stream closed by server.")
 except Exception as e:
 print(f"\nListener thread error: {e}")

def send_mcp_request(method: str, params: dict = {}, session_id: str = None):
 payload = {
 "jsonrpc": "2.0", "id": int(time.time()), "method": method,
 "params": params, "session_id": session_id
 }
 try:
 requests.post(SERVER_URL, json=payload)
 except requests.exceptions.ConnectionError as e:
 print(f"Could not send request. Is the server running? Error: {e}")
 exit()

def main():
 client = sseclient.SSEClient(SERVER_URL)
 listener = threading.Thread(target=listen_for_events, args=(client,), daemon=True)
 listener.start()

 print("Waiting for server to provide a session ID...")
 ready = SESSION_READY.wait(timeout=5)

 if not ready or not SESSION_STATE["id"]:
 print("\nError: Did not receive a session ID from the server. Exiting.")
 return

 session_id = SESSION_STATE["id"]

 print("\n>>> Sending request to list files...")
 send_mcp_request("resources/read", {"uri": "resource://files/list"}, session_id)
 time.sleep(1)

 print("\n>>> Sending request to read 'project_notes.txt'...")
 send_mcp_request("resources/read", {"uri": "file:///project_notes.txt"}, session_id)

 # Keep the main thread alive to allow the listener to receive responses
 print("\nClient has finished sending requests. Waiting for responses...")
 time.sleep(3)

if __name__ == "__main__":
 main()

