 import ast
import re

def check_syntax(file_path):
 try:
 with open(file_path, 'r') as file:
 source_code = file.read()
 ast.parse(source_code)
 return {"status": "success", "message": "Syntax is valid."}
 except FileNotFoundError:
 return {"status": "error", "message": "File not found."}
 except SyntaxError as e:
 return {"status": "error", "message": f"Syntax Error: {e.msg} on line {e.lineno}."}
 except Exception as e:
 return {"status": "error", "message": f"An unexpected error occurred: {e}"}

def check_hardcoded_secrets(file_path):
 try:
 with open(file_path, 'r') as file:
 lines = file.readlines()

 secret_pattern = r'(key|secret|password|token|DATABASE_URL)\s*=\s*["\'](.*?)["\']'
 found_secrets = []
 for i, line in enumerate(lines):
 if re.search(secret_pattern, line, re.IGNORECASE):
 found_secrets.append(f"Line {i+1}: Potential secret found.")

 if found_secrets:
 return {"status": "success", "findings": found_secrets}
 return {"status": "success", "message": "No hardcoded secrets found."}
 except FileNotFoundError:
 return {"status": "error", "message": "File not found."}

def check_missing_imports(file_path):
 try:
 with open(file_path, 'r') as file:
 source_code = file.read()
 tree = ast.parse(source_code)

 imported = {alias.asname or alias.name for node in ast.walk(tree) if isinstance(node, ast.Import) for alias in node.names}
 imported.update({alias.asname or alias.name for node in ast.walk(tree) if isinstance(node, ast.ImportFrom) for alias in node.names})

 defined = {node.name for node in ast.walk(tree) if isinstance(node, (ast.FunctionDef, ast.ClassDef))}
 defined.update({target.id for node in ast.walk(tree) if isinstance(node, ast.Assign) for target in node.targets if isinstance(target, ast.Name)})

 used = {node.id for node in ast.walk(tree) if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load)}

 known_names = imported | defined | set(dir(__builtins__))
 missing = list(used - known_names)

 if missing:
 return {"status": "success", "findings": f"Found undefined names: {missing}"}
 return {"status": "success", "message": "No missing imports found."}

 except FileNotFoundError:
 return {"status": "error", "message": "File not found."}
 except SyntaxError:
 return {"status": "error", "message": "Cannot check imports due to syntax error."}

 The __init__.py file inside the tools directory can remain empty. 

 3. The Agent's Brain 

 The agent.py file contains the CodeAgent class. Its main job is to take a user's request, ask Gemini Flash which tool to use, and then execute that tool. 

 SPECTO/agent.py 

 import os
import google.generativeai as genai
from dotenv import load_dotenv
from tools import code_tools

class CodeAgent:
 def __init__(self):
 load_dotenv()
 api_key = os.getenv("GEMINI_API_KEY")
 genai.configure(api_key=api_key)
 self.model = genai.GenerativeModel('gemini-1.5-flash')
 self.tools = {
 "syntax": code_tools.check_syntax,
 "secrets": code_tools.check_hardcoded_secrets,
 "imports": code_tools.check_missing_imports,
 }

 def decide_tool(self, query):
 tool_names = list(self.tools.keys())
 prompt = f"""
 You are a helpful assistant. Based on the user's request, choose the single best tool to use.
 Your choices are: {tool_names}.
 User Request: "{query}"
 Respond with only the name of the tool.
 """
 response = self.model.generate_content(prompt)
 return response.text.strip()

 def run_analysis(self, query, file_path):
 chosen_tool_name = self.decide_tool(query)

 if chosen_tool_name in self.tools:
 tool_to_run = self.tools[chosen_tool_name]
 result = tool_to_run(file_path)
 return {"tool_used": chosen_tool_name, "result": result}
 else:
 return {"error": f"Could not identify a valid tool for your request. Chose: {chosen_tool_name}"}

 4. The Main API Endpoint 

 Finally, main.py creates the API that other projects can call. It uses FastAPI to create an /analyze endpoint. 

 SPECTO/main.py 

 from fastapi import FastAPI
from pydantic import BaseModel
from agent import CodeAgent

app = FastAPI()
agent = CodeAgent()

class AnalysisRequest(BaseModel):
 query: str
 file_path: str

@app.get("/")
def read_root():
 return {"message": "SPECTO Code Analysis Agent is running."}

@app.post("/analyze")
def analyze_code(request: AnalysisRequest):
 result = agent.run_analysis(request.query, request.file_path)
 return result

