class InMemoryDBImpl(InMemoryDB):

 def __init__(self):
 self.data = {}
 self.history = {} # Store history of changes for each key-field pair

 def set(self, timestamp: int, key: str, field: str, value: int):
 if key not in self.data:
 self.data[key] = {}
 if key not in self.history:
 self.history[key] = {}
 if field not in self.history[key]:
 self.history[key][field] = []

 self.data[key][field] = {"value": value, "ttl": float('inf'), "start_time": 0}
 self.history[key][field].append((timestamp, {"value": value, "ttl": float('inf'), "start_time": 0}))

 def compare_and_set(self, timestamp: int, key: str, field: str, expected_value: int, new_value: int):
 if key in self.data and field in self.data[key]:
 record = self.data[key][field]
 if timestamp >= record["start_time"] + record["ttl"]:
 del self.data[key][field]
 return False
 if record["value"] == expected_value:
 self.data[key][field]["value"] = new_value
 if key not in self.history:
 self.history[key] = {}
 if field not in self.history[key]:
 self.history[key][field] = []
 self.history[key][field].append((timestamp, {"value": new_value, "ttl": record["ttl"], "start_time": record["start_time"]}))
 return True
 return False

 def compare_and_delete(self, timestamp: int, key: str, field: str, expected_value: int):
 if key in self.data and field in self.data[key]:
 record = self.data[key][field]
 if timestamp >= record["start_time"] + record["ttl"]:
