 .set-container { display: flex; gap: 12px; margin-top: 15px; flex-wrap: wrap; }

 /* MECHANICAL PUSH BUTTONS */
 .set-bubble {
 width: 44px; height: 44px; border-radius: 50%;
 display: flex; align-items: center; justify-content: center; 
