 <script>
 if ('serviceWorker' in navigator) { window.addEventListener('load', () => { navigator.serviceWorker.register('sw.js').catch(err => console.log('SW fail')); }); }

 let appData = null; let currentAudioType = 'playlists'; let totalTasks = 0; let timerInterval;

 const todayDateStr = new Date().toDateString();
 let savedState = JSON.parse(localStorage.getItem('fitforge_state')) || {};
 if (savedState.date !== todayDateStr || !savedState.checkedSets) {
 let existingVoice = savedState.voiceEnabled || false;
 savedState = { date: todayDateStr, checkedSets: {}, finisherDone: false, hasCelebrated: false, voiceEnabled: existingVoice };
 localStorage.setItem('fitforge_state', JSON.stringify(savedState));
 }

 $(document).ready(function () {
 if (savedState.voiceEnabled) { $('#voiceToggle').addClass('active').find('i').removeClass('fa-volume-xmark').addClass('fa-volume-high'); }

 fetch('data.json').then(res => res.json()).then(data => { appData = data; initApp(); })
 .catch(err => { $('#workoutContent').html(`<div class="alert alert-danger" style="background:#222; border-color:#ff3b30; color:#fff;">System Error: Run on Vercel to mount data.json.</div>`); });

 $('input[name="deviceToggle"]').on('change', function () { if (appData) renderAudioList(currentAudioType); });

 // Event Delegation for Tactile Bubbles
 $(document).on('click', '.set-bubble', function () {
 let exId = $(this).data('ex'); let setIdx = $(this).data('set'); let restTime = $(this).data('rest');

 if ($(this).hasClass('active')) {
 $(this).removeClass('active'); 
 savedState.checkedSets[exId] = savedState.checkedSets[exId].filter(s => s !== setIdx);
 } else {
 $(this).addClass('active'); 
 savedState.checkedSets[exId].push(setIdx);
 startRestTimer(restTime);
 }
 calculateProgress(true);
 });

 $(document).on('change', '#finisherToggle', function () { 
 savedState.finisherDone = this.checked; calculateProgress(true); 
 });
 });

 function toggleVoice() {
 savedState.voiceEnabled = !savedState.voiceEnabled;
 localStorage.setItem('fitforge_state', JSON.stringify(savedState));
 const $icon = $('#voiceToggle i');
 if (savedState.voiceEnabled) {
 $('#voiceToggle').addClass('active'); $icon.removeClass('fa-volume-xmark').addClass('fa-volume-high');
 let speech = new SpeechSynthesisUtterance(""); window.speechSynthesis.speak(speech);
 } else {
 $('#voiceToggle').removeClass('active'); $icon.removeClass('fa-volume-high').addClass('fa-volume-xmark');
 }
 }

 // Updated HTML Builder with Skeuomorphic Classes
 function buildCardHTML(ex, exId, index, bubblesHtml, isOptional) {
 let optBadge = isOptional ? `<span class="lcd-badge me-2" style="background:#222; border-color:#444; color:#aaa;">OPT</span>` : '';
 return `
 <div class="workout-card animate__animated animate__fadeInUp" id="card-${exId}" style="animation-delay: ${index * 0.1}s;">
 <div class="ex-header d-flex align-items-center">
 <h3 class="ex-title flex-grow-1">${optBadge}${ex.name}</h3>
 <span class="lcd-badge">${ex.sets}x${ex.reps}</span>
 </div>
 <div class="set-container">${bubblesHtml}</div>
 <div style="font-size: 0.8rem; color: #666; margin-top: 15px; border-top: 1px solid #111; padding-top: 10px;">
 <i class="fa-solid fa-microscope text-muted me-1"></i> ${ex.anatomy_pov}
 </div>
 </div>
 `;
 }

 function initApp() {
 const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
 const todayName = days[new Date().getDay()];
 $('#currentDay').text(todayName.toUpperCase());

 const todaysPlan = appData.schedule.find(day => day.day_of_week === todayName);
 $('#focusArea').text(todaysPlan.focus);
 const $content = $('#workoutContent');

 if (todaysPlan.is_rest_day) {
 $content.append(`<div class="workout-card text-center py-5 animate__animated animate__zoomIn"><i class="fa-solid fa-power-off fa-3x mb-3" style="color: var(--led-yellow); text-shadow: 0 0 10px var(--led-yellow);"></i><h4 class="brand-font text-white">RECOVERY CYLE</h4><p class="text-muted mt-2 px-3">${todaysPlan.notes}</p></div>`);
 } else {
 $('#progressContainer').show();
 totalTasks = 0;

 todaysPlan.exercises.forEach((ex, index) => {
 let exId = `ex${index}`;
 if (!savedState.checkedSets[exId]) savedState.checkedSets[exId] = [];

 let bubblesHtml = '';
 for (let s = 0; s < ex.sets; s++) {
 totalTasks++; 
 let isActive = savedState.checkedSets[exId].includes(s) ? 'active' : '';
 bubblesHtml += `<div class="set-bubble ${isActive}" data-ex="${exId}" data-set="${s}" data-rest="${ex.rest_seconds || 60}"></div>`;
 }
 $content.append(buildCardHTML(ex, exId, index, bubblesHtml, false));
 });

 if (todaysPlan.optional_exercises && todaysPlan.optional_exercises.length > 0) {
 $content.append(`
 <div class="text-center mt-5 mb-4 animate__animated animate__fadeInUp" style="animation-delay: 0.3s;">
 <button class="btn-groove" type="button" data-bs-toggle="collapse" data-bs-target="#optionalWorkouts">
 OPTIONAL MODULES <i class="fa-solid fa-chevron-down ms-2"></i>
 </button>
 </div>
 <div class="collapse" id="optionalWorkouts"></div>
 `);

 const $optionalContainer = $('#optionalWorkouts');
 todaysPlan.optional_exercises.forEach((ex, index) => {
 let exId = `opt${index}`;
 if (!savedState.checkedSets[exId]) savedState.checkedSets[exId] = [];

 let bubblesHtml = '';
 for(let s = 0; s < ex.sets; s++) {
 let isActive = savedState.checkedSets[exId].includes(s) ? 'active' : '';
 bubblesHtml += `<div class="set-bubble ${isActive}" data-ex="${exId}" data-set="${s}" data-rest="${ex.rest_seconds || 60}"></div>`;
 }
 $optionalContainer.append(buildCardHTML(ex, exId, index, bubblesHtml, true));
 });
 }

 if (todaysPlan.finisher) {
 totalTasks++; 
 let isChecked = savedState.finisherDone ? 'checked' : '';
 $content.append(`
 <div class="workout-card animate__animated animate__fadeInUp mt-4" style="animation-delay: 0.5s;">
 <h6 class="text-uppercase mb-3" style="font-size: 0.8rem; letter-spacing: 1px; color: var(--led-red); text-shadow: 0 0 5px rgba(255,59,48,0.5);">BURNOUT OVERRIDE</h6>
 <label class="finisher-label">
 <input type="checkbox" class="finisher-checkbox" id="finisherToggle" ${isChecked}>
 <span class="flex-grow-1" style="color: #fff;">${todaysPlan.finisher.name}</span>
 <span class="lcd-badge red">${todaysPlan.finisher.duration_minutes ? todaysPlan.finisher.duration_minutes + ' MIN' : todaysPlan.finisher.sets + 'x' + todaysPlan.finisher.reps}</span>
 </label>
 </div>
 `);
 }
 calculateProgress(false);
 }

 const $weekly = $('#weeklyContent');
 appData.schedule.forEach(day => {
 let isToday = day.day_of_week === todayName ? '<span class="lcd-badge ms-2" style="font-size: 0.6rem;">SYS.ACT</span>' : '';
 let dayHtml = `<div class="mb-3 border-bottom pb-2" style="border-color:#222 !important;"><strong class="d-block text-white">${day.day_of_week.toUpperCase()} ${isToday}<br><span style="color: var(--text-muted); font-size: 0.8rem;">${day.focus.toUpperCase()}</span></strong>`;
 if (day.is_rest_day) { dayHtml += `<span style="font-size: 0.75rem; color: #555;">RECOVERY CYCLE</span>`; } else { dayHtml += `<span style="font-size: 0.75rem; color: #555;">${day.exercises.map(ex => ex.name).join(', ').toUpperCase()}</span>`; }
 $weekly.append(dayHtml + `</div>`);
 });
 }

 function calculateProgress(triggerAnimation) {
 let completedSetsCount = 0;
 for (const exId in savedState.checkedSets) { completedSetsCount += savedState.checkedSets[exId].length; }
 if (savedState.finisherDone) completedSetsCount++;

 let percentage = totalTasks === 0 ? 0 : Math.min(100, Math.round((completedSetsCount / totalTasks) * 100));

 $('#workoutProgress').css('width', percentage + '%'); 

 if (percentage === 100) {
 if (triggerAnimation && !savedState.hasCelebrated) { triggerConfetti(); savedState.hasCelebrated = true; }
 $('#progressText').text("MAX YIELD").css({'color': 'var(--led-yellow)', 'text-shadow': '0 0 5px var(--led-yellow)'}); 
 $('#workoutProgress').css({'box-shadow': '0 0 15px var(--led-yellow)', 'background': 'var(--led-yellow)'});
 } else {
 savedState.hasCelebrated = false; 
 $('#progressText').text(percentage + '%').css({'color': 'var(--led-green)', 'text-shadow': '0 0 5px var(--led-green)'}); 
 $('#workoutProgress').css({'box-shadow': '0 0 15px rgba(0,255,136,0.5)', 'background': 'linear-gradient(90deg, #008f4c, var(--led-green))'});
 }
 localStorage.setItem('fitforge_state', JSON.stringify(savedState));
 }

 function startRestTimer(seconds) {
 clearInterval(timerInterval);
 const $timer = $('#floatingTimer'); const $display = $('#timerDisplay');
 $timer.removeClass('done').addClass('show');
 let timeLeft = seconds;

 let initM = Math.floor(timeLeft / 60).toString().padStart(2, '0');
 let initS = (timeLeft % 60).toString().padStart(2, '0');
 $display.text(`${initM}:${initS}`);

 timerInterval = setInterval(() => {
 timeLeft--;
 let m = Math.floor(timeLeft / 60).toString().padStart(2, '0');
 let s = (timeLeft % 60).toString().padStart(2, '0');
 $display.text(`${m}:${s}`);

 if (timeLeft <= 0) {
 clearInterval(timerInterval);
 $timer.addClass('done');
 $display.text("LIFT");
 if (navigator.vibrate) navigator.vibrate([200, 100, 200]);

 if (savedState.voiceEnabled && 'speechSynthesis' in window) {
 let speech = new SpeechSynthesisUtterance("Rest is over. Let's get back to your next rep.");
 speech.volume = 1; speech.rate = 1.1; speech.pitch = 1;
 window.speechSynthesis.speak(speech);
 }
 setTimeout(() => $timer.removeClass('show'), 5000);
 }
 }, 1000);
 }

 function dismissTimer() { $('#floatingTimer').removeClass('show'); clearInterval(timerInterval); }
 function triggerConfetti() { var duration = 3000; var animationEnd = Date.now() + duration; var defaults = { startVelocity: 30, spread: 360, ticks: 60, zIndex: 9999, colors: ['#00ff88', '#eab308', '#ff3b30'] }; function randomInRange(min, max) { return Math.random() * (max - min) + min; } var interval = setInterval(function () { var timeLeft = animationEnd - Date.now(); if (timeLeft <= 0) return clearInterval(interval); var particleCount = 50 * (timeLeft / duration); confetti(Object.assign({}, defaults, { particleCount, origin: { x: randomInRange(0.1, 0.3), y: Math.random() - 0.2 } })); confetti(Object.assign({}, defaults, { particleCount, origin: { x: randomInRange(0.7, 0.9), y: Math.random() - 0.2 } })); }, 250); }
 function createDeepLink(webUrl, device) { if (device === 'web') return webUrl; try { const urlObj = new URL(webUrl); const pathParts = urlObj.pathname.split('/').filter(p => p); if (pathParts.length >= 2) { const type = pathParts[0]; const id = pathParts[1]; if (device === 'ios') return `spotify:${type}:${id}`; if (device === 'android') return `intent://${type}/${id}#Intent;scheme=spotify;package=com.spotify.music;end;`; } } catch (e) { console.error(e); } return webUrl; }
 function openAudioModal(type) { currentAudioType = type; $('#audioModalTitle').html(type === 'playlists' ? 'MUSIC ROUTING' : 'PODCAST ROUTING'); renderAudioList(type); new bootstrap.Modal(document.getElementById('audioModal')).show(); }
 function renderAudioList(type) { const $list = $('#audioModalList').empty(); const device = $('input[name="deviceToggle"]:checked').val(); appData.audio[type].forEach(item => { const icon = type === 'playlists' ? 'fa-music' : 'fa-microphone-lines'; $list.append(`<a href="${createDeepLink(item.url, device)}" class="audio-list-item" style="background:var(--screen-bg); border:1px solid #111; box-shadow:inset 2px 2px 4px var(--shadow);" target="_blank"><i class="fa-solid ${icon} me-3" style="color:var(--led-off);"></i><span class="flex-grow-1" style="font-family:monospace; color:var(--led-yellow);">${item.name.toUpperCase()}</span><i class="fa-solid fa-arrow-up-right-from-square" style="color:#555; font-size: 0.8rem;"></i></a>`); }); }
 function shareApp() { if (navigator.share) navigator.share({ title: 'FitForge Protocol', text: 'Check out my custom daily hardware protocol.', url: window.location.href }).catch(console.error); else alert("Copy this link: " + window.location.href); }
 </script>
