Moving this to a full-stack architecture is exactly the right move. By introducing a FastAPI backend, we solve the two biggest issues in one go: 

 Security: We pull the OpenAI API key out of the browser and hide it on the server. 

 State Management: The backend can manage the local file system, cache the pages, and automatically stitch them together in Converted.md in the correct numerical order—regardless of the order in which you send the pages from the UI. 

 Here is the complete setup for your new backend and the updated frontend. 

 1. The FastAPI Backend ( app.py ) 

 This script acts as the orchestrator. It receives the sliced PDF page from the frontend, calls your extraction API, passes the text to OpenAI, and finally manages the Converted.md file. It uses a small pages_cache.json file to remember previous pages so it can always rebuild the markdown file in perfect numerical order. 

 First, install the required dependencies in your terminal: 

 pip install fastapi uvicorn requests python-multipart

 Now, create app.py in your project folder: 

 from fastapi import FastAPI, UploadFile, File, Form, HTTPException
from fastapi.middleware.cors import CORSMiddleware
import requests
import os
import json

app = FastAPI()

# Enable CORS so the frontend can talk to this local server
app.add_middleware(
 CORSMiddleware,
 allow_origins=["*"], # In production, restrict this to your frontend domain
 allow_credentials=True,
 allow_methods=["*"],
 allow_headers=["*"],
)

# --- CONFIGURATION ---
# Best practice: Export this in your terminal before running: export OPENAI_API_KEY="sk-..."
OPENAI_API_KEY = os.getenv("OPENAI_API_KEY", "YOUR_OPENAI_API_KEY_HERE")
EXTRACTION_API = "https://los-document-service-dev.soham.ai/los/doc-content-extraction-classify"

CACHE_FILE = "pages_cache.json"
OUTPUT_FILE = "Converted.md"

def update_markdown_document(page_num: int, markdown_text: str):
 """Saves the page to a cache and rebuilds Converted.md in numerical order."""

 # 1. Load existing pages from cache
 pages = {}
 if os.path.exists(CACHE_FILE):
 with open(CACHE_FILE, "r", encoding="utf-8") as f:
 pages = json.load(f)

 # 2. Update the current page
 pages[str(page_num)] = markdown_text

 # 3. Save back to cache
 with open(CACHE_FILE, "w", encoding="utf-8") as f:
 json.dump(pages, f, indent=4)

 # 4. Rebuild Converted.md sequentially
 with open(OUTPUT_FILE, "w", encoding="utf-8") as f:
 # Sort keys numerically (e.g., "1", "2", "10")
 sorted_pages = sorted([int(k) for k in pages.keys()])

 f.write("# Compiled Document\n\n")

 for p in sorted_pages:
 f.write(f"\n")
 f.write(pages[str(p)])
 f.write(f"\n\n\n")
 f.write("\n---\n\n") # Visual separator between pages

@app.post("/process-page")
async def process_page(file: UploadFile = File(...), page_number: int = Form(...)):
 try:
 # 1. Send the file to the Extraction API
 file_bytes = await file.read()
 files_payload = {"file": (file.filename, file_bytes, file.content_type)}

 ext_response = requests.post(EXTRACTION_API, files=files_payload)
 ext_response.raise_for_status()

 ext_data = ext_response.json()
 raw_text = ext_data.get("extracted_text")

 if not raw_text:
 raise HTTPException(status_code=400, detail="No text extracted from the API.")

 # 2. Send the raw text to OpenAI
 headers = {
 "Authorization": f"Bearer {OPENAI_API_KEY}",
 "Content-Type": "application/json"
 }
 ai_payload = {
 "model": "gpt-4o",
 "messages": [
 {
 "role": "system",
 "content": "You are a professional publisher. Take the raw OCR text and format it into a clean, print-ready document using Markdown. Fix obvious OCR typos, use hierarchical headings (h1, h2, h3), use bullet points, and ensure logical spacing. Output strictly the Markdown, no conversation."
 },
 {"role": "user", "content": raw_text}
 ],
 "temperature": 0.1
 }

 ai_response = requests.post("https://api.openai.com/v1/chat/completions", headers=headers, json=ai_payload)
 ai_response.raise_for_status()

 ai_data = ai_response.json()
 markdown_text = ai_data["choices"][0]["message"]["content"]

 # 3. Update the local Converted.md file
 update_markdown_document(page_number, markdown_text)

 return {
 "status": "success",
 "page_number": page_number,
 "markdown": markdown_text,
 "raw_text": raw_text
 }

 except Exception as e:
 raise HTTPException(status_code=500, detail=str(e))

 To start your backend, run this in your terminal: 

 uvicorn app:app --reload --port 8000

 2. The Updated Frontend ( index.html ) 

 Now that the backend handles the heavy lifting, the frontend becomes much lighter and more secure. We just need to update the sendBtn.addEventListener logic in your index.html to point to http://localhost:8000/process-page and append the page number to the FormData . 

 Replace the entire <script> section at the bottom of your index.html with this: 

 <script>
 // --- CONFIGURATION ---
 // Pointing directly to our new local FastAPI backend
 const BACKEND_API = 'http://localhost:8000/process-page';
 // ---------------------

 let originalPdfDoc = null;
 let totalPages = 0;
 let currentMarkdown = "";

 // DOM Elements
 const pdfInput = document.getElementById('pdfInput');
 const mainStatus = document.getElementById('mainStatus');
 const pipelineStatus = document.getElementById('pipelineStatus');
 const controlsEl = document.getElementById('controls');
 const pageSelector = document.getElementById('pageSelector');
 const pageRange = document.getElementById('pageRange');
 const sendBtn = document.getElementById('sendBtn');
 const documentContainer = document.getElementById('documentContainer');
 const renderedDocument = document.getElementById('renderedDocument');
 const rawContainer = document.getElementById('rawContainer');
 const rawArea = document.getElementById('rawArea');
 const newDocBtn = document.getElementById('newDocBtn');

 // File Selection Logic
 pdfInput.addEventListener('change', async (e) => {
 const file = e.target.files[0];
 if (!file) return;

 mainStatus.innerText = 'Parsing PDF...';
 mainStatus.className = 'status-badge active';

 try {
 const arrayBuffer = await file.arrayBuffer();
 originalPdfDoc = await PDFLib.PDFDocument.load(arrayBuffer);
 totalPages = originalPdfDoc.getPageCount();

 pageSelector.max = totalPages;
 pageSelector.value = 1;
 pageRange.innerText = `of ${totalPages} pages`;

 mainStatus.innerText = 'Document Ready';
 mainStatus.className = 'status-badge success';
 controlsEl.classList.remove('hidden');
 pipelineStatus.innerText = "Select a page to begin processing.";
 } catch (error) {
 mainStatus.innerText = 'Error';
 mainStatus.className = 'status-badge';
 pipelineStatus.innerText = `Failed to load PDF: ${error.message}`;
 pipelineStatus.style.color = '#ef4444';
 }
 });

 // Processing Logic
 sendBtn.addEventListener('click', async () => {
 const selectedPageNumber = parseInt(pageSelector.value, 10);
 if (isNaN(selectedPageNumber) || selectedPageNumber < 1 || selectedPageNumber > totalPages) return;

 // UI Reset for new run
 sendBtn.disabled = true;
 sendBtn.innerHTML = `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" class="spin"><path d="M21 12a9 9 0 1 1-6.219-8.56"/></svg> Processing...`;
 documentContainer.classList.add('hidden');
 rawContainer.classList.add('hidden');
 rawContainer.removeAttribute('open');
 pipelineStatus.style.color = 'var(--text-muted)';

 try {
 // STEP 1: Slicing the PDF in the browser
 pipelineStatus.innerHTML = `<strong>Step 1/2:</strong> Isolating page ${selectedPageNumber}...`;
 const singlePageDoc = await PDFLib.PDFDocument.create();
 const [copiedPage] = await singlePageDoc.copyPages(originalPdfDoc, [selectedPageNumber - 1]);
 singlePageDoc.addPage(copiedPage);
 const pdfBytes = await singlePageDoc.save();
 const blob = new Blob([pdfBytes], { type: 'application/pdf' });

 // Package the file AND the page number for the backend
 const formData = new FormData();
 formData.append('file', blob, `page_${selectedPageNumber}.pdf`);
 formData.append('page_number', selectedPageNumber);

 // STEP 2: Send to FastAPI Backend
 pipelineStatus.innerHTML = `<strong>Step 2/2:</strong> Extracting text and applying AI formatting via backend...`;

 const response = await fetch(BACKEND_API, {
 method: 'POST',
 body: formData
 });

 const responseData = await response.json();

 if (!response.ok) {
 throw new Error(responseData.detail || "Unknown backend error occurred.");
 }

 currentMarkdown = responseData.markdown;

 // Show raw data in the collapsible debug box
 rawArea.innerText = responseData.raw_text;
 rawContainer.classList.remove('hidden');

 // Render the Markdown visually
 renderedDocument.innerHTML = marked.parse(currentMarkdown);
 documentContainer.classList.remove('hidden');

 pipelineStatus.innerHTML = `<span style="color: var(--success);">✓ Page ${selectedPageNumber} processed successfully and saved to Converted.md!</span>`;

 } catch (error) {
 pipelineStatus.innerHTML = `<strong>Error:</strong> ${error.message}`;
 pipelineStatus.style.color = '#ef4444';
 } finally {
 sendBtn.disabled = false;
 sendBtn.innerHTML = `<svg width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" viewBox="0 0 24 24"><path d="m22 2-7 20-4-9-9-4Z"/><path d="M22 2 11 13"/></svg> Process Next`;
 }
 });

 // Download Markdown Logic
 newDocBtn.addEventListener('click', () => {
 if (!currentMarkdown) return;
 const blob = new Blob([currentMarkdown], { type: 'text/markdown' });
 const url = URL.createObjectURL(blob);
 const a = document.createElement('a');
 a.href = url;
 a.download = `extracted_page.md`;
 document.body.appendChild(a);
 a.click();
 document.body.removeChild(a);
 URL.revokeObjectURL(url);
 });
 </script>

