 2. css/style.css (Rich Textures & 3D Depth) 

 Velvet Texture: We use a radial gradient on the flaps ( #500000 to #200000 ) to create a spotlight effect, making the fabric look curved and rich. 

 Shadows: Deep shadows on .flap-top make it look like it's physically overlapping the bottom flap. 

 Tassels: Added CSS styling for hanging thread tassels on the knot. 

 /* =========================================
 1. VARIABLES & RESET
========================================== */
:root {
 --paper-bg: #FDFCF0;
 --paper-texture: url('https://www.transparenttextures.com/patterns/cream-paper.png');
 --ink-color: #4B3621;
 --royal-red: #800000;
 --kalava-yellow: #FFC107;
 --kalava-red: #D32F2F;
 --font-heading: 'Rozha One', serif;
 --font-body: 'Playfair Display', serif;
 --font-telugu: 'Ramabhadra', sans-serif;
}

body {
 background-color: #1a0505; /* Deep wood/darkroom */
 /* Subtle Wood Texture */
 background-image: repeating-linear-gradient(45deg, rgba(0,0,0,0.1) 0px, rgba(0,0,0,0.1) 2px, transparent 2px, transparent 4px);
 color: var(--ink-color);
 font-family: var(--font-body);
 overflow-x: hidden;
}
body.overflow-hidden { overflow: hidden; height: 100vh; }

/* =========================================
 2. THE VELVET WRAP LOADER (Realistic)
========================================== */
#loader-overlay {
 position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;
 z-index: 9999;
}

/* The Flaps (Rich Velvet with Spotlight) */
.flap-top, .flap-bottom {
 position: absolute; left: 0; width: 100%; height: 50.5%; /* Slight overlap */
 background: radial-gradient(circle at center, #600000 0%, #300000 70%, #150000 100%);
 box-shadow: inset 0 0 50px rgba(0,0,0,0.8); /* Inner vignette */
 transition: transform 1s cubic-bezier(0.7, 0, 0.3, 1);
}

.flap-top {
 top: 0; transform-origin: top; z-index: 2;
 /* The shadow cast by the top flap onto the bottom one */
 box-shadow: 0 10px 30px rgba(0,0,0,0.8), inset 0 0 50px rgba(0,0,0,0.8);
 border-bottom: 1px solid rgba(212, 175, 55, 0.2);
}
.flap-bottom {
 bottom: 0; transform-origin: bottom; z-index: 1;
 border-top: 1px solid rgba(212, 175, 55, 0.2);
}

/* Gold Ornamental Borders */
.gold-border-bottom {
 position: absolute; bottom: 10px; left: 5%; width: 90%; height: 2px;
 background: linear-gradient(90deg, transparent, var(--kalava-yellow), transparent);
}
.gold-border-top {
 position: absolute; top: 10px; left: 5%; width: 90%; height: 2px;
 background: linear-gradient(90deg, transparent, var(--kalava-yellow), transparent);
}

/* The Thread (Split) */
.thread-container {
 position: absolute; top: 50%; left: 0; width: 100%; height: 100px;
 transform: translateY(-50%); z-index: 100; pointer-events: none;
}
.thread-line {
 position: absolute; top: 50%; height: 6px; margin-top: -3px;
 /* Realistic Kalava Pattern (Red/Yellow twist) */
 background: repeating-linear-gradient(45deg, var(--kalava-red) 0px, var(--kalava-red) 10px, var(--kalava-yellow) 10px, var(--kalava-yellow) 20px);
 box-shadow: 0 5px 10px rgba(0,0,0,0.5);
}
.thread-left { left: 0; width: 50%; transform-origin: left; }
.thread-right { right: 0; width: 50%; transform-origin: right; }

/* The Knot */
.kalava-knot {
 position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
 width: 120px; height: 120px; pointer-events: auto; cursor: pointer;
 display: flex; flex-direction: column; align-items: center; justify-content: center;
 z-index: 101;
}

/* Knot Center */
.knot-center {
 width: 30px; height: 30px; background: var(--kalava-red);
 border-radius: 50%; border: 3px solid var(--kalava-yellow);
 box-shadow: 0 5px 15px rgba(0,0,0,0.6); position: relative; z-index: 2;
}

/* Hanging Tassels */
.knot-tassels {
 width: 4px; height: 60px; background: var(--kalava-red);
 margin-top: -15px; position: relative; z-index: 1;
 box-shadow: 0 2px 5px rgba(0,0,0,0.5);
}
.knot-tassels::after {
 content: ''; position: absolute; bottom: 0; left: -10px;
 width: 24px; height: 24px; background: var(--kalava-yellow);
 border-radius: 50% 50% 5px 5px; /* Tassel shape */
 box-shadow: 0 2px 5px rgba(0,0,0,0.4);
}

.knot-label {
 position: absolute; top: -30px;
 color: var(--kalava-yellow); font-size: 0.8rem; text-transform: uppercase;
 letter-spacing: 2px; text-shadow: 0 2px 5px rgba(0,0,0,0.8);
 opacity: 0.8; transition: 0.3s;
}
.kalava-knot:hover .knot-label { opacity: 1; transform: translateY(-5px); }
.kalava-knot:hover .knot-center { transform: scale(1.1); }

/* =========================================
 3. ROYAL SCROLL (Paper Physics)
========================================== */
.scroll-wrapper {
 display: flex; justify-content: center; padding: 40px 0;
 opacity: 0; transform: translateY(100px); /* Start lower */
}

.royal-scroll {
 width: 90%; max-width: 700px;
 background-color: var(--paper-bg);
 background-image: var(--paper-texture);
 box-shadow: 0 0 60px rgba(0,0,0,0.8); /* Deep shadow to float */
 padding: 60px 40px;
 position: relative;
 border-radius: 5px;

 /* Torn Paper Edge (Top and Bottom) */
 mask-image: radial-gradient(circle, black 70%, transparent 100%);
 /* We use a simple border radius here for reliability, 
 but you can use complex SVG masks for jagged edges if needed */
}

/* Decorative Gold Corners inside scroll */
.royal-scroll::before, .royal-scroll::after {
 content: '❄'; color: var(--royal-red); font-size: 2rem;
 position: absolute; opacity: 0.3;
}
.royal-scroll::before { top: 20px; left: 20px; }
.royal-scroll::after { bottom: 20px; right: 20px; }

/* Ink Typography */
.ink-om { width: 70px; filter: sepia(1) hue-rotate(-50deg) saturate(3); opacity: 0.9; }
.ink-title { 
 font-family: var(--font-heading); font-size: 4rem; color: var(--royal-red);
 text-shadow: 1px 1px 0px rgba(0,0,0,0.2); line-height: 1.1; margin-bottom: 10px;
}
.script-intro { font-family: 'Playfair Display', serif; font-style: italic; font-size: 1.1rem; color: #555; }
.ink-line { height: 2px; background: var(--ink-color); width: 80px; margin: 0 auto; opacity: 0.4; border-radius: 50%; }

/* Ink Countdown */
.ink-countdown { display: flex; justify-content: center; gap: 20px; font-family: var(--font-heading); color: var(--royal-red); }
.ink-time span { font-size: 2.2rem; display: block; line-height: 1; }
.ink-sep { font-size: 1.8rem; opacity: 0.2; }

/* Couple Stamps */
.photo-stamp {
 width: 220px; height: 280px; margin: 0 auto;
 border: 8px solid #fff; box-shadow: 1px 2px 8px rgba(0,0,0,0.15);
 background: #fff;
 transform: rotate(-3deg); transition: transform 0.4s ease;
}
.col-md-6:last-child .photo-stamp { transform: rotate(3deg); }
.photo-stamp:hover { transform: scale(1.05) rotate(0deg); z-index: 5; }
.photo-stamp img { width: 100%; height: 100%; object-fit: cover; filter: sepia(0.3) contrast(1.1); }
.ink-name { font-family: var(--font-heading); font-size: 1.8rem; color: var(--royal-red); margin-top: 15px; }
.ink-parents { font-size: 0.9rem; font-style: italic; color: #666; }

/* Events Box */
.event-ink-box {
 border: 1px dashed var(--ink-color); padding: 15px; margin: 20px auto; max-width: 350px;
 background: rgba(255,255,255,0.4);
}
.highlight-ink { border: 2px solid var(--royal-red); background: rgba(128,0,0,0.03); }
.vertical-ink-line { height: 30px; width: 1px; background: var(--ink-color); margin: 0 auto; opacity: 0.2; }
.event-ink-box h4 { font-family: var(--font-heading); color: var(--royal-red); margin-bottom: 5px; }

/* Gallery */
.polaroid-img {
 width: 100%; height: 200px; object-fit: cover;
 border: 6px solid #fff; border-bottom: 25px solid #fff;
 box-shadow: 0 2px 5px rgba(0,0,0,0.1); filter: contrast(1.1); transition: transform 0.3s;
}
.polaroid-img:hover { transform: scale(1.03); }

/* Bookmark Nav */
.bookmark-nav {
 position: fixed; right: 0; top: 50%; transform: translateY(-50%);
 display: flex; flex-direction: column; gap: 8px; z-index: 500;
}
.book-link {
 background: var(--royal-red); color: var(--kalava-yellow);
 width: 40px; height: 40px; display: flex; align-items: center; justify-content: center;
 text-decoration: none; border-radius: 5px 0 0 5px;
 box-shadow: -2px 2px 5px rgba(0,0,0,0.3); transition: 0.3s;
 font-size: 1.2rem;
}
.book-link span { display: none; }
