 3. js/script.js (The Snap Animation) 

 The physics here is key: 

 Shake: The knot shakes when clicked. 

 Drop: The knot drops down . 

 Snap: The left thread flies left, right thread flies right (Retracting). 

 Open: The top flap moves up, bottom flap moves down. 

 Rise: The scroll rises up from the darkness. 

 $(document).ready(function() {

 // 1. Init AOS
 AOS.init({ duration: 1000, once: true });

 // 2. REALISTIC UNTYING ANIMATION
 $('#enter-btn').on('click', function() {
 var tl = gsap.timeline();

 // A. Knot Shake & Drop (Simulate loosening)
 tl.to(".kalava-knot", { rotation: 15, duration: 0.1, yoyo: true, repeat: 3 })
 .to(".kalava-knot", { y: 200, opacity: 0, duration: 0.5, ease: "power2.in" });

 // B. String Snap (Retract to sides)
 tl.to(".thread-left", { width: "0%", duration: 0.4, ease: "power4.in" }, "-=0.3");
 tl.to(".thread-right", { width: "0%", duration: 0.4, ease: "power4.in" }, "<");

 // C. Open the Velvet Flaps
 tl.to(".flap-top", { y: "-100%", duration: 1.2, ease: "power2.inOut" });
 tl.to(".flap-bottom", { y: "100%", duration: 1.2, ease: "power2.inOut" }, "<");

 // D. Remove Overlay
 tl.set("#loader-overlay", { display: "none" });

 // E. Scroll Rise (Float up)
 tl.to(".scroll-wrapper", { 
 opacity: 1, 
 y: 0, 
 duration: 1.5, 
 ease: "power3.out",
 onStart: function() {
 $('body').removeClass('overflow-hidden');
 }
 }, "-=0.5");

 // F. Ink Reveal
 tl.from(".ink-title", { scale: 0.9, opacity: 0, duration: 1, ease: "back.out" }, "-=1");
 });

 // 3. COUNTDOWN
 const weddingDate = new Date("Aug 24, 2026 10:45:00").getTime();
 setInterval(function() {
 const now = new Date().getTime();
 const dist = weddingDate - now;
 $('#days').text(Math.floor(dist / (1000 * 60 * 60 * 24)).toString().padStart(2, '0'));
 $('#hours').text(Math.floor((dist % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60)).toString().padStart(2, '0'));
 $('#minutes').text(Math.floor((dist % (1000 * 60 * 60)) / (1000 * 60)).toString().padStart(2, '0'));
 }, 1000);

 // 4. BOOKMARK ACTIVE STATE
 $(window).scroll(function() {
 var scrollPos = $(document).scrollTop();
 $('.book-link').each(function() {
 var currLink = $(this);
 var refElement = $(currLink.attr("href"));
 if (refElement && refElement.position()) {
 if (refElement.position().top <= scrollPos + 300 && refElement.position().top + refElement.height() > scrollPos + 300) {
 $('.book-link').removeClass("active");
 currLink.addClass("active");
 }
 }
 });
 });

});

