 /* =========================================
 1. VARIABLES & RESET
========================================== */
:root {
 --primary-bg: #FDFCF0;
 --primary-accent: #800000; /* Crimson */
 --luxury-gold: #D4AF37;
 --text-dark: #2c2c2c;

 --font-heading: 'Rozha One', serif;
 --font-body: 'Playfair Display', serif;
 --font-telugu: 'Ramabhadra', sans-serif;
}

body {
 margin: 0; padding-bottom: 80px; /* Space for dock */
 font-family: var(--font-body);
 color: var(--text-dark);
 overflow-x: hidden;
}
body.overflow-hidden { overflow: hidden; height: 100vh; }

/* Fixed Background Pattern */
.fixed-bg {
 position: fixed; top: 0; left: 0; width: 100%; height: 100%;
 background-color: var(--primary-bg);
 /* Subtle Gold Pattern */
 background-image: radial-gradient(var(--luxury-gold) 0.5px, transparent 0.5px);
 background-size: 20px 20px;
 opacity: 0.5; z-index: -1;
}

/* =========================================
 2. MANDALA LOADER (The Reveal)
========================================== */
#loader-overlay {
 position: fixed; top: 0; left: 0; width: 100%; height: 100%;
 background: var(--primary-accent);
 z-index: 9999; display: flex; justify-content: center; align-items: center;
}
.mandala-wrapper {
 position: relative; width: 250px; height: 250px;
 display: flex; justify-content: center; align-items: center;
}
.mandala-svg {
 position: absolute; width: 100%; height: 100%;
 animation: spin 15s linear infinite;
}
.loader-btn {
 position: relative; z-index: 2; width: 80px; height: 80px;
 background: var(--luxury-gold); border-radius: 50%;
 display: flex; align-items: center; justify-content: center;
 cursor: pointer; box-shadow: 0 0 20px rgba(212, 175, 55, 0.6);
 transition: transform 0.3s;
}
.loader-btn:hover { transform: scale(1.1); }
.loader-btn span { font-family: var(--font-heading); color: var(--primary-accent); }

@keyframes spin { 100% { transform: rotate(360deg); } }

/* =========================================
 3. HERO & TYPOGRAPHY
========================================== */
.hero-section { min-height: 100vh; }
.glass-card {
 background: rgba(255, 255, 255, 0.7);
 backdrop-filter: blur(12px);
 border: 1px solid rgba(255, 255, 255, 0.5);
 border-radius: 20px;
 box-shadow: 0 10px 30px rgba(0,0,0,0.05);
 max-width: 600px; margin: 0 auto;
}
.couple-names-v2 {
 font-family: var(--font-heading); font-size: 4rem;
 color: var(--primary-accent); line-height: 1;
}
.text-gold { color: var(--luxury-gold); }
.blessing-top {
 font-family: var(--font-telugu); color: var(--luxury-gold);
 font-weight: bold; letter-spacing: 1px;
}
.venue-pill {
 display: inline-block; padding: 5px 15px; background: var(--primary-accent);
 color: #fff; border-radius: 20px; font-size: 0.8rem; letter-spacing: 1px; margin-top: 5px;
}

/* Timer Circles */
.timer-circle {
 width: 60px; height: 60px; border: 1px solid var(--luxury-gold);
 border-radius: 50%; display: flex; flex-direction: column;
 align-items: center; justify-content: center; background: #fff;
}
.timer-circle span { font-family: var(--font-heading); font-size: 1.2rem; color: var(--primary-accent); line-height: 1; }
.timer-circle small { font-size: 0.6rem; color: #888; }

/* =========================================
 4. COMPONENTS
========================================== */
.section-title { font-family: var(--font-heading); color: var(--primary-accent); font-size: 2.5rem; }

/* Arch Images */
.arch-frame {
 width: 250px; height: 320px; margin: 0 auto;
 border-radius: 125px 125px 0 0; /* Arch Shape */
 overflow: hidden; border: 4px solid var(--luxury-gold);
