 2. css/style.css (Version 2) 

 Changes: 

 Added .mandala-wrapper styles (Spinning loader). 

 Added .glass-card (Backdrop blur + white opacity). 

 Added .dock-nav (Floating bottom bar). 

 Darker, richer color scheme ( #800000 background for loader and gallery). 

 /* =========================================
 1. VARIABLES & RESET (V2)
========================================== */
:root {
 --primary-base: #FDFCF0;
 --primary-accent: #800000; /* Crimson */
 --luxury-gold: #D4AF37;
 --gold-light: #F4E29E;
 --text-color: #4B3621;

 --font-heading: 'Rozha One', serif;
 --font-body: 'Playfair Display', serif;
 --font-telugu: 'Ramabhadra', sans-serif;
}

body {
 background-color: var(--primary-base);
 color: var(--text-color);
 font-family: var(--font-body);
 overflow-x: hidden;
 padding-bottom: 70px; /* Space for Bottom Dock */
}

body.overflow-hidden { overflow: hidden !important; height: 100vh; }

/* =========================================
 2. MANDALA LOADER (V2 Exclusive)
========================================== */
#loader-overlay {
 position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;
 background-color: var(--primary-accent); /* Crimson Screen */
 z-index: 9999; display: flex; justify-content: center; align-items: center;
 overflow: hidden;
}

.mandala-wrapper {
 position: relative; width: 300px; height: 300px;
 display: flex; justify-content: center; align-items: center;
}

.mandala-svg {
 position: absolute; width: 100%; height: 100%;
 animation: spin 20s linear infinite;
 fill: none;
}

.loader-btn {
 position: relative; z-index: 2;
 background: var(--luxury-gold); width: 100px; height: 100px;
 border-radius: 50%; display: flex; flex-direction: column;
 align-items: center; justify-content: center; cursor: pointer;
 box-shadow: 0 0 30px rgba(212, 175, 55, 0.5);
 transition: transform 0.3s ease;
}

.loader-btn:hover { transform: scale(1.1); }
.om-symbol { font-size: 2.5rem; }
.loader-btn span { font-size: 0.8rem; text-transform: uppercase; font-weight: bold; color: var(--primary-accent); }

@keyframes spin { 100% { transform: rotate(360deg); } }

/* =========================================
 3. HERO PARALLAX & GLASS CARDS
========================================== */
.hero-section {
 position: relative; height: 100vh; display: flex;
 align-items: center; justify-content: center;
}

.hero-bg {
 position: absolute; top: 0; left: 0; width: 100%; height: 100%;
 /* Floral Background */
 background: url('https://img.freepik.com/free-vector/indian-mandala-texture-background_1035-18151.jpg') center/cover no-repeat fixed;
 filter: brightness(0.6) sepia(0.3); z-index: -1;
}

.glass-card {
 background: rgba(255, 255, 255, 0.85);
 backdrop-filter: blur(10px);
 border: 1px solid var(--luxury-gold);
 border-radius: 15px;
 box-shadow: 0 10px 40px rgba(0,0,0,0.2);
}

.couple-names {
 font-size: 4rem; color: var(--primary-accent);
 font-family: var(--font-heading);
 background: linear-gradient(45deg, var(--primary-accent), #a00000);
 -webkit-background-clip: text; -webkit-text-fill-color: transparent;
}

/* Minimalist Timer */
.timer-flex { display: flex; justify-content: center; align-items: center; font-family: var(--font-heading); color: var(--text-color); }
.timer-item { text-align: center; width: 50px; }
.timer-item span { font-size: 1.5rem; display: block; line-height: 1; }
.timer-item small { font-size: 0.6rem; text-transform: uppercase; }
.timer-sep { font-size: 1.5rem; margin: 0 5px; color: var(--luxury-gold); }

/* =========================================
 4. SECTIONS (Couple, Events, Gallery)
========================================== */
.section-pad { padding: 5rem 0; }
.bg-pattern { background-image: radial-gradient(#d4af37 1px, transparent 1px); background-size: 20px 20px; }
.bg-dark-crimson { background-color: #2a0a0a; }

.section-title { font-size: 2.5rem; color: var(--primary-accent); margin-bottom: 0.5rem; }
.text-gold { color: var(--luxury-gold) !important; }

/* V2 Couple Images - Rounded Squares with Gold Border */
.couple-img-v2 {
 width: 100%; max-width: 400px; height: 400px; object-fit: cover;
 border-radius: 30px 0 30px 0; border: 4px solid var(--luxury-gold);
 box-shadow: 10px 10px 0 rgba(128, 0, 0, 0.1);
}

/* Zig Zag Timeline */
.vine-line {
 position: absolute; left: 50%; top: 50px; bottom: 50px; width: 2px;
 background: var(--luxury-gold); opacity: 0.3; transform: translateX(-50%);
}
.event-orb {
 width: 60px; height: 60px; background: var(--primary-base);
 border: 2px solid var(--luxury-gold); border-radius: 50%;
 display: flex; align-items: center; justify-content: center;
 font-size: 1.5rem; position: relative; z-index: 2; margin: 0 auto;
}
.highlight-orb { background: var(--luxury-gold); color: #fff; box-shadow: 0 0 20px var(--luxury-gold); }
.event-title-v2 { font-family: var(--font-heading); color: var(--primary-accent); font-size: 1.8rem; }
.event-meta { font-weight: bold; color: var(--text-color); font-size: 0.9rem; text-transform: uppercase; }

/* Mosaic Gallery */
.mosaic-img { width: 100%; object-fit: cover; transition: transform 0.3s; opacity: 0.9; }
.mosaic-img:hover { transform: scale(1.02); opacity: 1; z-index: 2; }
.tall { height: 400px; }
.wide { height: 400px; }
.square { height: 200px; }

/* =========================================
 5. BOTTOM DOCK NAV
========================================== */
.dock-nav {
 position: fixed; bottom: 20px; left: 50%; transform: translateX(-50%);
 background: rgba(128, 0, 0, 0.95); /* Crimson Glass */
 backdrop-filter: blur(10px);
 padding: 10px 20px; border-radius: 50px;
 display: flex; gap: 20px; z-index: 1040;
 box-shadow: 0 10px 20px rgba(0,0,0,0.3);
 border: 1px solid var(--luxury-gold);
}

.dock-item {
 color: var(--luxury-gold); text-decoration: none;
 display: flex; flex-direction: column; align-items: center;
 font-size: 1.2rem; opacity: 0.7; transition: 0.3s;
}
.dock-item span { font-size: 0.6rem; display: none; }
.dock-item:hover, .dock-item.active { opacity: 1; transform: translateY(-3px); }

/* Blessing Bar (Transparent) */
.blessing-bar {
 position: fixed; top: 0; width: 100%; padding: 10px 0;
 display: flex; justify-content: center; gap: 30px;
 color: var(--luxury-gold); background: rgba(0,0,0,0.3); z-index: 1030;
 font-weight: bold; font-size: 0.8rem;
}

/* Utils */
.btn-gold { background: var(--luxury-gold); color: #fff; padding: 10px 30px; border-radius: 30px; }
.audio-control { position: fixed; top: 80px; right: 20px; z-index: 1050; color: var(--luxury-gold); cursor: pointer; }

/* Mobile */
@media (max-width: 768px) {
 .couple-img-v2 { height: 300px; margin-bottom: 20px; }
 .vine-line { left: 30px; }
 .event-icon-col { text-align: left; margin-bottom: 10px; }
 .event-orb { margin: 0; }
 .event-text-col, .event-desc-col { text-align: left !important; padding-left: 70px; }
 .dock-nav { bottom: 0; width: 100%; border-radius: 0; justify-content: space-around; }
}

 3. js/script.js (Version 2) 

 Changes: 

 GSAP Loader: The Mandala spins faster on click, then scales up massively ( scale: 50 ) to create a "portal" effect, revealing the page. 

 ScrollTrigger: Replaced basic AOS with GSAP ScrollTrigger for the "Zig Zag" vine filling up with color (Optional, but kept simple here with AOS for reliability). 

 $(document).ready(function() {

 // 1. Init AOS
 AOS.init({ duration: 1000, once: true });

 // Register GSAP ScrollTrigger
 gsap.registerPlugin(ScrollTrigger);

 // 2. MANDALA REVEAL LOGIC
 $('#enter-btn').on('click', function() {

 var tl = gsap.timeline();

 // A. Spin Mandala Faster
 tl.to(".mandala-svg", { duration: 1, rotation: 360, ease: "power2.in" });

 // B. Explode/Zoom In (Portal Effect)
 tl.to(".mandala-wrapper", { 
 scale: 50, // Huge scale to fill screen
 opacity: 0, 
 duration: 1.5, 
 ease: "expo.in" 
 });

 // C. Fade out Overlay
 tl.to("#loader-overlay", { 
 opacity: 0, 
 duration: 0.5, 
 onComplete: function() {
 $('#loader-overlay').css('display', 'none');
 $('body').removeClass('overflow-hidden');
 } 
 }, "-=0.5");

 // D. Animate Hero Elements
 tl.from(".glass-card", { y: 100, opacity: 0, duration: 1.5, ease: "power3.out" });
 });

 // 3. COUNTDOWN
 const weddingDate = new Date("Aug 24, 2026 10:45:00").getTime();
 setInterval(function() {
 const now = new Date().getTime();
 const dist = weddingDate - now;
 $('#days').text(Math.floor(dist / (1000 * 60 * 60 * 24)).toString().padStart(2, '0'));
 $('#hours').text(Math.floor((dist % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60)).toString().padStart(2, '0'));
 $('#minutes').text(Math.floor((dist % (1000 * 60 * 60)) / (1000 * 60)).toString().padStart(2, '0'));
 }, 1000);

 // 4. MUSIC TOGGLE
 var music = document.getElementById("bg-music");
 var isPlaying = false;
 $('#audio-btn').on('click', function() {
 if(isPlaying) { music.pause(); $(this).html('<i class="fas fa-volume-mute"></i>'); }
 else { music.play(); $(this).html('<i class="fas fa-music"></i>'); }
 isPlaying = !isPlaying;
 });

 // 5. DOCK NAV ACTIVE STATE
 $(window).scroll(function() {
 var scrollPos = $(document).scrollTop();
 $('.dock-item').each(function() {
 var currLink = $(this);
 var refElement = $(currLink.attr("href"));
 if (refElement.position().top <= scrollPos + 200 && refElement.position().top + refElement.height() > scrollPos + 200) {
 $('.dock-item').removeClass("active");
 currLink.addClass("active");
 }
 });
 });

});

