 $(document).ready(function() {

 // Register GSAP ScrollTrigger
 gsap.registerPlugin(ScrollTrigger);

 // 1. CURTAIN REVEAL SEQUENCE
 $('#enter-btn').on('click', function() {
 var tl = gsap.timeline();

 // Stamp Vanish
 tl.to(".royal-stamp", { scale: 0.7, opacity: 0, duration: 0.6, ease: "back.in(1.5)" });

 // Curtain Pull (Complex "Lux" Ease)
 tl.to(".curtain-left", {
 xPercent: -100, scaleX: 0.3, rotation: -6, borderBottomRightRadius: "80% 120vh",
 duration: 2.8, ease: "expo.inOut"
 }, "<+=0.1");

 tl.to(".curtain-right", {
 xPercent: 100, scaleX: 0.3, rotation: 6, borderBottomLeftRadius: "80% 120vh",
 duration: 2.8, ease: "expo.inOut"
 }, "<");

 // UI Reveal
 tl.add(() => {
 $('#curtain-overlay').css('visibility', 'hidden');
 $('body').removeClass('overflow-hidden');

 // Show Navbar
 gsap.to(".navbar", { opacity: 1, y: 0, duration: 0.8 });

 // Init Scroll Triggers after load
 initScrollAnimations();
 });

 // Hero Content Animation
 tl.from(".anim-hero", { opacity: 0, y: 30, duration: 1, stagger: 0.2, ease: "power3.out" }, "-=1.5");
 });

 // 2. SCROLL ANIMATIONS (GSAP ScrollTrigger)
 function initScrollAnimations() {
 // Generic Fade Up for sections
 gsap.utils.toArray('.gs-reveal').forEach(elem => {
 gsap.from(elem, {
 scrollTrigger: { trigger: elem, start: "top 85%" },
 y: 50, opacity: 0, duration: 1.2, ease: "power3.out"
 });
 });

 // Slide from Left
 gsap.utils.toArray('.gs-reveal-left').forEach(elem => {
 gsap.from(elem, {
 scrollTrigger: { trigger: elem, start: "top 85%" },
 x: -50, opacity: 0, duration: 1.2, ease: "power3.out"
 });
 });

 // Slide from Right
 gsap.utils.toArray('.gs-reveal-right').forEach(elem => {
 gsap.from(elem, {
 scrollTrigger: { trigger: elem, start: "top 85%" },
 x: 50, opacity: 0, duration: 1.2, ease: "power3.out"
 });
 });
 }

 // 3. COUNTDOWN TIMER (Simple JS)
 const weddingDate = new Date("August 24, 2026 10:35:00").getTime();

 const timer = setInterval(function() {
 const now = new Date().getTime();
 const distance = weddingDate - now;

 if (distance < 0) {
 clearInterval(timer);
 $("#countdown-box").html("<h3 class='text-white'>The Moment Has Arrived!</h3>");
 return;
 }

 const days = Math.floor(distance / (1000 * 60 * 60 * 24));
 const hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
 const minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
 const seconds = Math.floor((distance % (1000 * 60)) / 1000);

 $("#days").text(days < 10 ? "0" + days : days);
 $("#hours").text(hours < 10 ? "0" + hours : hours);
 $("#minutes").text(minutes < 10 ? "0" + minutes : minutes);
 $("#seconds").text(seconds < 10 ? "0" + seconds : seconds);
 }, 1000);

 // 4. NAVBAR SCROLL EFFECT
 $(window).scroll(function() {
 if ($(this).scrollTop() > 100) {
 $('.navbar').addClass('bg-white').css('padding', '10px 0');
 } else {
 $('.navbar').removeClass('bg-white').css('padding', '15px 0');
 }
 });

 // Close mobile menu on click
 $('.nav-link').click(function() {
 $('.navbar-collapse').collapse('hide');
 });
});

