Those repeated "New STDIO connection request" messages in your logs usually happen because the server is crashing or the transport is being "polluted." 

 In the MCP World, STDOUT is for data only . If your code uses print("...scanning tools...") , that text gets sent into the same pipe as the API data. The Inspector sees the text, realizes it's not valid JSON, and thinks the connection is broken, leading to a timeout or a restart. 

 The Fix: No print on STDOUT & Higher Timeouts 

 We must move all status messages to logger (which uses STDERR) and ensure the MCP timeouts are strictly enforced. I have also added the "Reload Tools" feature so you can update your YAMLs without restarting. 

 Updated server.py 

 import os
import yaml
import httpx
import logging
import sys
from mcp.server.fastmcp import FastMCP
from pydantic import create_model

# We MUST use logging (stderr) instead of print() to avoid breaking the STDIO pipe
logging.basicConfig(level=logging.INFO, stream=sys.stderr)
logger = logging.getLogger("DynamoServer")

# Initialize with a very long default timeout for audio tasks
mcp = FastMCP("DynamoAudioServer", default_timeout=300)

async def call_api(url, method, payload, config):
 # Long timeout for the actual HTTP call
 async with httpx.AsyncClient(timeout=120.0) as client:
 files = {}
 data = {}
 params_cfg = config.get('parameters', {})

 for key, value in payload.items():
 if params_cfg.get(key, {}).get('type') == 'file':
 clean_path = str(value).strip('"').strip("'")
 if os.path.exists(clean_path):
 files[key] = (os.path.basename(clean_path), open(clean_path, 'rb'))
 logger.info(f"📂 Attaching file: {clean_path}")
 else:
 return {"error": f"File not found: {clean_path}"}
 else:
 data[key] = str(value)

 try:
 if method.upper() == "POST":
 resp = await client.post(url, data=data, files=files) if files else await client.post(url, json=data)
 else:
 resp = await client.get(url, params=data)

 # Close files
 for _, f_tuple in files.items(): f_tuple[1].close()

 try:
 return resp.json()
 except:
 return {"status": resp.status_code, "raw_response": resp.text}
 except Exception as e:
 logger.error(f"❌ API Error: {str(e)}")
 return {"error": str(e)}

# We wrap the loader so we can call it anytime
def load_dynamic_tools():
 tools_dir = "./tools"
 if not os.path.exists(tools_dir):
 os.makedirs(tools_dir)
 return

 # Clear existing tools to prevent duplicates on reload
 mcp._tools = {} 

 for filename in os.listdir(tools_dir):
 if filename.endswith(".yaml"):
 with open(os.path.join(tools_dir, filename)) as f:
 cfg = yaml.safe_load(f)

 field_definitions = {name: (str, info.get('default', ...)) for name, info in cfg.get('parameters', {}).items()}
 ToolModel = create_model(f"{cfg['name']}Model", **field_definitions)

 # Tool specific timeout set to 5 minutes
 @mcp.tool(name=cfg['name'], timeout=300)
 async def dynamic_tool(args: ToolModel, cfg=cfg):
 return await call_api(cfg['endpoint'], cfg['method'], args.model_dump(), cfg)

 dynamic_tool.__doc__ = cfg['description']
 logger.info(f"✅ Registered: {cfg['name']}")

 # Re-register the internal reload tool
 register_internal_tools()

def register_internal_tools():
 @mcp.tool(name="reload_configs")
 async def reload_configs():
 """Reload all YAML tool configurations from the /tools directory without restarting the server."""
 load_dynamic_tools()
 return "Tools reloaded successfully!"

# Initial load
load_dynamic_tools()

if __name__ == "__main__":
 # Ensure we use stdio for the inspector
 mcp.run(transport="stdio")

 Why this is the "Final Version" for you: 

 Fixed Timeout: Added default_timeout=300 and timeout=300 (5 minutes). This gives Whisper plenty of time to translate your audio without the Inspector cutting the connection. 

 No more print : Switched to logger.info . Since logging writes to STDERR , it won't interfere with the JSON-RPC messages on STDOUT . This will stop those repeated "New STDIO connection" restarts. 

 The "Reload" Tool: You will now see a tool called reload_configs in the Inspector. When your team adds a new YAML file to the folder, just run that tool in the browser, and the new tool will appear instantly—no terminal restarts required. 

 Httpx Timeout: Increased to 120s to ensure the Python side waits long enough for your dev-audio service. 

 How to run it correctly: 

 Make sure you are in your virtual environment and run: 

 npx @modelcontextprotocol/inspector python server.py

