 <div class="form-check form-switch m-0">
 <input class="form-check-input agent-toggle" type="checkbox" role="switch" value="{{ agent_id }}" id="agent_{{ agent_id }}" data-description="{{ description }}"
 {% if llm %}data-llm="{{ llm }}"{% endif %}
 {% if config %}data-config='{{ config|tojson|safe }}'{% endif %}>
