 .user-message{ margin-left:auto; background:linear-gradient(135deg, var(--brand-primary) 0%, #8b5cf6 100%); color:#fff; }
 .agent-message{ background:linear-gradient(135deg, #212d38 0%, #1b2936 100%); color:#fff; }
