<body>
 <div class="container-fluid py-4 page-wrapper">
 <div class="page-header mb-3">
 <h1 class="mb-0">Agentarium</h1>
 <a href="/agent-management" class="btn btn-sm">Manage Agents</a>
 </div>

 <div class="row g-3 main-content-row">
 <div class="col-lg-3 sidebar-column">
