 import json
from crewai import Crew, Process
from tasks import extraction_task
from agents import entity_extraction_agent

class ConversationManager:
 def __init__(self):
 self.conversations = {}
 self.conversation_states = {}

 def initialize_conversation(self, call_sid):
 self.conversations[call_sid] = []
 self.conversation_states[call_sid] = {
 "stage": "greeting",
 "details_collected": {
 "guardian_name": "N/A",
 "pet_name": "N/A",
 "pet_species": "N/A",
 "pet_breed": "N/A",
 "pet_dob": "N/A",
 "appointment_time": "Thursday, October 19th at 10:00 AM",
 "appointment_confirmed": False
 }
 }

 def update_with_extracted_data(self, call_sid, customer_response):
 if not customer_response.strip():
 return

 extraction_crew = Crew(
 agents=[entity_extraction_agent],
 tasks=[extraction_task],
 process=Process.sequential
 )

 try:
 result = extraction_crew.kickoff(inputs={"customer_response": customer_response})
 extracted_data = json.loads(result.raw)

 current_details = self.conversation_states[call_sid]["details_collected"]
 for key, value in extracted_data.items():
 if value and value != "N/A":
 # This is the fix: Allow overwriting existing data.
 current_details[key] = value
 except (json.JSONDecodeError, Exception) as e:
 print(f"Error during extraction: {e}")

 def update_conversation(self, call_sid, role, content):
 if call_sid not in self.conversations:
 self.initialize_conversation(call_sid)

 self.conversations[call_sid].append({"role": role, "content": content})

 if role == "customer":
 self.update_with_extracted_data(call_sid, content)
 self._update_state_based_on_response(call_sid, content)

 def _update_state_based_on_response(self, call_sid, response):
 state = self.conversation_states[call_sid]
 details = state["details_collected"]
 response_lower = response.lower()

 is_positive_confirmation = any(word in response_lower for word in ["yes", "correct", "that's right", "perfect", "sounds good", "yep", "confirm the date"])

 # Check if all personal/pet details have been collected
 all_details_filled = all(
 v not in [None, "N/A", ""] for k, v in details.items() 
 if k not in ["appointment_time", "appointment_confirmed"]
 )

 # If all details are filled and the user gives a positive confirmation, mark the appointment as confirmed
 if is_positive_confirmation and all_details_filled:
 details["appointment_confirmed"] = True
 state["stage"] = "final_questions"

 def get_conversation_context(self, call_sid):
 if call_sid not in self.conversations: return ""
 recent_messages = self.conversations[call_sid][-8:] # Increased context
