def display_trace_flow(traces):
 if not traces:
 st.info("No trace data available to display.")
 return
 columns = ['TraceId', 'SpanId', 'ParentSpanId', 'SpanName', 'SpanKind', 'Duration', 'Timestamp', 'SpanAttributes']
 spans_list = [dict(zip(columns, span_tuple)) for span_tuple in traces]
 span_tree = {}
 root_spans = []
 all_spans = {s['SpanId']: s for s in spans_list}
 for span_id in all_spans:
 span_tree[span_id] = []
 for span_id, span in all_spans.items():
 parent_id = span.get('ParentSpanId')
 if parent_id and parent_id in all_spans:
 span_tree[parent_id].append(span)
 else:
 root_spans.append(span)
 root_spans.sort(key=lambda s: s['Timestamp'])
 for parent_id in span_tree:
 span_tree[parent_id].sort(key=lambda s: s['Timestamp'])
 for root_span in root_spans:
 display_span_recursively(root_span, span_tree)

